    protected $send_time_type = [];

    private function getHasConfig($village_id, $field)
    {
        $database_house_village = D('House_village');
        $house_village_info = $database_house_village->get_one($village_id, $field);
        $config_info = $house_village_info[$field];
        return $config_info;
    }

    public function check_village_session($village_id, $pigcms_id = 0)
    {
        if (!empty($village_id)) {
            $where['uid'] = $this->_uid;
            $where['village_id'] = $village_id;
            $where['status'] = ['not in', [0,3,4]];
            // 房间
            if ($pigcms_id) {
                $where['pigcms_id'] = $pigcms_id;
            }
            $House_village_user_bindModel = D('House_village_user_bind');
            $bind_village_list = $House_village_user_bindModel->field(true)->where($where)->order('`pigcms_id` DESC')->select();
            if ($pigcms_id && empty($bind_village_list)) {
                unset($where['pigcms_id']);
                $bind_village_list = $House_village_user_bindModel->field(true)->where($where)->order('`pigcms_id` DESC')->select();
            }

            if (!$bind_village_list) {
                $bind_village_list = $House_village_user_bindModel->where(array('uid' => $this->_uid, 'village_id' => $village_id, 'parent_id' => array('neq', 0), 'status' => array('not in', [0,3,4])))->order('`pigcms_id` DESC')->select();
                if (!$bind_village_list) {
                    $bind_village_list = $House_village_user_bindModel->field(true)->where(array('uid' => $bind_village_list[0]['parent_id'], 'village_id' => $village_id))->order('`pigcms_id` DESC')->select();
                }
            }
            if (!empty($bind_village_list)) {
                if (count($bind_village_list) == 1) {
                    return $bind_village_list[0];
                } else {
                    return array();
                }
            }
        } else {
            return array();
        }
    }

    public function index()
    {
        $res = [];
        $village_id = I('village_id', 0, 'intval');
        if (empty($village_id)) {
            $this->returnCode('20090005');
        }
        $cacheindexkey = 'village:appapi_apiindex:' . $village_id;
        $cacheindexuidkey = 'village:appapi_apiindex:' . $village_id.'uid:'.$this->_uid;
        $wxapp_own_village_id = I('wxapp_own_village_id', 0);
        $property_id = I('property_id', 0);
        if ($wxapp_own_village_id) {
            $property_name_info = M('House_property')->where(['id' => $wxapp_own_village_id])->field('property_name,property_short_name')->find();
            $res['page_title'] = trim($property_name_info['property_short_name']) ? trim($property_name_info['property_short_name']) : trim($property_name_info['property_name']);
        } elseif ($property_id) {
            $property_name_info = M('House_property')->where(['id' => $property_id])->field('property_name,property_short_name')->find();
            $res['page_title'] = trim($property_name_info['property_short_name']) ? trim($property_name_info['property_short_name']) : trim($property_name_info['property_name']);
        } else {
            $res['page_title'] = $this->config['wechat_name'];
        }
        $now_village = D('House_village')->field('village_id,province_id,city_id,property_id,has_kefu,is_platform_guess,village_name,street_id,community_id,`long`,`lat`')->where(array('village_id' => $village_id))->find();
        $res['Popup'] = array();
        // 首页是否处于游客
        $tourist = $this->getHasConfig($village_id, 'tourist');
        $pigcms_id = I('pigcms_id', 0);
        if ($pigcms_id) {
            $bind_info = $this->check_village_session($village_id, $pigcms_id);
        }

        // 返回值 is_house_bind  0: 游客状态 1:　需要绑定 2： 跳转路径 is_redirect 数据
        $viewpage = I('viewpage', '');// 如果是后台访问，直接以游客模式访问
        if ($tourist != 1 && !$viewpage) {
            $pigcms_id = I('pigcms_id');
            $bind_info = $this->check_village_session($village_id, $pigcms_id);
//            $base_url = D('House_village')->base_url;
            if (!empty($bind_info)) {
                if ($bind_info['status'] == 2) {
                    $res['is_house_bind'] = 2;
                    $res['is_redirect'] = $this->config['site_url'] . '/wap.php?g=Wap&c=House&a=my_village_list';
                } else {
                    $res['is_house_bind'] = 0;
                    $res['is_redirect'] = '';
                }
            } else {
                if (empty($bind_info) && !$pigcms_id) {
                    $bind_info = $this->check_village_session($village_id, 0);
                    if (!empty($bind_info)) {
                        if ($bind_info['status'] == 2) {
                            $res['is_house_bind'] = 2;
                            $res['is_redirect'] = $this->config['site_url'] . '/wap.php?g=Wap&c=House&a=my_village_list';
                        } else {
                            $res['is_house_bind'] = 0;
                            $res['is_redirect'] = '';
                        }
                    } else {
                        $res['is_house_bind'] = 1;
                        $res['is_redirect'] = '';
                    }
                } else {
                    $res['is_house_bind'] = 0;
                    $res['is_redirect'] = '';
                }
            }
        } else {
            $res['is_house_bind'] = 0;
            $res['is_redirect'] = '';
        }
        $db_house_village = D('House_village');
        $app_version = intval($_POST['app_version']);
        $deviceId = trim($_POST['Device-Id']);
        $cacheArr = S($cacheindexkey);
        $toCacheArr = array();
        if (!empty($cacheArr) && isset($cacheArr['select_rooms_url']) && $cacheArr['select_rooms_url']) {
            $select_rooms_url = $cacheArr['select_rooms_url'];
        } else {
            $param = [
                'pageName' => 'selectRooms',
                'isAll' => true,
                'urlParam' => 'village_id=' . $village_id,
            ];
            $select_rooms_url = $db_house_village->villagePagePath($app_version, $deviceId, $param);
            $toCacheArr['select_rooms_url'] = $select_rooms_url;
        }
        $base_url = $db_house_village->base_url;
        $res['select_rooms_url'] = $select_rooms_url;
        //自动绑定一次
        if ($this->_uid) {
            $now_user = D('User')->get_user($this->_uid);
            if ($now_user['phone']) {
                D('House_village_user_bind')->bind($now_user['uid'], $now_user['phone']);
            }
            // 查询下客户登录最后一次进入的小区 如果记录不一致  新加记录
            $user_last_village_id = M('House_village_select_log')->where(['uid' => $this->_uid])->order('id DESC')->getField('village_id');
            if ($user_last_village_id != $village_id) {
                M('House_village_select_log')->data(['uid' => $this->_uid, 'village_id' => $village_id, 'add_time' => time()])->add();
            }
        }
        //弹窗通知
        $floor_id = 0;
        $news_id = false;
        if (!empty($bind_info)) {
            $pigcms_id = I('pigcms_id');
            $where['uid'] = $this->_uid;
            $where['village_id'] = $village_id;
            $where['pigcms_id'] = $pigcms_id;
            $House_village_user_bindModel = D('House_village_user_bind');
            $bind_village_list = $House_village_user_bindModel->field(true)->where($where)->find();
            $floor_id = $bind_village_list['floor_id'];
            if ($bind_village_list) {
                $time = $bind_village_list['login_time'];//进入时间
                /**
                 * todo 查询当前用户所在通知房间的数据
                 */
                $village_news_notice_where['_string'] = ' ( type = 1 AND room_id = ' . $bind_village_list['vacancy_id'] . ' ) OR (type = 0 AND village_id = ' . $village_id . ')';
                $news_notice = D('House_village_news_notice')->where($village_news_notice_where)->getField('news_id', true);
                if ($news_notice) {
                    $news_id = array_values(array_unique($news_notice));
                }
                //todo 查询指定房间
                $res['Popup'] = D('House_village_news')->get_popup_new_list($village_id, $time, $floor_id, $news_id);
                $House_village_user_bindModel->where($where)->data(array('login_time' => time()))->save();
            }
        } else {
            //todo 平台新闻查询
            $time = time();
            $news_notice = D('House_village_news_notice')->where(['village_id' => $village_id, 'type' => 0])->getField('news_id', true);
            if ($news_notice) {
                $news_id = array_values(array_unique($news_notice));
            }
            $res['Popup'] = D('House_village_news')->get_popup_new_list($village_id, $time, $floor_id, $news_id);
        }

        $link = A('System/link');
        if (!empty($cacheArr) && isset($cacheArr['modules']) && $cacheArr['modules']) {
            $modules = $cacheArr['modules'];
        } else {
            $modules = D('House_link')->village_library($village_id, $this->config, $link->village_modules, 'wap.php');
            $toCacheArr['modules'] = $modules;
        }
        $switch = C('config.house_visualize_switch') ? C('config.house_visualize_switch') : 0;
        if ($modules) {
            foreach ($modules as $k => $v) {
                if (intval($v['sub']) > 0) {
                    unset($modules[$k]);
                }
            }
            $modules = array_column($modules, 'module');
            $modules[]='customizedHappinessPropertyNav';
        }
        if (!empty($cacheArr) && isset($cacheArr['is_new_charge']) && $cacheArr['is_new_charge']) {
            $is_new_charge = $cacheArr['is_new_charge'];
        } else {
            $is_new_charge = D('House_village')->checkNewCharge($now_village['property_id']);
            $toCacheArr['is_new_charge'] = $is_new_charge;
        }
        $village_modules = [
            'switch' => $switch,
            'modules' => $modules,
            'is_new_charge' => $is_new_charge
        ];

        // 小区相关信息
        if (!empty($cacheArr) && isset($cacheArr['village_info']) && $cacheArr['village_info']) {
            $village_info = $cacheArr['village_info'];
        } else {
            $village_info = D('House_village_info')->getVillageInfo(array('village_id' => $village_id), '*');
            $toCacheArr['village_info'] = $village_info;
        }
        // 猜你喜欢配置项
        // 首页颜色配置要求保存后立即生效，不使用上面的首页组合缓存，避免并发请求回写旧配置。
        $home_color_config = D('House_village_info')->where(array('village_id' => $village_id))->field('switch_village_color,index_title_color,index_header_bg_color,index_header_bg_image')->find();
        $res['switch_village_color'] = preg_match('/^#[0-9A-Fa-f]{6}$/', $home_color_config['switch_village_color']) ? strtoupper($home_color_config['switch_village_color']) : '#FFFFFF';
        $res['index_title_color'] = preg_match('/^#[0-9A-Fa-f]{6}$/', $home_color_config['index_title_color']) ? strtoupper($home_color_config['index_title_color']) : '#000000';
        $res['index_header_bg_color'] = preg_match('/^#[0-9A-Fa-f]{6}$/', $home_color_config['index_header_bg_color']) ? strtoupper($home_color_config['index_header_bg_color']) : '';
        $res['index_header_bg_image'] = !empty($home_color_config['index_header_bg_image']) ? replace_file_domain($home_color_config['index_header_bg_image']) : '';
        $public_revenue_home_config = (array)D('House_village_info')
            ->where(array('village_id' => $village_id))
            ->field('public_revenue_home_show,public_revenue_home_title,public_revenue_home_bg_color,public_revenue_page_bg_color,public_revenue_page_bg_image')
            ->find();
        $public_revenue_title = trim($public_revenue_home_config['public_revenue_home_title']);
        if ($public_revenue_title === '') {
            $public_revenue_title = '公共资源经营收益';
        }
        $public_revenue_home_bg_color = preg_match('/^#[0-9A-Fa-f]{6}$/', $public_revenue_home_config['public_revenue_home_bg_color']) ? strtoupper($public_revenue_home_config['public_revenue_home_bg_color']) : '#FFFFFF';
        $public_revenue_page_bg_color = preg_match('/^#[0-9A-Fa-f]{6}$/', $public_revenue_home_config['public_revenue_page_bg_color']) ? strtoupper($public_revenue_home_config['public_revenue_page_bg_color']) : '#F3F4F6';
        $public_revenue_page_bg_image = !empty($public_revenue_home_config['public_revenue_page_bg_image']) ? replace_file_domain($public_revenue_home_config['public_revenue_page_bg_image']) : '';
        $res['public_revenue_home'] = array(
            'show' => intval($public_revenue_home_config['public_revenue_home_show']),
            'title' => $public_revenue_title,
            'background_color' => $public_revenue_home_bg_color,
            'page_background_color' => $public_revenue_page_bg_color,
            'page_background_image' => $public_revenue_page_bg_image,
            // 同时返回数据库原始字段名，兼容已发布的不同小程序版本并便于接口排查。
            'public_revenue_home_bg_color' => $public_revenue_home_bg_color,
            'public_revenue_page_bg_color' => $public_revenue_page_bg_color,
            'public_revenue_page_bg_image' => $public_revenue_page_bg_image,
            'balance_amount' => '0.00',
            'income_amount' => '0.00',
            'unit' => '元',
        );
        if ($res['public_revenue_home']['show'] === 1) {
            $public_revenue_period_model = M('Public_revenue_period');
            $current_public_revenue_year = intval(date('Y'));
            $current_public_revenue_quarter = intval(ceil(intval(date('n')) / 3));
            $latest_public_revenue_period = $public_revenue_period_model->where(array(
                'village_id' => $village_id,
                'year' => $current_public_revenue_year,
                'quarter' => array('between', array(0, $current_public_revenue_quarter)),
                'status' => 1,
            ))->order('year DESC,quarter DESC,id DESC')->find();
            if (!$latest_public_revenue_period) {
                $latest_public_revenue_period = $public_revenue_period_model->where(array(
                    'village_id' => $village_id,
                    'year' => array('lt', $current_public_revenue_year),
                    'quarter' => array('between', array(0, 4)),
                    'status' => 1,
                ))->order('year DESC,quarter DESC,id DESC')->find();
            }
            if ($latest_public_revenue_period) {
                $public_revenue_year = intval($latest_public_revenue_period['year']);
                $public_revenue_quarter = intval($latest_public_revenue_period['quarter']);
                $opening_public_revenue_period = $public_revenue_period_model->where(array(
                    'village_id' => $village_id,
                    'year' => $public_revenue_year,
                    'quarter' => 0,
                    'status' => 1,
                ))->find();
                $annual_public_revenue = array();
                if ($public_revenue_quarter > 0) {
                    $annual_public_revenue = $public_revenue_period_model->where(array(
                        'village_id' => $village_id,
                        'year' => $public_revenue_year,
                        'quarter' => array('between', array(1, $public_revenue_quarter)),
                        'status' => 1,
                    ))->field('SUM(actual_income_total) AS actual_income_total,SUM(actual_expense_total) AS actual_expense_total')->find();
                }
                $balance_amount = floatval($opening_public_revenue_period['opening_actual_balance'])
                    + floatval($annual_public_revenue['actual_income_total'])
                    - floatval($annual_public_revenue['actual_expense_total']);
                $balance_amount = number_format(round($balance_amount, 2, PHP_ROUND_HALF_UP), 2, '.', '');
                $res['public_revenue_home']['balance_amount'] = $balance_amount;
                // 保留旧字段，避免未同步升级的小程序首页出现空金额。
                $res['public_revenue_home']['income_amount'] = $balance_amount;
                $res['public_revenue_home']['year'] = $public_revenue_year;
                $res['public_revenue_home']['quarter'] = $public_revenue_quarter;
            }
        }
        $res['is_guess_like'] = $village_info['is_guess_like'];
        // 单行功能导航
        $cacheUidArr=S($cacheindexuidkey);
        $toCacheUidArr=array();
        if (!empty($cacheUidArr) && isset($cacheUidArr['single_nav']) && $cacheUidArr['single_nav']) {
            $single_nav = $cacheUidArr['single_nav'];
        } else {
            $single_nav = D('House_village_nav')->get_village_nav($village_id, $village_modules, $this->_uid, 1, $now_village);
            $toCacheUidArr['single_nav'] = $single_nav;
        }
        $res['single_nav']['list'] = $single_nav;
        $res['single_nav']['multiline_effect_config'] = $village_info['multiline_effect'];
        $res['single_nav']['view_num'] = $village_info['view_num'];
        // 中间栏功能导航
        $res['middle_nav']=array('list'=>array(),'is_have_middle_nav'=>0,'view_num'=>5);
        $res['is_have_pop_and_m']=0;
        $res['shop_goods_seckill']=array();
        $yuanJino2oCustomized=D('Config_customization')->getYuanJino2oCustomized();
        if($yuanJino2oCustomized){
            $res['is_have_pop_and_m']=1;
            $middle_nav = D('House_village_nav')->get_village_nav($village_id,$village_modules,$this->_uid,2,$now_village);
            $res['middle_nav']['is_have_middle_nav'] = 1;
            $res['middle_nav']['list'] = $middle_nav;
            if ($village_info['template_top'] == 5) {
                $res['search_url'] = $this->config['site_url'] . $base_url . 'pages/index/search';
