					$activityTime = '';
					if ($sessionCount == 1 && !empty($activity['session_start_time']) && !empty($activity['session_end_time'])) {
						$sessionStartTime = strtotime($activity['session_start_time']);
						$sessionEndTime = strtotime($activity['session_end_time']);
						if (date('Y-m-d', $sessionStartTime) == date('Y-m-d', $sessionEndTime)) {
							$activityTime = date('Y-m-d H:i', $sessionStartTime) . ' - ' . date('H:i', $sessionEndTime);
						}
					}
					$socialActivity[] = [
						'id' => $activity['activity_id'],
						'activity_id' => $activity['activity_id'],
						'name' => $activity['activity_name'],
						'activity_name' => $activity['activity_name'],
						'image' => replace_file_domain($activity['position_poster']),
						'poster' => replace_file_domain($activity['position_poster']),
						'start_time' => $activity['start_time'],
						'end_time' => $activity['end_time'],
						'activity_time' => $activityTime,
						'url' => C('config.site_url') . '/packapp/plat/pages/socialActivity/detail?id=' . $activity['activity_id'],
					];
				}
			}
	    }
	    $res['social_activity_list'] = $socialActivity;
        $this->returnCode(0, $res);
    }
    
