            $tips = '';
            if ($hotwords && is_array($hotwords)) {
                $total = count($hotwords);
                $randArr = array();
                if ($total > 1) {
                    $kkArr = array_rand($hotwords, 2);
                    $randArr[] = $hotwords[$kkArr[0]];
                    $randArr[] = $hotwords[$kkArr[1]];
                } else {
                    $randArr = $hotwords;
                }
                foreach ($randArr as $vv) {
                    $tips .= !empty($tips) ? '，“' . $vv['wordname'].'”' : '“'.$vv['wordname'].'”';
                }
            }
            $retArr['tips'] = $tips;
        }
        return $retArr;
    }

