    public function get_forum_post(){
        if(IS_POST){
            if(abs(intval($this->config['forum_is_custom'])) != 1){
                $this->returnCode(0, []);
            }
            $id = I('classify_id');
            if (empty($id)) {
                $id=0;
            }
            $start=0;
            $limit=abs(intval($this->config['forum_number']));
            if($limit <= 0 ){
                $limit=9999;
            }
            $rel=D('Discuz_api')->getForumPost($this->config['site_url'],$id,$start,$limit);
            $this->returnCode(0, $rel);
