    public function search_village()
    {
        $village_id = I('village_id');
        $wxapp_own_village_id = I('wxapp_own_village_id',0);
        if (empty($village_id)) {
            $this->returnCode('20090005');
        }
        $arr = [];
        $where['village_id'] = $village_id;
        if($wxapp_own_village_id)
            $where['property_id'] = $wxapp_own_village_id;
        $village_info = M('House_village')->where($where)->find();
        if ($village_info) {
            $arr['village_name'] = empty($village_info['village_name']) ? '' : $village_info['village_name'];
            $arr['seal_img_new'] = !empty($village_info['seal_img_new']) ? replace_file_domain($village_info['seal_img_new']) : '';
            if ($village_info['village_logo']) {
                $arr['village_logo'] = replace_file_domain($village_info['village_logo']);
            } elseif ($this->config['wechat_share_img']) {
                $arr['wechat_share_img'] = replace_file_domain($this->config['wechat_share_img']);
            } else {
                $arr['village_logo'] = '';
                $arr['wechat_share_img'] = '';
            }
        }
        $this->returnCode(0, $arr);
    }

    //看过通知后提示=>时间记录
    public function exit_adver()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('20090005');
        }
        $pigcms_id = I('pigcms_id');
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $where['uid'] = $this->_uid;
        $where['village_id'] = $village_id;
        $where['vacancy_id'] = $pigcms_id;
        $House_village_user_bindModel = D('House_village_user_bind');
        $res = $House_village_user_bindModel->where($where)->data(array('login_time' => time()))->save();
        $this->returnCode(0, $res);
    }

    //小区列表
    public function village_list()
    {
        $user_long = I('user_long');
        $user_lat = I('user_lat');
        if ($user_long && $user_lat && !(floatval($user_long)==0 && floatval($user_lat)==0)) {
            $long_lat = array(
                'long' => I('user_long'),
                'lat' => I('user_lat'),
            );
        }
        $return = array();

        $db_house_village = D('House_village');
        $app_version = intval($_POST['app_version']);
        $deviceId = trim($_POST['Device-Id']);
        $param = [
            'pageName' => 'selectRooms',
            'isAll' => true
        ];
        $is_redirect = $db_house_village->villagePagePath($app_version,$deviceId,$param);
        //找到用户已绑定的小区
        $property_id = I('property_id', '0', 'intval');
        $wxapp_own_village_id = I('wxapp_own_village_id',0);

        if (!$wxapp_own_village_id && isset($_POST['app_package_name']) && trim($_POST['app_package_name'])=='com.yhszkj.xhgj') {
            $wxapp_own_village_id = 20;
        }
        if($wxapp_own_village_id)
            $property_id = $wxapp_own_village_id;

        $return['bind_village_list'] = [];
        if ($this->_uid && I('page') < 2 && empty(I('keyword'))) {
            $database_house_village_user_bind = D('House_village_user_bind');
            $where['uid'] = $this->_uid;
            $where['status'] = ['not in', [3,4]];
            $parent_id_arr = $database_house_village_user_bind->where($where)->getField('pigcms_id');
            if ($this->config['is_demo_domain'] && empty($parent_id_arr)) {
                $bind_village_list = D('House_village')->get_bind_list($this->_uid, '', false, $long_lat, false, $property_id);
            } else {
                $bind_village_list = D('House_village')->get_bind_list($this->_uid, '', true, $long_lat, false, $property_id);
            }
            $now_user = D('User')->get_user($this->_uid);
            $village_ids = array();
            //判断得到用户位置
            if ($bind_village_list) {
                $rangeSort = array();
                foreach ($bind_village_list as &$village_value) {
                    if ($long_lat) {
                        $village_value['range_int'] = getDistance($village_value['lat'], $village_value['long'], $long_lat['lat'], $long_lat['long']);
                        $village_value['range'] = getRange($village_value['range_int']);
                        $rangeSort[] = $village_value['range_int'];

                    }
                    $village_ids[] = $village_value['village_id'];
                }
                $rangeSort && array_multisort($rangeSort, SORT_ASC, $bind_village_list);
            }

            $return['bind_village_list'] = $bind_village_list;
        }
        if (empty($this->_uid) && I('page') < 2 && empty(I('keyword')) && $this->config['is_demo_domain']) {
            $return['login_test'] = true;
        }
        if(empty(I('keyword'))) {
            //自动绑定一次
            if ($this->_uid) {
                $now_user = D('User')->get_user($this->_uid);
                if ($now_user['phone']) {
                    D('House_village_user_bind')->bind($now_user['uid'], $now_user['phone']);
                }
            }

            //绑定家属小区
            $database_house_village_user_bind = D('House_village_user_bind');
            $database_house_village = D('House_village');
            $where['phone'] = $now_user['phone'];
            $where['parent_id'] = array('neq', 0);
            $where['status'] = array('eq', 1);
            $parent_id_arr = $database_house_village_user_bind->where($where)->getField('pigcms_id,parent_id');

            if (!empty($parent_id_arr)) {
                $Map['pigcms_id'] = array('in', $parent_id_arr);
                $Map['hv.status'] = 1;
                $bind_family_list = $database_house_village->get_bind_family_list($Map, $long_lat, $property_id);

                foreach ($bind_family_list as $v) {
                    if (!in_array($v['village_id'], $village_ids)) {
                        $return['bind_village_list'][] = $v;
                    }
                }
            }
        }
        $database_house_village_config = D('House_village_config');
        $aHouseVillageList = D('House_village')->wap_get_list_new($long_lat, I('keyword'), I('account'), I('page'), $property_id);
        if ($aHouseVillageList) {
            foreach ($aHouseVillageList['village_list'] as $k => $v) {
                //去掉 禁止的小区
                if($v['status'] == 2)
                {
                    unset($aHouseVillageList['village_list'][$k]);
                }
           /*     $village_config = $database_house_village_config->field('village_id,village_sort')->where(array('village_id'=>$v['village_id']))->find();*/
                $return['village_list'][$k]['village_sort']=$v['village_sort'];
                $return['village_list'][$k]['village_id'] = $v['village_id'];
                $return['village_list'][$k]['village_name'] = $v['village_name'];
                $return['village_list'][$k]['village_address'] = $v['village_address'];
                $return['village_list'][$k]['range'] = $v['range'];
                $return['village_list'][$k]['village_logo'] = $v['village_logo'];
                $return['village_list'][$k]['seal_img_new'] = !empty($v['seal_img_new']) ? $v['seal_img_new'] : '';
                /*
                $header_id = $v['header_id'] ? $v['header_id'] : $this->config['house_village_group_headerId'];
                $exist = M('Village_group_header')->where(array('id' => $header_id))->find();
                $header_id = $exist ? $header_id : 0;
                */

                $property_phone = explode(' ', $v['property_phone']);
                $return['village_list'][$k]['property_phone'] = $property_phone[0];
                $return['village_list'][$k]['isverify'] = $v['isverify'];
                $return['village_list'][$k]['property_name'] = $v['property_name'];
                $return['village_list'][$k]['is_redirect'] = $is_redirect . "?village_id={$v['village_id']}";
                $return['village_list'][$k]['tourist'] = $v['tourist'];
            }
          /*  array_multisort(array_column($return['village_list'],'village_sort'),SORT_DESC,$return['village_list']);
           */
            $return['totalPage'] = $aHouseVillageList['totalPage'];
            $return['village_count'] = $aHouseVillageList['village_count'];
        } else {
            $return['village_list'] = array();
            $return['totalPage'] = 0;
            $return['village_count'] = 0;
        }
        if (empty($return['village_list'])) {
            $return['village_list'] = [];
        }
        $return['open_house_logo_show'] = intval(C('config.open_house_logo_show'));

        //如果是物业跳转过来的页面
        $referer_url_msg = $this->referer_url_msg; // 旧页面归属
        $referer_new_url = $this->refererNewUrl(); // 新页面归属
        $referer_type = I('referer_type', '', 'trim');
        if ($referer_url_msg && $referer_url_msg[$referer_type]) {
            $referer_url = $this->config['site_url'] . $referer_url_msg[$referer_type];
        } elseif ($referer_url_msg && $referer_new_url[$referer_type]) {
            $base_url = D('House_village')->base_url;
            $referer_url = $base_url . $referer_new_url[$referer_type];
            $referer_url = $this->config['site_url'] . $referer_url;
            if ('village_my_utilities_lists' == $referer_type) {
                $referer_url .= '&title=' . urlencode('水电煤上报');
            } elseif ('village_my_suggest_list' == $referer_type) {
                $referer_url .= '&title=' . urlencode('投诉建议');
            } elseif ('village_my_repair_lists' == $referer_type) {
                $referer_url .= '&title=' . urlencode('物业报修');
            } elseif ('village_my_utilities' == $referer_type) {
                $referer_url .= '&title=' . urlencode('水电煤上报');
            } elseif ('village_my_suggest' == $referer_type) {
                $referer_url .= '&title=' . urlencode('投诉建议');
            } elseif ('village_my_repair' == $referer_type) {
                $referer_url .= '&title=' . urlencode('物业报修');
            }
        } else {
            $referer_url = '';
        }
        $return['referer_url'] = $referer_url;
        $return['house_name']='小区';
        $house_name=$this->config['house_name'];
        $house_name=trim($house_name);
        if($house_name){
            $return['house_name']=$house_name;
        }
        $this->returnCode(0, $return);
    }

    //房间列表
    public function village_list_old()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20044013');
        }
        $village_id = I('village_id');
        $wxapp_own_village_id = I('wxapp_own_village_id',0);
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        // 查询下客户登录最后一次进入的小区 如果记录不一致  新加记录
        $user_last_village_id = M('House_village_select_log')->where(['uid'=>$this->_uid])->order('id DESC')->getField('village_id,id');
        if ($user_last_village_id['village_id']!=$village_id) {
           $log_id= M('House_village_select_log')->data(['uid'=>$this->_uid,'village_id'=>$village_id,'add_time'=>time()])->add();
            $where_log=array('id'=>$log_id);
        }else{
            $where_log=array('id'=>$user_last_village_id['id']);
        }
        $this->get_village($village_id);
        $House_village = D('House_village_user_bind');
        $village_list = $House_village->get_user_bind_list($this->_uid, $village_id);
        $arr = array();
        if ($village_list) {
            M('House_village_select_log')->where($where_log)->data(array('type'=>1))->save();
            foreach ($village_list as $k => $v) {
                $arr[$k] = array(
                    'pigcms_id' => $v['pigcms_id'],
                    'address' => $v['type'] == 4 ? '物业工作人员' : $v['address'],
                    'usernum' => $v['usernum'],
                    'parent_id' => $v['parent_id'],
                );
            }
        } else {
            $village_list = $House_village->get_family_user_bind_list($this->_uid, $village_id);
            foreach ($village_list as $k => $v) {
                $arr[$k] = array(
                    'pigcms_id' => $v['pigcms_id'],
                    'address' => $v['type'] == 4 ? '物业工作人员' : $v['address'],
                    'usernum' => $v['usernum'],
                    'parent_id' => $v['parent_id']
                );
            }
        }
        $this->returnCode(0, $arr);
    }

    //便民工具
    public function convenient_list()
    {
        $village_id = I('village_id');
        $wxapp_own_village_id = I('wxapp_own_village_id',0);
        $now_village = $this->get_village($village_id);
        $res = [];
        $res['cat_list'] = D('House_service_category')->getAllCatListApiNew($now_village['village_id']);

        if (!$res['cat_list']) {
//            $this->house_service_test($village_id);
            $this->house_service_test_new($village_id);
            $res['cat_list'] = D('House_service_category')->getAllCatListApiNew($now_village['village_id']);

        }


        //是否展示提供技术支持
        if($this->config['is_demo_domain']){
            $where['village_id'] = $village_id;
            if($wxapp_own_village_id)
                $where['wxapp_own_village_id'] = $wxapp_own_village_id;
            $now_village = D('House_village')->where($where)->find();
            if($now_village){
                $property = M('house_property')->where(array('id'=>$now_village['property_id']))->find();
                if($property['is_config_show'] == 1){
                    $res['footer_link'] = array(
                        'image_path' => $this->config['site_url'].'/static/images/house/fastwhale-logo.png',
                        'url' => $this->config['site_url'].'/static/pigcms_company/fastwhale/index.html',
                        'content'=>'快鲸智慧社区提供技术支持',
                        'title'=>'快鲸智慧社区',
                        'site_icp'=>C('config.site_icp'),
                        'site_icp_url'=>'https://beian.miit.gov.cn/'
                    );

                }else{
                    $res['footer_link'] = (object)[];
                }
            }else{
                $res['footer_link'] = (object)[];
            }
        }else{
            $res['footer_link'] = (object)[];
        }
        $this->returnCode(0, $res);
    }

    // 社区电话
    public function house_phone()
    {
        $village_id = I('village_id');
        $pigcms_id = I('pigcms_id');
        $wxapp_own_village_id = I('wxapp_own_village_id',0);
        $now_village = $this->get_village($village_id);
        $phone_list = D('House_village_phone_category')->getAllCatPhoneList($now_village['village_id']);
        $res = array();
        if ($now_village['property_phone']) {
            $now_village['property_phone'] = explode(' ', $now_village['property_phone']);
        }
        $res['now_village'] = $now_village;
        if (empty($phone_list)) {
            $phone_list = array();
        }
        $application_arr = D('Application_list')->get_application_all_auth($village_id);
        // 获取客服联系路径
        $customer_info = M('Merchant_store_kefu_customer')->where(['uid'=>$pigcms_id])->find();
        if($customer_info){
            $kf = M('Merchant_store_kefu')->where(array('id' => $customer_info['kefu_id']))->find();
        }else{
            $user_bind_info = M('House_village_user_bind')->where(['pigcms_id'=>$pigcms_id])->field('single_id')->find();
            if($user_bind_info['single_id']){
                $house_keeper_info = M('House_services_housekeeper')->where(['single_id'=>$user_bind_info['single_id']])->find();
                if($house_keeper_info['work_arr']){
                    $con['bind_uid'] = array('in',$house_keeper_info['work_arr']);
                    $kf = M('Merchant_store_kefu')->where($con)->find();
                    if(empty($kf)){
                        $kf = M('Merchant_store_kefu')->where(array('belong' => 'village', 'store_id' => $village_id))->find();
                    }
                }else{
                    $kf = M('Merchant_store_kefu')->where(array('belong' => 'village', 'store_id' => $village_id))->find();
                }
            }else{
                $kf = M('Merchant_store_kefu')->where(array('belong' => 'village', 'store_id' => $village_id))->find();
            }
        }
        if(in_array(1,$application_arr)){
            if ($village_id && $now_village['has_kefu'] == 1 && $kf && $pigcms_id) {
                $kfUrl = build_im_chat_url('villageBind_' . $pigcms_id, $kf['username'], 'villageBind2village');
                $res['kf_url'] = $kfUrl;
                $res['kf_img'] = $this->config['site_url'] . '/static/images/house/kefu.png?t=02';
                $count = count($phone_list);
                $phone_list[$count]['cat_id'] = 0;
                $phone_list[$count]['cat_name'] = '联系物业';
                $phone_list[$count]['phone_list'][0]['name'] = '在线客服';
                $phone_list[$count]['phone_list'][0]['url'] = $kfUrl;
                $phone_list[$count]['phone_list'][0]['phone'] = '';
                $phone_list[$count]['phone_list'][0]['type'] = 1;
            }
        }
        $res['phone_list'] = array_values($phone_list);
        $this->returnCode(0, $res);

    }



    //我的页面
    public function village_my()
    {

        $village_id = I('village_id');
        $wxapp_own_village_id = I('wxapp_own_village_id',0);
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_type = I('pigcms_type', 1);
        $pigcms_id = I('pigcms_id',0);
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $application_arr = D('Application_list')->get_application_all_auth($village_id);
        $now_village = $this->get_village($village_id);
        if ($this->is_weixin_browser) {
            $rtn = D('Weixin_bind')->is_property_weixin($now_village['property_id'],$this->_uid);
            if($rtn['error'] == 1001){
                $res['redirect_uri'] = $this->config['site_url'].$rtn['redirect_uri'];
            }else{
                $res['redirect_uri'] = '';
            }
        } else {
            $res['redirect_uri'] = '';
        }
        $now_user_info = $this->get_user_village_info($pigcms_id, $village_id, $this->_uid, true);
        if($now_village['set_id_code'] == 1){
            if(empty($now_user_info['id_card'])){
//                $res['set_id_code'] = true;
//                $res['set_id_code_info'] = '您的身份证信息未完善，请前去完善';
            }else{
                $res['set_id_code'] = false;
                $res['set_id_code_info'] = '';
            }
        }else{
            $res['set_id_code'] = false;
            $res['set_id_code_info'] = '';
        }
        if($wxapp_own_village_id)
            $res['not_show_wallet'] = true;
        else
            $res['not_show_wallet'] = false;
        $now_user = D('User')->get_user($this->_uid);
        $res['user'] = array(
            'name' => $now_user_info['name'],
            'usernum' => $now_user_info['usernum'],
            'address' => $now_user_info['type'] == 4 ? '物业工作人员' : $now_user_info['address'],
            'type' => $now_user_info['type'],
            'memo' => $now_user_info['memo'],
            'avatar' => $now_user['avatar'],
            'url' => $this->config['site_url'] . U('Wap/My/myinfo'),
            'money' => empty($now_user['now_money']) ? 0 : $now_user['now_money'], // 金额
            'score' => empty($now_user['score_count']) ? 0 : $now_user['score_count'], // 积分
            'level' => empty($now_user['level']) ? 0 : $now_user['level'], // 等级
            'my_money_url' => $this->config['site_url'] . '/wap.php?g=Wap&c=My&a=my_money', // 我的钱包链接
            'img' => $this->config['site_url'] . '/tpl/Wap/pure/static/images/money.png'
        );
        if (empty($now_user['avatar'])) {
            $res['user']['avatar'] = $this->config['site_url'] . '/tpl/Wap/pure/static/images/pic-default.png';
        }
        if (empty($res['user'])) {
            $res['user'] = array();
        } else {
            if ($pigcms_type == 1) {
                $res['user']['url'] = str_replace('appapi.php', 'wap.php', $res['user']['url']);
            } else if ($pigcms_type == 2) {
                $res['user']['url'] = str_replace('appapi.php', 'wap_house.php', $res['user']['url']);
            }
        }


        //我的钱包下面子项全都使用数组返回 start
        //余额
        if($this->config['open_user_money'] || getFormatNumber($now_user['now_money'])){
            $res['user_link_arr'][0]['value']  = $this->_uid ? sprintf('%.2f',$now_user['now_money']) : '--';
            $res['user_link_arr'][0]['name']  = L_('余额');
            $res['user_link_arr'][0]['url']  = $this->config['site_url'].'/wap.php?g=Wap&c=My&a=my_money';
        }

        //积分
        $res['user_link_arr'][1]['value']  =  $this->_uid ? getFormatNumber($now_user['score_count']) : '--';
        $res['user_link_arr'][1]['name']  = $this->config['score_name'];
        $res['user_link_arr'][1]['url']  = $this->config['site_url'].'/wap.php?g=Wap&c=My&a=integral';

        //等级
