        $now_user['lname'] = $this->_uid ? ($now_user['level'] ? $level[$now_user['level']] : 'VIP0') : '--';
        $res['user_link_arr'][2]['value']  = $this->_uid && $now_user['lname'] ? $now_user['lname'] : '--';
        $res['user_link_arr'][2]['name']  = L_('等级');
