        //物业小程序不展示积分商城
        if(!$wxapp_own_village_id){
            $menus_center_list[] = array(
                'title'=>$this->config['score_name'].'商城',
                'url'=>$this->config['site_url'].'/wap.php?g=Wap&c=Gift&a=index&village_id='.$now_village['village_id'] . '&pigcms_id='.$_POST['pigcms_id'],
                'icon' => $this->config['site_url'].'/static/images/house/my_gift_index.png?t=01'
            );
        }
        $menus_center_list[] = array(
            'title' => '我的订单',
            'url' => $this->config['site_url'] . $base_url .'pages/my/my_order?state=0',
            'icon' => $this->config['site_url'] . '/static/images/house/my_order.png?t=01'
        );
        $list[3] = $menus_center_list;
        $last = array();
        // 获取客服联系路径
        if ($worker_info) {
            $kf = M('Merchant_store_kefu')->where(array('belong' => 'village', 'store_id' => $village_id, 'bind_uid' => $worker_info['wid']))->find();
            $pigcms_id = $_POST['pigcms_id'];
            if ($village_id && $now_village['has_kefu']==1 && $kf && $pigcms_id) {
                //$kfUrl = build_store_im_conversation_url($kf['username'], 'village2villageBind');
                $kfUrl = build_im_chat_url('villageBind_' . $pigcms_id, $kf['username'], 'villageBind2village');
