                    'title'=>'我是客服',
                    'url'=>$kfUrl,
                    'icon' => $this->config['site_url'].'/static/images/house/my_kefu.png?t=01'
                );
            }
            $is_arr = [14,20];
            //套餐相关购买套餐有次功能，方可使用
            if(in_array('14',$content_id) || in_array('20',$content_id)) {
                $last[] = array(
                    'title' => '任务列表',
                    'url' => $this->config['site_url'] . $base_url . 'pages/village/mobileMeterReading/workList',
                    'icon' => $this->config['site_url'] . '/static/images/house/qrcode.png?t=01'
                );
            }
        }
        if(4 == $now_user_info['type']){
            $last[] = [
                'title' => '推广二维码',
                'url' => $this->config['site_url'] . $base_url . 'pages/village/my_pages/invitationCode',
                'icon' => $this->config['site_url'] . '/static/images/house/erweima.png?t=01'
            ];
        }

        $last[] = array(
            'title'=>'物业电话',
            'url'=>$this->config['site_url'].$base_url.'pages/village/commonly_used/house_phone?village_id='.$now_village['village_id'] . '&pigcms_id='.$_POST['pigcms_id'],
            'icon' => $this->config['site_url'].'/static/images/house/my_house_phone.png?t=01'
        );

        $list[4] = $last;
        $res['list'] = $list;
        $res['my_wallet_icon'] = $this->config['site_url'].'/static/images/house/my_wallet.png?t=01';


        //是否展示提供技术支持

        $now_village = D('House_village')->where(array('village_id'=>$village_id))->find();
        if($now_village){
            $property = M('house_property')->where(array('id'=>$now_village['property_id']))->find();
            if($property['is_config_show'] == 1){
                $res['footer_link'] = array(
                    'image_path' => $this->config['site_url'].'/static/images/house/fastwhale-logo.png',
                    'url' => $this->config['site_url'].'/static/pigcms_company/fastwhale/index.html',
                    'content'=>'快鲸智慧社区提供技术支持',
                    'title'=>'快鲸智慧社区',
                    'site_icp'=>C('config.site_icp'),
                    'site_icp_url'=>'https://beian.miit.gov.cn/'
                );

            }else{
                $res['footer_link'] = (object)[];
            }
        }else{
            $res['footer_link'] = (object)[];

        }
        $this->returnCode(0,$res);


    }


    //	查询是否绑定了当前小区
    protected function get_user_village_info($bind_id,$village_id,$uid, $is_my=false){
        $now_user_info = D('House_village_user_bind')->get_one_by_bindId($bind_id);
        if(empty($now_user_info)){
            if ($is_my) {
                $this->returnCode('20120002');
            } else {
                $this->returnCode('20120004');
            }
        }
        $database_house_village_user_bind = D('House_village_user_bind');
        $where['parent_id|pigcms_id'] = $bind_id;
        $where['uid'] = $uid;
        $where['village_id'] = $village_id;
        $house_village_user_bind_count = $database_house_village_user_bind->where($where)->count();
        if(!$house_village_user_bind_count){
            if ($is_my) {
                $this->returnCode('20120002');
            } else {
                $this->returnCode('20120004');
            }
        }
        return $now_user_info;
    }

