    public function bbs_list_new(){
        $village_id = I('village_id',0);
        $wxapp_own_village_id = I('wxapp_own_village_id',0);
        $village_type = I('village_type','house');
        $aBbs	=	D('Bbs')->isVillage($village_id,$village_type);

        $aPage	=	I('page',1);

        $arr = [];
        $newBbsAricleList	=	M('Bbs_aricle')->order('aricle_sort desc,update_time desc')->page($aPage,10)->where(array('bbs_id'=>$aBbs['bbs_id'],'aricle_status'=>1))->select();
        $dataList = [];
        if($newBbsAricleList){
            // 预览需要的大图
            $preview_width = 900;
            $preview_height = 900;
            foreach($newBbsAricleList as $k=>&$v){
                //	查找发布文章的用户
                $user = D('User')->field(array('uid','nickname','last_time','avatar'))->where(array('uid'=>$v['uid']))->find();
                if($user['avatar']){
                    $user['avatar'] = replace_file_domain($user['avatar']);
                }else{
                    $user['avatar'] = C('config.site_url') . '/static/images/user_avatar.jpg';
                }

                //	查找文章所属分类
                $cate	=	D('Bbs_category')->field(array('cat_id','cat_name'))->where(array('cat_id'=>$v['cat_id']))->find();

                $aricle_img = explode(';',$v['aricle_img']);
                $tmp_aricle_img = array();
                $previewimage = array();
                $img_num = count($aricle_img);
                if (!$img_num) {
                    $img_num = 0;
                }
                if ($img_num <= 1) {
                    $fill = '';
                    $width = 1000;
                    $height = 1000;
                } else {
                    $fill = 'fill';
                    $width = 400;
                    $height = 400;
                }
                foreach($aricle_img as $img){
                    if(!empty($img)){
                        $tmp_aricle_img[] = thumb_img($img, $width, $height, $fill);
                        $previewimage[] = thumb_img($img, $preview_width, $preview_height);
                    }
                }
                $aricle_img	=	$tmp_aricle_img;
                if($v['address']){
                    if(strpos($v['address'], 'a:') !== false && strpos($v['address'], ':{s:') !== false){
                        //老数据
                        $address	=	unserialize(html_entity_decode($v['address']));//兼容之前的数据
                        $address = $address['street'] . $address['street_number'];
                    }else{
                        //新数据
                        $address	=	$v['address'];
                    }
                }else{
                    $address = "";
                }
                M('Bbs_aricle')->where(array('aricle_id'=>$v['aricle_id']))->setInc('browse_num');
                if($this->_uid){
                    $mezan_num = D('Bbs_praise')->where(array('aricle_id'=>$v['aricle_id'],'uid'=>$this->_uid))->count();
                    $comment_num = D('Bbs_comment')->where(array('aricle_id'=>$v['aricle_id'],'uid'=>$this->_uid))->count();
                    if($mezan_num > 0){
                        $mezan = 1;//已赞
                    }else{
                        $mezan = 0;//未赞
                    }
                    if($comment_num > 0){
                        $comment_num = 1;//已评论
                    }else{
                        $comment_num = 0;//未评论
                    }
                }else{
                    $mezan = 0;//未赞
                    $comment_num = 0;//未评论
                }

                $list = array(
                    'aricle_id'=>$v['aricle_id'],
                    'user'=>$user,
                    'cate'=>$cate,
                    'aricle_title' => $v['aricle_title'],
                    'aricle_img' =>$aricle_img,
                    'previewimage' =>$previewimage,
                    'address'=>$address,
                    'browse_num'=>$v['browse_num'],
                    'aricle_praise_num'=>$v['aricle_praise_num'],
                    'create_time'=>date('m-d H:s',$v['create_time']),
                    'update_time'=>date('m-d H:s',$v['update_time']),
                    'mezan'=>$mezan,
                    'comment_num'=>$comment_num,
                    'img_num'=>$img_num,
                );
                $dataList[] = $list;

            }
            foreach($dataList as $k1=>&$v1){
                $aZanList	=	D('Bbs')->bbsAricleGetZan($v1['aricle_id'],1,8);
                if($aZanList){
                    foreach($aZanList as $k2=>&$v2){
                        if($v2['create_time']){
                            unset($v2['create_time']);
                        }
                        if($v2['uid']['last_time']){
                            unset($v2['uid']['last_time']);
                        }
                        if($v2['uid']['avatar']){
                            $v2['uid']['avatar'] = replace_file_domain($v2['uid']['avatar']);
                        }else{
                            $v2['uid']['avatar'] = C('config.site_url') . '/static/images/user_avatar.jpg';
                        }
                        $v1['aZanList'][] = $v2;
                    }
                }else{
                    $v1['aZanList'] = [];
                }
                //评论列表
                $aComment	=	D('Bbs')->bbsAricleCommentNew($v1['aricle_id'],1,3);
                $where = array('aricle_id'=>$v1['aricle_id'],'comment_status'=>1);
                $comment_sum = M('Bbs_comment')->where($where)->count();
                if($comment_sum > 3){
                    $v1['comment_sum'] = 1;
                }else{
                    $v1['comment_sum'] = 0;
                }
                $d_user = D('User');
                if($aComment){
                    foreach($aComment as $kkk=>&$vvv){

                        $vvv['create_time'] = date('m-d H:s',$vvv['create_time']);
                        if ($vvv['comment_fid']>0) {
                            $comment = M('Bbs_comment')->where(array('comment_id'=>$vvv['comment_fid']))->find();
                            $nickname = $d_user->where(array('uid'=>$comment['uid']))->getField('nickname');
                            if (!$nickname) {
                                $nickname = '';
                            }
                            $vvv['comment_fid_nickname'] = $nickname;
                        }
                        if(empty($vvv['uid']['avatar'])){
                            $vvv['uid']['avatar']	=	$this->config['site_url'].$this->urlTot;
                        } else {
                            $vvv['uid']['avatar']	= replace_file_domain($vvv['uid']['avatar']);
                        }
                    }
                    $v1['aComment'] = $aComment;
                }else{
                    $v1['aComment'] = [];
                }
            }
        }
        $arr['dataList'] = $dataList;
        $bind_info = $this->check_village_session($village_id, I('pigcms_id'));
        $meComent_num = 0;
        $meZan_num = 0;
        if($bind_info){
            $where['_string'] = " create_time >".$bind_info['message_time']." AND uid !=".$this->_uid;
            if($this->_uid){

                $village_type = I('village_type','house');
                $aBbs	=	D('Bbs')->isVillage($village_id,$village_type);
                $aBbsAricle	=	M('Bbs_aricle')->where(array('uid'=>$this->_uid,'aricle_status'=>1,'bbs_id'=>$aBbs['bbs_id']))->select();
                if($aBbsAricle){
                    $aricle = [];
                    foreach($aBbsAricle as $k=>$value){
                        $aricle[] = $value['aricle_id'];
                    }
                    $where['aricle_id'] = array('in',$aricle);
                    $mezan_num = D('Bbs_praise')->where($where)->count();

                    if($mezan_num > 0){
                        $meZan_num = $mezan_num;
                    }else{
                        $meZan_num = 0;
                    }
                    $comment_num = D('Bbs_comment')->where($where)->count();
                    if($comment_num > 0){
                        $meComent_num =  $comment_num;
                    }else{
                        $meComent_num =  0;
                    }

                    $user_praise = D('Bbs_praise')->where($where)->order('create_time desc')->limit(1)->find();
                    $user_comment = D('Bbs_comment')->where($where)->order('create_time desc')->limit(1)->find();

                    if($user_praise && $user_comment){
                        if(intval($user_praise['create_time']) > intval($user_comment['create_time'])){
                            $user = D('User')->field(array('avatar'))->where(array('uid'=>$user_praise['uid']))->find();
                            if($user['avatar']){
                                $user_message_avater['avatar'] = replace_file_domain($user['avatar']);
                            }else{
                                $user_message_avater['avatar'] = $this->config['site_url'].$this->urlTot;
                            }
                        }else{
                            $user = D('User')->field(array('avatar'))->where(array('uid'=>$user_comment['uid']))->find();
                            if($user['avatar']){
                                $user_message_avater['avatar'] = replace_file_domain($user['avatar']);
                            }else{
                                $user_message_avater['avatar'] = $this->config['site_url'].$this->urlTot;
                            }
                        }
                    }elseif($user_praise && empty($user_comment)){
                        $user = D('User')->field(array('avatar'))->where(array('uid'=>$user_praise['uid']))->find();
                        if($user['avatar']){
                            $user_message_avater['avatar'] = replace_file_domain($user['avatar']);
                        }else{
                            $user_message_avater['avatar'] = $this->config['site_url'].$this->urlTot;
                        }
                    }elseif(empty($user_praise) && $user_comment){
                        $user = D('User')->field(array('avatar'))->where(array('uid'=>$user_comment['uid']))->find();
                        if($user['avatar']){
                            $user_message_avater['avatar'] = replace_file_domain($user['avatar']);
                        }else{
                            $user_message_avater['avatar'] = $this->config['site_url'].$this->urlTot;
                        }
                    }else{
                        $user_message_avater['avatar'] = '';
                    }
                }
            }else{
                $meZan_num = 0;
                $meComent_num =  0;
            }
            $House_village_user_bindModel = D('House_village_user_bind');
            if($aPage >= 2){
                $House_village_user_bindModel->where(array('uid'=>$this->_uid,'pigcms_id'=>$bind_info['pigcms_id'],'village_id'=>$village_id))->data(array('message_time'=>time()))->save();
            }

        }

        $arr['totle'] =  $meComent_num+$meZan_num;
        $arr['user_message_avater'] =  $user_message_avater['avatar'];

        if($this->config['is_demo_domain']){
            $con['village_id'] = $village_id;
            if($wxapp_own_village_id)
                $con['property_id'] = $wxapp_own_village_id;
            $now_village = D('House_village')->where($con)->find();
            if($now_village){
                $property = M('house_property')->where(array('id'=>$now_village['property_id']))->find();
                if($property['is_config_show'] == 1){
                    $arr['footer_link'] = array(
                        'image_path' => $this->config['site_url'].'/static/images/house/fastwhale-logo.png',
                        'url' => $this->config['site_url'].'/static/pigcms_company/fastwhale/index.html',
                        'content'=>'快鲸智慧社区提供技术支持',
                        'title'=>'快鲸智慧社区',
                        'site_icp'=>C('config.site_icp'),
                        'site_icp_url'=>'https://beian.miit.gov.cn/'
                    );
                }else{
                    $arr['footer_link'] = (object)array();
                }
            }else{
                $arr['footer_link'] = (object)array();
            }
        }else{
            $arr['footer_link'] = (object)[];
        }
        $arr['title']='邻里';
        $this->returnCode(0,$arr);

    }
    public function get_bbs_cates(){
        $village_id = I('village_id',0,'intval');
        $village_type = I('village_type','house','trim');
        $bbsCates=array();
        $bbsCates['village_id']=$village_id;
        $bbsCates['dataList']=array();
        if($village_id>0){
            $aBbs	=	D('Bbs')->isVillage($village_id,$village_type);
            if($aBbs && isset($aBbs['bbs_id']) &&($aBbs['bbs_id']>0) ){
                $where=array();
                $where['bbs_id'] = $aBbs['bbs_id'];
                $where['cat_status'] =1;
                $listTmp =D('Bbs')->get_category_list($where,'cat_id,bbs_id,cat_name,cat_logo,cat_aricle_total,cat_aricle_num');
                if(!empty($listTmp)){
                    $linkcode=$this->config['site_url'].'/packapp/village/pages/village/resident/residentCategory?cat_id=';
                    $linkcode=str_replace('//packapp','/packapp',$linkcode);
                    foreach ($listTmp as $bkk=>$bvv){
                        $listTmp[$bkk]['url']=$linkcode.$bvv['cat_id'];
                    }
                    $bbsCates['dataList']=$listTmp;
                }
            }
        }
        $arr['title']='邻里';
        $this->returnCode(0,$bbsCates);
    }
    public function bbs_list_cate_new(){
        $village_id = I('village_id',0);
        $village_type = I('village_type','house');
        $aBbs	=	D('Bbs')->isVillage($village_id,$village_type);

        $aPage	=	I('page',1);

        $cat_id = I('cat_id');
        if(empty($cat_id)){
            $this->returnCode('30000006');
        }
        $arr = [];
        $newBbsAricleList	=	M('Bbs_aricle')->order('aricle_sort desc,update_time desc')->page($aPage,10)->where(array('bbs_id'=>$aBbs['bbs_id'],'aricle_status'=>1,'cat_id'=>$cat_id))->select();
        $dataList = [];
        if($newBbsAricleList){
            $preview_width = 900;
            $preview_height = 900;
            foreach($newBbsAricleList as $k=>&$v){
                //	查找发布文章的用户
                $user = D('User')->field(array('uid','nickname','last_time','avatar'))->where(array('uid'=>$v['uid']))->find();
                if($user['avatar']){
                    $user['avatar'] = replace_file_domain($user['avatar']);
                }else{
                    $user['avatar'] = $this->config['site_url'].$this->urlTot;
                }
                //	查找文章所属分类
                $cate	=	D('Bbs_category')->field(array('cat_id','cat_name'))->where(array('cat_id'=>$v['cat_id']))->find();

                $aricle_img = explode(';',$v['aricle_img']);
                $tmp_aricle_img = array();
                $previewimage = array();
                $img_num = count($aricle_img);
                if (!$img_num) {
                    $img_num = 0;
                }
                if ($img_num <= 1) {
                    $fill = '';
                    $width = 400;
                    $height = 400;
                } else {
                    $fill = 'fill';
                    $width = 200;
                    $height = 200;
                }
                foreach($aricle_img as $img){
                    if(!empty($img)){
                        $tmp_aricle_img[] = thumb_img($img, $width, $height, $fill);
                        $previewimage[] = thumb_img($img, $preview_width, $preview_height);
                    }
                }
                $aricle_img	=	$tmp_aricle_img;
                if($v['address']){
                    if(strpos($v['address'], 'a:') !== false && strpos($v['address'], ':{s:') !== false){
                        //老数据
                        $address	=	unserialize(html_entity_decode($v['address']));//兼容之前的数据
                    }else{
                        //新数据
                        $address	=	$v['address'];
                    }
                }else{
                    $address = "";
                }
                M('Bbs_aricle')->where(array('aricle_id'=>$v['aricle_id']))->setInc('browse_num');
                if($this->_uid){
                    $mezan_num = D('Bbs_praise')->where(array('aricle_id'=>$v['aricle_id'],'uid'=>$this->_uid))->count();
                    if($mezan_num > 0){
                        $mezan = 1;//已赞
                    }else{
                        $mezan = 0;//未赞
                    }
                }else{
                    $mezan = 0;//未赞
                }
                if($this->_uid){
                    $comment_num = D('Bbs_comment')->where(array('aricle_id'=>$v['aricle_id'],'uid'=>$this->_uid))->count();
                    if($comment_num > 0){
                        $comment_num = 1;//已评论
                    }else{
                        $comment_num = 0;//未评论
                    }
                }else{
                    $comment_num = 0;//未评论
                }

                $list = array(
                    'aricle_id'=>$v['aricle_id'],
                    'user'=>$user,
                    'cate'=>$cate,
                    'aricle_title' => $v['aricle_title'],
                    'aricle_img' =>$aricle_img,
                    'previewimage' =>$previewimage,
                    'address'=>$address,
                    'browse_num'=>$v['browse_num'],
                    'aricle_praise_num'=>$v['aricle_praise_num'],
                    'create_time'=>date('m-d H:s',$v['create_time']),
                    'update_time'=>date('m-d H:s',$v['update_time']),
                    'mezan'=>$mezan,
                    'comment_num'=>$comment_num,
                    'img_num' =>$img_num
                );
                $dataList[] = $list;

            }
            $d_user = D('User');
            foreach($dataList as $k1=>&$v1){
                $aZanList	=	D('Bbs')->bbsAricleGetZan($v1['aricle_id'],1,8);
                if($aZanList){
                    foreach($aZanList as $k2=>&$v2){
                        if($v2['create_time']){
                            unset($v2['create_time']);
                        }
                        if($v2['uid']['last_time']){
                            unset($v2['uid']['last_time']);
                        }
                        $v1['aZanList'][] = $v2;
                    }
                }else{
                    $v1['aZanList'] = [];
                }
                //评论列表
                $aComment	=	D('Bbs')->bbsAricleCommentNew($v1['aricle_id'],1,3);
                $where = array('aricle_id'=>$v1['aricle_id'],'comment_status'=>1);
                $comment_sum = M('Bbs_comment')->where($where)->count();
                if($comment_sum > 3){
                    $v1['comment_sum'] = 1;
                }else{
                    $v1['comment_sum'] = 0;
                }
                if($aComment){
                    foreach($aComment as &$vvv){
                        $vvv['create_time'] = date('m-d H:s',$vvv['create_time']);
                        if ($vvv['comment_fid']>0) {
                            $comment = M('Bbs_comment')->where(array('comment_id'=>$vvv['comment_fid']))->find();
                            $nickname = $d_user->where(array('uid'=>$comment['uid']))->getField('nickname');
                            if (!$nickname) {
                                $nickname = '';
                            }
                            $vvv['comment_fid_nickname'] = $nickname;
                        }
                        if(empty($vvv['uid']['avatar'])){
                            $vvv['uid']['avatar']	=	C('config.site_url') . '/static/images/user_avatar.jpg';
                        } else {
                            $vvv['uid']['avatar']	= replace_file_domain($vvv['uid']['avatar']);
                        }
                    }
                    $v1['aComment'] = $aComment;
                }else{
                    $v1['aComment'] = [];
                }
            }
        }
        $arr['dataList'] = $dataList;


        $arr['totle'] =  0;
        $category = M('Bbs_category')->where(array('cat_id'=>$cat_id))->find();
        $category['add_time'] = date('Y-m-d H:i',$category['add_time']);
        $category['last_time'] = date('Y-m-d H:i',$category['last_time']);
        $arr['category'] = $category;
        $this->returnCode(0,$arr);

    }

    public function see_list()
    {
        $arr = [];

        if(empty($this->_uid)){
            $this->returnCode('20000009');

        }
        $aBbsAricle	=	M('Bbs_aricle')->where(array('uid'=>$this->_uid,'aricle_status'=>1))->select();
        foreach($aBbsAricle as $k=>$value){
            $arice[] = $value['aricle_id'];
        }
        $where['a.uid'] = $this->_uid;

        $my_list = M('Bbs_aricle')->field('a.*,b.*,c.*')->join('AS a left join ' . C('DB_PREFIX') . 'bbs_praise b on a.aricle_id =b.aricle_id left join ' . C('DB_PREFIX') . 'bbs_comment c ON c.aricle_id =a.aricle_id')
            ->where($where)->order('b.create_time DESC,c.create_time DESC')->select();

        $arr['my_list'] = $my_list;
        $this->returnCode(0,$arr);
    }
    //	论坛文章详情接口
    public function web_bbs_aricele_details(){
        $arr = array();

        $village_id = I('village_id');
        $aricle_id	=	I('aricle_id',109);
        $page	=	I('page',1);
        $zanPageNumber	=	I('zanPageNumber',1);
        if(empty($aricle_id)){
            $this->returnCode('30000003');
        }
        M('Bbs_aricle')->where(array('aricle_id'=>$aricle_id))->setInc('browse_num');
        $cat_id		=	I('cat_id',0);
        if(empty($cat_id)){
            $cat_id	=	I('cat_id',0);
        }
        if(empty($cat_id)){
            $findCat_id	=	M('Bbs_aricle')->field('cat_id')->where(array('aricle_id'=>$aricle_id))->find();
            $cat_id	=	$findCat_id['cat_id'];
        }
        $cateName	=	M('Bbs_category')->field('cat_name')->where(array('cat_id'=>$cat_id))->find();

        $status		=	I('status',2);
        if($this->_uid){
            $mezan_num = D('Bbs_praise')->where(array('aricle_id'=>$aricle_id,'uid'=>$this->_uid))->count();
            if($mezan_num){
                if($mezan_num > 0){
                    $mezan = 1;//已赞
                }else{
                    $mezan = 0;//未赞
                }
            }else{
                $mezan = 0;//未赞
            }
        }



        $aDetails	=	D('Bbs')->bbsAricleDetailsNew($aricle_id);
        if($aDetails['uid']['uid'] == $this->_uid){
            $is_uid	=	1;
        }else{
            $is_uid	=	2;
        }
        if($aDetails && is_array($aDetails)){
            $aDteais	=	$this->bbsAricleFormatNew(array($aDetails));


            $aComment	=	D('Bbs')->bbsAricleComment($aricle_id,$page,9999);
            $d_user = D('User');
            if($aComment['status'] != 0){
                foreach($aComment['list'] as $k=>$v){
                    if(empty($v['uid']['avatar'])){
                        $aComment['list'][$k]['uid']['avatar']	=	C('config.site_url') . '/static/images/user_avatar.jpg';
                    } else {
                        $aComment['list'][$k]['uid']['avatar']	= replace_file_domain($aComment['list'][$k]['uid']['avatar']);
                    }

                    if ($v['comment_fid']>0) {
//                        $v['comment_id']
                        $comment = M('Bbs_comment')->where(array('comment_id'=>$v['comment_fid']))->find();
                        $nickname = $d_user->where(array('uid'=>$comment['uid']))->getField('nickname');
                        if (!$nickname) {
                            $nickname = '';
                        }
                        $aComment['list'][$k]['comment_fid_nickname'] = $nickname;
                    }
                    if($this->_uid){
                        if($v['uid']['uid']	==	$this->_uid){
                            $aComment['list'][$k]['uid']['status']	=	1;
                        }else{
                            $aComment['list'][$k]['uid']['status']	=	2;
                        }
                    }else{
                        $aComment['list'][$k]['uid']['status']	=	2;
                    }

                    $aComment['list'][$k]['create_time']	=	date('m-d H:i',$aComment['list'][$k]['create_time']);
                }
            }
        }

        $aZanList	=	D('Bbs')->bbsAricleGetZan($aricle_id,$zanPageNumber,9999);

        $tmp_aZanList = array();
        foreach($aZanList as $k=>$v){
            $tmp_aZanList[] = $v;
        }
        $aZanList = $tmp_aZanList;
        foreach($aZanList as $k=>$v){
            if($this->_uid){
                if($this->_uid == $v['uid']['uid']){
                    $exist	=	1;break;
                }else{
                    $exist	=	0;
                }
            }else{
                $exist	=	0;
            }

        }

        if($aDteais[0]['type']==1){
            $activity_apply_num = D('Bbs_activity_apply')->where(array('bbs_id'=>$aDteais[0]['aricle_id'],'is_del'=>0))->count();
            $aDteais[0]['activity_apply_num'] = $activity_apply_num;
        }

        if($this->_uid){
            $database_bbs_activity_apply = D('Bbs_activity_apply');
            $is_bbs_activity_apply = ($database_bbs_activity_apply->where(array('aricle_id'=>$_GET['aricle_id'],'uid'=>$this->_uid))->count()) ? true : false;
        }else{
            $is_bbs_activity_apply = false;
        }

        //评论数
        $aDteais[0]['aricle_comment_total'] = D('Bbs_comment')->where(array('aricle_id'=>$aricle_id,'comment_status'=>1))->count();

        $arr	=	array(
            'aricle_id' => $aricle_id,
            'mezan' => $mezan,
            'cat_id' => $cat_id,
            'status' => $aricle_id,
            'village_id' => $village_id,
            'index' => $cateName['cat_name'],
            'aDetails'	=>	$aDteais[0],
            'is_uid'	=>	$is_uid,
            'aComment'	=>	$aComment['list'],
            'aZanList'	=>	$aZanList,
            'exist'		=>	$exist,
            'img'		=>	$this->imgGet(),
            'page'		=>	$page,
            'is_bbs_activity_apply' => $is_bbs_activity_apply,
        );


        $this->returnCode(0,$arr);
    }

    //点赞
    public function web_bbs_aricele_zan(){

        $arr = [];
        $aricle_id	=	I('aricle_id',0);
