        if(empty($this->_uid)){
            $this->returnCode('20000009');
        }
        if(empty($aricle_id)){
            $this->returnCode('30000003');
        }

        if(empty($this->_uid)){
            $this->returnCode('30010010');
        }
        if($type == 1){
            $arr['sZan']	=	D('Bbs')->NewbbsAricleZan($aricle_id,$this->_uid);

        }else{
            $arr['sZan']	=	D('Bbs')->NewbbsAricleZanCancel($aricle_id,$this->_uid);
