    //获取邻里分类接口论坛
    public function bbs_cate_list()
    {
        $res = array();
        $village_id = I('village_id');
        $village_id=$village_id ? intval($village_id):0;
        $cat_id = I('cat_id');
        $cat_id = $cat_id ? intval($cat_id):0;
        $village_type = I('village_type','house');
        $aBbs=D('Bbs')->isVillage($village_id,$village_type);
        if($aBbs['status']){
            $this->returnCode('30000002');
        }
        if($aBbs['status'] == 0){
            $this->bbs_category_test($village_id);
        }
        $res['bbs_list']	=	D('Bbs')->indexType($aBbs['bbs_id'],$village_id,100,$cat_id);

        $db_house_village = D('House_village');
        $app_version = intval($_POST['app_version']);
        $deviceId = trim($_POST['Device-Id']);
        $param = [
            'pageName' => 'myPosts',
            'isAll' => true,
            'urlParam' => 'village_id='.$village_id,
        ];
        $myPostsUrl = $db_house_village->villagePagePath($app_version,$deviceId,$param);
        $res['my_posts_url']  = $myPostsUrl;
        $this->returnCode(0,$res);
