    //发布论坛
    public function web_bbs_aricele_wite(){
        $village_id = I('village_id');
        $wxapp_own_village_id = I('wxapp_own_village_id',0);
        $cat_id	=	I('cat_id');
        $village_type = I('village_type','house');
        $aBbs=D('Bbs')->isVillage($village_id,$village_type);
        $type = I('type',0);

        if(empty($this->_uid)){
            $this->returnCode('20000009');
        }
        $ban_info = M('Bbs_ban_list')->where(array('uid'=>$this->_uid,'village_id'=>$village_id))->find();
        if ($ban_info) {
            if ($ban_info['status']==1 && (($ban_info['type']==0&&($ban_info['time']+$ban_info['days']*86400)>time()) || $ban_info['type']==1)) {
                $this->returnCode('30010015');
            }
        }


        $aricle_title	=	I('aricle_title','');
        $aricle_content	=	I('aricle_content','');
        if(empty($cat_id)){
            $this->returnCode('30000006');
        }

        $aricle_content	=	str_replace("\n", "</p><p>",$aricle_content);
        $aricle_content	=	str_replace("&amp;amp;quot;", '"',$aricle_content);
        $aricle_title	=	str_replace("&amp;amp;quot;", '"',$aricle_title);
        $aricle_content	=	'<p>'.$aricle_content.'</p>';
        $inputimg	=	implode(';',I('inputimg',''));

        if($type == 0){
            $arr	=	array(
                'bbs_id'			=>	$this->aBbs['bbs_id'],
                'cat_id'			=>	$cat_id,
                'aricle_title'		=>	$aricle_title,
                'aricle_content'	=>	'',
                'uid'				=>	$this->_uid,
                'aricle_img'		=>	$inputimg,
                'aricle_status'		=>	$this->aBbs['auto_verify_post'],
                'create_time'		=>	time(),
                'update_time'		=>	time(),
                'exp_time'			=>	time(),
                'address'			=> I('address'),
                'type' 				=> 0
            );
        }else{
            $aricle_title	=	I('aricle_title_activity');


            $arr	=	array(
                'bbs_id'	=>	$this->aBbs['bbs_id'],
                'cat_id'	=>	$cat_id,
                'aricle_title'	=>	$aricle_title,
                'aricle_content'	=>	$aricle_content,
                'uid'			=>	$this->_uid,
                'aricle_img'		=>	$inputimg,
                'aricle_status'		=>	$this->aBbs['auto_verify_post'],
                'create_time'		=>	time(),
                'update_time'		=>	time(),
                'exp_time'			=>	time(),
                'address'			=> I('address'),
                'type' 				=> 1,
                'num'				=> $_POST['num'] + 0,
                'close_time'=>strtotime($_POST['activity_date'])
            );
        }

        $aAricleAdd	=	D('Bbs')->newBbsAricleWite($arr,explode(';',$inputimg));
        if(empty($aAricleAdd)){
            $this->returnCode('30020001');
        }else{
            M('Bbs_category')->where(array('cat_id'=>$cat_id))->setInc('cat_aricle_total');
            if($aBbs['auto_verify_post'] == 1){
                M('Bbs_category')->where(array('cat_id'=>$cat_id))->setInc('cat_aricle_num');
                $this->returnCodeOk(L_('文章发布成功'));
            }else{
                $con['village_id'] = $village_id;
                if($wxapp_own_village_id)
                    $con['property_id'] = $wxapp_own_village_id;
                M('House_village')->where($con)->setInc('bbs_aricle_reminder');
                $this->returnCodeOk(L_('文章发布成功'));
            }
        }

    }


    //邻里发布文章
    public function web_bbs_aricele_wite_new()
    {
        $village_id = I('village_id');
        $wxapp_own_village_id = I('wxapp_own_village_id',0);
        $cat_id	=	I('cat_id');
        $address	=	I('address','');

        if(empty($this->_uid)){
            $this->returnCode('20000009');
        }
        $village_type = I('village_type',0);
        if(empty($village_type)){
            $village_type = I('village_type','house');
        }
        $aBbs	=	D('Bbs')->isVillage($village_id,$village_type);
        if($aBbs['status']){
            $this->returnCode('30000002');
        }
        $ban_info = M('Bbs_ban_list')->where(array('uid'=>$this->_uid,'village_id'=>$village_id))->find();
        if ($ban_info) {
            if ($ban_info['status']==1 && (($ban_info['type']==0&&($ban_info['time']+$ban_info['days']*86400)>time()) || $ban_info['type']==1))           {
                $this->returnCode('30010015');
            }
        }
        $aricle_title	=	I('aricle_title','');
        if(empty($cat_id)){
            $this->returnCode('30000006');
        }
        if ($aricle_title) {
            $check_msg = D('House_village')->msgSecCheck($aricle_title);
            if ($check_msg['errcode'] != 0) {
                fdump(date('Y-m-d H:i:s'),'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
                fdump('web_bbs_aricele_wite_new____'.__LINE__,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
                fdump($_GET,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
                fdump($_POST,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
                fdump($check_msg,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
                $this->returnCodeError('内容含有违法违规内容');
            }
        }
        $inputimg	=	implode(';',I('inputimg',[]));
        $inputimg_str = I('inputimg_str','','trim');
        $inputimg_arr = explode(';',$inputimg_str);
        if ($inputimg_arr && $inputimg_arr[0]) {
            $inputimg = $inputimg_str;
        }
        $arr	=	array(
            'bbs_id'	=>	$aBbs['bbs_id'],
            'cat_id'	=>	$cat_id,
            'aricle_title'	=>	$aricle_title,
            'aricle_content'	=>	'',
            'uid'			=>	$this->_uid,
            'aricle_img'		=>	$inputimg,
            'aricle_status'		=>	$aBbs['auto_verify_post'],
            'create_time'		=>	time(),
            'update_time'		=>	time(),
            'exp_time'			=>	time(),
            'address'			=> $address,
            'type' 				=> 0
        );
        $aAricleAdd	=	D('Bbs')->newBbsAricleWite($arr,explode(';',$inputimg));
        if(empty($aAricleAdd)){
            $this->returnCode('30020001');
        }else{
            M('Bbs_category')->where(array('cat_id'=>$cat_id))->setInc('cat_aricle_total');
            if($aBbs['auto_verify_post'] == 1){
                M('Bbs_category')->where(array('cat_id'=>$cat_id))->setInc('cat_aricle_num');
                $this->returnCodeOk(L_('发布成功'));
            }else{
                $con['village_id'] = $village_id;
                if($wxapp_own_village_id)
                    $con['property_id'] = $wxapp_own_village_id;
                M('House_village')->where($con)->setInc('bbs_aricle_reminder');
                $this->returnCodeOk(L_('发布成功'));
            }
        }
    }

    //	图片上传
    public function ajaxImgUpload() {

        $mulu=isset($_GET['ml']) ? trim($_GET['ml']):'group';
        $mulu=!empty($mulu) ? $mulu : 'group';
        $filename = trim($_POST['filename']);
        $img = $_POST[$filename];
        $img = str_replace('data:image/png;base64,', '', $img);
        $img = str_replace(' ', '+', $img);
        $imgdata = base64_decode($img);
        $rand_num = date('Ymd');
        $getupload_dir = "/upload/bbs/aricle_img/".$rand_num;
        $upload_dir = "." . $getupload_dir;
        if (!is_dir($upload_dir)) {
            mkdir($upload_dir, 0777, true);
        }
        $newfilename = $mulu.'_' . date('YmdHis').mt_rand(10,99). '.jpg';
        $save = file_put_contents($upload_dir . '/' . $newfilename, $imgdata);
        if ($save) {
            $arr['siteurl'] = $this->config['site_url'];
            $arr['imgurl'] = $getupload_dir . '/' . $newfilename;
            $this->returnCode(0,$arr);

        } else {
            $this->returnCode('30020004');
        }
    }

    public function image()
    {
        $errors = [
            UPLOAD_ERR_INI_SIZE => '上传的文件超过了 php.ini 中 upload_max_filesize 选项限制的值',
            UPLOAD_ERR_FORM_SIZE => '上传文件的大小超过了 HTML 表单中 MAX_FILE_SIZE 选项指定的值',
            UPLOAD_ERR_PARTIAL => '文件只有部分被上传',
            UPLOAD_ERR_NO_FILE => '没有文件被上传',
            UPLOAD_ERR_NO_TMP_DIR => '找不到临时文件夹',
            UPLOAD_ERR_CANT_WRITE => '文件写入失败'
        ];
        if ($_FILES['imgFile']['error'] === UPLOAD_ERR_OK) {
            $image = D('Image')->handle(0, 'bbs/aricle_img', 2, array('size' => 10), false);
            if ($image['error']) {
                $this->returnCode(1001, [], $image['message']);
            } else {
                $imageUrl = replace_file_domain($image['url']['imgFile']);
                $imageUrl_path = $image['url']['imgFile'];
                $this->returnCode(0, ['url' => thumb_img($imageUrl, 200, 200, 'fill'),'imageUrl_path'=>$imageUrl_path, 'imageUrl'=>$imageUrl ]);
            }
        } else {
            $this->returnCode(1001, [], isset($errors[$_FILES['imgFile']['error']]) ? $errors[$_FILES['imgFile']['error']] : '上传失败');
        }
    }



    public function bbs_comment()
    {
        $aricle_id	=	I('aricle_id');
        $comment_fid	=	I('comment_fid',0);
        $comment_content	=	I('comment_content',0);
        $village_id	=	I('village_id');
        $village_type = I('village_type','house');
        $pigcms_id = I('pigcms_id','');

        if(empty($this->_uid)){
            $this->returnCode('20000009');
        }
        if(empty($aricle_id)){

            $this->returnCode('20120043');
        }else if(empty($comment_content)){

            $this->returnCode('73000015');
        }
        $check_msg = D('House_village')->msgSecCheck($comment_content);
        if ($check_msg['errcode'] != 0) {
            fdump(date('Y-m-d H:i:s'),'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            fdump('bbs_comment____'.__LINE__,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            fdump($_GET,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            fdump($_POST,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            fdump($check_msg,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            $this->returnCodeError('内容含有违法违规内容');
        }
        $this->get_user_village_info($pigcms_id,$village_id,$this->_uid);

        $aBbs = D('Bbs')->isVillage($village_id,$village_type);
        $arr	=	array(
            'comment_fid'	=>	$comment_fid,
            'aricle_id'	=>	$aricle_id,
            'comment_content'	=>	$comment_content,
            'comment_status'	=>	$aBbs['auto_verify_reply'],
            'create_time'	=>	time(),
        );

        $arr['uid'] = $this->_uid;

        $sWite	=	D('Bbs')->bbsAricleCommentWite($arr);
        if($sWite){
            if($comment_fid > 0){
                $arr['comment']['aricle_id'] = $aricle_id;
                $arr['comment']['comment_content'] = $comment_content;
                $arr['comment']['comment_fid'] = $comment_fid;
                $arr['comment']['comment_id'] = 0;
                $arr['comment']['create_time'] = date('m-d H:i',time());
                $user	=	M('User')->field(array('uid','nickname','avatar','last_time'))->where(array('uid'=>$this->_uid))->find();
                if($user['avatar']){
                    $user['avatar'] = replace_file_domain($user['avatar']);
                }else{
                    $user['avatar'] = C('config.site_url') . '/static/images/user_avatar.jpg';
                }
                $arr['comment']['uid']=$user;
            }else{
                $arr['comment']['aricle_id'] = $aricle_id;
                $arr['comment']['comment_content'] = $comment_content;
                $arr['comment']['comment_fid'] = $comment_fid;
                $arr['comment']['comment_id'] = 0;
                $arr['comment']['create_time'] = date('m-d H:i',time());
                $user	=	M('User')->field(array('uid','nickname','avatar','last_time'))->where(array('uid'=>$this->_uid))->find();
                if($user['avatar']){
                    $user['avatar'] = replace_file_domain($user['avatar']);
                }else{
                    $user['avatar'] = C('config.site_url') . '/static/images/user_avatar.jpg';
                }

                $arr['comment']['uid']=$user;
            }

            if($aBbs['auto_verify_reply'] == 1){
                $this->returnCode(0,$arr);
            }else{
                $this->returnCode(0,$arr);
            }
        }else{
            $this->returnCode('40000012');
        }
    }

