    //	文章的连接格式化
    public function bbsAricleFormat($arr=array()){
        foreach($arr as $kk=>$vv){
            if($vv['aricle_img']){
                $aricle_img_arr = explode(';' , $vv['aricle_img']);
                $tmp_aricle_img = array();
                foreach($aricle_img_arr as $img){
                    if(!empty($img)){
                        $tmp_aricle_img[] = $this->config['site_url'].$img;
                    }
                }
                $arr[$kk]['aricle_img']	=	$tmp_aricle_img;
            }
            if($vv['uid']['avatar']){
                $arr[$kk]['uid']['avatar']	=	$vv['uid']['avatar'];
            }else{
                $arr[$kk]['uid']['avatar']	=	$this->config['site_url'].$this->urlTot;
            }
            if($vv['update_time']){
                $arr[$kk]['update_time']	=	date('m-d H:i',$arr[$kk]['update_time']);

            }

            if($vv['aricle_content']){

            }

            if($vv['address']){
                $arr[$kk]['address']	=	unserialize(html_entity_decode($vv['address']));
            }

            if($vv['exp_time'] <= time() && $vv['exp_time'] != 0){
                $arr[$kk]['exp_time']	=	'已结束';
            }else if($vv['exp_time'] == 0){
                $arr[$kk]['exp_time']	=	'';
            }else{
                $expTime	=	$vv['exp_time']-time();
                if($expTime >= 86400){
                    $arr[$kk]['exp_time']	=	'还剩'.floor($expTime/86400).'天';
                }else if($expTime >= 3600){
                    $arr[$kk]['exp_time']	=	'还剩'.intval($expTime/3600).'小时';
                }else if($expTime >= 60){
                    $arr[$kk]['exp_time']	=	'还剩'.intval($expTime/60).'分钟';
                }else if($expTime >= 0){
                    $arr[$kk]['exp_time']	=	'还剩'.intval($expTime).'秒';
                }
            }
            foreach($vv['img'] as $kkk=>$vvv){
                $arr[$kk]['img'][$kkk]['aricle_img']	=	$this->config['site_url'].$vvv['aricle_img'];
            }
        }
        return $arr;
    }



    public function bbsAricleFormatNew($arr=array()){
        foreach($arr as $kk=>$vv){
            if($vv['aricle_img']){
                $aricle_img_arr = explode(';' , $vv['aricle_img']);
                $tmp_aricle_img = array();
                // 预览需要的大图
                $previewimage = array();
                $preview_width = 900;
                $preview_height = 900;

                $img_num = count($aricle_img_arr);
                if (!$img_num) {
                    $img_num = 0;
                }
                if ($img_num <= 1) {
                    $fill = '';
                    $width = 400;
                    $height = 400;
                } else {
                    $fill = 'fill';
                    $width = 200;
                    $height = 200;
                }
                foreach($aricle_img_arr as $k=> $img){
                    if(!empty($img)){
                        $tmp_aricle_img[] = array(
                            'img_path'=>thumb_img($img, $width, $height, $fill),
                            'img_Id'=>$k,
                        );
                        $previewimage[] = thumb_img($img, $preview_width, $preview_height);
                    }
                }
                $arr[$kk]['img_num'] = $img_num;
                $arr[$kk]['aricle_imgs']	=	$tmp_aricle_img;
                $arr[$kk]['previewimage']	=	$previewimage;
            }
            if($vv['uid']['avatar']){
                $arr[$kk]['uid']['avatar']	=	$vv['uid']['avatar'];
            }else{
                $arr[$kk]['uid']['avatar']	=	C('config.site_url') . '/static/images/user_avatar.jpg';
            }
            if($vv['update_time']){
                $arr[$kk]['update_time']	=	date('m-d H:i',$arr[$kk]['update_time']);

            }

            if($vv['create_time']){
                $arr[$kk]['create_time']	=	date('m-d H:i',$arr[$kk]['create_time']);

            }

            if($vv['address']){
//                $arr[$kk]['address']	=	unserialize(html_entity_decode($vv['address']));
                if(strpos($vv['address'], 'a:') !== false && strpos($vv['address'], ':{s:') !== false){
                    //老数据
                    $arr[$kk]['address']	=	unserialize(html_entity_decode($vv['address']));//兼容之前的数据
                }else{
                    //新数据
                    $arr[$kk]['address']	=	$vv['address'];
                }
            }else{
                $arr[$kk]['address'] = "";
            }


        }
        return $arr;
    }


    public function message_new(){
        $my_list = array();
        if(empty($this->_uid)){
            $this->returnCode('20000009');
        }
        $pigcms_id	=	I('pigcms_id','');
        if(empty($pigcms_id)){
            $this->returnCode('20120004');
        }
        $village_id =   I('village_id','');
        if(empty($village_id)){
            $this->returnCode('30000001');
        }
        $now_user_info = $this->get_user_village_info($pigcms_id,$village_id,$this->_uid);
        $village_type = I('village_type','house');
        $aBbs	=	D('Bbs')->isVillage($village_id,$village_type);

        $aBbsAricle	=	M('Bbs_aricle')->where(array('uid'=>$this->_uid,'aricle_status'=>1,'bbs_id'=>$aBbs['bbs_id']))->select();
        if($aBbsAricle) {
            $aricle = [];
            foreach ($aBbsAricle as $k => $value) {
                $aricle[] = $value['aricle_id'];
            }
        }
        $aricle_count = implode(',',$aricle);

        $sql = "(SELECT '".$this->config['site_url']."/static/images/house/zan.jpg' AS comment_content,uid,create_time,1 as type,aricle_id";
        $sql .= " FROM ".C('DB_PREFIX')."bbs_praise";
        $sql .= " WHERE create_time >".$now_user_info['message_time']." AND uid !=".$this->_uid." AND aricle_id IN (".$aricle_count.") ORDER BY create_time DESC)";
        $sql .= " UNION (SELECT comment_content,uid, create_time,2 as type,aricle_id";
        $sql .= " FROM ".C('DB_PREFIX') ."bbs_comment";
        $sql .= " WHERE create_time >".$now_user_info['message_time']." AND uid !=".$this->_uid." AND aricle_id IN (".$aricle_count.") ORDER BY create_time DESC)";
        $list = M()->query($sql);
        fdump($sql,'new_aricle',1);
        foreach($list as $k=>$v){
            if($v['aricle_id']){
                $bbs_aricle_info = M('bbs_aricle')->where(array('aricle_id'=>$v['aricle_id']))->find();
                if($bbs_aricle_info['aricle_img']){
                    $iamge = explode(';',$bbs_aricle_info['aricle_img']);
                    $aricle_img = file_domain().$iamge[0];
                }else{
                    $aricle_title = $bbs_aricle_info['aricle_title'];
                }
            }
            $user = M('User')->where(array('uid'=>$v['uid']))->find();

            $last_times = (time()-$v['create_time']);

            if($last_times >= 86400){
                // $time_status	=	floor($last_times/86400).'天前';
                $time_status	=	date('m-d H:i',$v['create_time']);
            }else if($last_times >= 3600){
                $time_status	=	intval($last_times/3600).'小时前';
            }else if($last_times >= 60){
                $time_status	=	intval($last_times/60).'分钟前';
            }else if($last_times >= 0){
                $time_status	=	'刚刚';
            }
            $my_list[]=array(
                'uid'=>$user['uid'],
                'nickname'=>$user['nickname'],
                'avatar'=>empty($user['avatar'])?C('config.site_url') . '/static/images/user_avatar.jpg':replace_file_domain($user['avatar']),
                'comment_content'=>$v['comment_content'],
                'type'=>$v['type'],
                'aricle_img'=>$aricle_img,
                'aricle_title'=>$aricle_title,
                'aricle_id'=>$v['aricle_id'],
                'time_status'=>$time_status
            );

        }
        //处理已读的
        $House_village_user_bindModel = D('House_village_user_bind');
        $House_village_user_bindModel->where(array('uid'=>$this->_uid,'pigcms_id'=>$pigcms_id,'village_id'=>$village_id))->data(array('message_time'=>time()))->save();

        $arr['my_list'] = $my_list;
        $this->returnCode(0,$arr);


    }


