    public function bbsAricleInfoFormat($arr = array())
    {
        $urlTot = '/static/images/user_avatar.jpg';
        if ($arr['aricle_img']) {
            $aricle_img_arr = explode(';', $arr['aricle_img']);
            $tmp_aricle_img = array();
            foreach ($aricle_img_arr as $img) {
                $tmp_aricle_img[] = $this->config['site_url'] . $img;
            }
            $arr['aricle_img'] = $tmp_aricle_img;
        } else {
            $arr['aricle_img'] = array();
        }
        if ($arr['uid']['avatar']) {
            $arr['uid']['avatar'] = $arr['uid']['avatar'];
        } else {
            $arr['uid']['avatar'] = $this->config['site_url'] . $urlTot;
        }
        if ($arr['update_time']) {
            $arr['update_time'] = date('m-d', $arr['update_time']);
        }

        if ($arr['address']) {
            $adress_bak = unserialize(html_entity_decode($arr['address']));
            $adress = $adress_bak['city'] . '-' . $adress_bak['district'];
            $arr['address'] = $adress;
        }

        if ($arr['exp_time'] <= time() && $arr['exp_time'] != 0) {
            $arr['exp_time'] = L_('已结束');
        } else if ($arr['exp_time'] == 0) {
            $arr['exp_time'] = '';
        } else {
            $expTime = $arr['exp_time'] - time();
            if ($expTime >= 86400) {
                $arr['exp_time'] = L_('还剩X1天', floor($expTime / 86400));
            } else if ($expTime >= 3600) {
                $arr['exp_time'] = L_('还剩X1小时', intval($expTime / 3600));
            } else if ($expTime >= 60) {
                $arr['exp_time'] = L_('还剩X1分钟', intval($expTime / 60));
            } else if ($expTime >= 0) {
                $arr['exp_time'] = L_('还剩X1秒', intval($expTime));
            }
        }
        foreach ($arr['img'] as $kkk => $vvv) {
            $arr['img'][$kkk]['aricle_img'] = $this->config['site_url'] . $vvv['aricle_img'];
        }
        return $arr;
    }

    public function village_newslist()
    {
        $village_id = I('village_id');
        $cat_id = I('cat_id', 0);
        $now_village = $this->get_village($village_id);
        $arr = [];$news_id=false;
        $category_list = D('House_village_news_category')->get_limit_list($now_village['village_id']);
        if (empty($category_list) || !$category_list) {
            $category_list = [];
        }
        array_unshift($category_list,['cat_name'=>'平台通知','cat_id'=>'_99']);
        if ($category_list) {

            $arr['category_list'] = $category_list;


//            $cat_id = $cat_id ? $cat_id : '_999';


            // 处理下
            $pigcms_id = I('pigcms_id');
            if ($pigcms_id>0) {
                $where['village_id'] = $village_id;
                $where['pigcms_id'] = $pigcms_id;
//                $floor_id = M('House_village_user_bind')->where($where)->getField('floor_id');
                $bind_village_list = M('House_village_user_bind')->where($where)->find();

                /**
                 * todo 查询当前用户所在通知房间的数据
                 */
                $village_news_notice_where['_string']=' ( type = 1 AND room_id = '.$bind_village_list['vacancy_id'].' ) OR (type = 0 AND village_id = '.$village_id.')';
                $news_notice=D('House_village_news_notice')->where($village_news_notice_where)->getField('news_id',true);
                if($news_notice){
                    $news_id=array_values(array_unique($news_notice));
                }
            }else{
                //todo 平台新闻查询
                $news_notice=D('House_village_news_notice')->where(['village_id'=>$village_id,'type'=>0])->getField('news_id',true);
                if($news_notice){
                    $news_id=array_values(array_unique($news_notice));
                }
            }
            $floor_id = 0;

            $news_list = D('House_village_news')->get_list_by_cid($cat_id, $floor_id,$news_id,$village_id);

            foreach ($news_list as $k => &$v) {
                $v['add_time'] = date('m-d H:i', $v['add_time']);
            }

            $arr['news_list'] = $news_list;

            $this->returnCode(0, $arr);
        } else {
            $arr['news_list'] = [];
            $this->returnCode(0, $arr);
        }
    }

    public function village_news()
    {
        $village_id = I('village_id',0,'intval');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $news_id = I('news_id',0,'intval');
        if (empty($news_id)) {
            $this->returnCode('71000020');
        }
        $page = I('page', 1, 'intval');
        $arr = [];
        $now_news = D('House_village_news')->get_one_new($news_id, '');
//        $now_news = D('House_village_news')->get_one_new($news_id, $village_id);
        //$now_news['content'] = strip_tags(htmlspecialchars_decode($now_news['content']));
        M('House_village_news')->where(array('news_id' => $news_id))->setInc('read_sum');
        if ($now_news) {
//            $condition['village_id'] = $village_id;
//            $is_check =  D('House_village_config')->where($condition)->getField('village_news_is_need_check');
            $news_reply = M('House_village_news_reply')->where(array('news_id' => $news_id,'status'=>1))->page($page, 1000)->select();
            if ($news_reply) {
                $news_reply_list = [];
                foreach ($news_reply as $item) {
                    $list=array();
                    $user = D('User')->field(array('nickname', 'avatar'))->where(array('uid' => $item['uid']))->find();
                    if ($user['nickname']) {
                        $list['nickname'] = $user['nickname'];
                    } else {
                        $list['nickname'] = '';
                    }
                    if ($user['avatar']) {
                        $list['avatar'] = replace_file_domain($user['avatar']);
                    } else {
                        $list['avatar'] = C('config.site_url') . '/static/images/user_avatar.jpg';
                    }
                    $list['content'] = htmlspecialchars_decode($item['content']);
                    if (isset($item['images']) && $item['images']) {
                        $images = json_decode($item['images'],true);
                        $list['images'] = [];
                        foreach ($images as $image) {
                            $list['images'][] =  replace_file_domain($image);
                        }
                    }
                    $news_reply_list[] = $list;

                }
                $now_news['news_reply_list'] = $news_reply_list;
            } else {
                $now_news['news_reply_list'] = [];
            }

        }
        if (empty($now_news)) {
            $arr['now_news'] = [];
        } else {
            $now_news['content'] = replace_file_domain_content_img(htmlspecialchars_decode($now_news['content']));
            $now_news['add_time'] = date('m-d H:i', $now_news['add_time']);
            $arr['now_news'] = $now_news;

        }
        $this->returnCode(0, $arr);
    }

    public function add_new()
    {
        $news_id = intval($_POST['news_id']);
        if (empty($news_id)) {
            $this->returnCode('71000020');
        }
        $content = trim($_POST['content']);
        if (empty($content)) {
            $this->returnCode('20070002');
        }
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $check_msg = D('House_village')->msgSecCheck($content);
        if ($check_msg['errcode'] != 0) {
            fdump(date('Y-m-d H:i:s'),'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            fdump('add_new____'.__LINE__,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            fdump($_GET,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            fdump($_POST,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            fdump($check_msg,'api/log/'.date('Ymd').'/msgSecCheck_err_log',true);
            $this->returnCodeError('内容含有违法违规内容');
        }
        $data = [];
        $village_news=D('House_village_news')->where(['news_id'=>$news_id])->find();
        if(!$village_news){
            $this->returnCode('10100101');
        }
        //todo 平台小区新闻评论开关判断
        if($village_news['type'] == 1){
            $now_config = D('House_village_config')->where(['village_id' => $village_id])->find();
            if($now_config['village_news_is_need_check'] == 1){
                $data['status'] = 0;
            }else{
                $data['status'] = 1;
            }
        }else{
            $is_check=D('config')->where(['name'=>'house_news_comment_open'])->getField('value');
            if($is_check == 1){
                $data['status'] = 0;
            }else{
                $data['status'] = 1;
            }
        }


        $data['uid'] = $this->_uid;
        $data['village_id'] = $village_id;
        $data['news_id'] = $news_id;
        $data['content'] = $content;
        $data['add_time'] = time();
        $data['is_read'] = 0;
        $images = I('images');
        if ($images) {
            $data['images'] = json_encode($images,JSON_UNESCAPED_UNICODE);
        }
        $news_reply = M('House_village_news_reply')->data($data)->add();
        if (empty($news_reply)) {
            $this->returnCode('10100101');
        } else {
            $arr = [];
            if ($data['status'] == 1) {
                $user = D('User')->field(array('nickname', 'avatar'))->where(array('uid' => $this->_uid))->find();
                if ($user['nickname']) {
                    $arr['nickname'] = $user['nickname'];
                } else {
                    $arr['nickname'] = '';
                }
                if ($user['avatar']) {
                    $arr['avatar'] = replace_file_domain($user['avatar']);
                } else {
                    $arr['avatar'] = C('config.site_url') . '/static/images/user_avatar.jpg';
                }
                $arr['content'] = $content;
                $arr['is_check'] = false;
            }else{
                $arr['is_check'] = true;
            }
            $this->returnCode(0, $arr);
        }
    }


    public function village_my_utilitieslists_new()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        if (empty(I('type'))) {
            $this->returnCode('20090211');
        }
        $arr = [];
        $repair_list = D('House_village_repair_list')->field(true)->where(array('bind_id' => $pigcms_id, 'village_id' => $village_id, 'type' => I('type')))->order('`pigcms_id` DESC')->select();
        if(I('type') == 1){
            $statusDesc = array('未受理', '物业已受理', '维修员已受理', '维修员已处理', '业主已评价');
        }elseif(I('type') == 2){
            $statusDesc = array('未受理', '物业已受理', '客服专员已受理', '客服专员已处理', '业主已评价');
        }elseif(I('type') == 3){
            $statusDesc = array('未受理', '物业已受理', '客服专员已受理', '客服专员已处理', '业主已评价');
        }

        if ($statusDesc) {
            foreach ($repair_list as $k => $v) {
                $list['time'] = date('Y-m-d H:i', $v['time']);
                $list['content'] = $v['content'];
                $list['id'] = $v['pigcms_id'];
                $list['status'] = $v['status'];
                $list['statusDesc'] = $statusDesc[$v['status']];
                $arr['repair_list'][] = $list;
            }
        } else {
            $arr['repair_list'] = [];
        }
        $this->returnCode(0, $arr);
    }


