    public function village_my_utilities_detail_new()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        if (empty(I('id'))) {
            $this->returnCode('20090208');
        }
        $repair_detail = D('House_village_repair_list')->field(true)->where(array('pigcms_id' => I('id')))->find();
        if (empty($repair_detail)) {
            $this->returnCode('20090210');
        }
        $arr = [];
        if ($repair_detail['wid']) $this->worker($repair_detail['wid']);

        if ($repair_detail['pic']) {
            $repair_detail['picArr'] = explode('|', $repair_detail['pic']);
            foreach ($repair_detail['picArr'] as $k1 => &$v1) {
                if (substr($v1, 1, 6) == 'upload') {
                    $v1 = file_domain() . $v1;
                } else {
                    //                    $v1 = file_domain() . '/upload/house/' . $v1; //2020/07/30 前段bug  不显示  修改
                    $v1 = file_domain() . '/upload/activity/' . $v1;
                }

            }
        }
        if ($repair_detail['reply_pic']) {
            $repair_detail['reply_picArr'] = explode('|', $repair_detail['reply_pic']);
            foreach ($repair_detail['reply_picArr'] as $k1 => &$v1) {
                if (substr($v1, 1, 6) == 'upload') {
                    $v1 = file_domain() . $v1;
                } else {
                    $v1 = file_domain() . '/upload/worker/' . $v1;
                }

            }
        }
        if ($repair_detail['comment_pic']) {
            $repair_detail['comment_picArr'] = explode('|', $repair_detail['comment_pic']);
            foreach ($repair_detail['comment_picArr'] as $k1 => &$v1) {
                if (substr($v1, 1, 6) == 'upload') {
                    $v1 = file_domain() . $v1;
                } else {
                    $v1 = file_domain() . '/upload/house/' . $v1;
                }

            }
        }
        $follow_list_data = M('House_village_repair_follow')->where(array('village_id'=>$village_id,'repair_id'=>I('id')))->select();

        if($follow_list_data){

            $follow_list = [];
            foreach($follow_list_data as $k=>$v){
                $follow_list[] = array(
                    'add_time'=>date('Y-m-d H:i:s',$v['time']),
                    'content' =>$v['content'],
                );
            }

            //$arr['follow_list'] = $follow_list;
        }else{
            // $arr['follow_list'] = [];
        }
        $logs = D('House_village_repair_log')->field(true)->where(array('repair_id' => $repair_detail['pigcms_id']))->order('status desc')->select();
        foreach ($logs as $log) {
            $repair_detail['status_time_' . $log['status']] = $log['dateline'];
        }
        //$statusDesc = array('任务提交成功', '任务指派成功', '工作人员已受理', '工作人员已处理', '业主已评论');
        $statusDesc = array('任务提交成功', '任务指派成功', '工作人员已受理','工作人员跟进内容', '工作人员已处理', '业主已评论');
        foreach ($logs as $k => &$v) {
            $v['dateline'] = date('Y-m-d H:i', $v['dateline']);
            if($v['status'] == 3){
                $v['statusDesc'] = '工作人员已处理';
            }elseif($v['status'] == 4){
                $v['statusDesc'] = '业主已评论';
            }else{
                $v['statusDesc'] = $statusDesc[$v['status']];
            }
            if ($v['status'] == 0) {
                $v['content'] = $repair_detail['content'];
                if ($repair_detail['pic']) {
                    $v['picArr'] = $repair_detail['picArr'];
                } else {
                    $v['picArr'] = '';
                }
            } elseif ($v['status'] == 1) {
                $v['content'] = '';
            } elseif ($v['status'] == 2) {
                $v['content'] = $repair_detail['msg'];
            } elseif ($v['status'] == 3) {
                $v['content'] = $repair_detail['reply_content'];
                if ($repair_detail['reply_pic']) {
                    $v['picArr'] = $repair_detail['reply_picArr'];
                } else {
                    $v['picArr'] = '';
                }

            } elseif ($v['status'] == 4) {
                $v['content'] = $repair_detail['comment'];
                if ($repair_detail['comment_pic']) {
                    $v['picArr'] = $repair_detail['comment_picArr'];
                } else {
                    $v['picArr'] = '';
                }
                $v['score'] = $repair_detail['score'];
            }
        }
        if($follow_list){
            $follow_array[] = array(
                'status'=>"99",
                'statusDesc'=>'工作人员跟进内容',
                'follow_list'=>$follow_list,
            );
            if($repair_detail['status'] == 2){
                array_splice($logs, 0, 0, $follow_array);
            }elseif($repair_detail['status'] == 3){
                array_splice($logs, 1, 0, $follow_array);
            }

        }
        $arr['repair_status'] = $repair_detail['status'];
        $arr['repair_id'] = $repair_detail['pigcms_id'];
        $arr['logs'] = $logs;
        $this->returnCode(0, $arr);

    }

    public function village_comment_new()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        $id = I('id');
        if (empty($id)) {
            $this->returnCode('20090208');
        }

        $repair_detail = D('House_village_repair_list')->field(true)->where(array('pigcms_id' => $id, 'uid' => $this->_uid))->find();
        if (empty($repair_detail)) {
            $this->returnCode('20090210');
        }

        if ($repair_detail['wid']) {
            $this->worker($repair_detail['wid']);
        }
        if (empty(I('comment'))) {
            $this->returnCode('73000015');
        }
        $inputimg = implode(';', I('inputimg', []));
        $picArr = isset($inputimg) ? $inputimg : '';
        $data_repair['comment_pic'] = $picArr;
        $data_repair['comment'] = htmlspecialchars(I('comment'));
        $data_repair['comment_time'] = $_SERVER['REQUEST_TIME'];
        $data_repair['score'] = intval(I('score', ''));
        $data_repair['status'] = 4;


        if ($repair_id = D('House_village_repair_list')->where(array('pigcms_id' => $id, 'uid' => $this->_uid))->save($data_repair)) {

            D('House_worker')->add_score($repair_detail['wid'], $data_repair['score']);
            D('House_village_repair_log')->add_log(array('status' => 4, 'repair_id' => $id));
            $this->returnCodeOk(L_('提交成功'));
        } else {
            $this->returnCodeOk(L_('提交失败'));
        }
    }

    public function utilities_image()
    {
        $errors = [
            UPLOAD_ERR_INI_SIZE => '上传的文件超过了 php.ini 中 upload_max_filesize 选项限制的值',
            UPLOAD_ERR_FORM_SIZE => '上传文件的大小超过了 HTML 表单中 MAX_FILE_SIZE 选项指定的值',
            UPLOAD_ERR_PARTIAL => '文件只有部分被上传',
            UPLOAD_ERR_NO_FILE => '没有文件被上传',
            UPLOAD_ERR_NO_TMP_DIR => '找不到临时文件夹',
            UPLOAD_ERR_CANT_WRITE => '文件写入失败'
        ];
        if ($_FILES['imgFile']['error'] === UPLOAD_ERR_OK) {
            $image = D('Image')->handle(0, 'house', 2, array('size' => 10), false);
            if ($image['error']) {
                $this->returnCode(1001, [], $image['message']);
            } else {
                $imageUrl = replace_file_domain($image['url']['imgFile']);
                $imageUrl_path = $image['url']['imgFile'];
                $this->returnCode(0, ['url' => thumb_img($imageUrl, 200, 200, 'fill'), 'imageUrl_path' => $imageUrl_path, 'imageUrl' => $imageUrl]);
            }
        } else {
            $this->returnCode(1001, [], isset($errors[$_FILES['imgFile']['error']]) ? $errors[$_FILES['imgFile']['error']] : '上传失败');
        }
    }


    public function add_utilities()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $bind_info=D('house_village_user_bind')->field(true)->where(array('pigcms_id' => $pigcms_id))->find();
        if (empty($bind_info)||$bind_info['status']!=1){
            $this->returnCodeError('无有效住户身份，可进入个人中心申请入住');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $content = I('content');
        if (empty($content)) {
            $this->returnCode('20070002');
        }
        if (empty(I('type'))) {
            $this->returnCode('20090211');
        }
        /*if(I('type') == 1){
            if(empty(I('repair_type'))){
                $this->returnCode('20090252');
            }
            if(I('repair_type') == '2'){
                if(empty(I('repair_time'))){
                    $this->returnCodeError('在线报修时间必须填!');
                }
            }
        }*/
		if (empty(I('cate_id'))&&I('type') != 2) {
            $this->returnCodeError('请选择类型');
        }
        $inputimg = implode('|', I('inputimg', []));
        $picArr = isset($inputimg) ? $inputimg : '';
        $data_repair['pic'] = $picArr;
        $data_repair['content'] = $content;
        $data_repair['village_id'] = $village_id;
        $data_repair['uid'] = $this->_uid;
        $data_repair['bind_id'] = $pigcms_id;
        $data_repair['is_read'] = '0';
        $data_repair['status'] = '0';
        $data_repair['type'] = I('type');
        $data_repair['cate_id'] = I('cate_id','');//分类id
        $data_repair['cate_fid'] = I('cate_fid','');//分类fid
        $data_repair['time'] = $_SERVER['REQUEST_TIME'];
        if(I('type') == 1){
            if(empty(I('classify_id'))){
                $this->returnCode('20090252');
            }
            $cate=D('House_village_repair_cate')->where(['id'=>$data_repair['cate_id']])->find();
            if(!$cate){
                $this->returnCodeOk(L_('该故障类型不存在'));
            }
            //cate_fid 故障类型一级分类id  cate_id 故障类型二级分类id
            if(intval($cate['parent_id']) == 0){
                $data_repair['cate_fid']=$data_repair['cate_id'];
                $data_repair['cate_id']=0;
            }else{
                $data_repair['cate_fid']=$cate['parent_id'];
            }
            $data_repair['classify_id'] = I('classify_id',0);
            $classify=D('House_village_repair_classify')->where(['id'=>$data_repair['classify_id'],'del_time'=>0,'village_id'=>$village_id])->find();
            if(empty($classify)){
                $this->returnCodeOk(L_('该报修类别不存在'));
            }
            $data_repair['repair_type']=$classify['type'];
            if($classify['type'] == 2){
                if(empty(I('repair_time'))){
                    $this->returnCodeError('在线报修时间必须填!');
                }
                $data_repair['repair_time'] = strtotime(I('repair_time'));
            }
        }
        if ($repair_id = D('House_village_repair_list')->data($data_repair)->add()) {
            D('House_village_repair_log')->add_log(array('status' => 0, 'repair_id' => $repair_id));
            $this->returnCodeOk(L_('提交成功'));
        } else {
            $this->returnCodeOk(L_('提交失败'));
        }
    }

    private function worker($wid)
    {
        $worker = D('House_worker')->field(true)->where(array('wid' => $wid))->find();
        $this->assign('worker', $worker);
    }


