    public function village_property_pay()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $now_village = $this->get_village($village_id);
        $arr = [];
        $now_user_info_data = $this->get_user_village_info($pigcms_id, $village_id, $this->_uid);

        //家属 获取业主的欠费信息
        if ($now_user_info_data['parent_id']) {
            $now_user_info_data = $this->get_user_village_info($now_user_info_data['parent_id'], $village_id, $this->_uid);
        }
        if ($now_user_info_data['floor_id']) {
            $database_house_village_floor = D('House_village_floor');
            $floor_where['status'] = 1;
            $floor_where['floor_id'] = $now_user_info_data['floor_id'];
            $floor_info = $database_house_village_floor->where($floor_where)->find();
            $database_house_village_floor_type = D('House_village_floor_type');
            $type_where['status'] = 1;
            $type_where['id'] = $floor_info['floor_type'];
            if ($floor_type_name = $database_house_village_floor_type->where($type_where)->getField('name')) {
                $now_user_info_data['floor_type_name'] = $floor_type_name;
            } else {
                $now_user_info_data['floor_type_name'] = '暂无';
            }
        }
        //基本信息
        $now_user_info['housesize'] = $now_user_info_data['housesize'];
        $now_user_info['floor_type_name'] = empty($now_user_info_data['floor_type_name']) ? '暂无' : $now_user_info_data['floor_type_name'];
        $now_user_info['property_time_str'] = ($now_user_info_data['property_starttime'] ? date('Y-m-d', $now_user_info_data['property_starttime']) : '暂无') . ' 至 ' . ($now_user_info_data['property_endtime'] ? date('Y-m-d', $now_user_info_data['property_endtime']) : '暂无');


        //物业缴费周期
        $database_house_village_property = D('House_village_property');
        $property_condition['village_id'] = $now_village['village_id'];
        $property_condition['status'] = 1;
        $property_list = $database_house_village_property->house_village_proerty_page_list($property_condition, true, 'property_month_num desc', 99999);

        $property_list = $property_list['list'];

        if (!$property_list['list']) {
            $this->returnCode('20120012');
        }

        $property_data_list = [];
        foreach ($property_list['list'] as $k => $v) {
            if ($v['property_month_num']) {
                $list['property_month_num_desc'] = $v['property_month_num'] . "个月";
            }
            if ($v['presented_property_month_num'] > 0) {
                $list['presented_property_month_num_desc'] = "送" . $v['presented_property_month_num'] . "个月";
            } else {
                $list['presented_property_month_num_desc'] = "";
            }
            $list['property_month_num'] = $v['property_month_num'];
            $list['presented_property_month_num'] = $v['presented_property_month_num'];
            if ($v['diy_type'] == 1) {
                $list['diy_content'] = $v['diy_content'];
            }
            $list['id'] = $v['id'];
            $list['village_id'] = $v['village_id'];
            $property_data_list[] = $list;
        }
        $arr['property_list'] = $property_data_list;
        $standard_id = M('House_village_property_standard_bind')->where(['pigcms_id'=>$now_user_info_data['vacancy_id'],'is_del'=>1])->field('standard_id')->find();
        if(!$standard_id['standard_id']){
            $arr['total_price'] = 0;
            $now_user_info['property_fee'] = 0;
        }else{
            $date = M('House_village_property_standard')->where(['id'=>$standard_id['standard_id']])->field('date_month')->find();
            $arr['total_price'] = $this->get_all_fee(unserialize($date['date_month']),$now_user_info_data['housesize'],strtotime(date('Y-m',time())),$property_list['list'][0]['property_month_num']);
            $arr['total_price'] = getFormatNumber($arr['total_price']);

            $now_property_fee = $this->get_now_property_fee(unserialize($date['date_month']),time());
            $now_user_info['property_fee'] = getFormatNumber($now_property_fee);
        }
        $arr['now_user_info'] = $now_user_info;
        $arr['has_property_pay'] = $now_village['has_property_pay'];
        $arr['min_num'] = 1;
        $arr['max_num'] = 36;
        $this->returnCode(0, $arr);
    }


    public function add_presented_property_month()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        $id = I('id');//物业缴费周期不存在
        if (!$id) {
            $this->returnCode('20090180');
        }
        //郭先森
        $database_house_village_property = D('House_village_property');
        $where['id'] = $id;
        $property_info = $database_house_village_property->where($where)->find();
        if ($property_info['diy_type']==0) {
            $property_info['diy_content'] = '';
        }
        //==>郭先森==>去掉不需要的
        unset($property_info['add_time']);
        unset($property_info['diy_type']);
        unset($property_info['status']);
        if (!empty($property_info)) {
            $database_house_village_user_bind = D('House_village_user_bind');
            $database_house_village_floor = D('House_village_floor');
            $bind_info = $database_house_village_user_bind->get_one_by_bindId($pigcms_id);//===>郭先森存入房间id
            $floor_where['floor_id'] = $bind_info['floor_id'];
            $floor_where['status'] = 1;
            $floor_info = $database_house_village_floor->house_village_floor_detail($floor_where);
            $floor_info = $floor_info['detail'];



            if ($bind_info['parent_id']) {
                $parent_info = $database_house_village_user_bind->get_one_by_bindId($bind_info['parent_id']);
                $bind_info['housesize'] = $parent_info['housesize'];
            }

            $standard_id = M('House_village_property_standard_bind')->where(['pigcms_id'=>$bind_info['vacancy_id'],'is_del'=>1])->field('standard_id')->find();
            if(!$standard_id['standard_id']){
                $total_price = 0;
            }else{
                $date = M('House_village_property_standard')->where(['id'=>$standard_id['standard_id']])->field('date_month')->find();
                $total_price = $this->get_all_fee(unserialize($date['date_month']),$bind_info['housesize'],strtotime(date('Y-m',time())),$property_info['property_month_num']);
            }

            //$total_price = floatval($property_fee) * floatval($bind_info['housesize']) * floatval($property_info['property_month_num']);

            //计算物业费和抵扣金额
            //判断是否允许使用积分
            $village_config = D('House_village_config')->where(array('village_id' => $floor_info['village_id']))->find();

            //首先得到 积分比例 和 用户总积分
            $system_config = D('Config')->get_config();

            //得到多少积分抵扣一元
            $moneytointegral = $system_config['user_score_use_percent'];
            //得到用户总积分
            $userinfo = D('User')->get_user($this->_uid); //===>郭先森===>传入uid
            $user_score_count = $userinfo['score_count'];

            //第一步 判断是否允许使用积分 (注意 这里是针对设置了小区本身的缴费配置)
            if ($village_config['village_pay_use_integral'] == 1) { //允许使用积分 针对小区开启

                if ($village_config['village_pay_owe_use_integral'] == 1) { //欠缴物业费允许使用积分

                    $property_info_arr = $this->ajax_integral_info($total_price, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                } else { // 欠缴物业费不允许使用积分情况

                    //首先计算缴费月份 并且得到是否欠缴物业费

                    $database_house_village_property_paylist = D('House_village_property_paylist');
                    $pay_list = $database_house_village_property_paylist->where(array('bind_id' => $this->village_bind['pigcms_id'], 'uid' => $this->_uid))->order('add_time asc')->select();

                    if (!empty($pay_list)) {
                        $start_pay_info = reset($pay_list);
                        $end_pay_info = end($pay_list);
                        if ($start_pay_info && $end_pay_info) {

                            //这里判断是否欠缴物业费
                            if ($end_pay_info['end_time'] > time()) {

                                $property_info_arr = $this->ajax_integral_info($total_price, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                            } else {

                                $date1 = explode("-", date("Y-m-d"));
                                $date2 = explode("-", date("Y-m-d", $end_pay_info['end_time']));
                                $time1 = strtotime(date("Y-m-d"));
                                $time2 = strtotime(date("Y-m-d", $end_pay_info['end_time']));
                                $months = abs($date1[0] - $date2[0]) * 12;
                                if ($time1 > $time2) {
                                    $owe_mouth = $months + $date1[1] - $date2[1];
                                } else {
                                    $owe_mouth = $months + $date2[1] - $date1[1];
                                }

                                if ($owe_mouth >= floatval($property_info['property_month_num'])) {
                                    $property_info_arr['use_total_score_count'] = 0;
                                    $property_info_arr['use_total_money'] = 0;
                                } else {
                                    $owe_money = $this->get_all_fee(unserialize($date['date_month']),$bind_info['housesize'],strtotime(date('Y-m',time())),$owe_mouth);
                                    $now_total_integral_money = $total_price - $owe_money;

                                    $property_info_arr = $this->ajax_integral_info($now_total_integral_money, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                                }

                            }

                        } else {
                            $property_info_arr = $this->ajax_integral_info($total_price, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);
                        }
                    } else { // 第一次缴物业费 就不存在欠费
                        $property_info_arr = $this->ajax_integral_info($total_price, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                    }


                }

            } elseif ($village_config['village_pay_use_integral'] == 0) { // 继承系统设置

                if ($system_config['village_pay_use_integral'] == 1) {

                    if ($system_config['village_owe_pay_use_integral'] == 1) { //欠缴物业费允许使用积分

                        $property_info_arr = $this->ajax_integral_info($total_price, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                    } else { // 欠缴物业费不允许使用积分情况

                        //首先计算缴费月份 并且得到是否欠缴物业费
                        $database_house_village_property_paylist = D('House_village_property_paylist');

                        //通过房间号处理
                        $pay_list = $database_house_village_property_paylist->where(array('bind_id' => $pigcms_id, 'uid' => $this->_uid))->order('add_time asc')->select();

                        if (!empty($pay_list)) {
                            $start_pay_info = reset($pay_list);
                            $end_pay_info = end($pay_list);
                            if ($start_pay_info && $end_pay_info) {

                                //这里判断是否欠缴物业费
                                if ($end_pay_info['end_time'] > time()) {

                                    $property_info_arr = $this->ajax_integral_info($total_price, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                                } else {

                                    $date1 = explode("-", date("Y-m-d"));
                                    $date2 = explode("-", date("Y-m-d", $end_pay_info['end_time']));
                                    $time1 = strtotime(date("Y-m-d"));
                                    $time2 = strtotime(date("Y-m-d", $end_pay_info['end_time']));
                                    $months = abs($date1[0] - $date2[0]) * 12;
                                    if ($time1 > $time2) {
                                        $owe_mouth = $months + $date1[1] - $date2[1];
                                    } else {
                                        $owe_mouth = $months + $date2[1] - $date1[1];
                                    }

                                    if ($owe_mouth >= floatval($property_info['property_month_num'])) {
                                        $property_info_arr['use_total_score_count'] = 0;
                                        $property_info_arr['use_total_money'] = 0;
                                    } else {
                                        $owe_money = $this->get_all_fee(unserialize($date['date_month']),$bind_info['housesize'],strtotime(date('Y-m',time())),$owe_mouth);
                                        $now_total_integral_money = $total_price - $owe_money;
                                        $property_info_arr = $this->ajax_integral_info($now_total_integral_money, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                                    }

                                }

                            } else {
                                $property_info_arr = $this->ajax_integral_info($total_price, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);
                            }
                        } else { // 第一次缴物业费 就不存在欠费
                            $property_info_arr = $this->ajax_integral_info($total_price, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                        }


                    }

                } else {

                    $property_info_arr['use_total_score_count'] = 0;
                    $property_info_arr['use_total_money'] = 0;

                }

            } else {
                $property_info_arr['use_total_score_count'] = 0;
                $property_info_arr['use_total_money'] = 0;

            }

            $property_info['total_price'] = getFormatNumber($total_price);
            $property_info['use_total_score_count'] = $property_info_arr['use_total_score_count'];
            $property_info['use_total_money'] = $property_info_arr['use_total_money'];
            if ($property_info['property_month_num'] > 0) {
                $property_info['property_month_num_desc'] = '送' . $property_info['property_month_num'] . '个月';
            } else {
                $property_info['property_month_num_desc'] = '';
            }
            if ($property_info['presented_property_month_num']) {
                $property_info['presented_property_month_num_desc'] = '送' . $property_info['presented_property_month_num'] . '个月';
            } else {
                $property_info['presented_property_month_num_desc'] = '';
            }
            $this->returnCode(0, $property_info);
        } else {
            $this->returnCode(0, $property_info);
        }

    }


    public function add_diy_presented_property_month()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $diy_propertyt_month_num = I('diy_propertyt_month_num');
        if ($diy_propertyt_month_num <= 0 || $diy_propertyt_month_num > 36) {
            $this->returnCode('20090207');
        }

        $database_house_village_property = D('House_village_property');

        $where['village_id'] = $village_id;
        $where['status'] = 1;
        $property_list = $database_house_village_property->house_village_proerty_page_list($where, true, 'property_month_num desc', 99999);

        $database_house_village_user_bind = D('House_village_user_bind');
        $database_house_village_floor = D('House_village_floor');
        $bind_info = $database_house_village_user_bind->get_one_by_bindId($pigcms_id);//===>郭先森

        $floor_where['floor_id'] = $bind_info['floor_id'];
        $floor_where['status'] = 1;
        $floor_info = $database_house_village_floor->house_village_floor_detail($floor_where);
        $floor_info = $floor_info['detail'];

        $standard_id = M('House_village_property_standard_bind')->where(['pigcms_id'=>$bind_info['vacancy_id'],'is_del'=>1])->field('standard_id')->find();
        if(!$standard_id['standard_id']){
            $property_fee = 0;
            $total_price = 0;
        }else{
            $date = M('House_village_property_standard')->where(['id'=>$standard_id['standard_id']])->field('date_month')->find();
            $property_fee = $this->get_now_property_fee(unserialize($date['date_month']),time());
            $total_price = floatval($property_fee) * floatval($bind_info['housesize']) * floatval($diy_propertyt_month_num);
        }
        if ($bind_info['parent_id']) {
            $parent_info = $database_house_village_user_bind->get_one_by_bindId($bind_info['parent_id']);
            $bind_info['housesize'] = $parent_info['housesize'];
        }

        //计算物业费和抵扣金额
        //判断是否允许使用积分
        $village_config = D('House_village_config')->where(array('village_id' => $floor_info['village_id']))->find();

        //首先得到 积分比例 和 用户总积分
        $system_config = D('Config')->get_config();

        //得到多少积分抵扣一元
        $moneytointegral = $system_config['user_score_use_percent'];
        //得到用户总积分
        $userinfo = D('User')->get_user($this->_uid);//===>郭先森===>uid
        $user_score_count = $userinfo['score_count'];

        //第一步 判断是否允许使用积分 (注意 这里是针对设置了小区本身的缴费配置)
        if ($village_config['village_pay_use_integral'] == 1) { //允许使用积分 针对小区开启

            if ($village_config['village_pay_owe_use_integral'] == 1) { //欠缴物业费允许使用积分

                $property_info = $this->ajax_integral_info($total_price, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);

            } else { // 欠缴物业费不允许使用积分情况

                //首先计算缴费月份 并且得到是否欠缴物业费

                $database_house_village_property_paylist = D('House_village_property_paylist');
                $pay_list = $database_house_village_property_paylist->where(array('bind_id' => $pigcms_id, 'uid' => $this->_uid))->order('add_time asc')->select();

                if (!empty($pay_list)) {
                    $start_pay_info = reset($pay_list);
                    $end_pay_info = end($pay_list);
                    if ($start_pay_info && $end_pay_info) {

                        //这里判断是否欠缴物业费
                        if ($end_pay_info['end_time'] > time()) {

                            $property_info = $this->ajax_integral_info($total_price, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                        } else {

                            $date1 = explode("-", date("Y-m-d"));
                            $date2 = explode("-", date("Y-m-d", $end_pay_info['end_time']));
                            $time1 = strtotime(date("Y-m-d"));
                            $time2 = strtotime(date("Y-m-d", $end_pay_info['end_time']));
                            $months = abs($date1[0] - $date2[0]) * 12;
                            if ($time1 > $time2) {
                                $owe_mouth = $months + $date1[1] - $date2[1];
                            } else {
                                $owe_mouth = $months + $date2[1] - $date1[1];
                            }

                            if ($owe_mouth >= floatval($property_info['property_month_num'])) {
                                $property_info['use_total_score_count'] = 0;
                                $property_info['use_total_money'] = 0;
                            } else {

                                $now_total_integral_money = $total_price - floatval($property_fee) * floatval($bind_info['housesize']) * $owe_mouth;

                                $property_info = $this->ajax_integral_info($now_total_integral_money, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                            }

                        }

                    } else {
                        $property_info = $this->ajax_integral_info($total_price, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);
                    }
                } else { // 第一次缴物业费 就不存在欠费
                    $property_info = $this->ajax_integral_info($total_price, $village_config['use_max_integral_percentage'], $village_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                }


            }

        } elseif ($village_config['village_pay_use_integral'] == 0) { // 继承系统设置

            if ($system_config['village_pay_use_integral'] == 1) {

                if ($system_config['village_owe_pay_use_integral'] == 1) { //欠缴物业费允许使用积分

                    $property_info = $this->ajax_integral_info($total_price, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                } else { // 欠缴物业费不允许使用积分情况

                    //首先计算缴费月份 并且得到是否欠缴物业费

                    $database_house_village_property_paylist = D('House_village_property_paylist');
                    $pay_list = $database_house_village_property_paylist->where(array('bind_id' => $pigcms_id, 'uid' => $this->_uid))->order('add_time asc')->select();

                    if (!empty($pay_list)) {
                        $start_pay_info = reset($pay_list);
                        $end_pay_info = end($pay_list);
                        if ($start_pay_info && $end_pay_info) {

                            //这里判断是否欠缴物业费
                            if ($end_pay_info['end_time'] > time()) {

                                $property_info = $this->ajax_integral_info($total_price, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                            } else {

                                $date1 = explode("-", date("Y-m-d"));
                                $date2 = explode("-", date("Y-m-d", $end_pay_info['end_time']));
                                $time1 = strtotime(date("Y-m-d"));
                                $time2 = strtotime(date("Y-m-d", $end_pay_info['end_time']));
                                $months = abs($date1[0] - $date2[0]) * 12;
                                if ($time1 > $time2) {
                                    $owe_mouth = $months + $date1[1] - $date2[1];
                                } else {
                                    $owe_mouth = $months + $date2[1] - $date1[1];
                                }

                                if ($owe_mouth >= floatval($property_info['property_month_num'])) {
                                    $property_info['use_total_score_count'] = 0;
                                    $property_info['use_total_money'] = 0;
                                } else {

                                    $now_total_integral_money = $total_price - floatval($property_fee) * floatval($bind_info['housesize']) * $owe_mouth;

                                    $property_info = $this->ajax_integral_info($now_total_integral_money, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                                }

                            }

                        } else {
                            $property_info = $this->ajax_integral_info($total_price, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);
                        }
                    } else { // 第一次缴物业费 就不存在欠费
                        $property_info = $this->ajax_integral_info($total_price, $system_config['use_max_integral_percentage'], $system_config['use_max_integral_num'], $moneytointegral, $user_score_count);

                    }
                }

            } else {

                $property_info['use_total_score_count'] = 0;
                $property_info['use_total_money'] = 0;

            }

        } else {
            $property_info['use_total_score_count'] = 0;
            $property_info['use_total_money'] = 0;

        }


        if ($property_list['list']['list']) {
            foreach ($property_list['list']['list'] as $property) {

                if ($diy_propertyt_month_num / $property['property_month_num'] > 1) {
                    if ($property['diy_type'] == 0) {

                        $arr['max_presented_property_month'] = $property['presented_property_month_num'] * intval($diy_propertyt_month_num / $property['property_month_num']);
                        $arr['total_price'] = getFormatNumber($total_price);
                        $arr['diy_type'] = 0;
                        $arr['property_id'] = $property['id'];
                        $arr['use_total_score_count'] = $property_info['use_total_score_count'];
                        $arr['use_total_money'] = $property_info['use_total_money'];
                        if ($arr['max_presented_property_month']) {
                            $arr['presented_property_month_num'] = $arr['max_presented_property_month'];
                            $arr['presented_property_month_num_desc'] = '送' . $arr['max_presented_property_month'] . '个月';
                            unset($arr['max_presented_property_month']);
                        } else {
                            unset($arr['max_presented_property_month']);
                            $arr['presented_property_month_num'] = 0;
                            $arr['presented_property_month_num_desc'] = '';
                        }
                        $this->returnCode(0, $arr);

                    } else {

                        $arr['diy_content'] = $property['diy_content'];
                        $arr['total_price'] = getFormatNumber($total_price);
                        $arr['diy_type'] = 1;
                        $arr['property_id'] = $property['id'];
                        $arr['use_total_score_count'] = $property_info['use_total_score_count'];
                        $arr['use_total_money'] = $property_info['use_total_money'];

                        $this->returnCode(0, $arr);
                    }
                } elseif ($diy_propertyt_month_num >= $property['property_month_num']) {
                    if ($property['diy_type'] == 0) {

                        $arr['max_presented_property_month'] = $property['presented_property_month_num'];
                        $arr['total_price'] = getFormatNumber($total_price);
                        $arr['diy_type'] = 0;
                        $arr['property_id'] = $property['id'];
                        $arr['use_total_score_count'] = $property_info['use_total_score_count'];
                        $arr['use_total_money'] = $property_info['use_total_money'];
                        if ($arr['max_presented_property_month']) {
                            $arr['presented_property_month_num'] = $arr['max_presented_property_month'];
                            $arr['presented_property_month_num_desc'] = '送' . $arr['max_presented_property_month'] . '个月';
                            unset($arr['max_presented_property_month']);
                        } else {
                            unset($arr['max_presented_property_month']);
                            $arr['presented_property_month_num'] = 0;
                            $arr['presented_property_month_num_desc'] = '';
                        }

                        $this->returnCode(0, $arr);

                    } else {

                        $arr['diy_content'] = $property['diy_content'];
                        $arr['total_price'] = getFormatNumber($total_price);
                        $arr['diy_type'] = 1;
                        $arr['property_id'] = $property['id'];
                        $arr['use_total_score_count'] = $property_info['use_total_score_count'];
                        $arr['use_total_money'] = $property_info['use_total_money'];
                        $this->returnCode(0, $arr);
                    }
                }
            }

            $arr['max_presented_property_month'] = 0;
            $arr['total_price'] = getFormatNumber($total_price);
            $arr['diy_type'] = 0;
            $arr['use_total_score_count'] = $property_info['use_total_score_count'];
            $arr['use_total_money'] = $property_info['use_total_money'];
            if ($arr['max_presented_property_month'] == 0) {
                unset($arr['max_presented_property_month']);
                $arr['presented_property_month_num'] = 0;
                $arr['presented_property_month_num_desc'] = '';
            }
            $this->returnCode(0, $arr);
        } else {
            $arr['max_presented_property_month'] = 0;
            $arr['total_price'] = getFormatNumber($total_price);
            $arr['diy_type'] = 0;
            $arr['use_total_score_count'] = $property_info['use_total_score_count'];
            $arr['use_total_money'] = $property_info['use_total_money'];
            if ($arr['max_presented_property_month'] == 0) {
                unset($arr['max_presented_property_month']);
                $arr['presented_property_month_num'] = 0;
                $arr['presented_property_month_num_desc'] = '';
            }
            $this->returnCode(0, $arr);
        }


    }


    public function property_go_pay()
    {
        $base_url = D('House_village')->base_url;
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $now_village = $this->get_village($village_id);

        $now_user_info = $this->get_user_village_info($pigcms_id, $village_id, $this->_uid);//==>郭先森==>获取当前社区我的信息

        //家属 获取业主的欠费信息
        if ($now_user_info['parent_id']) {
            $now_user_info = $this->get_user_village_info($now_user_info['parent_id'], $village_id, $this->_uid);
        }
        if (empty(I('money'))) {
            $this->returnCode('20120048');
        }

        $pay_type = I('pay_type', 'property');
        $pay_name = $this->pay_list_type[$pay_type];//缴费类型
        if (empty($pay_name)) {
            $this->returnCode('20120011');
        }

        if (empty($now_village['property_price'])) {
            $this->returnCode('20120012');//不支持缴纳物业费===>郭先森
        }
        if (I('property_month_num') > 36 || I('property_month_num') <= 0) {
            $this->returnCode('20090207');
        }

        $order_list = D('House_village_user_paylist')->field('`ydate`,`mdate`,`property_price` AS `price`')->where(array('usernum' => $now_user_info['usernum']))->order('`pigcms_id` DESC')->select();
        foreach ($order_list as $key => $value) {
            $order_list[$key]['desc'] = '物业费 ' . floatval($value['price']) . C('config.Currency_txt') . '';
        }
        if ($now_user_info['floor_id']) {
            $database_house_village_floor = D('House_village_floor');

            $floor_where['status'] = 1;
            $floor_where['floor_id'] = $now_user_info['floor_id'];
            $floor_info = $database_house_village_floor->where($floor_where)->find();
            if ($floor_info['property_fee'] != '0.00') {
                $now_user_info['property_fee'] = $floor_info['property_fee'];
            } else {
                $village_info = D('House_village')->where(array('village_id' => $now_village['village_id']))->find();
                $now_user_info['property_fee'] = $village_info['property_price'];
            }
            $database_house_village_floor_type = D('House_village_floor_type');

            $type_where['status'] = 1;
            $type_where['id'] = $floor_info['floor_type'];
            if ($floor_type_name = $database_house_village_floor_type->where($type_where)->getField('name')) {
                $now_user_info['floor_type_name'] = $floor_type_name;
            } else {
                $now_user_info['floor_type_name'] = '暂无';
            }
        } else {
            $village_info = D('House_village')->where(array('village_id' => $now_village['village_id']))->find();
            $now_user_info['property_fee'] = $village_info['property_price'];
        }
        $data_order['order_name'] = $pay_name;
        $data_order['property_month_num'] = intval(I('property_month_num') + 0);
        $data_order['money'] = I('money') + 0;
        $data_order['house_size'] = $now_user_info['housesize'] ? $now_user_info['housesize'] : '0.00';
        $data_order['property_fee'] = $now_user_info['property_fee'] ? $now_user_info['property_fee'] : '0.00';
        $data_order['floor_type_name'] = $now_user_info['floor_type_name'] ? $now_user_info['floor_type_name'] : '';


        $data_order['uid'] = $this->_uid;
        $data_order['bind_id'] = $now_user_info['pigcms_id'];
        $data_order['village_id'] = $now_village['village_id'];
        $data_order['time'] = $_SERVER['REQUEST_TIME'];
        $data_order['paid'] = 0;
        $data_order['order_type'] = $pay_type;
        if($now_user_info['property_endtime'] < time()) {
            $data_order['is_owe'] = 1;
        }


        if (I('house_village_property_id')) {
            $database_house_village_property = D('House_village_property');

            $property_where['status'] = 1;
            $property_where['id'] = I('house_village_property_id');
            $house_village_property_info = $database_house_village_property->house_village_property_detail($property_where);
            if (!$house_village_property_info['status']) {
                $this->returnCode('20120012');
            } else {
                $house_village_property_info = $house_village_property_info['detail'];
                $data_order['diy_type'] = $house_village_property_info['diy_type'];
                if ($house_village_property_info['diy_type'] == 1) {
                    $data_order['diy_content'] = $house_village_property_info['diy_content'];
                } else {
                    $data_order['presented_property_month_num'] = intval(I('presented_property_month_num') + 0);
                }
            }
        } else {
            $data_order['presented_property_month_num'] = intval(I('presented_property_month_num') + 0);
        }


        $userinfo = D('User')->get_user($this->_uid);

        $property_info = D('House_village_pay_order')->get_score($data_order, $userinfo);
        $data_order['score_can_use'] = $property_info['use_total_score_count'];
        $data_order['score_can_pay'] = $property_info['use_total_money'];
        $data_order['score_percent'] = $property_info['score_percent'];
        $data_order['score_can_get'] = $property_info['generate_integral'];

        $score_data['score'] = $property_info['use_total_score_count'];
        $score_data['desc'] = "缴纳" . $data_order['order_name'] . " " . I('money') . C('config.Currency_txt') . " 支出积分";
        $score_data['generate_integral'] = $property_info['generate_integral'];
        $score_data['generate_integral_desc'] = "缴纳" . $data_order['order_name'] . " " . I('money') . C('config.Currency_txt') . " 增加积分";

        if ($order_id = D('House_village_pay_order')->data($data_order)->add()) {
            $arr = [];
            //$arr['order_url'] = $this->config['site_url'] .'/wap.php?g=Wap&c=House&a=pay_order&order_id='.$order_id.'&village_id='.$village_id.'&score='.$score_data['score'].'&desc='.$score_data['desc'] .'&generate_integral='.$score_data['generate_integral'].'&generate_integral_desc='.$score_data['generate_integral_desc'];
//            $arr['order_id'] = $order_id;
//            $arr['village_id'] = $village_id;
//            $arr['score'] = $score_data['score'];
//            $arr['desc'] = $score_data['desc'];
//            $arr['generate_integral'] = $score_data['generate_integral'];
//            $arr['generate_integral_desc'] = $score_data['generate_integral_desc'];

            //添加到订单，直接支付
            $now_order = D('House_village_pay_order')->field(true)->where(array('order_id' => $order_id))->find();
            $pay_order_param = array(
                'business_type' => 'house_village_pay',
                'business_id' => $now_order['order_id'],
                'order_name' => $now_order['order_name'],
                'uid' => $now_order['uid'],
                'total_money' => $now_order['money'],
                'wx_cheap' => 0,
            );
            if ($this->config['open_village_sub_mchid'] && $now_village['sub_mch_id']) {
                $pay_order_param['is_own'] = 5;
            } else {
                $pay_order_param['is_own'] = 4;

            }

            $plat_order_result = D('Plat_order')->add_order($pay_order_param);
            if ($plat_order_result['error_code']) {
                $this->returnCodeError($plat_order_result['error_msg']);
            }
            $arr['type'] = 'plat';
            $arr['order_id'] = $plat_order_result['order_id'];
            $arr['order_url'] = $this->config['site_url'] . $base_url . 'pages/shop_new/confirmOrder/pay?order_id=' . $plat_order_result['order_id'] . '&type=plat';
            $this->returnCode(0, $arr);

        } else {
            $this->returnCode('40000002');
        }


    }


    #计算是否使用积分 -
    public function ajax_integral_info($total_price, $use_max_integral_percentage, $use_max_integral_num, $moneytointegral, $user_score_count)
    {

        /****************************************************************
         * $total_price 总价格
         * $use_max_integral_percentage 使用最大积分占总额百分比
         * $use_max_integral_num 允许使用的最大积分
         * $moneytointegral 多少积分抵扣一元
         * $user_score_count 用户总共多少积分
         ****************************************************************/
        if ($user_score_count <= 0) {
            $property_info['use_total_score_count'] = 0;
            $property_info['use_total_money'] = 0;
            return $property_info;
        }
        if ($use_max_integral_percentage > 0) { //使用最大百分比

            //得到最大抵扣金额
            $max_use_price = sprintf("%.2f", $total_price * $use_max_integral_percentage / 100);

            //计算可以使用多少积分
            $use_total_score_count = floor($max_use_price * $moneytointegral);

            //这里计算用户应该支出的积分  和 应该抵扣的钱  和 要支付的钱
            if ($user_score_count < $use_total_score_count) {

                $property_info['use_total_money'] = sprintf("%.2f", $user_score_count / $moneytointegral);
                $property_info['use_total_score_count'] = $property_info['use_total_money'] * $moneytointegral;

            } else {
                $property_info['use_total_money'] = $max_use_price;
                $property_info['use_total_score_count'] = $use_total_score_count;

            }


        } elseif ($use_max_integral_num > 0) { //使用最大积分

            if ($use_max_integral_num < $user_score_count) {
                $property_info['use_total_money'] = sprintf("%.2f", $use_max_integral_num / $moneytointegral);
                $property_info['use_total_score_count'] = $property_info['use_total_money'] * $moneytointegral;
            } else {
                $property_info['use_total_money'] = sprintf("%.2f", $user_score_count / $moneytointegral);
                $property_info['use_total_score_count'] = $property_info['use_total_money'] * $moneytointegral;
            }

            if ($property_info['use_total_money'] > $total_price) { // 可抵扣金额大于支付金额
                $property_info['use_total_money'] = $total_price;
                $property_info['use_total_score_count'] = $total_price * $moneytointegral;
            }

        } else { // 否则不计算
            $property_info['use_total_score_count'] = 0;
            $property_info['use_total_money'] = 0;

        }
        return $property_info;

    }


    public function village_my_pay()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $now_village = $this->get_village($village_id);

        $now_user_info = $this->get_user_village_info($pigcms_id, $village_id, $this->_uid);//==>郭先森==>获取当前社区我的信息
        //家属 获取业主的欠费信息
        if ($now_user_info['parent_id']) {
            $now_user_info = $this->get_user_village_info($now_user_info['parent_id'], $village_id, $this->_uid);
        }
        // 楼层信息
        $now_floor = D('House_village_floor')->get_floor_info($now_user_info['floor_id']);

        //缴费
        $pay_list = array();
        $now_village['property_price'] = getFormatNumber($now_village['property_price']);
        $now_village['water_price'] = getFormatNumber($now_village['water_price']);
        $now_village['electric_price'] = getFormatNumber($now_village['electric_price']);
        $now_village['gas_price'] = getFormatNumber($now_village['gas_price']);
        $now_village['park_price'] = getFormatNumber($now_village['park_price']);

        // 计算欠缴物业费
        $standard_id = M('House_village_property_standard_bind')->where(['pigcms_id'=>$now_user_info['vacancy_id'],'is_del'=>1])->field('standard_id')->find();
        if(!$standard_id['standard_id']){
            $property_price = 0;
        }elseif ($now_user_info['property_endtime'] && $now_user_info['property_endtime'] < time()){
            /*$num = D('House_village_user_bind')->getTimeNum($now_user_info['property_endtime'], strtotime(date("Y-m-d")), 'M');
            if (floatval($now_floor['property_fee'])>0) {
                $property_price = floatval($now_floor['property_fee']) * floatval($now_user_info['housesize']) * floatval($num);
            } else {
                $property_price = floatval($now_village['property_price']) * floatval($now_user_info['housesize']) * floatval($num);
            }*/
            $date = M('House_village_property_standard')->where(['id'=>$standard_id['standard_id']])->field('date_month')->find();
            $num = D('House_village_user_bind')->getMonthNum($now_user_info['property_endtime'] + 1, time());
            if(date('d',time()) > date('d',$now_user_info['property_endtime'] + 1))
                $num+=1;
            $start_time = strtotime(date('Y-m',$now_user_info['property_endtime']));
            $dateMonth[] = $start_time;
            for ($i=1;$i<$num;$i++){
                $dateMonth[] = strtotime("+ $i month",$start_time);
            }
            $property_price = $this->property_price($dateMonth,unserialize($date['date_month']),$now_user_info['housesize']);
        }else{
            $property_price = 0;
        }
        if ($standard_id['standard_id'] || $property_price>0) {
            $pay_list[] = array(
                'type' => 'property',
                'name' => $this->pay_list_type['property'],
                'money' => floatval($property_price)?getFormatNumber($property_price):0,
                'bind_id' => 0,
                'paid_cycle' => 0,
                'property_month_num'=> count($dateMonth)?count($dateMonth):0,
            );
        }

        if ($now_village['water_price'] || $now_user_info['water_price']) {
            $pay_list[] = array(
                'type' => 'water',
                'name' => $this->pay_list_type['water'],
                'money' => floatval($now_user_info['water_price'])?getFormatNumber($now_user_info['water_price']):0,
                'bind_id' => 0,
                'paid_cycle' => 0,
            );
        }
        if ($now_village['electric_price'] || $now_user_info['electric_price']) {
            $pay_list[] = array(
                'type' => 'electric',
                'name' => $this->pay_list_type['electric'],
                'money' => floatval($now_user_info['electric_price'])?getFormatNumber($now_user_info['electric_price']):0,
                'bind_id' => 0,
                'paid_cycle' => 0,
            );
        }
        if ($now_village['gas_price'] || $now_user_info['gas_price']) {
            $pay_list[] = array(
                'type' => 'gas',
                'name' => $this->pay_list_type['gas'],
                'money' => floatval($now_user_info['gas_price'])?getFormatNumber($now_user_info['gas_price']):0,
                'bind_id' => 0,
                'paid_cycle' => 0,
            );
        }
        $parkConfigWhere=array('village_id'=>$village_id);
        $parkConfigWhere['park_versions']=2;
        $park_garage_config=D('House_village_park_garage_config')->getVillageParkConfigByWhere($parkConfigWhere);
        if(!empty($park_garage_config) && $park_garage_config['park_versions'] == 2){
            //新版
            $pay_list[] = array(
                'type' => 'new_park',
                'name' => '停车费',
                'money' => 0,
                'bind_id' => 0,
                'paid_cycle' => 0,
            );
        }else{
            //老版
            if ($now_village['park_price'] || $now_user_info['park_price']) {
                $pay_list[] = array(
                    'type' => 'park',
                    'name' => $this->pay_list_type['park'],
                    'money' => floatval($now_user_info['park_price'])?getFormatNumber($now_user_info['park_price']):0,
                    'bind_id' => 0,
                    'paid_cycle' => 0,
                );
            }
        }



        $payment_list = D('')->table(array(C('DB_PREFIX') . 'house_village_payment_standard_bind' => 'psb',
            C('DB_PREFIX') . 'house_village_payment_standard' => 'ps',
            C('DB_PREFIX') . 'house_village_payment' => 'p'))
            ->where("psb.pigcms_id= '" . $now_user_info['pigcms_id'] . "' AND p.payment_id = psb.payment_id AND ps.standard_id = psb.standard_id AND psb.village_id=$village_id")->select();
        $payment_list = $payment_list ? $payment_list : array();

        // 车位缴费
        $position_payment_list = D('House_village_bind_position')->get_user_position_payment_list(array('pigcms_id' => $now_user_info['pigcms_id']));
        if ($position_payment_list) {
            $payment_list = array_merge($payment_list, $position_payment_list);
        }
        $cycle_type = array('Y' => 'year', 'M' => 'month', 'D' => 'day');
        foreach ($payment_list as $kk => $value) {
            if ($value['garage_num']) {
                $payment_list[$kk]['payment_name'] = $value['payment_name'] . '(' . $value['garage_num'] . '-' . $value['position_num'] . ')';
            }

            $payment_list[$kk]['pay_icon'] = file_domain() . $value['pay_icon'];

            if ($value['cycle_sum'] - $value['paid_cycle'] <= 0) {
                // 签订周期已缴完
                unset($payment_list[$kk]);
                continue;
            }

            switch ($value['cycle_type']) {
                case 'Y':
                    $end_time = $value['start_time'] + $value['pay_cycle']*$value['paid_cycle']*86400*365;
                    break;
                case 'M':
                    $end_time = $value['start_time'] + $value['pay_cycle']*$value['paid_cycle']*86400*30;
                    break;
                case 'D':
                    $end_time = $value['start_time'] + $value['pay_cycle']*$value['paid_cycle']*86400;
                    break;
            }
            if ($end_time < time()) {
                $num = D('House_village_user_bind')->getTimeNum($end_time, time(), $value['cycle_type']);
                $num = ceil($num / $value['pay_cycle']);
                $num = min($num, $value['cycle_sum']);
                $payment_list[$kk]['num'] = $num;
                if ($value['pay_type'] == 1) {
                    $payment_list[$kk]['money'] = round($value['pay_money'] * $num, 2);
                } else {
                    $payment_list[$kk]['money'] = round($value['pay_money'] * $num * $value['metering_mode_val'], 2);
                }
            } else {
                $payment_list[$kk]['num'] = 0;
                $payment_list[$kk]['money'] = 0;

            }
        }
        // $arr['payment_list'] = $payment_list;

        $dataList = [];
        foreach ($payment_list as $k => $v) {
            $dataList[] = array(
                'type' => 'custom_payment',
                'name' => $v['payment_name'],
                'money' => $v['money'],
                'bind_id' => $v['bind_id'],
                'paid_cycle' => $v['num'],
            );
        }
        $payment_list = array_merge($pay_list, $dataList);

        $arr['pay_list'] = $payment_list;

        if($now_village['has_custom_pay'] == 1){
            $arr['has_custom_pay'] = true;
        }else{
            $arr['has_custom_pay'] = false;
        }
        $this->returnCode(0, $arr);
    }

