        $property_info = D('House_village_pay_order')->get_score($data_order, $userinfo);
        $data_order['score_can_use'] = $property_info['use_total_score_count'];
        $data_order['score_can_pay'] = $property_info['use_total_money'];
        $data_order['score_percent'] = $property_info['score_percent'];
        $data_order['score_can_get'] = $property_info['generate_integral'];

        $score_data['score'] = $property_info['use_total_score_count'];
        $score_data['desc'] = "缴纳" . $data_order['order_name'] . " " . I('money') . C('config.Currency_txt') . " 支出积分";
        $score_data['generate_integral'] = $property_info['generate_integral'];
        $score_data['generate_integral_desc'] = "缴纳" . $data_order['order_name'] . " " . I('money') . C('config.Currency_txt') . " 增加积分";

        if ($order_id = D('House_village_pay_order')->data($data_order)->add()) {
            $arr = [];
            // $arr['order_url'] = $this->config['site_url'] . '/wap.php?g=Wap&c=House&a=pay_order&order_id=' . $order_id . '&village_id=' . $village_id . '&score=' . $score_data['score'] . '&desc=' . $score_data['desc'] . '&generate_integral=' . $score_data['generate_integral'] . '&generate_integral_desc=' . $score_data['generate_integral_desc'];
            // $this->returnCode(0, $arr);
            //添加到订单，直接支付
            $now_order = D('House_village_pay_order')->field(true)->where(array('order_id' => $order_id))->find();
            $pay_order_param = array(
                'business_type' => 'house_village_pay',
                'business_id' => $now_order['order_id'],
                'order_name' => $now_order['order_name'],
                'uid' => $now_order['uid'],
                'total_money' => $now_order['money'],
                'wx_cheap' => 0,
            );
            if ($this->config['open_village_sub_mchid'] && $now_village['sub_mch_id']) {
                $pay_order_param['is_own'] = 5;
            } else {
                $pay_order_param['is_own'] = 4;

            }

            $plat_order_result = D('Plat_order')->add_order($pay_order_param);
            if ($plat_order_result['error_code']) {
                $this->returnCodeError($plat_order_result['error_msg']);
            }
            $base_url = D('House_village')->base_url;
            $arr['type'] = 'plat';
            $arr['order_id'] = $plat_order_result['order_id'];
            $arr['order_url'] = $this->config['site_url'] . $base_url . 'pages/shop_new/confirmOrder/pay?order_id=' . $plat_order_result['order_id'] . '&type=plat';
            $this->returnCode(0, $arr);
        } else {
            $this->returnCode('40000002');
        }

    }

    //已缴费处理
    public function village_my_paylist()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $now_village = $this->get_village($village_id);

        $now_user_info = $this->get_user_village_info($pigcms_id, $village_id, $this->_uid);//==>郭先森==>获取当前社区我的信息

        //家属 获取业主的欠费信息
        if ($now_user_info['parent_id']) {
            $now_user_info = $this->get_user_village_info($now_user_info['parent_id'], $village_id, $this->_uid);
        }
        $arr = [];

        $pay_list_type[0] = array(
            'type' => 'all',
            'name' => '全部'
        );
        $pay_list_type[1] = array(
            'type' => 'property',
            'name' => '物业费'
        );
        $pay_list_type[2] = array(
            'type' => 'water',
            'name' => '水费'
        );
        $pay_list_type[3] = array(
            'type' => 'electric',
            'name' => '电费'
        );
        $pay_list_type[4] = array(
            'type' => 'gas',
            'name' => '燃气费'
        );
        $pay_list_type[5] = array(
            'type' => 'park',
            'name' => '停车费'
        );
        $pay_list_type[6] = array(
            'type' => 'custom',
            'name' => '其他缴费'
        );
        $pay_list_type[7] = array(
            'type' => 'custom_payment',
            'name' => '自定义缴费'
        );
        if ($pay_list_type) {
            // 查询下单元信息
            foreach ($pay_list_type as $k => $v) {
                $floor_id = $now_user_info['floor_id'];
                $d_house_village_floor = M('House_village_floor');
                $house_village_floor = $d_house_village_floor->where(array('floor_id' => $floor_id))->field('property_fee, water_fee, electric_fee, gas_fee, parking_fee')->find();
                if ($now_village['property_price'] <= 0 && $house_village_floor['property_fee'] <= 0) {
                    // 社区和单元均无物业价格去除物业类型
                    // unset($pay_list_type['property']);
                    unset($pay_list_type[1]);
                }
                if ($now_village['water_price'] <= 0 && $house_village_floor['water_fee'] <= 0) {
                    // 社区和单元均无水费价格去除水费类型
                    // unset($pay_list_type['water']);
                    unset($pay_list_type[2]);
                }
                if ($now_village['electric_price'] <= 0 && $house_village_floor['electric_fee'] <= 0) {
                    // 社区和单元均无电费价格去除电费类型
                    // unset($pay_list_type['electric']);
                    unset($pay_list_type[3]);
                }
                if ($now_village['gas_price'] <= 0 && $house_village_floor['gas_fee'] <= 0) {
                    // 社区和单元均无燃气价格去除燃气类型
                    //unset($pay_list_type['gas']);
                    unset($pay_list_type[4]);
                }
                if ($now_village['park_price'] <= 0 && $house_village_floor['parking_fee'] <= 0) {
                    // 社区和单元均无	停车位价格去除	停车位类型
                    //unset($pay_list_type['park']);
                    unset($pay_list_type[5]);
                }
                if ($now_village['has_property_pay'] == 0) {
                    // 禁止自定义缴费  去除自定义缴费
                    //unset($pay_list_type['custom_payment']);
                    unset($pay_list_type[6]);
                }
                if ($now_village['has_custom_pay'] == 0) {
                    // 禁止临时缴费  去除临时缴费
                    //unset($pay_list_type['custom']);
                    unset($pay_list_type[7]);
                }
            }

        }

        $pay_list_type = array_values($pay_list_type);
        $arr['pay_type_list'] = $pay_list_type;

        $arr['has_custom_pay'] = $now_village['has_custom_pay'];
        $this->returnCode(0, $arr);
    }

    public function village_my_pay_list()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $order_type = I('order_type', 'all');
        $aPage = I('page', 1);
        $now_village = $this->get_village($village_id);

        $now_user_info = $this->get_user_village_info($pigcms_id, $village_id, $this->_uid);//==>郭先森==>获取当前社区我的信息

        //家属 获取业主的欠费信息
        if ($now_user_info['parent_id']) {
            $now_user_info = $this->get_user_village_info($now_user_info['parent_id'], $village_id, $this->_uid);
        }

        //显示自己所缴费用 业主显示房屋所有缴

        if($_GET['village_type'] == 'new'){
            $field = 'o.*,`p`.`start_time`,`p`.`end_time`,`r`.`e_record_id`';
            $join = 'left join ' . C('DB_PREFIX') . 'house_village_detail_record as `r` on o.order_id=r.order_id';
            $order = 'o.order_id desc';
            $where = '`o`.`is_paid`=1 AND (`o`.`pay_bind_id`=' . $now_user_info['pigcms_id'] . ') AND `o`.`village_id`=' . $now_village['village_id'];
            $order_list = D('House_new_pay_order')->alias('`o`')->field($field)->join($join)->where($where)->page($aPage, 20)->order($order)->select();
        }else{
            $field = 'o.*,`r`.`e_record_id`';
            $join = 'left join ' . C('DB_PREFIX') . 'house_village_property_paylist as `p` on o.order_id=p.order_id';
            $join1 = 'left join ' . C('DB_PREFIX') . 'house_village_detail_record as `r` on o.order_id=r.order_id';
            $order = 'o.order_id desc';
            $where = '`o`.`paid`=1 AND (`o`.`bind_id`=' . $now_user_info['pigcms_id'] . ') AND `o`.`village_id`=' . $now_village['village_id'];

            if ($order_type != 'all') {
                $where .= ' AND `o`.`order_type`="' . $order_type . '"';
            }
            $where .= ' AND `o`.`order_type` != "all"';
            $order_list = D('House_village_pay_order')->alias('`o`')->field($field)->join($join)->join($join1)->where($where)->page($aPage, 20)->order($order)->select();
        }
        $is_open_e = $this->is_open_e($village_id,'is_open,is_tui');
        $dataList = [];
        foreach ($order_list as $Key => $value) {
            if(empty($is_open_e))
                $list['is_show'] = 2;
            elseif($is_open_e['is_open'] == 1 && empty($value['e_record_id']) && $is_open_e['is_tui'] == 2)
                $list['is_show'] = 1;
            else
                $list['is_show'] = 2;
            $list['order_id'] = $value['order_id'];
            $list['order_name'] = $value['order_name'];
            $list['order_type'] = $value['order_type'];
            $list['money'] = $value['money'];
            $list['time'] = date('Y-m-d H:i', $value['pay_time']);
            if($_GET['village_type'] == 'new'){
                if($value['is_refund'] == 2)
                    $list['order_name'] .= '（已退款）';
            }else{
                if($value['order_status'] == 2)
                    $list['order_name'] .= '（已退款）';
            }
            $dataList[] = $list;
        }
        //判断小区是否开启电子发票功能
        //$is_open_e = $this->is_open_e($village_id,'is_open,is_tui');
        if(empty($is_open_e['is_tui']) || $is_open_e['is_tui'] == 1)
            $is_open = 2;
        else
            $is_open = $is_open_e['is_open'];
        $arr = [];
        $arr['order_list'] = $dataList;
        $arr['is_show'] = $is_open;
        $this->returnCode(0, $arr);
    }

    public function village_my_pay_info()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $order_id = I('order_id', '');
        if (empty($order_id)) {
            $this->returnCode('20130006');
        }
        $now_village = $this->get_village($village_id);

        $now_user_info = $this->get_user_village_info($pigcms_id, $village_id, $this->_uid);//==>郭先森==>获取当前社区我的信息

        //家属 获取业主的欠费信息
        if ($now_user_info['parent_id']) {
            $now_user_info = $this->get_user_village_info($now_user_info['parent_id'], $village_id, $this->_uid);
        }
        if($now_user_info['vacancy_id']){
            $date_month = M('House_village_property_standard_bind')
                ->join('AS sb LEFT JOIN '.C('DB_PREFIX').'house_village_property_standard AS s ON s.id = sb.standard_id')
                ->where(['sb.pigcms_id'=>$now_user_info['vacancy_id'],'is_del'=>1])
                ->getField('s.date_month');
            if(!empty($date_month)){
                $date_month = unserialize($date_month);
                $property_fee = array();
                foreach ($date_month as $k1=>$v1){
                    $property_fee[] = $v1['price'].'元/平方米/月--'.$v1['date_month'];
                }
            }else{
                $property_fee = array();
            }
        }else{
            $property_fee = array();
        }
        $now_floor = D('House_village_floor')->get_floor_info($now_user_info['floor_id']);
        //显示自己所缴费用 业主显示房屋所有缴
        $arr = [];
        $field = 'o.*,`p`.`start_time`,`p`.`end_time`';
        $join = 'left join ' . C('DB_PREFIX') . 'house_village_property_paylist as `p` on o.order_id=p.order_id';
        $order = 'o.order_id desc';
        $where = '`o`.`paid`=1 AND (`o`.`uid` = ' . $now_user_info['uid'] . ' OR `o`.`bind_id`=' . $now_user_info['pigcms_id'] . ') AND `o`.`village_id`=' . $now_village['village_id'];
        $order_info = D('House_village_pay_order')->alias('`o`')->field($field)->join($join)->where($where)->where(array('o.order_id' => $order_id))->order($order)->find();

        if ($order_info) {
            if($order_info['cashier_id']){
                $cashier_info = D('House_village_pay_cashier_order')->get_one($order_info['cashier_id']);
                $cashier_order_list = M('House_village_pay_order')->where(['cashier_id'=>$order_info['cashier_id']])->select();
                $order_all_money = 0;
                foreach ($cashier_order_list as $v){
                    $order_all_money += $v['money'];
                }
                $order_info['money'] = sprintf("%.2f",($order_info['money']/$order_all_money)* $cashier_info['money']);
            }
            // 业主信息
            $arr['money_num'] = '-' . $order_info['money'] . C('config.Currency_txt');
            if ($order_info['order_type'] != 'custom_payment') {
                $arr['image'] = $this->config['site_url'] . "/static/images/house/" . $order_info['order_type'] . ".png";
            } else {
                $standard_bind = M('house_village_payment_standard_bind')->where(array('bind_id' => $order_info['payment_bind_id']))->find();
                $standard = M('House_village_payment_standard')->where(array('standard_id' => $standard_bind['standard_id']))->find();
                $arr['image'] = file_domain() . $standard['pay_icon'];
            }
            $user_info = D('House_village_user_bind')->where(array('pigcms_id' => $order_info['bind_id']))->find();
            if($user_info['single_id'] && $user_info['floor_id'] && $user_info['vacancy_id'] && $user_info['layer_num'] && $user_info['village_id']){
                $user_info['address'] = D('House_village')->get_single_floor_room($user_info['single_id'],$user_info['floor_id'],$user_info['layer_num'],$user_info['vacancy_id'],$user_info['village_id']);
            }

            $menus_list = [];
            if ($order_info['order_name']) {
                $menus_list[] = array(
                    'name' => '缴费项目',
                    'value' => $order_info['order_name'],
                );
            }
            if ($order_info['time']) {
                $menus_list[] = array(
                    'name' => '缴费时间',
                    'value' => date('Y-m-d H:i', $order_info['pay_time']),
                );
            }
            if($order_info['pay_cost_type'] != ''){
                if($order_info['pay_cost_type'] == 1)
                {
                    $pay_cost_type = '积分抵扣';
                }else{
                    $pay_cost_type = '业主缴费';
                }
                $menus_list[] = array(
                    'name' => '缴费类型',
                    'value' => $pay_cost_type,
                );
            }
            if ($user_info['address']) {
                $menus_list[] = array(
                    'name' => '缴费房间',
                    'value' => D('House_village')->get_single_floor_room($user_info['single_id'],$user_info['floor_id'],$user_info['layer_id'],$user_info['vacancy_id'],$user_info['village_id']),
                );
            }
            if ($order_info['money']) {
                $menus_list[] = array(
                    'name' => '账单金额',
                    'value' => $order_info['money'] . C('config.Currency_txt'),
                );
            }
            if($order_info['pay_cost_type'] == 1)
            {
                $menus_list[] = array(
                    'name' => '积分抵扣数量',
                    'value' => $order_info['score_can_pay'],
                );
            }
            if($order_info['order_type'] == 'property'){
                if ($order_info['house_size']) {
                    $menus_list[] = array(
                        'name' => '房屋面积',
                        'value' => $order_info['house_size'] . '平方米',
                    );
                }
                if ($order_info['property_fee']) {
                    $menus_list[] = array(
                        'name' => '物业单价',
                        'type'=>1,
                        'value' => $property_fee,
                    );
                }
            }
            //优化 start
            if(in_array($order_info['order_type'],['water','electric','gas']))
            {
                $return_data = $this->meterReading($user_info['vacancy_id'],$village_id,$pigcms_id,$order_info['order_type']);
                $water_price=0;
                if ($now_floor['water_fee'] != 0) {
                    $water_price=$now_floor['water_fee'];
                } else {

                    $water_price=$now_village['water_price'];
                }
                $dosage=0;
                if($water_price>0){
                    $dosage=$order_info['money']/$water_price;
                    $dosage=round($dosage,2);
                }
                if($dosage>0){
                    $menus_list[] = array(
                        'name' => '用量',
                        'value' => $dosage,
                    );
                }
                $menus_list[] = array(
                    'name' => '公摊',
                    'value' => $return_data['pool_ammeter'],
                );
                $menus_list[] = array(
                    'name' => '倍率',
                    'value' => $return_data['rate'],
                );
            }
            //优化 end

            $list = $menus_list;

        } else {
            $list = [];
        }
        $is_open_e = $this->is_open_e($village_id,'is_open,is_tui');
        $is_record = $this->is_record($order_id);
        if(empty($is_open_e))
            $arr['is_show'] = 2;
        elseif($is_open_e['is_open'] == 1 && $is_record == 1 && $is_open_e['is_tui'] == 2)
            $arr['is_show'] = 1;
        else
            $arr['is_show'] = 2;
        $arr['order'] = $list;
        $this->returnCode(0, $arr);
    }

    /**
     * 判断相应的订单id是否已开电子发票
     * @author lijie
     * @date_time 2020/07/06
     * @param $order_id
     * @return mixed
     */
    public function is_record($order_id)
    {
        $e_record = D('House_village_detail_record');
        $where['order_id'] = $order_id;
        $is_record = $e_record->is_record($where);
        return $is_record;
    }

    //详情
    public function village_activity()
    {
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        $now_village = $this->get_village($village_id);
        if ($now_village['has_activity']) {
            $database_house_village_activity = D('House_village_activity');
            $where['id'] = I('activity_id') + 0;
            $where['status'] = 1;
            $now_activity = $database_house_village_activity->house_village_activity_detail($where);
            if ($now_activity['status'] == 0) {
                $this->returnCode('20120045');
            }
            $activity_detail = $now_activity['detail'];
            // 查询是否已报名
            $condition = array();
            $condition['user_bind_id'] = $this->_uid;
            $condition['activity_id'] = I('activity_id') + 0;
            $condition['is_del']=0;
            $exist_activity = D('House_village_activity_apply')->where($condition)->count();
            foreach ($activity_detail['pic'] as &$v) {
                $v = file_domain() . '/upload/activity/' . $v;
            }
            $arr = [];
            $arr['pic'] = $activity_detail['pic'];
            $arr['title'] = $activity_detail['title'];
            if(getFormatNumber($activity_detail['apply_fee'])){
                $arr['apply_fee'] = $activity_detail['apply_fee'] . C('config.Currency_txt');
            }else{
                $arr['apply_fee'] = '免费';
            }
            $arr['activity_start_time'] = date('Y-m-d', $activity_detail['activity_start_time']);
            $arr['activity_end_time'] = date('Y-m-d', $activity_detail['activity_end_time']);
            $arr['apply_end_time'] = date('Y-m-d', $activity_detail['apply_end_time']);
            if ($activity_detail['now_activity_apply_sum'] > 0) {
                $arr['now_activity_apply_sum'] = $activity_detail['now_activity_apply_sum'];
            } else {
                $arr['now_activity_apply_sum'] = 0;
            }
            $arr['activity_apply_remain_sum'] = $activity_detail['remain_num'];
            $arr['apply_limit_num'] = $activity_detail['apply_limit_num'];
            $arr['content'] = replace_file_domain_content_img($activity_detail['content']);

            if (time() <= ($activity_detail["apply_end_time"] + 86400)) {
                if ($exist_activity > 0 && $activity_detail["is_repeat_join"] == 0) {
                    $arr['status'] = 1;
                    $arr['statusDesc'] = '已报名';
                } else {
                    $arr['status'] = 2;
                    $arr['statusDesc'] = '我要报名';
                }
            } else {
                $arr['status'] = 3;
                $arr['statusDesc'] = '报名已截止';
            }
            $this->returnCode(0, $arr);
        } else {
            $this->returnCode('20120044');
        }
    }

    //报名
    public function village_activity_apply()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        $activity_id = I('activity_id');
        if (!$activity_id) {
            $this->returnCode('20090171');
        }

        $database_house_village_activity = D('House_village_activity');
        $where['id'] = $activity_id;
        $now_activity = $database_house_village_activity->house_village_activity_detail($where);
        $now_activity = $now_activity['detail'];
        if (!$now_activity) {
            $this->returnCode('20120045');
        }
        if (time() > $now_activity['apply_end_time'] + 86400) {
            $this->returnCode('20120046');
        }

        if ($now_activity['is_full']) {
            $this->returnCode('20120047');
        }

        $database_house_village_activity_apply = D('House_village_activity_apply');

        //判断是否可以重复报名
        if ($now_activity['is_repeat_join'] == 0) { // 不可重复报名
            $where = array();
            $where['phone'] = I('phone');
            $where['activity_id'] = $activity_id;
            $where['is_del']=0;
            $exist_activity = $database_house_village_activity_apply->where($where)->count();
            if ($exist_activity) {
                $this->returnCodeError('您当前不可以重复报名');
            }
        }
        $data['name'] = I('name');
        if (empty($data['name'])) {
            $this->returnCode('20046018');
        }
        $data['phone'] = I('phone');
        if (empty($data['phone'])) {
            $this->returnCode('20046019');
        }
        if (!C('config.international_phone') && !preg_match('/^[0-9]{11}$/', $data['phone'])) {
            $this->returnCodeError('请填写正确的手机号');
        }
        $data['apply_num'] = I('apply_num');
        if (empty($data['apply_num'])) {
            $this->returnCodeError('请填写报名人数');
        }
        $data['village_id'] = $village_id;
        $data['activity_id'] = $activity_id;
        $database_house_village_user_bind = D('House_village_user_bind');
        $database_house_village_activity = D('House_village_activity');

        $where['phone'] = $data['phone'];
        $where['type'] = ['in', [0,1,2,3]];
        $where['status'] = 1;
        $where['village_id'] = $data['village_id'];
        $bind_info = $database_house_village_user_bind->where($where)->find();
        if ($bind_info) {
            $data['user_bind_id'] = $bind_info['uid'];
        } else {
            $where_user = [
                'phone' => $data['phone'],
                'status' =>1
            ];
            $uid = M('User')->where($where_user)->getField('uid');
            if ($uid) {
                $data['user_bind_id'] = $uid;
            } else {
                $data['user_bind_id'] = $this->_uid;
            }
        }

        $Map['id'] = $data['activity_id'];
        $now_activity = $database_house_village_activity->house_village_activity_detail($Map);
        $now_activity = $now_activity['detail'];

        $apply_where['activity_id'] = $data['activity_id'];
        $apply_where['is_del'] = 0;
        $apply_where['apply_status'] = 1;
        $now_apply_sum = D('House_village_activity_apply')->where($apply_where)->sum('apply_num');
        if ($now_activity['apply_now_num']) {
            if ($data['apply_num'] > ($now_activity['apply_now_num'] - $now_apply_sum)) {
                $this->returnCodeError('超出单次报名人数限制');
            }
        } else if ($now_activity['apply_limit_num']) {
            if ($data['apply_num'] > ($now_activity['apply_limit_num'] - $now_apply_sum)) {
                $this->returnCodeError('当前报名人数已满');
            }
        }

        $data['apply_time'] = time();
        $data['village_id'] = $village_id;
        $data['apply_status'] = 1;
        $data['memo'] = I('memo');
        $insert_id = M('House_village_activity_apply')->data($data)->add();
        if ($insert_id) {
            $this->returnCodeOk(L_('报名成功'));
        } else {
            $this->returnCodeOk(L_('报名失败，请重试'));
        }
    }

    //快递代收
    public function express_service_list()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        $database_house_village_express = D('House_village_express');

        $has_express_service = $this->getHasConfig($village_id, 'has_express_service');
        if ($has_express_service) {
            $where['village_id'] = $village_id;
            $where['uid'] = $this->_uid;
            $list = $database_house_village_express->express_service_list($where);

            $arr1 = array('未取件', '已取件（业主)', '已取件（小区）');
            $paidDesc = array('未支付', '已支付');
            $dataList = [];
            $express_config = M('House_village_express_config')->where(array('village_id' => $village_id))->find();
            foreach ($list['list'] as $k => $v) {
                $model['id'] = $v['id'];
                $model['express_no'] = $v['express_no'];
                $model['status'] = $v['status'];
                $model['statusDesc'] = $arr1[$v['status']];
                $model['fetch_code'] = $v['fetch_code'];
                $model['express_name'] = $v['express_name'];
                $model['send_time'] = date('Y-m-d H:i:s', $v['order_info']['send_time']);
                $model['money'] = $v['money'] . C('config.Currency_txt');
                $model['price'] = $v['money'];
                $model['paid'] = $v['order_info']['paid'];
                $model['paidDesc'] = $paidDesc[$v['order_info']['paid']];
                $model['memo'] = $v['memo'];
                $model['add_time'] = date('Y-m-d H:i:s', $v['add_time']);
                $model['delivery_time'] = date('Y-m-d H:i:s', $v['delivery_time']);
                if (empty($v["order_info"]["paid"]) && $express_config["status"] == 1 && $v["status"] == 0) {
                    $model['expressDesc'] = '预约上门送件';
                    $model['expressStatus'] = 1;
                    $model['chk_express'] = '确认取件';
                    $model['chk_status'] = 1;

                } elseif (!empty($v["order_info"]) && ($v["order_info"]["paid"] == 1) && ($v["order_info"]["status"] == 0)) {
                    $model['expressDesc'] = '派送中';
                    $model['expressStatus'] = 2;
                    $model['chk_express'] = '确认取件';
                    $model['chk_status'] = 1;
                } else {
                    $model['expressDesc'] = '';
                    $model['expressStatus'] = 3;
                    $model['chk_express'] = '';
                    $model['chk_status'] = 3;
                }
                $dataList[] = $model;
            }

            $arr['list'] = $dataList;

            $this->returnCode(0, $arr);
        } else {
            $this->returnCode('20120019');
        }

    }

