    //预约取件
    public function express_appoint_add()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        $express_id = I('express_id');
        if(empty($express_id)){
            $this->returnCode('20090050');
        }
        $send_time = I('send_time');//送达时间
        if(empty($send_time)){
            $this->returnCode('20090212');
        }
        //业务处理
        $now_user = D('User')->get_user($this->_uid);
        if (empty($now_user)) {
            $this->returnCode('20045011');
        }
        $database_house_village_express_order = D('House_village_express_order');

        $order_where['express_id'] = $express_id;
        //$order_where['paid'] = 0;

        $now_order = $database_house_village_express_order->house_village_express_order_detail($order_where);
        $now_order = $now_order['detail'];
        $express_config = M('House_village_express_config')->where(array('village_id' => $village_id))->find();
        $time = strtotime($send_time);
        $start_time = strtotime(date('G:i:s', $express_config['start_time']));
        $end_time = strtotime(date('G:i:s', $express_config['end_time']));

        // 配送时间段
        $e_time = strtotime(date('G:i:s', strtotime($send_time)));

        if (empty($send_time)) {
            $this->returnCode('20090212');
        }

        if ($time < time()) {
            $this->returnCodeError('预约时间超出代送范围，请重新选择');
        }
        if ($e_time<$start_time || $e_time>$end_time) {
            $this->returnCode('预约时间超出代送范围，请重新选择');
        }

        $base_url = D('House_village')->base_url;
        if ($now_order) {
            $saveArr=array('send_time'=>$time);
            $database_house_village_express_order->where(array('order_id'=>$now_order['order_id'],'express_id'=>$express_id))->data($saveArr)->save();

            if ($now_order['paid'] == 0) {
                $now_user = D('User')->get_user($this->_uid);
                if (empty($now_user)) {
                    $this->returnCode('20045011');
                }

                $use_money = $now_order['express_collection_price'];

                $pay_order_param = array(
                    'business_type' => 'house_village_express',
                    'business_id' => $now_order['order_id'],
                    'order_name' => '快递代送',
                    'uid' => $now_user['uid'],
                    'total_money' => $use_money,
                    'wx_cheap' => 0,
                );

                $plat_order_result = D('Plat_order')->add_order($pay_order_param);
                $arr = [];
                $arr['type'] = 'plat';
                $arr['order_id'] = $plat_order_result['order_id'];
                $arr['order_url'] = $this->config['site_url'] . $base_url . 'pages/shop_new/confirmOrder/pay?order_id=' . $plat_order_result['order_id'] . '&type=plat';
                $this->returnCode(0, $arr);
            }else{
                $arr = [];
                $db_house_village = D('House_village');
                $app_version = intval($_POST['app_version']);
                $deviceId = trim($_POST['Device-Id']);
                $param = [
                    'pageName' => 'expressManagement',
                    'isAll' => true,
                    'urlParam' => 'current=1&village_id='.$village_id.'&pigcms_id='.$pigcms_id,
                ];
                $expressManagementsUrl = $db_house_village->villagePagePath($app_version,$deviceId,$param);
                $arr['order_url'] = $expressManagementsUrl;
                $this->returnCode(0, $arr);
            }

        }else{
            $now_user = D('User')->get_user($this->_uid);
            $data['express_id'] = $express_id;

            $data['send_time'] = strtotime($send_time);
            $data['uid'] = $this->_uid;
            $data['phone'] = $now_user['phone'];
            $data['express_collection_price'] = I('express_collection_price') + 0;
            $data['village_id'] =$village_id;
            $data['add_time'] = time();

            $express_order_id = $database_house_village_express_order->data($data)->add();
            if (!$express_order_id) {
                $this->returnCode('20120040');
            } else {
                $now_user = D('User')->get_user($this->_uid);
                if (empty($now_user)) {
                    $this->returnCode('40000051');
                }
                $order_where['express_id'] = $express_order_id + 0;
                $order_where['paid'] = 0;
                $now_order = $database_house_village_express_order->house_village_express_order_detail($order_where);
                $now_order = $now_order['detail'];
                $use_money = $now_order['express_collection_price'];

                $pay_order_param = array(
                    'business_type' => 'house_village_express',
                    'business_id' => $now_order['order_id'] ? $now_order['order_id'] : $express_order_id,
                    'order_name' => '快递代送',
                    'uid' => $now_user['uid'],
                    'total_money' => $use_money ? $use_money : $data['express_collection_price'],
                    'wx_cheap' => 0,
                );

                $plat_order_result = D('Plat_order')->add_order($pay_order_param);
                $arr = [];
                $arr['type'] = 'plat';
                $arr['order_id'] = $plat_order_result['order_id'];
                $arr['order_url'] = $this->config['site_url'] . $base_url . 'pages/shop_new/confirmOrder/pay?order_id=' . $plat_order_result['order_id'] . '&type=plat';
                $this->returnCode(0, $arr);

            }
        }

    }

    //确认取件
    public function express_edit()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        $database_house_village_express = D('House_village_express');
        $id = I('id') + 0;
        $status = 1;
        if (!$id || !$status) {
            $this->error('传递参数有误！');
        }

        $where['id'] = $order_where['express_id'] = $id;
        $data['status'] = $status;

        $database_house_village_express_order = D('House_village_express_order');
        $database_house_village_express_order->house_village_express_order_edit($order_where, $data);
        $data['delivery_time'] = time();
        $result = $database_house_village_express->house_village_express_edit($where, $data);
        if (!$result) {
            $this->returnCode('20120040');
        } else {
            if ($status == 1) {
                $express_config = M('House_village_express_config')->where(array('village_id' => $village_id))->find();
                $order_info = M('House_village_express')->field('e.id,o.send_time,u.name,ex.name as express_name , e.express_no,v.village_name')->join('as e LEFT JOIN ' . C('DB_PREFIX') . 'house_village_express_order  o ON e.id = o.express_id left join ' . C('DB_PREFIX') . 'express ex ON e.express_type = ex.id left join ' . C('DB_PREFIX') . 'house_village v ON e.village_id = v.village_id left join  ' . C('DB_PREFIX') . 'house_village_user_bind u ON e.uid = u.uid')->where(array('e.village_id' => $village_id, 'e.id' => $id))->find();
                if ($this->config['village_sms'] && $order_info['send_time'] > 0) {
                    $sms_data = array('mer_id' => $express_config['village_id'], 'store_id' => 0, 'type' => 'village_express');
                    $sms_data['uid'] = 0;
                    $sms_data['mobile'] = $express_config['notice_phone'];
                    $sms_data['sendto'] = 'village';
                    $sms_data['content'] = '【提醒】您好，' . $order_info['village_name'] . $order_info['name'] . '业主，已确认收货，收货时间:' . date('Y-m-d H:i', $order_info['send_time']) . '，' . $order_info['express_name'] . '，单号：' . $order_info['express_no'] . '。[' . $this->config['site_name'] . ']';
                    Sms::sendSms($sms_data);
                }
            }
            $this->returnCodeOk(L_('取件成功'));
        }
    }

