    public function express_send_add()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $userInfo = D('User')->where(array('uid' => $this->_uid))->field('now_money,nickname,phone')->find();
        //业务处理
        if (I('send_price')) {
            
            if ($userInfo['now_money'] < I('send_price')) {
                $this->returnCode('50000005');
            }
        }
        if (empty(I('send_uname')) || empty(I('collect_uname'))) {
            $this->returnCode('20090059');
        }

        if (empty(I('collect_phone')) || empty(I('send_phone'))) {
            $this->returnCode('20090060');
        }
        if (empty(I('collect_city')) || empty(I('send_city')) || empty(I('send_adress')) || empty(I('send_adress'))) {
            $this->returnCode('10052002');
        }



        $data['send_uname'] = I('send_uname');
        $data['send_phone'] = I('send_phone');
        $data['send_city'] = I('send_city');
        $data['send_adress'] = I('send_adress');
        $data['collect_uname'] = I('collect_uname');
        $data['collect_phone'] = I('collect_phone');
        $data['collect_city'] = I('collect_city');
        $data['collect_adress'] = I('collect_adress');
        $data['weight'] = I('weight', '1');
        $data['goods_type'] = I('goods_type');
        $data['express'] = I('express');
        $data['remarks'] = I('remarks');
        $data['send_price'] = I('send_price', 0);
        $data['village_id'] = $village_id;


        $data['uid'] = $this->_uid;
        $data['add_time'] = time();

        $res = D("House_village_express_send")->data($data)->add();
        if ($res) {
            //2020/8/24 新增 start  //由于您购买的套餐中不包括收费管理功能，所以导致该功能无法使用
            $express_send_price = $this->getHasConfig($village_id, 'express_send_price');
            $is_open_pay_management = D('House_menu_new')->getPayCostAppIsUsable($village_id);
            //2020/8/24 新增 end
            $send_price=I('send_price', 0);
            if($is_open_pay_management) {
                //以下两行代码以前就存在 判断新加的 注：2020/8/24
                D('User')->where(array('uid' => $this->_uid))->setDec('now_money', $send_price);
                $save_paid_order_record=array('source_from'=>1);
                $save_paid_order_record['house_type']='house_express_send';
                $save_paid_order_record['business_type']='house_express_send';
                $save_paid_order_record['business_name']='快递代发';
                $save_paid_order_record['uid']=$this->_uid;
                $save_paid_order_record['order_id']=$res ? $res:0;
                $save_paid_order_record['order_no']=$res ? $res:'';
                $save_paid_order_record['u_name']=$userInfo['nickname'] ? $userInfo['nickname']:'';
                $save_paid_order_record['u_phone']=$userInfo['phone'] ? $userInfo['phone']:'';
                $save_paid_order_record['table_name']='house_village_express_send';
                $save_paid_order_record['order_money']=$send_price;
                $save_paid_order_record['is_own']=1;
                $save_paid_order_record['pay_type']='balance';
                $save_paid_order_record['balance_money']=$send_price;
                $save_paid_order_record['pay_type_from']='system_balance';
                $save_paid_order_record['is_online']=1;
                $save_paid_order_record['pay_time']=time();
                $save_paid_order_record['village_id']=$village_id;
                D('Paid_order_record')->data($save_paid_order_record)->add();
                
                D('User_money_list')->add_row($this->_uid, 2, I('send_price', 0), "支付待寄快递服务费 " . I('send_price', 0) . C('config.Currency_txt') . "", true, 5, $res);
            }
            $order_param['village_id'] = $village_id;
            $order_param['desc'] = '快递代发费用';
            $order_param['balance_pay'] = $send_price;
            $order_param['payment_money'] = 0;
            $order_param['is_own'] = 4;
            $order_param['order_type'] = 'express';
            $order_param['order_id'] = 0;

            if($is_open_pay_management>0) {
                //以下一行代码以前就存在 判断新加的 注：2020/8/24
                $return = D('SystemBill')->bill_method(4, $order_param);
            }
            $this->returnCodeOk(L_('添加成功!'));
        }


    }

    public function get_visitor_info()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $arr = [];
        $bind_info = $this->check_village_session($village_id, $pigcms_id);
        if (!in_array($bind_info['type'],[0,3])) {
            $this->returnCodeError('您当前不是业主身份无法使用该功能');
        }
        $arr['owner_name'] = $bind_info['name'];
        $arr['owner_phone'] = $bind_info['phone'];
        $arr['address'] = D('House_village')->get_single_floor_room($bind_info['single_id'],$bind_info['floor_id'],$bind_info['layer_id'],$bind_info['vacancy_id'],$bind_info['village_id']);;

        $now_village = D('House_village')->where(array('village_id'=>$village_id))->find();
        if($now_village['is_visitor_car'] == 1){
            $is_park_rate = false;//预存停车费的  //2020/4/20新加功能,暂时不处理,由于前端没做功能

        }else{
            $is_park_rate = false;//预存停车费的

        }
        //开门权限
        $is_open_door = D('House_village')->village_door_status($village_id);

        //分享二维码 2020/12/7 start
        $base_url = D('House_village')->base_url;
        $share_url = $this->config['site_url'] . $base_url . 'pages/village/visitorPass/visitorinfo?village_id='.I('village_id').'&pigcms_id='.I('pigcms_id');
        $share_qrcode = $this->config['site_url'].U('get_own_qrcode',array('qrCon'=>urlencode(htmlspecialchars_decode($share_url))));
        $arr['share_qrcode'] = $share_qrcode;
        $arr['share_url'] = $share_url;
        //分享二维码 end

        $arr['is_park_rate'] = $is_park_rate;
        $arr['is_open_door'] = $is_open_door;
        $arr['is_face'] = $this->config['is_face'];
        
        //是否必填项设置（访客姓名，身份证）
        $visitorSet = [
            'name'=>1,
            'id_card'=>1
        ];
        $now_village['visitor_set_data'] = json_decode($now_village['visitor_set_data'],true);
        $visitorSet['name'] = $now_village['visitor_set_data']['name']??1;
        $visitorSet['id_card'] = $now_village['visitor_set_data']['id_card']??1;
        $arr['visitor_set'] = $visitorSet;
//        $arr['visitor_money'] = $visitor_money;

        $this->returnCode(0, $arr);
    }
    //分享页获取业主信息 访客自主填写信息
    public function getShareOwnerInfo(){
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $village_id = I('village_id', '');
        $uid = $this->_uid;
        //查询访客是否添加来访信息(未通行)
        $map['uid'] =$uid;
        $map['village_id'] =$village_id;
//        $map['status'] = 0;
        $bind_where['add_time'] = ['egt',strtotime(date('Y-m-d',time()))];
        $visitor = D('House_village_visitor')->where($map)->find();
        if($visitor){
            $share_arr['visitor_status'] = true;//已添加，存在未通行
        }else{
            $share_arr['visitor_status'] = false;//不存在未通行信息
        }


        $pigcms_id = I('pigcms_id');
        $is_open_door = I('is_open_door');//是否允许开门
        if(!$pigcms_id){
            $this->returnCodeError('参数异常');
        }

        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $bind_where['uid'] = $uid;
        $bind_where['village_id'] = $village_id;
//        $bind_where['owner_uid'] = $pigcms_id;
        $bind_where['add_time'] = ['egt',strtotime(date('Y-m-d',time()))];
        $bind_visitor = D('House_village_visitor')->where($bind_where)->find();
        if($bind_visitor){
            $share_arr['visitor_id'] = $bind_visitor['id'];
            $share_arr['is_join'] = true;
        }else{
            $share_arr['is_join'] = false;
        }
        $ownerInfo = D('House_village_user_bind')
            ->where(['pigcms_id'=>$pigcms_id])
            ->field('pigcms_id,name,phone,village_id,floor_id,vacancy_id,single_id,layer_id')
            ->find();
        $owner_names = mb_substr($ownerInfo['name'], 0, 1, 'utf-8');
//        $share_arr['owner_name'] =substr_replace($ownerInfo['name'],'**',1);
        $share_arr['owner_name'] =$owner_names.'**';
        if(strlen($ownerInfo['phone']) == 11){
            $share_arr['owner_phone'] =substr_replace($ownerInfo['phone'],'****',3,4);
        }else{
            $share_arr['owner_phone'] = '****';
        }
        $share_arr['address'] = D('House_village')->get_single_floor_room($ownerInfo['single_id'],$ownerInfo['floor_id'],$ownerInfo['layer_id'],$ownerInfo['vacancy_id'],$ownerInfo['village_id']);;
        $share_arr['visitor_uid'] = $this->_uid;//访客uid
        //允许开门
        if($is_open_door) {
            //访客开门方式
            $open_door_type = D('House_village_about_config')->where(['village_id' => $village_id])->getField('open_door_type');
            $share_arr['open_door_type'] = $open_door_type; //1人脸开门 2远程开门
            $face_device = D('House_face_device')->where(['village_id' => $village_id, 'device_status' => 1])->find();
            if ($face_device && $face_device == 1) {
                $share_arr['open_type'] = 1;
            } else {
                $share_arr['open_type'] = 2;
            }
        }
        $share_arr['is_open_door'] = $is_open_door;//业主是否允许开门
        $db_house_village = D('House_village');
        $app_version = intval($_POST['app_version']);
        $deviceId = trim($_POST['Device-Id']);
        $param = [
            'pageName' => 'faceAccessControl',
            'isAll' => true,
            'urlParam' => 'type=2&village_id='.$village_id.'&uid='.$uid,
        ];
        $faceAccessControlUrl = $db_house_village->villagePagePath($app_version,$deviceId,$param);
        $share_arr['face_url'] =  $faceAccessControlUrl;
        $face = D('House_face_img')->where(['uid'=>$uid,'status'=>['neq',1]])->count();
        if($face){
            $share_arr['face_status'] = '已上传';
        }else{
            $share_arr['face_status'] = '未上传';
        }
        $user_info = D('User')->where(['uid'=>$this->_uid])->field('nickname,phone')->find();
        $share_arr['user_phone'] = $user_info['phone'];
        $share_arr['user_name'] = $user_info['nickname'];
        $is_face = $this->config['is_face'];
        $share_arr['is_face'] = $is_face;
        $this->returnCode(0, $share_arr);
    }
    public function check_village_session_visitor($village_id, $pigcms_id)
    {
        if (!empty($village_id)) {
            //$where['uid'] = $this->_uid;
            $where['village_id'] = $village_id;
            $where['pigcms_id'] = $pigcms_id;
//            $where['type'] = ['in',[0,1,2,3]];
            $House_village_user_bindModel = D('House_village_user_bind');
            $bind_village_list = $House_village_user_bindModel->field(true)->where($where)->order('`pigcms_id` DESC')->select();

            if (!$bind_village_list) {
                $bind_village_list = $House_village_user_bindModel->where(array('uid' => $this->_uid, 'village_id' => $village_id, 'parent_id' => array('neq', 0)))->order('`pigcms_id` DESC')->select();
                if (!$bind_village_list) {
                    $bind_village_list = $House_village_user_bindModel->field(true)->where(array('uid' => $bind_village_list[0]['parent_id'], 'village_id' => $village_id))->order('`pigcms_id` DESC')->select();
                }
            }
            if (!empty($bind_village_list)) {
                if (count($bind_village_list) == 1) {
                    return $bind_village_list[0];
                } else {
                    return array();
                }
            }
        } else {
            return array();
        }
    }
    public function add_visitor()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $db_house_village=D('House_village');
        $house_village_info = $db_house_village->where(['village_id'=>$village_id])->field('village_name,property_id,now_sms_number,visitor_set_data')->find();
        $visitor_set_data = $house_village_info['visitor_set_data'] ? json_decode($house_village_info['visitor_set_data'],true) : [];
        $has_name = $visitor_set_data['name']??0;
        $has_id_card = $visitor_set_data['id_card']??0;
        //查询访客姓名、身份证是否必填
        if(empty(I('visitor_name')) && $has_name){
            $this->returnCodeError('访客姓名必填');
        }
        if(empty(I('id_card')) && $has_id_card){
            $this->returnCodeError('身份证号必填');
        }

        if(empty(I('visitor_phone'))){
            $this->returnCodeError('访客联系方式必须填');
        }
        if (empty(I('add_time'))){
            $this->returnCodeError('到访时间不能为空');
        }
        $bind_info = $this->check_village_session_visitor($village_id, $pigcms_id);
        if (!in_array($bind_info['type'],[0,3])) {
            $this->returnCodeError('您当前不是业主身份无法使用该功能');
        }
        if ($bind_info['name']=='测试业主' && $bind_info['address']=='测试业主之家' && !$bind_info['vacancy_id']) {
            $this->returnCodeError('您当前是体验身份无法使用该功能');
        }

        if(!$bind_info){
            $this->returnCodeError('未到对应业主');
        }
        if(!$bind_info['single_id']){
            $single_id = D('House_village_floor')->where(['village_id'=>$bind_info['village_id'],'floor_id'=>$bind_info['floor_id']])->getField('single_id');
            D('House_village_user_bind')->where(['pigcms_id'=>$bind_info['pigcms_id']])->data(['single_id'=>$single_id])->save();
        }
        //2020/12/16 start
        $data['single_id'] =$bind_info['single_id']?$bind_info['single_id']:$single_id;
        $data['floor_id'] = $bind_info['floor_id'];
        $data['layer_id'] = $bind_info['layer_id'];
        $data['vacancy_id'] = $bind_info['vacancy_id'];
        //end
        $data['owner_name'] = $bind_info['name'];  //业主名称
        $data['owner_phone'] = $bind_info['phone'];//业主手机号
        $data['owner_address'] = $bind_info['address'];

        $data['owner_uid'] = $bind_info['uid'];
        $data['village_id'] = $village_id;
        $data['visitor_name'] = I('visitor_name');
        $data['visitor_phone'] = I('visitor_phone');
        $data['status'] = 3;//通行状态  未到访
        $data['visitor_sex'] = I('visitor_sex','');
        $data['is_car'] = I('is_car','');
        if(I('is_car') == 1){
            if(empty(I('car_id'))){
                $this->returnCodeError('车牌号不能为空');
            }
            $data['car_id'] = I('car_id','');
        }
        $data['is_park_rate'] = I('is_park_rate','');//预存停车费
        if(I('is_park_rate') == 1){
            if(empty(I('park_rate'))){
                $this->returnCodeError('预存停车费不能为空');
            }
            $data['park_rate'] = I('park_rate','');
        }
        if(empty(I('add_time'))){
            $this->returnCodeError('请选择到访时间');
        }
        $data['is_open_door'] = I('is_open_door');
        $data['add_time'] = strtotime(I('add_time'));

        $database_house_village_visitor = D('House_village_visitor');
        $share_data = array(
            'share_uid'=>$bind_info['uid'],
            'share_use_day'=>$data['add_time'],
        );
        $door_share_id = D('House_village_bind_share')->add_visitor_share($village_id,$share_data);
        if($door_share_id){
            $data['door_share_id'] = $door_share_id;
        }
        //给访客创建小区身份用户
        $address_arr = [
            'single_id' => $bind_info['single_id'],
            'floor_id' => $bind_info['floor_id'],
            'layer_id' => $bind_info['layer_id'],
            'vacancy_id' => $bind_info['vacancy_id'],
            'add_time' => $data['add_time'],
        ];
        $now_time = time();
        $user_bind = $this->bind_user($village_id,$data['visitor_phone'],$data['visitor_name'],$address_arr,$now_time);
        $data['uid'] = $this->_uid;
        $data['visitor_bind_id'] = $user_bind['bind_id'];
        $data['time'] = $now_time;
        $visitor_id = $database_house_village_visitor->data($data)->add();
        if($visitor_id){
            $arr['visitor_id'] = $visitor_id;
            //给访客添加开门时间限制
            if (isset($data['car_id']) && trim($data['car_id']) && $village_id > 0) {
                invoke_v20_service('\app\community\model\service\Car\CarHandleGetInfoService/clearVisitorInfo', ['village_id' => $village_id]);
            }
            if ($bind_info) {
                $whereArr = array();
                if ($bind_info['uid'] > 0) {
                    $whereArr = array('uid' => $bind_info['uid']);
                } else if (!empty($bind_info['phone'])) {
                    $whereArr = array('phone' => $bind_info['phone']);
                }
                $userInfo = M('User')->where($whereArr)->find();
                $village_info_extend=D('House_village_info')->where(array('village_id'=>$village_id))->field('*')->find();
                $urge_notice_type = 0;
                if ($village_info_extend && isset($village_info_extend['urge_notice_type'])) {
                    //1短信通知2微信模板通知3短信和微信模板通知
                    $urge_notice_type = $village_info_extend['urge_notice_type'];
                }
                if($urge_notice_type!=1 && $userInfo && !empty($userInfo['openid'])){
                    $app_version = intval($_POST['app_version']);
                    $app_version=$app_version>0 ?$app_version:0;
                    $deviceId = trim($_POST['Device-Id']);
                    $deviceId=$deviceId?$deviceId:'';
                    $param = [
                        'pageName' => 'visitorRegistration',
                        'isAll' => true,
                        'urlParam' => 'village_id=' . $village_id,
                    ];
                    $visitorRegistrationUrl = $db_house_village->villagePagePath($app_version,$deviceId,$param);
                    $href = $visitorRegistrationUrl;
                    $model = new templateNews(C('config.wechat_appid'), C('config.wechat_appsecret'));
                    $href .= '&pigcms_id='.$pigcms_id;
                    $model->sendTempMsg('OPENTM408101810', //todo 类目模板OPENTM408101810
                        array(
                            'href' => $href, 
                            'wecha_id' => $userInfo['openid'], 
                            'first' => '您好，'.$house_village_info['village_name'].'业主，您有新访客到访', 
                            'keyword1' => $data['visitor_name'],
                            'keyword2' => $data['visitor_phone'], 
                            'keyword3' => date('Y年m月d日 H时i分'),
                            'remark' => '\n访客正在等候，需要您的确认！',
                            'new_info' => [//新版本发送需要的信息
                                'tempKey'=>'43728',//新模板号
                                'thing2'=>$data['visitor_name'],//来访人员
                                'phone_number10'=>$data['visitor_phone'],//联系电话
                                'time9'=>date('Y年m月d日 H:i'),//拜访时间
                            ],
                        ),0,$house_village_info['property_id'],1);
                }

                if ($bind_info['phone'] && $urge_notice_type!=2 && C('config.village_sms') == 1 && $house_village_info['now_sms_number'] > 0) {
                    $sms_data=array();
                    $sms_data['uid'] = $bind_info['uid'];
                    $sms_data['mobile'] = $bind_info['phone'];
                    $sms_data['sendto'] = 'user';
                    $sms_data['type'] = 'village_vistor';
                    if ($data['visitor_name']) {
                        $sms_data['content'] = '您好，' . $house_village_info['village_name'] . '业主，姓名为' . $data['visitor_name'] . '，手机号为' . $data['visitor_phone'] . '的访客正在等候，需要您的确认！';
                    } else {
                        $sms_data['content'] = '您好，' . $house_village_info['village_name'] . '业主，手机号为' . $data['visitor_phone'] . '的访客正在等候，需要您的确认！';
                    }
                    Sms::sendSms(($sms_data));
                    M('House_village')->where(array('village_id' =>$village_id))->setDec('now_sms_number');
                }
                
            }
            $add_time = I('add_time');
            $effectTimeStamp = strtotime($add_time);
            $expireTimeStamp = strtotime($add_time.' 23:59:59');
            $user_bind_data['property_starttime'] = $effectTimeStamp;
            $user_bind_data['property_endtime']   = $expireTimeStamp;
            $user_bind_data['id_card'] = I('id_card','', 'trim');
            D('House_village_user_bind')->where(['pigcms_id'=>$user_bind['bind_id'],'type'=>6])->data($user_bind_data)->save();

            $open_door_type = D('House_village_about_config')->where(['village_id' => $village_id])->getField('open_door_type');
            if($open_door_type == 1) { //1人脸开门 2远程开门
                //需要调用人脸同步
                $location = ['floor_'.$data['floor_id']];
                $face_device = D('House_face_img')->face_user_to_device($user_bind['bind_id'], $village_id, $location);
                /*
                if ($face_device) {
                    $wheres['pigcms_id'] = $pigcms_id;
                    $data_bind = [
                        'face_img_status' => '0',
                        'add_face_time' => time(),
                    ];
                    D('House_village_user_bind')->where($wheres)->data($data_bind)->save();
                }
                */
            }
            $db_house_face_device = M('House_face_device');
            $hik_info_vision_i_community_app_key = C('config.hik_info_vision_i_community_app_key');
            $hik_info_vision_i_community_app_secret = C('config.hik_info_vision_i_community_app_secret');
            // todo 获取设备二维码 注意有测试条件需要删除
            $hasHikInfoVisionICommunity = 0;
            if ($hik_info_vision_i_community_app_key && $hik_info_vision_i_community_app_secret) {
                $whereFace = [
                    'village_id' => $village_id, 'device_type' => 5, 'is_del' => 0, 'thirdProtocol' => 15,
                ];
                $deviceInfo = $db_house_face_device->where($whereFace)->find();
                if (isset($deviceInfo['device_id']) && $deviceInfo['device_id']) {
                    $hasHikInfoVisionICommunity = 1;
                }
                if ($hasHikInfoVisionICommunity == 1) {
                    // 注册人员信息
                    $hikRet = invoke_v20_service('\app\community\model\service\Device\HikInfoVisionICommunityService/handleBindUserToHikCommunity', ['village_id' => $village_id, 'pigcms_id' => $user_bind['bind_id']]);
                    $arr['hikRet'] = $hikRet;
                } else {
                    $returnArr = ['err_code' => 1, 'err_msg' => '相关小区没有对应设备'];
                    $hikRet = ['status' => 1000, 'data' => ['error_no' => 0, 'error_msg' => '', 'retval' => $returnArr], 'msg' => ''];
                    $arr['hikRet'] = $hikRet;
                }
            }
            $getHikFaceDeviceVisitorQRCode = D('Config_customization')->getHikFaceDeviceVisitorQRCode();
            fdump_api(['msg' => '业主是否添加A5访客二维码','$params' => $getHikFaceDeviceVisitorQRCode], 'visitor/ownerAddVisitorLog',1);
            if ($getHikFaceDeviceVisitorQRCode) {
                // 下发访客二维码
                $visitor_open_number_limit = D('House_face_device')->getQrCodeNumber($village_id);
                $cardNo = 100000000000 + $visitor_id;
                $visitor_param = [
                    'cardNo'     => $cardNo,
                    'effectTime' => date('ymdHis', $effectTimeStamp),
                    'expireTime' => date('ymdHis', $expireTimeStamp),
                    'openTimes'  => $visitor_open_number_limit,
                ];
                fdump_api(['msg' => '获取A5设备二维码参数','visitor_param' => $visitor_param, 'vistor_open_number_limit' => $visitor_open_number_limit], 'visitor/ownerAddVisitorLog',1);
                $visitor_device_result = D('Face_door_a5_service')->getVisitorQrcode($visitor_param);
                fdump_api(['msg' => '获取A5设备二维码结果', 'visitor_device_result' => $visitor_device_result], 'visitor/ownerAddVisitorLog',1);
                $qrCodeUrl = isset($visitor_device_result['data']['qrCodeUrl']) && $visitor_device_result['data']['qrCodeUrl'] ? $visitor_device_result['data']['qrCodeUrl'] : '';
                $db_face_user_bind_device = D('Face_user_bind_device');
                $bind_arr = [
                    'bind_type'   => 40,
                    'bind_id'     => $visitor_id,
                    'device_type' => 5,
                    'code'        => $cardNo,
                    'person_id'   => $data['visitor_bind_id'],// 访客对应小区身份id
                    'personID'    => $data['owner_uid'],// 访客对应业主uid
                    'group_id'    => $data['vacancy_id'],// 访客要拜访房间id
                    'groupID'     => $data['village_id'],// 访客要拜访小区
                    'person_text' => json_encode($visitor_param,JSON_UNESCAPED_UNICODE), // 获取访客二维码时候的传参
                    'face_txt'    => json_encode($visitor_device_result,JSON_UNESCAPED_UNICODE), // 反馈结果
                ];
                if ($qrCodeUrl) {
                    $bind_arr['face_img'] = $qrCodeUrl; // 对应访客开门用二维码
                    $bind_arr['face_status'] = 2; 
                } else {
                    $bind_arr['face_status'] = 3;
                    $bind_arr['face_reason'] = isset($visitor_device_result['message']) && $visitor_device_result['message'] ? $visitor_device_result['message'] : '获取失败';
                }
                $bind_arr['face_time'] = time();
                $bind_arr['add_time'] = $effectTimeStamp;
                fdump_api(['msg' => '获取A5设备二维码关联记录', 'bind_arr' => $bind_arr], 'visitor/ownerAddVisitorLog',1);
                $id = $db_face_user_bind_device->add($bind_arr);
                if ($id && $qrCodeUrl) {
                    fdump_api(['msg' => '下发', 'user_bind' => $user_bind, 'id' => $id], 'visitor/ownerAddVisitorLog',1);
                    $face_device = D('House_face_img')->house_user_face_device_info(0, $user_bind['bind_id']);
                    fdump_api(['msg' => '下发结果', 'face_device' => $face_device], 'visitor/ownerAddVisitorLog',1);
                }
            }
            $getFaceCloud260Judge = D('Config_customization')->getFaceCloud260Judge();
            $hasFaceCloud260 = 0;
            if ($getFaceCloud260Judge) {
                $whereFace = [
                    'village_id' => $village_id, 'device_type' => 30, 'is_del' => 0,
                ];
                $deviceInfo = $db_house_face_device->where($whereFace)->find();
                if (isset($deviceInfo['device_id']) && $deviceInfo['device_id']) {
                    $hasFaceCloud260 = 1;
                }
                if ($hasFaceCloud260 == 1) {
                    fdump_api(['msg' => '业主-是否添加260云访客二维码','$params' => $getFaceCloud260Judge], '260Cloud/ownerAddVisitorLog',1);
                    $visitor_open_number_limit = D('House_face_device')->getQrCodeNumber($village_id);
                    $employeeQRCodeArr = [
                        'cmd_id' => $user_bind['bind_id'],
                        'cmd' => 'selectPassInfo',
                        'device_text' => 'cloud260',
                        'device_type' => 30,
                        'type' => 'face',
                    ];
                    $employeeQRCode = md5(json_encode($employeeQRCodeArr,JSON_UNESCAPED_UNICODE));
                    $visitor_param = [
                        'cardNo'     => $employeeQRCode,
                        'effectTime' => date('Y-m-d H:i:s', $effectTimeStamp),
                        'expireTime' => date('Y-m-d H:i:s', $expireTimeStamp),
                        'openTimes'  => $visitor_open_number_limit, // 开门总次数
                        'surplusOpenTimes'  => $visitor_open_number_limit, // 剩余次数
                    ];
                    $db_face_user_bind_device = D('Face_user_bind_device');
                    $bind_arr = [
                        'bind_type'   => 30,
                        'bind_id'     => $data['visitor_bind_id'],// 访客对应小区身份id
                        'device_type' => 30,
                        'open_key'    => 'visitor',
                        'open_key_time' => $expireTimeStamp,
                        'code'        => $employeeQRCode,
                        'person_id'   => $visitor_id,// 访客id
                        'personID'    => $data['owner_uid'],// 访客对应业主uid
                        'group_id'    => $data['vacancy_id'],// 访客要拜访房间id
                        'groupID'     => $data['village_id'],// 访客要拜访小区
                        'person_text' => json_encode($visitor_param,JSON_UNESCAPED_UNICODE), // 获取访客二维码时候的传参
                        'face_txt'    => json_encode($employeeQRCodeArr,JSON_UNESCAPED_UNICODE), // 反馈结果
                    ];
                    $bind_arr['face_time'] = time();
                    $bind_arr['add_time'] = $effectTimeStamp;
                    fdump_api(['msg' => '业主-获取260云设备二维码关联记录', 'bind_arr' => $bind_arr], '260Cloud/ownerAddVisitorLog',1);
                    $id = $db_face_user_bind_device->add($bind_arr);
                    D('House_face_img')->house_user_face_device_info(0, $user_bind['bind_id']);
                }
            }
            $hasXiHan = 0;
            $getXiHanJudge = D('Config_customization')->getFaceXiHanDoorSwitch();
            if ($getXiHanJudge) {
                $whereFace = [
                    'village_id' => $village_id, 'device_type' => 31, 'is_del' => 0,
                ];
                $deviceInfo = $db_house_face_device->where($whereFace)->find();
                if (isset($deviceInfo['device_id']) && $deviceInfo['device_id']) {
                    $hasXiHan = 1;
                }
                if ($hasXiHan == 1) {
                    $xiHanParams = [
                        'uid' => isset($user_bind['uid']) && $user_bind['uid'] ? $user_bind['uid'] : 0,
                        'village_id' => $village_id, 'pigcms_id' => $user_bind['bind_id']
                    ];
                    $xiHanParams['hasXiHan'] = $hasXiHan;
                    invoke_v20_service('\app\community\model\service\Device\XiHanEventService/getUserOpenCode', ['params' => $xiHanParams]);
                }
            }

            $is_func_cloudmrsqfw_special=D('Config_customization')->getFuncCloudmrsqfwSpecial();
            if($is_func_cloudmrsqfw_special && $user_bind && $visitor_id>0){
                $whereArr=array('village_id'=>$village_id);
                $village_data = M('House_village')->where($whereArr)->find();
                if($village_data && !empty($village_data['lilin_pf_client_id']) && !empty($village_data['lilin_pf_client_secret']) && !empty($village_data['lilin_village_no'])){
                    $whereArr=array('village_id'=>$village_id,'third_dev_source'=>'lilin_pf','third_dev_id'=>array('neq',''),'is_del'=>array('lt',4));
                    $lilin_third_dev= D('House_face_device')->where($whereArr)->find();
                    if($lilin_third_dev){
                        $models = '\app\community\model\service\Device\LiLinDevAccessApiService/visitorAddEditToLiLin';
                        $param = [
                            'village_id'=>$village_id,
                            'visitor_id' => $visitor_id,
                        ];
                        $visitorLiLin = invoke_v20_service($models,$param);
                        fdump_api(['param' =>$param, 'visitorLiLin' => $visitorLiLin], 'LiLinDevAccess/visitorAddEditToLiLin',1);
                    }
                }
            }

            invoke_v20_service('\app\community\model\service\Device\HouseDeviceQrcodeService/addDeviceQrCode', ['pigcms_id' => $user_bind['bind_id']]);
            $this->returnCode(0, $arr);
        }else{
            $this->returnCodeError("添加失败，请重试。");
        }


    }
    //绑定用户
    public function bind_user($village_id,$phone,$name,$address_arr,$now_time=0)
    {
        if (!$now_time) {
            $now_time = time();
        }
        $userInfo = D('User')->where(['phone'=>$phone])->field('uid,phone')->find();
        if(!$userInfo)
        {
            $data_user = array(
                'nickname' 	=> $name,
                'phone' 	=> $phone,
                'source' 	=> 'houseautoreg',
            );
            $reg_result = D('User')->autoreg($data_user);
            $uid = $reg_result['uid'];
        }else{
            $uid = $userInfo['uid'];
        }
        $arr = [
            'village_id'=>$village_id,
            'uid'=>$uid,
            'phone'=>$phone,
            'name'=>$name,
            'type'=>6,
            'usernum'=>rand(1000,9999).'-'.$now_time,
            'single_id'=>$address_arr['single_id'],
            'floor_id'=>$address_arr['floor_id'],
            'layer_id'=>$address_arr['layer_id'],
            'vacancy_id'=>$address_arr['vacancy_id'],
            'add_time' => $now_time
        ];
        $add_time = isset($address_arr['add_time']) && intval($address_arr['add_time']) > 0 ? intval($address_arr['add_time']) : time();
        $property_starttime = strtotime(date('Y-m-d 00:00:00', $add_time));
        $property_endtime = strtotime(date('Y-m-d 23:59:59', $add_time));
        $arr['property_starttime'] = $property_starttime;
        $arr['property_endtime'] = $property_endtime;
        
        $pigcms_id = D('House_village_user_bind')->add($arr);
        $data['uid'] = $uid;
        $data['bind_id'] = $pigcms_id;

        return $data;
    }
    public function visitor_info()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $visitor_id = I('visitor_id');
        $visitortype = I('visitor_type', '','trim'); //myall 所有
        $base_url = D('House_village')->base_url;
        $qrcode_url = $this->config['site_url'] . $base_url . 'pages/village/visitorPass/visitorinfo?village_id='.I('village_id').'&pigcms_id='.I('pigcms_id').'&visitor_id='.I('visitor_id');
        if(empty($visitor_id)){
            $this->returnCodeError('访客通行内容不存在');
        }
        $pigcms_id = I('pigcms_id', '0','intval');//户号
        if (empty($pigcms_id) && $visitortype!='myall') {
            $this->returnCode('20120004');
        }
        $database_house_village_visitor = D('House_village_visitor');
        $res = $database_house_village_visitor->where(array('id'=>$visitor_id))->find();
        $arr = [];
        if($res['owner_uid'] != $this->_uid){
            //处理绑定人脸开门
            D('House_village_bind_share')->bind_share($res['door_share_id'], $this->_uid);
            $arr['edit_phone_status'] = true;
        }else{
            $arr['edit_phone_status'] = false;
        }
        if(empty($res)){
            $this->returnCodeError('访客开门内容不存在');
        }
        $House_village_user_bindModel = D('House_village_user_bind');
        $bind_info = $House_village_user_bindModel->get_one_by_bindId($pigcms_id);
        if(empty($bind_info) && $visitortype!='myall'){
            $this->returnCodeError('房间信息不存在!');
        }
        $house_village_info = M('House_village')->where(array('village_id' => $res['village_id']))->field('village_name,village_address,long,lat')->find();

        $arr['village_address'] = $house_village_info['village_address'];//小区地址
        $arr['village_lng'] = $house_village_info['long'];//小区经纬度
        $arr['village_lat'] = $house_village_info['lat'];//小区经纬度
        $arr['village_name'] = $house_village_info['village_name']; // 小区名称

        if ($arr['village_lat'] && $arr['village_lng']) {
            $longlatClass = new longlat();
            $longlat = $longlatClass->baiduToGcj02($arr['village_lat'],$arr['village_lng']);
            $arr['village_lng_gcj02'] = $longlat['lng'];//腾讯地图的坐标 经纬度
            $arr['village_lat_gcj02'] = $longlat['lat'];//腾讯地图的坐标 经纬度
        }

        $arr['visitor_id'] = $res['id'];//id
        $arr['visitor_name'] = $res['visitor_name']?$res['visitor_name']:'';//访客姓名
        $arr['visitor_phone'] = $res['visitor_phone']?$res['visitor_phone']:'';//访客手机号
        $arr['car_id'] = $res['car_id']?$res['car_id']:'';//访客车牌号
        if ($res['add_time']) {
            $arr['visitor_time'] = date('Y/m/d',$res['add_time']);//访客来访时间
        } else {
            $arr['visitor_time'] = '';//访客来访时间
        }
        $arr['add_time'] = '门禁时间:'.date('Y.m.d',$res['add_time']);//门禁时间
        $arr['owner_name'] = $res['owner_name']?$res['owner_name']:'';//业主姓名
        $arr['owner_phone'] = $res['owner_phone']?$res['owner_phone']:'';//业主电话
        $arr['owner_address'] = $res['owner_address']?$res['owner_address']:'';//业主地址
        $arr['room'] = $bind_info && $bind_info['address']?$bind_info['address']:'';//房间地址
        $arr['visitor_sex'] = $res['visitor_sex']?$res['visitor_sex']:'';//性别
        $arr['is_car'] = $res['is_car']?$res['is_car']:'';//是否驾车
        $arr['is_open_door'] = $res['is_open_door']?$res['is_open_door']:'';//是否有开门权限

        $arr['qrcode_url'] = $this->config['site_url'].U('get_own_qrcode',array('qrCon'=>urlencode(htmlspecialchars_decode($qrcode_url))));
        $visitor_count = $database_house_village_visitor->where(array('owner_uid'=>$this->_uid))->count();
        if($visitor_count == 0){
            $arr['visitor_status'] = true;
        }else{
            $arr['visitor_status'] = false;
        }
        $arr['qrcode_path_url'] = $qrcode_url;
        //start 2020/12/7 访客开门方式 （1人脸开门 2远程开门)
        //访客开门方式
        $open_door_type = D('House_village_about_config')->where(['village_id' => $res['village_id']])->getField('open_door_type');
        $arr['open_door']['open_door_type'] = (int)$open_door_type;//1人脸开门 2远程开门
        //人脸门禁
        $face_device = D('House_face_device')->where(['village_id' => $res['village_id'],'device_status'=>1])->count();
        //蓝牙门禁
        $door_bluetooth = D('house_village_door')->where(['village_id' => $res['village_id'],'door_status'=>1])->count();
        //如果访客开门方式设置人脸开门且有蓝牙门禁时
        if( $open_door_type==1){
            if($door_bluetooth && $face_device){
                $arr['open_door']['face_device_type'] =2; //蓝牙开门、人脸开门都有 (有去开门按钮)
//                $arr['open_door']['face_device_text'] ='蓝牙门禁';
            }elseif($face_device){
                $arr['open_door']['face_device_type'] =3;//没有蓝牙开门、只有人脸开门（录入人脸）
            }else{
                $arr['open_door']['face_device_type'] =0;//蓝牙开门、人脸开门都没有
            }
        }else{
            if($face_device){
                $arr['open_door']['face_device_type'] =1; //原有远程开门
            }else{
                $arr['open_door']['face_device_type'] =0;//蓝牙开门、人脸开门都没有
            }
        }
        //end
        $face = D('House_face_img')->where(['uid'=>$this->_uid,'status'=>['neq',1]])->count();
        if($face){
            $arr['face_status'] = '已上传';
        }else{
            $arr['face_status'] = '未上传';
        }
        $arr['share_img'] = $this->config['site_url'] . '/static/wxapp/visitor_open.png';
        $arr['share_wx'] = $this->config['pay_wxapp_important'] && $this->config['pay_wxapp_username'] ? 'wxapp' : 'h5';
        $arr['userName'] = $this->config['pay_wxapp_username'];
        $now_time = time();
        $getHikFaceDeviceVisitorQRCode = D('Config_customization')->getHikFaceDeviceVisitorQRCode();
        if ($getHikFaceDeviceVisitorQRCode) {
            $db_face_user_bind_device = D('Face_user_bind_device');
            $whereBindType = [
                'bind_type'   => 40,
                'device_type' => 5,
                'bind_id'     => $res['id'],// 访客id
                'groupID'     => $res['village_id'],// 访客要拜访小区
            ];
            $aboutFaceUser = $db_face_user_bind_device->where($whereBindType)->find();
            $qrCodeUrl = isset($aboutFaceUser['face_img']) && $aboutFaceUser['face_img'] ? $aboutFaceUser['face_img'] : '';
            $add_time = $res['add_time'];
            $end_time = strtotime(date('Y-m-d 23:59:59', $add_time));
            
            if ($end_time <= $now_time) {
                $qrCodeUrl = $this->config['site_url'].'/static/images/house/visitor/QRCodeinvalid.png';// 默认失效图片
            }
            $arr['visitorQRCode'] = $getHikFaceDeviceVisitorQRCode;
            $arr['visitorQRCodeUrl'] = $qrCodeUrl;

            if ($end_time > $now_time && $res['visitor_bind_id'] && $qrCodeUrl) {
                fdump_api(['msg' => '详情下发', 'res' => $res], 'visitor/ownerAddVisitorLog',1);
                $face_device = D('House_face_img')->house_user_face_device_info(0, $res['visitor_bind_id']);
                fdump_api(['msg' => '详情下发结果', 'face_device' => $face_device], 'visitor/ownerAddVisitorLog',1);
            }
        }


        $getFaceCloud260Judge = D('Config_customization')->getFaceCloud260Judge();
        if ($getFaceCloud260Judge) {
            // todo 设备二维码开门暂时不考虑多个不同品牌设备支持 只考虑单一品牌
            $db_face_user_bind_device = D('Face_user_bind_device');
            $whereBindType = [
                'bind_type' => 30,
                'device_type' => 30,
                'person_id' => $res['id'],// 访客id
                'groupID' => $res['village_id'],// 访客要拜访小区
            ];
            $aboutFaceUser = $db_face_user_bind_device->where($whereBindType)->find();
            $employeeQRCode = isset($aboutFaceUser['code']) && $aboutFaceUser['code'] ? $aboutFaceUser['code'] : '';
            if ($employeeQRCode) {
                $qrCodeUrl = $this->config['site_url'] . "/index.php?c=Recognition&a=get_own_qrcode&qrCon={$employeeQRCode}";
            }
            
            $add_time = $res['add_time'];
            $end_time = strtotime(date('Y-m-d 23:59:59', $add_time));
            $now_time = time();
            if ($end_time <= $now_time) {
                $qrCodeUrl = $this->config['site_url'].'/static/images/house/visitor/QRCodeinvalid.png';// 默认失效图片
            }
            $arr['visitorQRCode'] = $getFaceCloud260Judge;
            if (isset($qrCodeUrl) && $qrCodeUrl) {
                $arr['visitorQRCodeUrl'] = $qrCodeUrl;
            }

            if ($end_time > $now_time && $res['visitor_bind_id'] && $qrCodeUrl) {
                fdump_api(['msg' => '详情下发', 'res' => $res], 'visitor/ownerAddVisitorLog',1);
                $face_device = D('House_face_img')->house_user_face_device_info(0, $res['visitor_bind_id']);
                fdump_api(['msg' => '详情下发结果', 'face_device' => $face_device], 'visitor/ownerAddVisitorLog',1);
            }
        }

        $hik_info_vision_i_community_app_key=C('config.hik_info_vision_i_community_app_key');
        $hik_info_vision_i_community_app_secret=C('config.hik_info_vision_i_community_app_secret');
        if($hik_info_vision_i_community_app_key && $hik_info_vision_i_community_app_secret && $res['visitor_bind_id']>0){
            $arr['visitorQRCode']=true;
            $arr['visitorQRCodeUrl']='';
            $visitor_bind=$House_village_user_bindModel->where(array('village_id'=>$res['village_id'],'pigcms_id'=>$res['visitor_bind_id']))->find();
            if ($visitor_bind['property_endtime'] <= $now_time) {
                $arr['visitorQRCodeUrl'] = $this->config['site_url'].'/static/images/house/visitor/QRCodeinvalid.png';// 默认失效图片
            }else if($visitor_bind['hik_community_card_no']){
                $arr['visitorQRCodeUrl']=$this->config['site_url'].U('get_own_qrcode',array('qrCon'=>$visitor_bind['hik_community_card_no']));
            }elseif($visitor_bind['property_endtime']>$now_time && empty($visitor_bind['hik_community_card_no'])){
                //获取二维码信息
                $duration=($visitor_bind['property_endtime']-$now_time)/60;
                $duration=ceil($duration);
                $hikRet=invoke_v20_service('\app\community\model\service\Device\HikInfoVisionICommunityService/getDoorbarCodeStr', ['village_id'=>$visitor_bind['village_id'],'pigcms_id'=>$visitor_bind['pigcms_id'],'uid'=>$visitor_bind['uid'],'duration'=>$duration]);
                $arr['hikRet']=$hikRet;
                if($hikRet && isset($hikRet['data']) && isset($hikRet['data']['retval']) &&  !empty($hikRet['data']['retval'])){
                    $cardBindInfo=$hikRet['data']['retval'];
                    if(isset($cardBindInfo['bar_code']) && !empty($cardBindInfo['bar_code'])){
                        $arr['visitorQRCodeUrl']= $this->config['site_url'].U('get_own_qrcode',array('qrCon'=>$cardBindInfo['bar_code']));
                    }
                }
            }
        }

        $is_func_cloudmrsqfw_special=D('Config_customization')->getFuncCloudmrsqfwSpecial();
        if($is_func_cloudmrsqfw_special && $res['visitor_bind_id']>0){
            $visitor_bind=$House_village_user_bindModel->where(array('village_id'=>$res['village_id'],'pigcms_id'=>$res['visitor_bind_id']))->find();
            $whereArr=array('village_id'=>$res['village_id']);
            $village_data = M('House_village')->where($whereArr)->find();
            if($village_data && !empty($village_data['lilin_pf_client_id']) && !empty($village_data['lilin_pf_client_secret']) && !empty($village_data['lilin_village_no']) && $visitor_bind['third_type']=='lilin_pf' && $visitor_bind['uid_third_id']){
                $whereArr=array('village_id'=>$res['village_id'],'third_dev_source'=>'lilin_pf','third_dev_id'=>array('neq',''),'is_del'=>array('lt',4));
                $lilin_third_dev= D('House_face_device')->where($whereArr)->find();
                if($lilin_third_dev){
                    $models = '\app\community\model\service\Device\LiLinDevAccessApiService/getUserOpenCode';
                    $param = [
                        'pigcms_id' => $res['visitor_bind_id'],
                        'village_id'=>$res['village_id'],
                        'is_visitor'=>1,
                    ];
                    $resultLiLin = invoke_v20_service($models,$param);
                    $retvalOpt = $resultLiLin['data']['retval'];
                    fdump_api(['param' =>$param, 'resultLiLin' => $resultLiLin], 'LiLinDevAccess/getUserOpenCode',1);
                    if (isset($retvalOpt['codeUrl']) && $retvalOpt['codeUrl']) {
                        $arr['visitorQRCode']=true;
                        $arr['visitorQRCodeUrl']= $retvalOpt['codeUrl'];
                    }
                }
            }
        }

        $hasXiHan = 0;
        $db_house_face_device = M('House_face_device');
        $getXiHanJudge = D('Config_customization')->getFaceXiHanDoorSwitch();
        fdump_api(['getXiHanJudge' => $getXiHanJudge], 'xiHanQrCodeResult');
        $xiHanResult = [];
        $xiHanQrCodeResult = [];
        $village_id = isset($res['village_id']) && $res['village_id'] ? $res['village_id'] : 0;
        if ($getXiHanJudge) {
            $whereFace = [
                'village_id' => $village_id, 'device_type' => 31, 'is_del' => 0,
            ];
            $deviceInfo = $db_house_face_device->where($whereFace)->find();
            fdump_api(['whereFace' => $whereFace, 'deviceInfo' => $deviceInfo], 'xiHanQrCodeResult', 1);
            if (isset($deviceInfo['device_id']) && $deviceInfo['device_id']) {
                $hasXiHan = 1;
            }
            fdump_api(['hasXiHan' => $hasXiHan], 'xiHanQrCodeResult', 1);
            if ($hasXiHan == 1 && isset($res['visitor_bind_id']) && $res['visitor_bind_id']) {
                $xiHanParams = [
                    'village_id' => $village_id, 'pigcms_id' => $res['visitor_bind_id']
                ];
                $xiHanParams['hasXiHan'] = $hasXiHan;
                fdump_api(['xiHanParams' => $xiHanParams], 'xiHanQrCodeResult', 1);
                $xiHanResult = invoke_v20_service('\app\community\model\service\Device\XiHanEventService/getUserOpenCode', ['params' => $xiHanParams]);
                fdump_api(['xiHanResult' => $xiHanResult], 'xiHanQrCodeResult', 1);
                $xiHanResult = isset($xiHanResult['data']['retval']) ? $xiHanResult['data']['retval'] : [];
                $xiHanQrCodeResult = isset($xiHanResult['qrCodeInfos']) ? $xiHanResult['qrCodeInfos'] : [];
            }
        }
        fdump_api(['xiHanQrCodeResult' => $xiHanQrCodeResult], 'xiHanQrCodeResult', 1);
        $qrCodeResult = invoke_v20_service('\app\community\model\service\Device\HouseDeviceQrcodeService/addDeviceQrCode', ['pigcms_id' => $res['visitor_bind_id']]);
        $qrCodeResult = isset($qrCodeResult['data']['retval']) ? $qrCodeResult['data']['retval'] : [];
        fdump_api(['qrCodeResult' => $qrCodeResult], 'xiHanQrCodeResult', 1);
        if (! isset($qrCodeResult['qrCodeInfos'])) {
            $qrCodeResult = $xiHanResult;
            $qrCodeInfos = isset($qrCodeResult['qrCodeInfos']) ? $qrCodeResult['qrCodeInfos'] : [];
        } else {
            $qrCodeInfos = isset($qrCodeResult['qrCodeInfos']) ? $qrCodeResult['qrCodeInfos'] : [];
            if (!empty($xiHanQrCodeResult) && empty($qrCodeInfos)) {
                $qrCodeInfos = $xiHanQrCodeResult;
            } elseif (!empty($qrCodeInfos) && !empty($xiHanQrCodeResult)) {
                $qrCodeInfos = array_merge($qrCodeInfos, $xiHanQrCodeResult);
            }
        }
        fdump_api(['qrCodeInfos' => $qrCodeInfos], 'xiHanQrCodeResult', 1);
        $qrCodeResult['qrCodeInfos'] = $qrCodeInfos;
        $arr['qrCodeResult'] = $qrCodeResult;
        $qrCount = count($qrCodeInfos) + 1;
        if (isset($arr['visitorQRCodeUrl']) && $arr['visitorQRCodeUrl']) {
            $qrCount += 1;
        }
        $arr['qrCount'] = $qrCount;

        $this->returnCode(0, $arr);
    }
    
