    //访客通行
    public function visitor_list()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '0','intval');//房间号
        $visitortype = I('visitor_type', '','trim'); //myall 所有
        if (empty($pigcms_id) && $visitortype!='myall') {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $page = I('page',1);
        //业务处理
        $arr = [];
        $database_house_village_visitor = D('House_village_visitor');
        $bind_info = $this->check_village_session($village_id, $pigcms_id);
        $arr['owner_name']='';
        $arr['owner_phone']='';
        $arr['address']='';
        if($bind_info){
            $arr['owner_name'] = $bind_info['name'];
            $arr['owner_phone'] = $bind_info['phone'];
            $arr['address'] = D('House_village')->get_single_floor_room($bind_info['single_id'],$bind_info['floor_id'],$bind_info['layer_id'],$bind_info['vacancy_id'],$bind_info['village_id']);
        }
        $has_visitor = $this->getHasConfig($village_id, 'has_visitor');
        $visitor_type = $database_house_village_visitor->visitor_type;
        $village_name = M('House_village')->where(['village_id' => $village_id])->getField('village_name');
        if($has_visitor){
            $where['village_id'] = $village_id;
            if($visitortype=='myall'){
                $where['uid'] = $this->_uid;
            }else{
                $where['owner_uid'] = $this->_uid;
            }
            $where['status'] = ['in', [0,3]];
            $lists = $database_house_village_visitor->house_village_visitor_page_list_api($where,true,'id desc',20,$page);
            $status_desc =  array('未通行','已通行（业主）','已通行（小区）','未到访','已到访', '已通行（人脸门禁）');
            $dataList = [];
            if($lists){
                foreach($lists as $k=>$v){
                    $detail_url = "pages/village_my/shareVisitor?visitor_id={$v['id']}&village_id={$village_id}&pigcms_id={$pigcms_id}&village_name={$village_name}&visitor_type={$visitortype}";
                    $list = [];
                    $list['id']                = $v['id'];
                    $list['owner_uid']         = $v['owner_uid'];
                    $list['visitor_name']      = $v['visitor_name'];
                    $list['visitor_phone']     = $v['visitor_phone'];
                    $list['time_txt']          = $v['time'] > 0 ? date('Y-m-d H:i:s', $v['time']) : '';
                    $list['add_time']          = $v['add_time'] == 0 ? '' : date('Y-m-d', $v['add_time']);
                    $list['pass_time']         = $v['pass_time'] == 0 ? '' : date('Y-m-d H:i:s', $v['pass_time']);//放行时间
                    $list['status']            = $v['status'];
                    $list['statusDesc']        = $status_desc[$v['status']];
                    $list['memo']              = $v['memo'];
                    $list['visitor_type']      = $v['visitor_type'];
                    $list['visitor_type_desc'] = $visitor_type[$v['visitor_type']];
                    $list['detail_url']        = get_base_url($detail_url);
                    if($visitortype=='myall'){
                        $list['visitor_type_desc']='';
                    }
                    $dataList[] = $list;
                }
            }
            $arr['dataList'] = $dataList;
            if ($bind_info && in_array($bind_info['type'],[0,3])) {
                $arr['is_owner'] = true;
            } else {
                if( $visitortype=='myall'){
                    $arr['is_owner'] = true;
                    $arr['msg'] = '';
                }else{
                    $arr['is_owner'] = false;
                    $arr['msg'] = '您当前不是业主身份无法使用该功能';
                }

            }
            //$arr['is_owner'] = true;

            $this->returnCode(0, $arr);
        }else{
            $this->returnCode('20090176');
        }
    }

    //确认通行
    public function chk_visitor_info()
    {
        $id = I('id');
        if (!$id) {
            $this->returnCode('20090171');
        }
        $database_house_village_visitor = D('House_village_visitor');
        $where['id'] = $id;
        $data['status'] = 1;
        $data['pass_time'] = time();
        $result = $database_house_village_visitor->where($where)->save($data);
        if (!$result) {
            $this->returnCode('20120040');
        } else {
            $this->returnCodeOk('放行成功');
        }
    }

    public function visitor_history_list()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }

        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $page = I('page',1);
        $arr = [];

        $bind_info = $this->check_village_session($village_id, $pigcms_id);
        if (!in_array($bind_info['type'],[0,3])) {
            $this->returnCodeError('您当前不是业主身份无法使用该功能');
        }

        $arr['owner_name'] = $bind_info['name'];
        $arr['owner_phone'] = $bind_info['phone'];
//        $arr['address'] = $bind_info['address'];
        $arr['address'] = D('House_village')->get_single_floor_room($bind_info['single_id'],$bind_info['floor_id'],$bind_info['layer_id'],$bind_info['vacancy_id'],$bind_info['village_id']);
        $database_house_village_visitor = D('House_village_visitor');
        $visitor_type = $database_house_village_visitor->visitor_type;
        $has_visitor = $this->getHasConfig($village_id, 'has_visitor');
        if($has_visitor){
            $where['village_id'] = $village_id;
            $where['owner_uid'] = $this->_uid;
            $where['status'] = array('neq',0);
            $lists = $database_house_village_visitor->house_village_visitor_page_list_api($where,true,'id desc',20,$page);
            $status_desc     = $database_house_village_visitor->status_desc;
            $status_desc_img = $database_house_village_visitor->status_desc_img;
            $dataList = [];
            if($lists){
                $village_name = M('House_village')->where(['village_id' => $village_id])->getField('village_name');
                $site_url = $this->config['site_url'];
                foreach($lists as $k=>$v){
                    $detail_url = "pages/village_my/shareVisitor?visitor_id={$v['id']}&village_id={$village_id}&pigcms_id={$pigcms_id}&village_name={$village_name}";
                    $list['id'] = $v['id'];
                    $list['owner_uid'] = $v['owner_uid'];
                    $list['visitor_name'] = $v['visitor_name'];
                    $list['visitor_phone'] = $v['visitor_phone'];
                    $list['time_txt'] = $v['time'] > 0 ? date('Y-m-d H:i:s', $v['time']) : '';
                    $list['add_time'] = $v['add_time'] == 0 ? '' : date('Y-m-d', $v['add_time']);
                    $list['pass_time'] = $v['pass_time'] == 0 ? '' : date('Y-m-d H:i:s', $v['pass_time']);//放行时间
                    $list['status'] = $v['status'];
                    $list['car_id'] = $v['car_id'] ? $v['car_id'] : '';
                    $list['statusDesc'] = $status_desc[$v['status']];
                    $list['statusImg'] = isset($status_desc_img[$v['status']]) ? $site_url. $status_desc_img[$v['status']].'?t=01' : '';
                    $list['memo'] = $v['memo'];
                    $list['visitor_type'] = $v['visitor_type'];
                    $list['visitor_type_desc'] = $visitor_type[$v['visitor_type']];
                    $list['detail_url'] = get_base_url($detail_url);
                    $list['pass_url'] = $site_url . '/wap.php?c=Login&a=visitor_pass&visitor_id='.$v['id'];
                    $dataList[] = $list;
                }
            }
            $arr['dataList'] = $dataList;

            $this->returnCode(0, $arr);
        }else{
            $this->returnCode('20090176');
        }

    }


