                $village_type = I('village_type','house');
                $aBbs	=	D('Bbs')->isVillage($village_id,$village_type);
                $aBbsAricle	=	M('Bbs_aricle')->where(array('uid'=>$this->_uid,'aricle_status'=>1,'bbs_id'=>$aBbs['bbs_id']))->select();
                if($aBbsAricle){
                    $aricle = [];
                    foreach($aBbsAricle as $k=>$value){
                        $aricle[] = $value['aricle_id'];
