//            $this->returnCode('20120004');
//        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        $aricle_id = I('aricle_id');
        if(empty($aricle_id)){
            $this->returnCode('30000003');
        }

        $findCat_id = M('Bbs_aricle')->where(array('aricle_id' => $aricle_id,'uid'=>$this->_uid))->delete();
        if($findCat_id){
            M('Bbs_comment')->where(array('aricle_id' => $aricle_id,'uid'=>$this->_uid))->delete();
            D('Bbs_praise')->where(array('aricle_id' => $aricle_id,'uid'=>$this->_uid))->delete();
            $this->returnCodeOk(L_('删除成功!'));
        }else{
            $this->returnCodeOk(L_('删除失败!'));
        }


    }

    public function my_web_bbs_aricele_details()
    {
        $arr = array();
        if(empty($this->_uid)){
            $this->returnCode('20000009');
        }
        $village_id = I('village_id');
        $aricle_id = I('aricle_id', 109);
        $page = I('page', 1);
        $zanPageNumber = I('zanPageNumber', 1);
        if (empty($aricle_id)) {
            $this->returnCode('30000003');
        }
        //M('Bbs_aricle')->where(array('aricle_id' => $aricle_id))->setInc('browse_num');
        $cat_id = I('cat_id', 0);
        if (empty($cat_id)) {
            $cat_id = I('cat_id', 0);
        }
        if (empty($cat_id)) {
            $findCat_id = M('Bbs_aricle')->field('cat_id')->where(array('aricle_id' => $aricle_id))->find();
            $cat_id = $findCat_id['cat_id'];
        }
        $cateName = M('Bbs_category')->field('cat_name')->where(array('cat_id' => $cat_id))->find();

        $status = I('status', 2);
        if ($this->_uid) {
            $mezan_num = D('Bbs_praise')->where(array('aricle_id' => $aricle_id, 'uid' => $this->_uid))->count();
            if ($mezan_num) {
                if ($mezan_num > 0) {
                    $mezan = 1;//已赞
                } else {
                    $mezan = 0;//未赞
                }
            } else {
                $mezan = 0;//未赞
            }
        }


        $aDetails = D('Bbs')->bbsAricleDetailsNew($aricle_id);
        if ($aDetails['uid']['uid'] == $this->_uid) {
            $is_uid = 1;
        } else {
            $is_uid = 2;
        }
        if ($aDetails && is_array($aDetails)) {
            $aDteais = $this->bbsAricleFormatNew(array($aDetails));


            $aComment = D('Bbs')->bbsAricleComment($aricle_id, $page, 9999);
            $d_user = D('User');
            if ($aComment['status'] != 0) {
                foreach ($aComment['list'] as $k => $v) {
                    if (empty($v['uid']['avatar'])) {
                        $aComment['list'][$k]['uid']['avatar'] = C('config.site_url') . '/static/images/user_avatar.jpg';
                    } else {
                        $aComment['list'][$k]['uid']['avatar'] = replace_file_domain($aComment['list'][$k]['uid']['avatar']);
                    }

                    if ($v['comment_fid'] > 0) {
//                        $v['comment_id']
                        $comment = M('Bbs_comment')->where(array('comment_id' => $v['comment_fid']))->find();
                        $nickname = $d_user->where(array('uid' => $comment['uid']))->getField('nickname');
                        if (!$nickname) {
                            $nickname = '';
                        }
                        $aComment['list'][$k]['comment_fid_nickname'] = $nickname;
                    }
                    if ($this->_uid) {
                        if ($v['uid']['uid'] == $this->_uid) {
                            $aComment['list'][$k]['uid']['status'] = 1;
                        } else {
                            $aComment['list'][$k]['uid']['status'] = 2;
                        }
                    } else {
                        $aComment['list'][$k]['uid']['status'] = 2;
                    }

                    $aComment['list'][$k]['create_time'] = date('m-d H:i', $aComment['list'][$k]['create_time']);
                }
            }
        }

        $aZanList = D('Bbs')->bbsAricleGetZan($aricle_id, $zanPageNumber, 9999);

        $tmp_aZanList = array();
        foreach ($aZanList as $k => $v) {
            $tmp_aZanList[] = $v;
        }
        $aZanList = $tmp_aZanList;
        foreach ($aZanList as $k => $v) {
            if ($this->_uid) {
                if ($this->_uid == $v['uid']['uid']) {
                    $exist = 1;
                    break;
                } else {
                    $exist = 0;
                }
            } else {
                $exist = 0;
            }

        }

        if ($aDteais[0]['type'] == 1) {
            $activity_apply_num = D('Bbs_activity_apply')->where(array('bbs_id' => $aDteais[0]['aricle_id'], 'is_del' => 0))->count();
            $aDteais[0]['activity_apply_num'] = $activity_apply_num;
        }

        if ($this->_uid) {
            $database_bbs_activity_apply = D('Bbs_activity_apply');
            $is_bbs_activity_apply = ($database_bbs_activity_apply->where(array('aricle_id' => $_GET['aricle_id'], 'uid' => $this->_uid))->count()) ? true : false;
        } else {
            $is_bbs_activity_apply = false;
        }


        $arr = array(
            'aricle_id' => $aricle_id,
            'mezan' => $mezan,
            'cat_id' => $cat_id,
            'status' => $aricle_id,
            'village_id' => $village_id,
            'index' => $cateName['cat_name'],
            'aDetails' => $aDteais[0],
            'is_uid' => $is_uid,
            'aComment' => $aComment['list'],
            'aZanList' => $aZanList,
            'exist' => $exist,
            'img' => $this->imgGet(),
            'page' => $page,
            'is_bbs_activity_apply' => $is_bbs_activity_apply,
        );


        $this->returnCode(0, $arr);
    }


    public function service_list(){
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $userinfo = D('User')->get_user($this->_uid); //===>郭先森===>传入uid

        $page = I('page',1);
        $id = I('id');
        if(empty($id)){
            $this->returnCode('30000006');
        }
        $arr = [];
        $database_house_service_info = M('House_service_info');
        $return['count'] = $database_house_service_info->where(array('cat_id'=>$id,'status'=>'1'))->count();
        if($return['count'] > ($page-1)*10){
            $return['list'] = $database_house_service_info->field('`id`,`title`,`phone`,`img_path`,`url`')->where(array('cat_id'=>$id,'status'=>'1'))->order('sort DESC,id ASC')->limit((($page-1)*10).',10')->select();
            foreach($return['list'] as &$serviceValue){
                if(!$serviceValue['phone']){
                    $serviceValue['phone'] = '';
                }
                if(!empty($serviceValue['img_path'])){
                    $serviceValue['img_path'] = file_domain().'/upload/service/'.$serviceValue['img_path'];
                }else{
                    $serviceValue['img_path'] = '';
                }
                $tmpLbs = wapLbsTranform($serviceValue['url'],array('title'=>$serviceValue['title'],'pic'=>$serviceValue['img_path'],'phone'=>$serviceValue['phone']),true);
                if(is_array($tmpLbs)){
                    $serviceValue['url'] = $tmpLbs['url'];
                    $long_lat = D('User_long_lat')->getLocation($userinfo['openid']);
                    if($long_lat){
                        import('@.ORG.longlat');
                        $longlat_class = new longlat();
                        $serviceValue['range'] = $longlat_class->GetDistanceMToKm($long_lat['lat'],$long_lat['long'],$tmpLbs['lat'],$tmpLbs['long'],true);
                    }
                }
            }
        }else{
            $return['list'] = array();
        }
        $arr['list'] = $return['list'];
        $this->returnCode(0, $arr);

    }

