            $village_vacancy_list['village_address']     =  $v4['village_address'];
            $village_vacancy_list['floor_id']          =  $v4['floor_id'];
            $village_vacancy_list['floor_name']          =  $v4['floor_name'];
            $village_vacancy_list['floor_layer']         =  $v4['floor_layer'];
            $village_vacancy_list['type']         =  $v4['type'];

