                $village_vacancy_list['del_status_desc'] = '';
                $village_vacancy_list['desc'] = '加入失败';
            }
            $my_village_vacancy_data[] = $village_vacancy_list;
        }
//        $my_village['my_village_vacancy'] = $my_room_not_master;
        $my_village['my_village_vacancy_data'] = $my_village_vacancy_data;
        $this->returnCode(0, $my_village);
    }

