                    $protocol['pcontent']=htmlspecialchars_decode($protocol['pcontent'],ENT_QUOTES);
                    $protocol['pcontent']=replace_file_domain_content($protocol['pcontent']);
                    $my_village['protocol']=$protocol;
                }
            }
        }

        
        $this->returnCode(0, $my_village);
    }
    
    public function get_user_bind_vacancy_protocol(){
        $village_id=trim($_POST['village_id']);
        $village_id=intval($village_id);
        $id=trim($_POST['id']);
        $id=intval($id);
        $whereArr=array('cfromtype'=>'user_bind_vacancy');
        if($village_id>0){
            $whereArr['village_id']=$village_id;
            if($id>0){
                $whereArr['id']=$id;
            }
            $protocol=D('House_village_protocol')->where($whereArr)->order('id desc')->find();
            if(!empty($protocol)){
                $protocol['status']=intval($protocol['status']);
                $protocol['pcontent']=htmlspecialchars_decode($protocol['pcontent'],ENT_QUOTES);
                $protocol['pcontent']=htmlspecialchars_decode($protocol['pcontent'],ENT_QUOTES);
                $protocol['pcontent']=replace_file_domain_content($protocol['pcontent']);
                $this->returnCode(0, $protocol);
            }
        }
        $protocol=array('id'=>$id,'village_id'=>$village_id,'pcontent'=>'','ptitle'=>'');
        $this->returnCode(0, $protocol);
    }

    public function get_house_user_register_protocol(){
        $village_id=I('village_id');
        $phone = I('phone');
        $phone=trim($phone);
        $village_id=intval($village_id);
        $show_sky_cockpit_entrance=C('config.show_sky_cockpit_entrance');
        $show_sky_cockpit_entrance=$show_sky_cockpit_entrance ? intval($show_sky_cockpit_entrance):0;
        $house_register_agreement=C('config.house_register_agreement');
        $house_register_agreement=trim($house_register_agreement);
        if($house_register_agreement){
            $house_register_agreement=str_replace(PHP_EOL,'<br/>',$house_register_agreement);
        }
        $site_name=C('config.site_name');
        $house_register_protocol=array('is_intercept_handle'=>0,'house_name'=>$site_name,'protocol_content'=>'','is_customized'=>0,'phone'=>$phone);
        $sqAeondeLightJiangsuCustomized_judge = D('Config_customization')->getSqAeondeLightJiangsuCustomized();
        if($sqAeondeLightJiangsuCustomized_judge){
            $register_agreement=C('config.register_agreement');
            $house_register_protocol['protocol_content']=$register_agreement;
        }
        if($show_sky_cockpit_entrance>0 ){
            $house_register_protocol['is_customized']=1;
            $house_register_protocol['protocol_content']=$house_register_agreement;
            if(!empty($phone)){
                $user=D('User')->where(array('phone'=>$phone))->find();
                if(empty($user)){
                    $house_register_protocol['is_intercept_handle']=1;
                }else if($user['source']=='houseautoreg' && $user['add_time']==$user['last_time']){
                    $house_register_protocol['is_intercept_handle']=1;
                }
            }
        }
        $this->returnCode(0, $house_register_protocol);
    }
    
    //确认拒绝绑定
    public function child_bind()
    {
        $pigcms_id = I('pigcms_id');
        if(empty($pigcms_id)){
            $this->returnCode('50000004');
        }
        $no_bind = I('no_bind');
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $now_village = D('House_village')->where(array('village_id'=>$village_id))->find();
        $database_house_village_user_bind = D('House_village_user_bind');
        $now_user = $database_house_village_user_bind->get_one_by_bindId($pigcms_id);
        if(!$now_user){
            $this->returnCode('72000050');//信息暂时不存在!
        }

        if(!$no_bind) {
            if ($now_user['status'] == 1) {
                $this->error('20090194');//已通过审核
            }
        }

        // 平台用户
        $user_info = D('User')->get_user($now_user['phone'], 'phone');

        fdump_api(['单个编辑业主'.__LINE__,$_GET,$_POST,$no_bind,$this->user_session],'house/houseApi/child_bind_log',1);

        if($no_bind){
            $reason = trim(I('reason')) ? htmlspecialchars(trim(I('reason'))) : '无';
            $insert_id = $database_house_village_user_bind->where(array('pigcms_id'=>$pigcms_id))->data(array('pass_time'=>time(),'status'=>0,'reason'=>$reason))->save();

            if($now_user['type'] != 3){
                if ($now_user['status'] == 1 ) {
                    $first = '您在【'.$now_village['village_name'].'】的'.(C('config.open_house_user_name')?'亲友':'家属').'入住申请已解绑。原因：'.$reason.'\n';
                    $keyword1 = ''.(C('config.open_house_user_name')?'亲友':'家属').'入住申请';
                }else{
                    $first = '您在【'.$now_village['village_name'].'】的'.(C('config.open_house_user_name')?'亲友':'家属').'入住申请审核未通过。原因：'.$reason.'\n';
                    $keyword1 = ''.(C('config.open_house_user_name')?'亲友':'家属').'入住申请';
                }
            }else{
                $first = '您在【'.$now_village['village_name'].'】的替换房主申请审核未通过。原因：'.$reason.'\n';
                $keyword1 = '替换房主申请';
            }
        }else{
            if($now_user['type'] != 3){
                // 房屋信息
                $database_house_village_user_vacancy = D('House_village_user_vacancy');
                $vacancy_condition['pigcms_id'] = $now_user['vacancy_id'];
                $bind_info = $database_house_village_user_vacancy->where($vacancy_condition)->find();
                if($now_user['phone'] == $bind_info['phone']){
                    if ($bind_info['status']==2) {
                        if ($_GET['data_type'] == 'json' ) {
                            exit(json_encode(array('status'=>1,'msg'=>'该手机号已提交申请')));
                        }
                        $this->error('该手机号已提交申请');
                    }else{
                        if ($_GET['data_type'] == 'json' ) {
                            exit(json_encode(array('status'=>1,'msg'=>'手机号不能与业主一致')));
                        }
                        $this->error('手机号不能与业主一致');
