                // $database_house_village_user_bind->where(array('pigcms_id'=>$now_user['parent_id']))->data(array('status'=>0))->save();
                #修改之前房主下面的绑定亲属/租客 替换到现在房主下面
                // $database_house_village_user_bind->where(array('parent_id'=>$now_user['parent_id']))->data(array('parent_id'=>$now_user['pigcms_id']))->save();
                $reason = '';
                $first = '您在【'.$now_village['village_name'].'】的替换房主申请审核已通过'.$reason.'\n';
                $keyword1 = '替换房主申请';
            }
        }

        //发送模板消息
        if ($user_info['openid']) {
            $href = C('config.site_url').'/wap.php?g=Wap&c=House&a=my_village_list';
            $model = new templateNews(C('config.wechat_appid'), C('config.wechat_appsecret'));
            $model->sendTempMsg('OPENTM405462911', array('href' => $href, 'wecha_id' => $user_info['openid'],'first' => $first, 'keyword1' =>  $keyword1,  'keyword2' => '已发送', 'keyword3' => date('Y-m-d H:i:s',$_SERVER['REQUEST_TIME']), 'keyword4' => $user_info['nickname'], 'remark' => '\n请点击查看详细信息！'),0,$now_village['property_id'],1);
        }

        if($insert_id){
            // 修改信息，进行同步
            D('House_village_face_door')->modify_user($insert_id);

            $this->returnCodeOk(L_('修改成功'));
