            $this->returnCodeOk(L_('修改成功'));

        }

    }

    // 删除申请记录 业主
    public function delete_audit_yezhu(){
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $pigcms_id = I('pigcms_id');
        if(!$pigcms_id){
            $this->returnCode('20090171');
        }
        $result=D('House_village_user_bind')->user_bind_del($pigcms_id);
        if(!$result['error']){
            $this->returnCode('20046026');
        }else{
            $this->returnCodeOk(L_('删除申请成功'));
        }
        exit();

        //查询bind信息
        $database_house_village_user_vacancy = D('House_village_user_vacancy');

        $bind_info = $database_house_village_user_vacancy->where(array('pigcms_id'=>$pigcms_id))->find();
        if(!$bind_info){
            $this->returnCode('20090198');
        }

        if($bind_info['status'] != 2){
            $this->returnCode('20090212');
        }

        if ($bind_info['uid'] != $this->_uid) { //不是当前用户信息
            $this->returnCode('20090213');
        }
        $where = array();
        $where['pigcms_id'] = $pigcms_id;
        $data = array(
            'status' => 1, //空置
            'uid' => 0,
            'name' => '',
            'phone' => '',
        );
        $result = $database_house_village_user_vacancy->where($where)->data($data)->save();
        if($result){
            $this->returnCodeOk('删除申请成功!');
        }else{
            $this->returnCodeOk('删除申请失败!');
        }
    }

    #用户删除申请记录 房主/亲属/租客
    public function delete_audit(){
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $pigcms_id = I('pigcms_id');
        if(!$pigcms_id){
            $this->returnCode('20090171');
        }

