        if(!$bind_info){
            $this->returnCode('20090214');
        }

        if($bind_info['status'] != 2){
            $this->returnCode('20090212');
        }
        if ($bind_info['uid'] != $this->_uid) { //不是当前用户信息
            //查看是不是业主删除家属记录
            $user_info = $database_house_village_user_bind->where(array('vacancy_id'=>$bind_info['vacancy_id'],'type'=>0,'status'=>1,'uid'=>$this->_uid))->find();
