                'uid' => 0,
                'name' => '',
                'phone' => '',
            );
            D('House_village_user_vacancy')->where($where)->data($data)->save();
        }
        if($result){
            $this->returnCodeOk('删除申请成功!');
        }else{
            $this->returnCodeOk('删除申请失败!');
        }
    }

    #删除业主下面的租客/亲属
    public function delete_bind(){
        $data_pigcms_id = I('pigcms_id');
        $data_village_id = I('village_id');
        if(!$data_pigcms_id || !$data_village_id){
            $this->returnCode('20090171');
        }
        $where['pigcms_id'] = $data_pigcms_id;
        $where['village_id'] = $data_village_id;

        $database_house_village_user_bind = D('House_village_user_bind');
        //增加记录
        $user_bind = $database_house_village_user_bind->where($where)->find();
        $data['village_id'] = $user_bind['village_id'];
        $data['vacancy_id'] = $user_bind['vacancy_id'];
        $data['floor_id'] = $user_bind['floor_id'];
        $data['uid'] = $user_bind['uid'];
        $data['name'] = $user_bind['name'];
        $data['phone'] = $user_bind['phone'];
        $data['type'] = $user_bind['type'];
        $data['check_in_time'] = $user_bind['add_time'];
        $data['user_bind_id'] = $data_pigcms_id;
        $data['add_time'] = time();
        M('house_village_user_record')->data($data)->add();
        
        fdump_api([$user_bind, $_POST],'house_user_bind/user_bind_delete_log',1);
        $nowTime = time();
        $insert_id = $database_house_village_user_bind->where($where)->data(['usernum'=>$user_bind['usernum'].'_'.$data_pigcms_id.'del'.$nowTime,'status'=>4])->save();
        $database_house_village_user_bind->delLiLinPfHousehold($data_pigcms_id,0,$data_village_id);
        // 删除  同步进行删除
        try {
            D('House_village_face_door')->del_a3_user_bind($data_pigcms_id, $user_bind['village_id'],$user_bind);
        }catch (\Exception $e) {
            fdump_api(['删除时同步设备出错'.__LINE__,$data_pigcms_id,$user_bind,$e->getMessage()],'house_user_bind/del_a3_user_bind_log_err',1);
        }
        
        if($insert_id){
            $this->returnCodeOk('删除成功!');
        }else{
            $this->returnCodeOk('删除失败!');
        }
    }

