    //审核失败,重新加入房间====>郭先森 需要审核
    public function village_room_info_add(){
        $ExternalUserID = I('ExternalUserID','');
        $type = trim($_POST['type']);//角色身份
        $attribute = intval($_POST['attribute']);//属性
        $phone = trim($_POST['phone']); //我的手机号
        $name = trim($_POST['name']); //名称
        $chk_phone = trim($_POST['master_phone']); //获取业主的手机号
        //         资料字段开始
        $data_post = $_POST['dataList'];
        if($data_post){
            foreach($data_post as $k=>$v){
                if($v['is_must'] == 1 && empty($v['value'])){
                    $this->returnCodeError($v['title'].'为必填项！');
                }
            }
            $arr_data = [];
            foreach($data_post as $kk=>$vv){
                if($vv['value']){
                    $arr1[$vv['key']] = array(
                        'type'=>$vv['type'],
                        'is_must'=>$vv['is_must'],
                        'key'=>$vv['key'],
                        'title'=>$vv['title'],
                        'value'=>$vv['value'],

                    );
                }else{
                    $arr1[$vv['key']] = array(
                        'type'=>$vv['type'],
                        'is_must'=>$vv['is_must'],
                        'key'=>$vv['key'],
                        'title'=>$vv['title'],
                        'value'=>'',

                    );
                }

                $arr_data = $arr1;
            }
            $bind_data['authentication_field'] = serialize($arr_data);
        }else{
            $bind_data['authentication_field'] = '';
        }


//        $bind_data['authentication_field'] = serialize($data_post);
//         资料字段结束
        $pigcms_id = trim($_POST['pigcms_id']);//房间id
        if(!$pigcms_id){
            $this->returnCode('20090171');
        }

        if(!$phone || empty($phone)){
            $this->returnCodeError('请填写手机号');
        }

        if(!$name){
            $this->returnCodeError('请填写正确的姓名');
        }
        $id_card = I('id_card');

        if(!$this->config['international_phone'] && !preg_match('/^[0-9]{11}$/',$phone)){
            $this->returnCode('20042003');
        }

        $database_house_village_user_bind = D('House_village_user_bind');
        $database_house_village_user_vacancy = D('House_village_user_vacancy');

        $database_house_village = D('House_village');
        $database_house_village_floor = D('House_village_floor');

        $bind_where['pigcms_id'] = $pigcms_id;
        $bind_where['is_del'] = 0;
        $bind_info = $database_house_village_user_vacancy->where($bind_where)->find(); // 房间信息
        //业主主动入住身份证号填写设置 2020/11/12 start
        $fieldStr='village_id,village_name,village_address,property_name,property_phone,property_address,openid,property_id,set_id_code';
        $house_village_info = D('House_village')->get_village_info($bind_info['village_id'],$fieldStr);
        if($house_village_info['set_id_code'] == 1){//强制填写
            if(!$id_card){
                $this->returnCodeError('身份证号码不能为空');
            }
            if(is_idcard($id_card) == false){
                $this->returnCodeError('请填写正确的身份证号码');
            }
        }
        //业主主动入住身份证号填写设置 2020/11/12 end
        if(!$bind_info){
            $this->returnCode('20120038');
        }
        $house_village_extend = D('house_village_info')->where(array('village_id'=>$bind_info['village_id']))->find();
        $room_bind_people_num=0;
        if($house_village_extend && isset($house_village_extend['room_bind_people_num']) &&  ($house_village_extend['room_bind_people_num']>0)){
            $room_bind_people_num=$house_village_extend['room_bind_people_num'];
        }
        if ($bind_info && isset($bind_info['bind_people_num']) && ($bind_info['bind_people_num'] > 0)) {
            $room_bind_people_num = $bind_info['bind_people_num'];
        }
        //绑定人数判断
        $whereArr = array();
        $whereArr['status'] = array('in', array(1, 2));
        $whereArr['type'] = array('in', array(0, 1, 2, 3));
        $whereArr['floor_id'] = array('gt', 0);
        $whereArr['vacancy_id'] = $pigcms_id;
