                $this->returnCode('20120053');
            }
        }

        $bind_data['housesize'] = $bind_info['housesize'] + 0;
        $bind_data['park_flag'] = $_POST['park_flag'] + 0;
        if($type == 0){
            if($phone == $bind_info['phone']){
                $this->returnCode('20090196');
            }
            if (!empty($bind_info['phone'])) {
                if ($bind_info['status'] == 2) {
                    $this->returnCode('20090220');
                } else {
                    $this->returnCode('20090221');
                }
