            }

            $floor_condition['floor_id'] =  $bind_info['floor_id'];
            $floor_info = $database_house_village_floor->where($floor_condition)->find();
            $bind_data1['park_flag'] = $_POST['park_flag'] + 0;
            $bind_data1['village_id'] = $bind_info['village_id'];
            $bind_data1['address']    = $floor_info['floor_layer'] . $floor_info['floor_name'] . $bind_info['layer'] . '#' . $bind_info['room'];
            $bind_data1['layer_num']  = $bind_info['layer'];
