    //提交后获取二维码
    public function get_qrcode()
    {
        $phone = I('phone','');
        if(empty($phone)){
            $this->returnCode('10042001');
        }
        $village_id = I('village_id');
        if(empty($village_id)){
            $this->returnCode('20090005');
        }
        $pigcms_id = I('pigcms_id');
        $user = D('User')->where(array('phone'=>$phone))->find();
        if($user['openid']){
            $arr['qrcode_url'] = '';
        }else{
            $house_village = D('House_village')->where(array('village_id'=>$village_id))->find();
            if($house_village){

                $weixin_bind = D('Weixin_bind')->where(array('mer_id' => $house_village['property_id'], 'type' => 2))->find();
                if($weixin_bind){
                    $url = urlencode($weixin_bind['qrcode_url']);
                    $arr['qrcode_url'] = D('Image')->wx_image_download($url,$house_village['property_id']);
//                    $arr['qrcode_url'] = $this->config['site_url'].'/index.php?c=Image&a=wx_image_download&url='.urlencode($weixin_bind['qrcode_url']).'&path='.$house_village['property_id'];
                }else{
//                    $pay_qrcode_url = $this->config['site_url'] . '/index.php?c=Recognition&a=get_tmp_qrcode&qrcode_id=' . (62000000000000 + $pigcms_id);
                    $pay_qrcode_url= $qrcode_return = D('Recognition')->get_tmp_qrcode((2700000000 + $pigcms_id));
                    //二维码
                    if($pay_qrcode_url['error_code'] == false){
                        $arr['qrcode_url'] = $pay_qrcode_url['ticket'];
                    }else{
                        $arr['qrcode_url'] = $this->config['wechat_qrcode'];
                    }

                }
            }
        }
        $this->returnCode(0, $arr);
    }

    #用户解除绑定 房主/亲属/租客
    public function user_unbind(){
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $pigcms_id = I('pigcms_id');
        if(!$pigcms_id){
            $this->returnCode('20090171');
        }
        $note      = trim(I('note'));
        if(empty($note)){
            $this->returnCode('20090215');
        }

        $data['bind_id'] = $pigcms_id;
        $data['note'] = $note;
        $data['addtime'] = $data['edittime'] = time();
        $data['uid'] = $this->_uid;

        //查询bind信息
        $database_house_village_user_bind = D('House_village_user_bind');
        $database_house_village_user_unbind = D('House_village_user_unbind');

        $bind_info = $database_house_village_user_bind->where(array('pigcms_id'=>$pigcms_id , 'uid'=>$data['uid']))->find();
        if($bind_info){

            $unbind_status = $database_house_village_user_unbind->where(array('type'=>$bind_info['type'],'village_id'=>$bind_info['village_id'],'name'=>$bind_info['name'] ,'phone'=>$bind_info['phone'],'floor_id'=>$bind_info['floor_id'],'room_id'=>$bind_info['vacancy_id'],'uid'=>$data['uid'],'status'=>1))->count();
            if($unbind_status > 0){
                $this->returnCode('20090216');
            }

            $data['name'] = $bind_info['name'];
            $data['phone'] = $bind_info['phone'];
            $data['type'] = $bind_info['type'];
            $data['room_id'] = $bind_info['vacancy_id'];
            $data['village_id'] = $bind_info['village_id'];
            $data['floor_id'] = $bind_info['floor_id'];
            $data['status'] = 1;

            $result = $database_house_village_user_unbind->data($data)->add();
            if($result){
                $this->returnCodeOk('提交申请解绑成功!');
            }else{
                $this->returnCodeError('提交申请解绑失败!');
            }
        }else{
            $this->returnCode('20090171');
        }
    }


    //搜索显示小区列表
    public function empty_village_list(){

        $village_name = I('village_name');
        $page = I('page',1);
        if(!empty($village_name)){
            $village_where['village_name'] = array('like' , '%'.$village_name.'%');
        }
        $wxapp_own_village_id = I('wxapp_own_village_id',0);
        if($wxapp_own_village_id){
            $village_lists = M('House_village')->where(['property_id'=>$wxapp_own_village_id,'status'=>1])->field('village_id')->select();
            if($village_lists){
                $village_id = '';
                foreach ($village_lists as $v){
                    $village_id .= $v['village_id'].',';
                }
                $village_id = rtrim($village_id,',');
                $village_where['village_id'] = array('in',$village_id);
            }
        }
        $database_house_village = D('House_village');
        $village_where['status'] = 1;
        $village_list = $database_house_village->where($village_where)->page($page,20)->select();
        $arr = [];
        $dataList = [];
        $arr['totalPage'] = 0;
        $arr['village_count'] = 0;
        if($village_list){
            foreach($village_list as $k=>$v){
                $list['village_id'] = $v['village_id'];
                $list['village_name'] = $v['village_name'];
                $list['village_address'] = $v['village_address'];
                $list['village_logo'] = $v['village_logo'] ? file_domain().$v['village_logo'] : C('config.site_url').'/static/images/wap_house/village_logo.png';
                $list['seal_img_new'] = !empty($v['seal_img_new']) ? file_domain().$v['seal_img_new'] : '';
                $dataList[] = $list;
            }
            $count = $database_house_village->where($village_where)->count();
            $arr['totalPage'] = ceil($count/20);
            $arr['village_count'] = count($village_list);
        }

        $arr['village_list'] = $dataList;
        $this->returnCode(0, $arr);

    }

    public function village_single_list()
    {
        $village_id = I('village_id');
        if(empty($village_id)){
            $this->returnCode('20090005');
        }

        $arr = [];
        //查询小区信息
        $database_House_village = D('House_village');
        $village_info = $database_House_village->get_village_info($village_id);
        $arr['village_id'] = $village_info['village_id'];
        $arr['village_name'] = $village_info['village_name'];
        $arr['village_address'] = $village_info['village_address'];
        $arr['village_logo'] = $village_info['village_logo'] ? file_domain().$village_info['village_logo'] : C('config.site_url').'/static/images/wap_house/village_logo.png';
        $arr['seal_img_new'] = !empty($village_info['seal_img_new']) ? file_domain().$village_info['seal_img_new'] : '';

        //查询小区楼栋信息
        $condition['village_id'] = $village_id;
        $condition['status'] = 1;
        
        $unit_list = M('House_village_single')->where($condition)->order('sort desc, id desc')->select();
        $dataList = [];
        foreach($unit_list as $k=>$v){
            $list['village_id'] = $v['village_id'];
            if(preg_match('/[\x7f-\xff]/', $v['single_name'])) {
                $list['single_name'] = $v['single_name'];
            }else{
                $list['single_name'] = $v['single_name'].'号'.(D('House_village')->getHouseAlias('single_name',$village_id)?:'楼');
            }
            $list['single_id'] = $v['id'];
            $dataList[] = $list;
        }
        $count = M('House_village_single')->where($condition)->count();
        $arr['totalPage'] = ceil($count/20);
        $arr['single_list'] = $dataList;
        $this->returnCode(0, $arr);


    }

    //根据小区 查询单元
    public function village_unit_list(){

        $village_id = I('village_id');
        if(empty($village_id)){
            $this->returnCode('20090005');
        }

        $single_id = I('single_id');
        if(empty($single_id)){
            $this->returnCodeError('楼栋号不存在');
        }
        $arr = [];
        $database_House_village = D('House_village');
        $database_house_village_floor = D('House_village_floor');
        //查询小区信息
        $village_info = $database_House_village->get_village_info($village_id);
        $arr['village_id'] = $village_info['village_id'];
        $arr['village_name'] = $village_info['village_name'];
        $arr['village_address'] = $village_info['village_address'];
        $arr['village_logo'] = $village_info['village_logo'] ? file_domain().$village_info['village_logo'] : C('config.site_url').'/static/images/wap_house/village_logo.png';
        $arr['seal_img_new'] = !empty($village_info['seal_img_new']) ? file_domain().$village_info['seal_img_new'] : '';

        //查询小区单元信息
        $condition['village_id'] = $village_id;
        $condition['status'] = 1;
        $condition['single_id'] = $single_id;

        $count = $database_house_village_floor->where($condition)->count();
        $arr['totalPage'] = ceil($count/20);

        $unit_list = $database_house_village_floor->where($condition)->order('sort desc, floor_id desc')->select();
        $dataList = [];
        foreach($unit_list as $k=>$v){
            $list['village_id'] = $v['village_id'];
            $list['floor_id'] = $v['floor_id'];
            if(preg_match('/[\x7f-\xff]/', $v['floor_name'])) {
                $list['floor_name'] = $v['floor_name'];
            }else{
                $list['floor_name'] = $v['floor_name'].(D('House_village')->getHouseAlias('floor_name',$village_id)?:'单元');
            }
            $list['floor_layer'] = $v['floor_layer'];
            $dataList[] = $list;
        }
        $count = $database_house_village_floor->where($condition)->count();
        $arr['totalPage'] = ceil($count/20);
        $arr['unit_list'] = $dataList;
        $this->returnCode(0, $arr);
    }


