        }
        $arr['vacancy_list'] = $dataList;
        $this->returnCode(0, $arr);
    }

    //通过单元找楼号
    public function get_village_layer_list()
    {
        $floor_id = I('floor_id');
        if(!$floor_id){
            $this->returnCode('20090171');
        }

        $database_house_village = D('House_village');
        $database_house_village_floor = D('House_village_floor');
        $arr = [];
        //查询单元信息 小区信息
        $find_village_floor = $database_house_village_floor->get_unit_find($floor_id , 'village_id,floor_name,floor_layer');
        $find_village = $database_house_village->get_village_info($find_village_floor['village_id'] , 'village_name,village_address');
        $find_info = array(
            'village_name'    =>  $find_village['village_name'],
            'village_address' =>  $find_village['village_address'],
            'floor_name'      =>  $find_village_floor['floor_name'],
            'floor_layer'     =>  $find_village_floor['floor_layer'],
            'village_id'     =>  $find_village_floor['village_id']
        );
        $arr['find_info'] = $find_info;
        $where_layer = [
            'status' => 1,
            'floor_id'=>$floor_id
        ];
        $layer_list = M('House_village_layer')->where($where_layer)->order('sort DESC, id DESC')->select();
        if($layer_list){
            $data_list = [];
            foreach($layer_list as $k=>$v){
                $list['layer_id'] = $v['id'];
                if(preg_match('/[\x7f-\xff]/', $v['layer_name'])) {
                    $list['layer_name'] = $v['layer_name'];
                }else{
                    $list['layer_name'] = $v['layer_name'].'层';
                }
                $list['floor_id'] = $v['floor_id'];
                $list['single_id'] = $v['single_id'];
                $data_list[] = $list;
            }
            $arr['data_list'] = $data_list;
        }else{
            $arr['data_list'] = [];
        }
        $this->returnCode(0, $arr);

    }


