            $list['room'] = $v['room'];
            $list['pigcms_id'] = $v['pigcms_id'];
            $list['room_info'] = $v['room'];
            $dataList[] = $list;
        }
        $arr['vacancy_list'] = $dataList;
        $this->returnCode(0, $arr);
    }



