        //查询用户所属业主的所有房屋列表
        $field = 'pigcms_id as bind_id,park_flag,housesize,village_id,uid,usernum,name,phone,address,layer_num,room_addrss,floor_id,parent_id,add_time,memo,type,relatives_type,vacancy_id as pigcms_id,status,reason,single_id,layer_id';
        $user_all_village_list = $database_house_village_user_bind -> get_my_village_lists($this->_uid,$field,'uid',1);

        $arr = [];
        foreach($user_all_village_list as $k=>&$v){
            //获取小区信息和房间信息
            $find_village_floor = $database_house_village_floor->get_unit_find($v['floor_id'] , 'floor_name,floor_layer,single_id');
