    # 根据手机号 获取用户
    public function empty_bind_relatives_user(){
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $phone = I('relatives_user_phone');//获取输入手机号码的用户信息

        $pigcms_id = I('pigcms_id');//房间id
        if(!$pigcms_id){
            $this->returnCode('20090171');
        }
        if(empty($phone)){
            $this->returnCode('10042001');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $where['uid'] =$this->_uid;
        $where['status'] =1;
        $user = D('User') -> field(true)->where($where)->find();
        if($phone == $user['phone']){
            $this->returnCode('20090217');
        }
        $condition['phone'] = $phone;
        $condition['status'] =1;
        $arr = [];
        $user_info = D('User') -> field(true)->where($condition)->find();
        $house_village = D('House_village')->where(array('village_id'=>$village_id))->field('property_id')->find();
        if($user_info){
            $relatives_user_uid = $user_info['uid'];
            $where_face['uid'] = $relatives_user_uid;
            $where_face['status'] = array('in','0,3');
            $face_img = M('House_face_img')->where($where_face)->select();
            if(empty($face_img)){
                $is_face_upload = false;
            }else{
                $is_face_upload = true;
            }
            $arr['nickname'] = $user_info['nickname'];
            if($user_info['avatar']){
                $arr['avatar'] = replace_file_domain($user_info['avatar']);
            }else{
                $arr['avatar'] = C('config.site_url') . '/static/images/user_avatar.jpg';
            }
            $arr['phone'] = $user_info['phone'];
            if ($house_village['property_id']) {
                $where_data_config = array('village_id'=>0,'property_id'=>$house_village['property_id'],'is_display'=>1,'is_close' => 0);
                //业主资料
                $dataList = D('House_village_data_config')->where($where_data_config)->select();
            } else{
                $dataList = [];
            }
            if (empty($dataList)) {
                $where_data_config = array('village_id'=>$village_id,'is_display'=>1,'is_close' => 0);
                //业主资料
                $dataList = D('House_village_data_config')->where($where_data_config)->select();
            }
            if(!empty($dataList)){
                foreach($dataList as $k=>&$v){

                    unset($v['acid']);
                    unset($v['add_time']);
                    unset($v['sort']);
                    unset($v['village_id']);
                    unset($v['is_display']);
                    if($v['type'] == 2){
                        if($v['is_system'] == 1){
                            $v['use_field'] = D('House_village')->get_system_value($v['key']);
                        }else{
                            $v['use_field'] = explode(',',$v['use_field']);
                        }
                    }elseif($v['type'] == 3){

                        $v['use_field'] = [];
                    }else{
                        $v['use_field'] = [];
                    }
                    $v['value'] = '';

                }

                $arr['dataList'] = $dataList;
            }else{
                $arr['dataList'] = [];
            }
        }else{
//            $arr=$this->getObj();

            //增加渠道二维码以及物业二维码
            $user = D('User') -> field(true)->where($condition)->find();
            if($user['openid']){//有,则关注过
                $arr['qrcode_url'] = '';
                $arr['qrcode_url_status'] = 3;
            }else{
                if($house_village){
                    //物业二维码
                    $weixin_bind = D('Weixin_bind')->where(array('mer_id' => $house_village['property_id'], 'type' => 2))->find();
                    if($weixin_bind){
                        $url = urlencode($weixin_bind['qrcode_url']);
                        $arr['qrcode_url'] = D('Image')->wx_image_download($url,$house_village['property_id']);
//                        $arr['qrcode_url'] = $this->config['site_url'].'/index.php?c=Image&a=wx_image_download&url='.urlencode($weixin_bind['qrcode_url']).'&path='.$house_village['property_id'];
                    }else{
//                    $pay_qrcode_url = $this->config['site_url'] . '/index.php?c=Recognition&a=get_tmp_qrcode&qrcode_id=' . (62000000000000 + $pigcms_id);
                        $pay_qrcode_url= $qrcode_return = D('Recognition')->get_tmp_qrcode((2700000000 + $pigcms_id));
                        if($pay_qrcode_url['error_code'] == false){
                            $arr['qrcode_url'] = $pay_qrcode_url['ticket'];
                        }else{
                            $arr['qrcode_url'] = $this->config['wechat_qrcode'];
                        }


                    }
                }
            }

        }
        $arr['set_id_code'] = D('House_village')->where(array('village_id'=>$village_id))->getField('set_id_code');
        $arr['face_status'] = D('House_village_about_config')->where(array('village_id'=>$village_id))->getField('face_status');
        $my_face_door_switch = $this->config['my_face_door_switch']?1:0;
        if ($my_face_door_switch==1) {
            // 用户端人脸入口，关闭后用户端相关人脸相关入口均会隐藏
            $arr['face_status'] = 3;
        }
        $arr['uid'] = isset($relatives_user_uid)?$relatives_user_uid:0;
        $arr['is_face_upload'] = isset($is_face_upload)?$is_face_upload:false;
	    $arr['use_new_page'] = $this->config['faceImgUseNewPage'] == 1 ? 1 : 0; //有这个值表示后端代码已更新，前端页面根据这个参数判断是否是用新版的人脸上传页面

	    $this->returnCode(0, $arr);

    }

    //绑定家属添加==>郭先森==>未测试
    public function bind_relatives_add()
    {
        $database_house_village_user_vacancy = D("House_village_user_vacancy");
        $database_house_village_floor = D('House_village_floor');
        $database_village_list = D('House_village');
        $database_house_village_user_bind = D('House_village_user_bind');

        $type = trim($_POST['type']);//角色身份
        if(empty($type)){
            $this->returnCodeError('角色为必填项！');
        }
        if($type == 1){
            $relatives_type = I('relatives_type');
            if(empty($relatives_type))
                $this->returnCodeError('请选择关系！');
        }
        $phone = trim(I('phone'));
        $name = trim(I('name'));
        $pigcms_id = intval(I('pigcms_id'));

        $where_bind_info['type'] = array("in" , array(0,3));
        $where_bind_info['status'] = 1;
        $where_bind_info['vacancy_id'] = $pigcms_id;
        $bind_info = $database_house_village_user_bind->where($where_bind_info)->find();
        $set_id_code = M('House_village')->where(['village_id'=>$bind_info['village_id']])->getField('set_id_code');
        if($set_id_code == 1){
            if(!$_POST['id_card']){
                $this->returnCodeError('身份证号码不能为空！');
            }
            if(is_idcard($_POST['id_card']) == false){
                $this->returnCodeError('请填写正确的身份证号码');
            }
            $bind_data['id_card'] = $_POST['id_card'];
        }
        $parent_id = $bind_info['pigcms_id'];
        $data_post = $_POST['dataList'];
        if($data_post){
            foreach($data_post as $k=>$v){
                if($v['is_must'] == 1 && empty($v['value'])){
                    $this->returnCodeError($v['title'].'为必填项！');
                }
            }
            $arr_data = [];
            foreach($data_post as $kk=>$vv){
                if($vv['value']){
                    $arr1[$vv['key']] = array(
                        'type'=>$vv['type'],
                        'is_must'=>$vv['is_must'],
                        'key'=>$vv['key'],
                        'title'=>$vv['title'],
                        'value'=>$vv['value'],

                    );
                }else{
                    $arr1[$vv['key']] = array(
                        'type'=>$vv['type'],
                        'is_must'=>$vv['is_must'],
                        'key'=>$vv['key'],
                        'title'=>$vv['title'],
                        'value'=>'',

                    );
                }

                $arr_data = $arr1;
            }
            $bind_data['authentication_field'] = serialize($arr_data);
        }else{
            $bind_data['authentication_field'] = '';
        }
        if(!$this->config['international_phone'] && !preg_match('/^[0-9]{11}$/',$phone)){
            $this->returnCode('20042003');
        }

        $uid = D('User')->get_user_by_phone($phone);

        if($uid > 0){
            $bind_data['uid'] = $uid;
            $face_status = D('House_village_about_config')->where(array('village_id'=>$bind_info['village_id']))->getField('face_status');
            $my_face_door_switch = $this->config['my_face_door_switch']?1:0;
            if ($my_face_door_switch==1) {
                // 用户端人脸入口，关闭后用户端相关人脸相关入口均会隐藏
                $face_status = 3;
            }
            if($face_status == 1){
                $where_face['uid'] = $uid;
                $where_face['status'] = array('in',array(0,3));
                $face_imgs = D('House_face_img')->where($where_face)->select();
                if(empty($face_imgs)){
                    $this->returnCode('20090171');
                }
            }
        }else{
            $this->returnCode('20090218');
        }

        $bind_data['housesize'] = I('housesize');
        $bind_data['park_flag'] = I('park_flag');


        $vacancy_condition['pigcms_id'] = $pigcms_id;

        $bind_info = $database_house_village_user_vacancy->where($vacancy_condition)->find();

        if($phone == $bind_info['phone']){
            $this->returnCode('20090196');
        }
        $house_village_extend = D('house_village_info')->where(array('village_id'=>$bind_info['village_id']))->find();
        $room_bind_people_num=0;
        if($house_village_extend && isset($house_village_extend['room_bind_people_num']) &&  ($house_village_extend['room_bind_people_num']>0)){
            $room_bind_people_num=$house_village_extend['room_bind_people_num'];
        }
        if ($bind_info && isset($bind_info['bind_people_num']) && ($bind_info['bind_people_num'] > 0)) {
            $room_bind_people_num = $bind_info['bind_people_num'];
        }
        //绑定人数判断
        $whereArr = array();
        $whereArr['status'] = array('in', array(1, 2));
        $whereArr['type'] = array('in', array(0, 1, 2, 3));
        $whereArr['floor_id'] = array('gt', 0);
        $whereArr['vacancy_id'] = $pigcms_id;
        $binded_people_num = $database_house_village_user_bind->where($whereArr)->count();
        if ($room_bind_people_num > 0 && $binded_people_num >= $room_bind_people_num) {
            $this->returnCodeError("房间人员已满，请联系管理人员处理！");
        }
        
        $bind_condition['parent_id'] =   $parent_id;
        $bind_condition['phone']     =   $phone;
        $bind_condition['type']      =   $type;
        $bind_condition['status']    =   1;

        $family_bind_info = $database_house_village_user_bind->where($bind_condition)->find();

        //判断是否被拒绝 如果不被拒绝再提交的 应该删除之前拒绝的信息 重新添加
        $bind_condition_not['parent_id'] = $parent_id?$parent_id:0;
        $bind_condition_not['phone'] = $phone;
        $bind_condition_not['type'] = $type;
        $bind_condition_not['status'] = array('in' , array(0,2));
        $family_bind_info_not = $database_house_village_user_bind->where($bind_condition_not)->find();
        if($family_bind_info_not){
            fdump('>>>>>>'.__LINE__,'api/log/'.date('Ymd').'/house_user_bind/user_bind_delete_log',true);
            fdump($_SERVER,'api/log/'.date('Ymd').'/house_user_bind/user_bind_delete_log',true);
            fdump('houseapi--'.__FUNCTION__,'api/log/'.date('Ymd').'/house_user_bind/user_bind_delete_log',true);
            $user_del_info = $database_house_village_user_bind->where($bind_condition_not)->select();
            fdump($user_del_info,'api/log/'.date('Ymd').'/house_user_bind/user_bind_delete_log',true);
            $database_house_village_user_bind->where($bind_condition_not)->delete();
            fdump($database_house_village_user_bind->_sql(),'api/log/'.date('Ymd').'/house_user_bind/user_bind_delete_log',true);
            fdump($database_house_village_user_bind->getDbError(),'api/log/'.date('Ymd').'/house_user_bind/user_bind_delete_log',true);
        }

        if($family_bind_info){
            $this->returnCode('20090219');
        }

        $floor_condition['floor_id'] =  $bind_info['floor_id'];
        $floor_info = $database_house_village_floor->where($floor_condition)->find();

        $bind_data['village_id'] = $bind_info['village_id'];
        $bind_data['address']    = $floor_info['floor_name'].$floor_info['floor_layer'].$bind_info['layer']."#".$bind_info['room'];
        $bind_data['layer_num']  = $bind_info['layer'];
        $bind_data['layer_id']  = $bind_info['layer_id'] ? $bind_info['layer_id'] :'';
        $bind_data['room_addrss']    = $bind_info['room'];
        $bind_data['single_id']   = $bind_info['single_id'];
        $bind_data['floor_id']   = $bind_info['floor_id'];
        $bind_data['vacancy_id']    =  $pigcms_id;
        $bind_data['housesize'] =  $bind_info['housesize'];
        $bind_data['park_flag'] =  $bind_info['park_flag'];

        $bind_data['uid'] = $uid;
        $bind_data['name'] = $name;
        $bind_data['type'] = $type;
        if($type == 1){
            $bind_data['relatives_type'] = $relatives_type;
        }else{
            $bind_data['relatives_type'] = '';
        }
        $bind_data['status'] = 1;
        $bind_data['phone'] = $phone;
        $bind_data['add_time'] = time();
        $bind_data['pass_time'] = time();
        $bind_data['usernum'] = rand(0,99999) . '-' . time();
        $bind_data['parent_id'] = $parent_id?$parent_id:0;
        $bind_data['memo'] = "";
        // 手机号不能与当前房屋中待审核和审核通过的手机号一样
        if ($phone) {
            $bind_condition = [];
            $bind_condition['vacancy_id'] = $bind_data['vacancy_id'];
            $bind_condition['phone'] = $phone;
            $bind_condition['type'] = ['in', [0,1,2,3]];
            $bind_condition['status'] = array('in' , [1,2]);
            $other_bind_info = D('House_village_user_bind')->where($bind_condition)->find();
            if($other_bind_info){
                $this->returnCodeError('该手机号已绑定或已申请绑定此房间');
            }
        }
        // 姓名不能与当前房屋中待审核和审核通过的姓名一样
        if ($name) {
            $bind_condition = [];
            $bind_condition['vacancy_id'] = $bind_data['vacancy_id'];
            $bind_condition['name'] = $name;
            $bind_condition['type'] = ['in', [0,1,2,3]];
            $bind_condition['status'] = array('in' , [1,2]);
            $other_bind_info = D('House_village_user_bind')->where($bind_condition)->find();
            if($other_bind_info){
                $this->returnCodeError("{$name}已绑定或已申请绑定此房间");
            }
        }
        $insert_id = $database_house_village_user_bind->data($bind_data)->add();
        if($insert_id){
            if (intval($insert_id)>0) {
                $change_param = [];
                $change_param['pigcms_id'] = $insert_id;
                D('House_village_user_vacancy')->change_user_bind_number($change_param);
            }
            //todo 用户同步写入属性表记录
            invoke_v20_service('\app\community\model\service\TaskReleaseService/userAttributeRecord', ['pigcms_id'=>$insert_id,'field'=>$bind_data['authentication_field']]);
            $this->returnCodeOk('添加成功!');
        }else{
            fdump($bind_data,'bind_relatives_add');
            fdump($database_house_village_user_bind->getDbError(),'bind_relatives_add',1);
            $this->returnCodeError('添加失败!');
        }
    }

    public function express_adver()
    {
        $village_id = I('village_id');//社区id
        if(empty($village_id)){
            $this->returnCode('20090003');
        }

        $equipment_id = I('equipment_id');//设备id
        if(empty($equipment_id)){
            $this->returnCode('20090225');
        }
        $express = M('Intelligence_express')->where(array('equipment_id'=>$equipment_id))->find();
        if(empty($express)){
            $this->returnCode('20090226');
        }
        $adver_list = M('House_open_door_adver')->order('add_time DESC')->where(array('status'=>1,'intelligent_hardware_type'=>2, 'equipment_type'=>$express['screen_size_type'], 'begin_time' => array('elt', time()), 'end_time' => array('egt', time())))->select();
        $adver_village_list = M('Adver_village')->where(array('status'=>1,'village_id'=>$village_id))->getField('adver_id,village_id');


        $adver_msg = array();
        if ($adver_list) {
            foreach ($adver_list as $item) {

                if ($adver_village_list && $adver_village_list[$item['id']]) {
                    $mediaType = 'image';
                    if (1==$item['advert_type']) {
                        $mediaType = 'video';
                    }
                    $advert = array(
                        'adver_id'=>$item['id'],
                        'title' => $item['name'],
                        'media' => replace_file_domain($item['android_pic']),
                        'mediaType' => $mediaType,
                        'duration' => $item['play_time'],
//                        'startDate' => $item['begin_time'],
//                        'endDate' => $item['end_time'],
                    );
                    $adver_msg[] = $advert;
                }
            }
        }
        $arr = array();
        $arr['adver_msg'] = $adver_msg;
        $base_url = D('House_village')->base_url;
        if($this->config['express_qrcode'] == 0){//网页
            $url = $this->config['site_url'].'/index.php?c=Recognition&a=get_own_qrcode_html&down=true&qrCon=';
            $qrcode_url = $url.urlencode($this->config['site_url'].$base_url . 'pages/village/smartExpressCabinet/selectExpress?equipment_id='.$equipment_id);
            $img_url = $this->config['site_url'].U('get_own_qrcode',array('qrCon'=>urlencode(htmlspecialchars_decode($qrcode_url)),'size'=>$_GET['size'],'down'=>$_GET['down']));
            $arr['qrcode'] = $img_url;

        }elseif($this->config['express_qrcode'] == 1){//公众号二维码

        }
        $this->returnCode(0, $arr);
    }
    public function get_qrcodes(){
        $url = I('url');
        if(!$url){
            $this->returnCodeError('参数异常');
        }
        $url = str_replace("amp;","",$url);
        $img_url = $this->config['site_url'].U('get_own_qrcode',array('qrCon'=>urlencode(htmlspecialchars_decode($url)),'size'=>$_GET['size'],'down'=>$_GET['down']));
        $arr['qrcode'] = $img_url;
        $this->returnCode(0, $arr);
    }
    public function get_own_qrcode(){
        header('Content-Type: image/png');
        ob_clean();
        $qrCon = $_GET['qrCon'];
        import('@.ORG.phpqrcode');
        $size = $_GET['size'] ? $_GET['size']: 10;
        $is_down = $_GET['down'] ? true: false;

        QRcode::png(htmlspecialchars_decode(urldecode($qrCon)),false,0,$size,1,$is_down);
    }

    public function exposure_number()
    {
        $adver_id = I('adver_id');
        if(empty($adver_id)){
            $this->returnCode('10080004');
        }
        D('House_open_door_adver')->where(array('id'=>$adver_id))->setInc('exposure_number');
