    public function authentication_config_list()
    {
        if($this->config['express_user_auth'] == 0){
            $this->returnCode('20090230');
        }
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $arr = [];
        $authentication_wenben = [];
        $authentication_info = D('Express_authentication')->where(array('uid'=>$this->_uid))->find();
        if($authentication_info){
            unset($authentication_info['authentication_price']);
            $authentication_info['authentication_field'] = unserialize($authentication_info['authentication_field']);
            $arr['authentication_info'] = $authentication_info;
            if($authentication_info['authentication_status'] == 3){
                $authentication_config_list = D('Express_authentication_config')->order('type asc')->select();
                $data_list_wenben = [];
                foreach ($authentication_config_list as $k => $v) {
                    if($v['type'] == 1){
                        if($authentication_info['authentication_field'][$v['key']]['value']){
                            $list['value'] = $authentication_info['authentication_field'][$v['key']]['value'];
                        }else{
                            $list['value'] = '';
                        }
                    }else{
                        if($authentication_info['authentication_field'][$v['key']]['value']){
                            $list['value'] = replace_file_domain($authentication_info['authentication_field'][$v['key']]['value']);
                        }else{
                            $list['value'] = '';
                        }
                    }
                    $list['title'] = $v['title'];
                    $list['key'] = $v['key'];
                    $list['type'] = $v['type'];
                    $data_list_wenben[] = $list;
                }

                $arr['data_list'] = $data_list_wenben;
                $this->returnCode(0, $arr);
            }elseif($authentication_info['authentication_status'] == 4){
                $this->returnCode('20090228');
            }elseif($authentication_info['authentication_status'] == 1){
                $this->returnCode('73000021');
            }
        }else{
            $authentication_config_list = D('Express_authentication_config')->order('type asc')->select();
            if (empty($authentication_config_list)) {
                $this->returnCode('20090227');
            }
            $data_list_wenben = [];
            foreach ($authentication_wenben as $k => $v) {
                $list['value'] = '';
                $list['title'] = $v['title'];
                $list['key'] = $v['key'];
                $list['type'] = $v['type'];
                $data_list_wenben[] = $list;
            }
            $arr['data_list'] = $data_list_wenben;
            $arr['authentication_info'] = '';
            $this->returnCode(0, $arr);
        }


    }

    public function authentication_data()
    {
        if($this->config['express_user_auth'] == 0){
            $this->returnCode('20090230');
        }
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $data['uid'] =  $this->_uid;
        $data['authentication_status'] = 1;
        $data['authentication_time'] = time();
        $authentication_id = I('authentication_id','');
        unset($_POST['imgFile']);
        unset($_POST['authentication_id']);
        foreach ($_POST['authentication_field'] as $key => $value) {
            if(!$value['value']){
                $this->returnCode('20090186');
            }
        }
        $data['authentication_field'] = serialize($_POST['authentication_field']);
        if($authentication_id){
            $res = D('Express_authentication')->where(array('authentication_id'=>$authentication_id))->data($data)->save();
            if($res){
                $this->returnCodeOk(L_('提交审核成功'));
            }else{
                $this->returnCodeOk(L_('提交失败,请重试!'));
            }
        }else{
            $res = D('Express_authentication')->data($data)->add();
            if($res){
                $this->returnCodeOk(L_('提交审核成功'));
            }else{
                $this->returnCodeOk(L_('提交失败,请重试!'));
            }
        }
    }

    public function authentication_image()
    {
        $errors = [
            UPLOAD_ERR_INI_SIZE => '上传的文件超过了 php.ini 中 upload_max_filesize 选项限制的值',
            UPLOAD_ERR_FORM_SIZE => '上传文件的大小超过了 HTML 表单中 MAX_FILE_SIZE 选项指定的值',
            UPLOAD_ERR_PARTIAL => '文件只有部分被上传',
            UPLOAD_ERR_NO_FILE => '没有文件被上传',
            UPLOAD_ERR_NO_TMP_DIR => '找不到临时文件夹',
            UPLOAD_ERR_CANT_WRITE => '文件写入失败'
        ];
        if ($_FILES['imgFile']['error'] === UPLOAD_ERR_OK) {
            $image = D('Image')->handle(0, 'authentication', 2, array('size' => 10), false);
            if ($image['error']) {
                $this->returnCode(1001, [], $image['message']);
            } else {
                $imageUrl = replace_file_domain($image['url']['imgFile']);
                $imageUrl_path = $image['url']['imgFile'];
                $this->returnCode(0, ['url' => thumb_img($imageUrl, 200, 200, 'fill'),'imageUrl_path'=>$imageUrl_path, 'imageUrl'=>$imageUrl ]);
            }
        } else {
            $this->returnCode(1001, [], isset($errors[$_FILES['imgFile']['error']]) ? $errors[$_FILES['imgFile']['error']] : '上传失败');
        }
    }


    //快递列表
    public function express_num_list()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $type = I('type','1');//1已取 2 存(待取)
        if(empty($type)){
            $this->returnCode('20090229');
        }
        $arr = [];
        $now_user = D('User')->get_user($this->_uid);
        $express_num_log = [];
        if($now_user){
            $authentication_info = D('Express_authentication')->where(array('uid'=>$now_user['uid']))->find();
            if($authentication_info){
                //工作人员
                $condition['type'] = $type;
                $condition['uid'] = $now_user['uid'];
                if(I('keyword')){
                    $condition['pickup_code|express_odd_numbers'] = I('keyword');
                }
                $express_num_log = M('Express_num_log')->where($condition)->select();
                $arr['user_type'] = 1;
                $arr['user_type_desc'] = '工作人员';
            }else{
                //业主
                $condition['type'] = $type;
                $condition['phone'] = $now_user['phone'];
                $express_num_log = M('Express_num_log')->where($condition)->select();
                $arr['user_type'] = 2;
                $arr['user_type_desc'] = '用户';
            }
        }else{
            $this->error('10052001');
        }
        $dataList = [];
        foreach($express_num_log as $k=>$v){
            $list['express_name'] = $v['express_name'];//快递名
            $list['express_odd_numbers'] = $v['express_odd_numbers']; //快递单号
            $list['name'] = empty($v['name'])?'':$v['name'];//用户名
            $list['phone'] = $v['phone'];
            $list['store_time'] = empty($v['store_time'])?'':date('Y-m-d H:i:s',$v['store_time']);//存放时间
            if($v['type'] == 1){
                $list['desc'] = '已取件';
                $list['status'] = 1;
                $list['end_time'] = empty($v['end_time'])?'':date('Y-m-d H:i:s',$v['end_time']);
            }elseif($v['type'] == 2){
                $list['desc'] = '未取件';
                $list['status'] = 2;
                $list['end_time'] = '';
            }
            $dataList[] = $list;
        }
        $arr['dataList'] = $dataList;
        $this->returnCode(0, $arr);
    }

