    //快递存
    public function express_num_add()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $express_odd_numbers = I('express_odd_numbers');
        $equipment_num = I('equipment_id');//设备
        if(empty($equipment_num)){
            $this->returnCode('20090233');
        }
        $express_num_id = I('express_num_id');//盒子id
        if(empty($express_num_id)){
            $this->returnCode('20090235');
        }
        $authentication_info = D('Express_authentication')->where(array('uid'=>$this->_uid))->find();
        if(empty($authentication_info)){
            $this->returnCode('20090238');
        }
        if($authentication_info['authentication_status'] == 1){
            $this->returnCode('20090231');
        }elseif($authentication_info['authentication_status'] == 3){
            $this->returnCode('20090232');
        }elseif($authentication_info['authentication_status'] == 4){
            $this->returnCode('20090228');
        }

        if(empty($express_odd_numbers)){
            $this->returnCode('20090047');
        }
        $phone = I('phone');
        if(empty($phone)){
            $this->returnCode('20090068');
        }
        $name = I('name');
        $express_name = I('express_name');//快递名称

        $data['type'] = 2;
        $data['pickup_code'] = createRandomStr(6,true);
        $data['express_odd_numbers'] = $express_odd_numbers;
        $data['create_time'] = time();
        $data['equipment_id'] = $equipment_num;
        $data['store_time'] = time();
        $data['name'] = $name;
        $data['phone'] = $phone;
        $data['express_uid'] = $this->_uid;
        $data['express_name'] =$express_name;
        $data['express_num_id'] = $express_num_id;

        $insert_id = M('Express_num_log')->data($data)->add();
        if($insert_id){
            M('Express_num')->where(array('equipment_id'=>$express_num_id))->save(array('is_null'=>1));
            $this->returnCodeOk(L_('存放成功'));
        }else{
            $this->returnCodeOk(L_('存放失败,请重试!'));
        }
    }

