    //任务列表
    public function my_task_list()
    {

        $week = array('周一','周二','周三','周四','周五','周六','周日');
        if (empty($this->_uid)) {
            $this->returnCode('20000009');

        }
        $aPage = I('page',1);
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $village_user_bind['village_id'] = $village_id;
        $village_user_bind['type'] = 4;
        $village_user_bind['uid'] = $this->_uid;
        $village_user_bind['status'] = ['not in', [3,4]];
        $bind_info = M('House_village_user_bind')->where($village_user_bind)->find();
        if(empty($bind_info)){
            $this->returnCode('20120052');
        }
        $house_worker = D('House_worker')->where(array('village_id'=>$bind_info['village_id'],'phone'=>$bind_info['phone'],'status'=>1,'is_del'=>0))->find();
        if(empty($house_worker)){
            $this->returnCode('20120052');
        }

        $qrcode_person = M('Wisdom_qrcode_person')->where(array('uid'=>$house_worker['wid'],'status'=>1))->select();
        if(empty($qrcode_person)){
            $this->returnCode('20090239');
        }
        $person = [];
        foreach($qrcode_person as $k1=>$v){

            $person[] = $v['cate_id'];
        }
        $where['id'] = array('in',$person);
        $dataList = D('Wisdom_qrcode_cate')->where($where)->page($aPage,15)->select();
        foreach($dataList as $k=>&$v){
            $v['add_time'] = date('Y-m-d');
            $v['cate_id'] = $v['id'];
            $qrcode_count = M('Wisdom_qrcode')->where(array('cate_id'=>$v['id']))->count();
            $v['total_num'] =$qrcode_count;
            $qrcode_person = M('Wisdom_qrcode_person')->where(array('uid'=>$house_worker['wid'],'cate_id'=>$v['id']))->find();
            if($qrcode_person){
                if($qrcode_person['record_type'] == 1){
                    $v['record_type'] = 1;
                    $v['record_type_desc'] = '每天';
                    $qrcode = M('Wisdom_qrcode')->where(array('cate_id'=>$v['id']))->select();
                    foreach($qrcode as $k1=>$v1){
                        $qrcode_num[] =  $v1['id'];
                    }
                    $record_log['qrcode_id'] = array('in',$qrcode_num);
                    $record_log['cate_id'] = $v['id'];
                    $dates = date('Y-m-d',time());
                    $start_time = strtotime($dates.' '.$qrcode_person['start_time']);
                    $end_time =strtotime($dates.' '.$qrcode_person['end_time']);
                    $record_log['add_time'] = array('between',array($start_time,$end_time));
                    $record_log_count = M('Wisdom_qrcode_record_log')->where($record_log)->count();
                    if($record_log_count){
                        if($record_log_count < $qrcode_count){
                            $v['desc'] = '待完成';
                            $v['desc_status'] = 1;
                            $v['num'] = ($qrcode_count- $record_log_count).'/'.$qrcode_count;
                        }else{
                            $v['desc'] = '已完成';
                            $v['desc_status'] = 2;
                            $v['num'] = $qrcode_count.'/'.$qrcode_count;
                        }
                    }else{
                        $v['desc'] = '待完成';
                        $v['desc_status'] = 1;
                        $v['num'] = '0'.'/'.$qrcode_count;
                    }
                    $v['record_time_one'] = $qrcode_person['start_time'].'-'.$qrcode_person['end_time'];
                    $v['record_time_two'] = '';
                    $v['record_time_three'] = '';
                }elseif($qrcode_person['record_type'] == 2){
                    $v['record_type'] = 2;
                    $v['record_type_desc'] = '每周 ';
                    if($qrcode_person['record_time']){
                        $v['record_type_desc'] .=  '(';
                    }
                    $record_time = explode(',',$qrcode_person['record_time']);
                    if(in_array('1',$record_time)){
                        $v['record_type_desc'] .= '周一,';
                    }

                    if(in_array('2',$record_time)){
                        $v['record_type_desc'] .= '周二,';
                    }
                    if(in_array('3',$record_time)){
                        $v['record_type_desc'] .= '周三,';
                    }
                    if(in_array('4',$record_time)){
                        $v['record_type_desc'] .= '周四,';
                    }
                    if(in_array('5',$record_time)){
                        $v['record_type_desc'] .= '周五,';
                    }
                    if(in_array('6',$record_time)){
                        $v['record_type_desc'] .= '周六,';
                    }
                    if(in_array('7',$record_time)){
                        $v['record_type_desc'] .= '周日,';
                    }

                    $v['record_type_desc'] = rtrim($v['record_type_desc'],',');

                    if($qrcode_person['record_time']){
                        $v['record_type_desc'] .=  ')';
                    }

                    $qrcode = M('Wisdom_qrcode')->where(array('cate_id'=>$v['id']))->select();
                    foreach($qrcode as $k1=>$v1){
                        $qrcode_num[] =  $v1['id'];
                    }
                    $record_log['qrcode_id'] = array('in',$qrcode_num);
                    $record_log['cate_id'] = $v['id'];
                    $record_time = explode(',',$qrcode_person['record_time']);
                    $dates = date('w',time());
                    if(in_array($dates,$record_time)){
                        $dates = date('Y-m-d',time());
                        $start_time = strtotime($dates.' '.$qrcode_person['start_time']);
                        $end_time =strtotime($dates.' '.$qrcode_person['end_time']);
                        $record_log['add_time'] = array('between',array($start_time,$end_time));
                        $record_log_count = M('Wisdom_qrcode_record_log')->where($record_log)->count();
                        if($record_log_count){
                            if($record_log_count < $qrcode_count){
                                $v['desc'] = '待完成';
                                $v['desc_status'] = 1;
                                $v['num'] = ($qrcode_count- $record_log_count).'/'.$qrcode_count;
                            }else{
                                $v['desc'] = '已完成';
                                $v['num'] = $qrcode_count.'/'.$qrcode_count;
                                $v['desc_status'] = 2;
                            }
                        }else{
                            $v['desc'] = '待完成';
                            $v['desc_status'] = 1;
                            $v['num'] = '0'.'/'.$qrcode_count;
                        }

                    }else{
                        $v['desc'] = '未来计划';
                        $v['desc_status'] = 3;
                        $v['num'] = '0'.'/'.$qrcode_count;
                    }
                    $v['record_time_one'] = '';
                    $v['record_time_two'] = $qrcode_person['start_time'].'-'.$qrcode_person['end_time'];
                    $v['record_time_three'] = '';
                }elseif($qrcode_person['record_type'] == 3){
                    $v['record_type'] = 3;
                    $v['record_type_desc'] = '每月 ('.$qrcode_person['record_time'].')';

                    $qrcode = M('Wisdom_qrcode')->where(array('cate_id'=>$v['id']))->select();
                    foreach($qrcode as $k1=>$v1){
                        $qrcode_num[] =  $v1['id'];
                    }
                    $record_log['qrcode_id'] = array('in',$qrcode_num);
                    $record_log['cate_id'] = $v['id'];
                    $record_time = explode(',',$qrcode_person['record_time']);
                    $dates = date('d',time());
                    if(in_array($dates,$record_time)){
                        $dates = date('Y-m-d',time());
                        $start_time = strtotime($dates.' '.$qrcode_person['start_time']);
                        $end_time =strtotime($dates.' '.$qrcode_person['end_time']);
                        $record_log['add_time'] = array('between',array($start_time,$end_time));
                        $record_log_count = M('Wisdom_qrcode_record_log')->where($record_log)->count();
                        if($record_log_count){
                            if($record_log_count < $qrcode_count){
                                $v['desc'] = '待完成';
                                $v['desc_status'] = 1;
                                $v['num'] = ($qrcode_count- $record_log_count).'/'.$qrcode_count;
                            }else{
                                $v['desc'] = '已完成';
                                $v['desc_status'] = 2;
                                $v['num'] = $qrcode_count.'/'.$qrcode_count;
                            }
                        }else{
                            $v['desc'] = '待完成';
                            $v['desc_status'] = 1;
                            $v['num'] = '0'.'/'.$qrcode_count;
                        }


                    }else{
                        $v['desc'] = '未来计划';
                        $v['desc_status'] = 3;
                        $v['num'] = '0'.'/'.$qrcode_count;
                        $dates = date('d',time());
                        $arr1=$record_time;
                        $arr1[]=$dates;
                        sort($arr1);
                        $key = array_search($dates,$arr1);
                        $v['record_time_one'] = '';
                        $v['record_time_two'] = '';
                        $v['record_time_three'] = date('Y-m',time()).'-'.$arr1[$key+1];
                    }

                }
            }else{
                $v['record_type'] = 0;
                $v['record_type_desc'] = '';
            }
        }
        $arr = [];
        $arr['task_list'] = $dataList;
        $this->returnCode(0, $arr);
    }



