            $qrcode_cate = D('Wisdom_qrcode_cate')->where(array('id'=>$v['cate_id']))->find();
            $qrcode_person = M('Wisdom_qrcode_person')->where(array('uid'=>$house_worker['wid'],'cate_id'=>$v['cate_id']))->find();
            if($qrcode_person['record_type'] == 1){

                $where['qrcode_id'] = $v['id'];
                $where['cate_id'] = $v['cate_id'];
                $dates = date('Y-m-d',time());
                $start_time = strtotime($dates.' '.$qrcode_person['start_time']);
                $end_time =strtotime($dates.' '.$qrcode_person['end_time']);
                $where['add_time'] = array('between',array($start_time,$end_time));
                $record_log_count = M('Wisdom_qrcode_record_log')->where($where)->count();
                $record_log_counts += $record_log_count;
                if($record_log_count){
                    $v['desc'] = '已记录';
                    $v['status'] = 1;
                    $count = $qrcode_count-$record_log_count;
                    if($count > 0){
//                        $qrcode_uncount = $count;
                        $qrcode_uncount = 0;
                    }else{
                        $qrcode_uncount = $qrcode_count;
                    }
                    //当任务有巡检记录时，待完成数量减1
                    $count1=$count1-1;
                    $qrcode_uncount = $count1;
                }else{
                    $v['desc'] = '待完成';
                    $v['status'] = 2;
                    $qrcode_uncount = ($qrcode_count-$record_log_counts);
                    //当任务没有巡检记录时，待完成数量保持不变
                    $qrcode_uncount = $count1;
                }
            }elseif($qrcode_person['record_type'] == 2){
                $where['qrcode_id'] = $v['id'];
                $where['cate_id'] = $v['cate_id'];
                $record_time = explode(',',$qrcode_person['record_time']);
                $dates = date('w',time());
                if(in_array($dates,$record_time)){
                    $dates = date('Y-m-d',time());
                    $start_time = strtotime($dates.' '.$qrcode_person['start_time']);
                    $end_time =strtotime($dates.' '.$qrcode_person['end_time']);
                    $where['add_time'] = array('between',array($start_time,$end_time));
                    $record_log_count = M('Wisdom_qrcode_record_log')->where($where)->count();
                    if($record_log_count){
                        if($record_log_count <= 0){
                            $v['desc'] = '待完成';
                            $v['status'] = 2;
                            $qrcode_uncount += 0;
                        }else{
                            $v['desc'] = '已记录';
                            $v['status'] = 1;

                            $count = $qrcode_count-$record_log_count;
                            if($count > 0){
                                $qrcode_uncount += $count;
                            }else{
                                $qrcode_uncount += $qrcode_count;
                            }
                        }
                    }else{
                        $v['desc'] = '待完成';
                        $v['status'] = 2;
                        $qrcode_uncount += 0;
                    }
                }else{
                    $v['desc'] = '待完成';
                    $v['status'] = 2;
                    $qrcode_uncount += 0;

                }
            }elseif($qrcode_person['record_type'] == 3){
                $where['qrcode_id'] = $v['id'];
                $where['cate_id'] = $v['cate_id'];
                $record_time = explode(',',$qrcode_person['record_time']);
                $dates = date('d',time());
                if(in_array($dates,$record_time)){
                    $dates = date('Y-m-d',time());
                    $start_time = strtotime($dates.' '.$qrcode_person['start_time']);
                    $end_time =strtotime($dates.' '.$qrcode_person['end_time']);
                    $where['add_time'] = array('between',array($start_time,$end_time));
                    $record_log_count = M('Wisdom_qrcode_record_log')->where($where)->count();
                    if($record_log_count){
                        if($record_log_count <= 0){
                            $v['desc'] = '待完成';
                            $v['status'] = 2;
                            $qrcode_uncount += 0;
                        }else{
                            $v['desc'] = '已记录';
                            $v['status'] = 1;

                            $count = $qrcode_count-$record_log_count;
                            if($count > 0){
                                $qrcode_uncount += $count;
                            }else{
                                $qrcode_uncount += $qrcode_count;
                            }
                        }
                    }else{
                        $v['desc'] = '待完成';
                        $v['status'] = 2;
                        $qrcode_uncount += 0;

                    }
                }else{
                    $v['desc'] = '待完成';
                    $v['status'] = 2;
                    $qrcode_uncount += 0;

                }
            }
            unset($v['id']);
        }

        $arr['qrcode_list'] = $qrcode_list;
        $arr['qrcode_count'] = $qrcode_count;
        $arr['qrcode_uncount'] = $qrcode_uncount;
        $this->returnCode(0, $arr);
    }
    //经纬度算距离
    public function GetDistance($lat1, $lng1, $lat2, $lng2, $len_type = 1, $decimal = 2){
        $EARTH_RADIUS = 6378.137;//地球半径
        $PI = 3.1415926;

        $radLat1 = $lat1 * $PI / 180.0;
        $radLat2 = $lat2 * $PI / 180.0;
        $a = $radLat1 - $radLat2;
        $b = ($lng1 * $PI / 180.0) - ($lng2 * $PI / 180.0);
        $s = 2 * asin(sqrt(pow(sin($a/2),2) + cos($radLat1) * cos($radLat2) * pow(sin($b/2),2)));
        $s = $s * $EARTH_RADIUS;
        $s = round($s * 1000);

        if ($len_type > 1){
            $s /= 1000;
        }
        return round($s, $decimal);
    }
    
