    //记录详情==>页面==>数据添加
    public function add_record_info()
    {
        $qrcode_id = I('qrcode_id');
        $qrcode_id = $qrcode_id ? intval($qrcode_id) :0;
        $village_id = I('village_id');
        $village_id = $village_id ? intval($village_id) :0;
        if(empty($qrcode_id)){
            $this->returnCode('20090237');
        }
        $qrcode = D('Wisdom_qrcode')->where(array('id'=>$qrcode_id))->find();
        if(empty($qrcode)){
            $this->returnCode('20090055');
        }
        $cate_id = $qrcode['cate_id'];

        $whereArr=array('id'=>$cate_id);
        if($village_id>0){
            $whereArr['village_id']=$village_id;
        }
        $qrcodeCate= M('Wisdom_qrcode_cate')->where($whereArr)->find();
        if(!empty($qrcodeCate)){
            $village_id=$qrcodeCate['village_id'];
        }else{
            $this->returnCode('20090055');
        }
        $c_where['category_id'] = $qrcode['category_id'];
        $c_where['status'] = 1;

        $dataList = M('wisdom_qrcode_record_cate')->where($c_where)->select();
        $field_config_fixed = [
            'record_name'=>'异常情况',
            'category_id'=>'9999',
            'record_cate_field_config'=>[[
                'is_must' => 1,
                'key' => 'FIXED_POINT_IS_ABNORMALITY',
                'title' => '点位是否存在异常情况',
                'type' => 3,
                'use_field' => ["是", "否"],
                'value' => 0,
            ]]
        ];
        $dataList[] = $field_config_fixed;
        if($dataList){
            foreach($dataList as $k=>&$v){

                $record_cate_field_config = M('Wisdom_qrcode_record_cate_field_config')->where(array('record_cate_id'=>$v['id']))->order('sort desc,acid desc')->select();
                if($record_cate_field_config){
                    foreach($record_cate_field_config as $k1=>&$v1){
                        $v1['value'] = '';

                        if($v1['type'] == 3){
                            $v1['use_field'] = explode(',',$v1['use_field']);
                        }else{
                            $v1['use_field'] = [];
                        }
                        unset($v1['acid']);

                        unset($v1['add_time']);
                        unset($v1['record_cate_id']);
//                        unset($v1['use_field']);
                        unset($v1['sort']);
                    }
                    $v['record_cate_field_config'] = $record_cate_field_config;
                }
                unset($v['id']);
                unset($v['add_time']);
                unset($v['sort']);
                unset($v['status']);
                unset($v['cate_id']);
            }
        }

        $arr = [];
        $arr['wisdom_qrcode_set']=1;
        if($village_id>0){
            $villageInfoWhere=array('village_id'=>$village_id);
            $villageInfoData= M('House_village_info')->where($villageInfoWhere)->field('village_id,property_id,wisdom_qrcode_set')->find();
            if(!empty($villageInfoData)){
                $arr['wisdom_qrcode_set']=$villageInfoData['wisdom_qrcode_set'];
            }
        }
        $arr['cate_id'] = $qrcode['cate_id'];
        $arr['task_list'] = $dataList;

        $this->returnCode(0, $arr);
    }

    public function qrcode_image()
    {
        $errors = [
            UPLOAD_ERR_INI_SIZE => '上传的文件超过了 php.ini 中 upload_max_filesize 选项限制的值',
            UPLOAD_ERR_FORM_SIZE => '上传文件的大小超过了 HTML 表单中 MAX_FILE_SIZE 选项指定的值',
            UPLOAD_ERR_PARTIAL => '文件只有部分被上传',
            UPLOAD_ERR_NO_FILE => '没有文件被上传',
            UPLOAD_ERR_NO_TMP_DIR => '找不到临时文件夹',
            UPLOAD_ERR_CANT_WRITE => '文件写入失败'
        ];
        if ($_FILES['imgFile']['error'] === UPLOAD_ERR_OK) {
            $image = D('Image')->handle(0, 'qrcode', 2, array('size' => 10), false);
            if ($image['error']) {
                $this->returnCode(1001, [], $image['message']);
            } else {
                $imageUrl = replace_file_domain($image['url']['imgFile']);
                $imageUrl_path = $image['url']['imgFile'];
                //$imageUrl = thumb_img($imageUrl, 1500, 1500);
                $size = 90;
                $datePath = "/upload/qrcode/".date("Ymd")."/";
                $upload_dir = ".".$datePath;
                if(!is_dir($upload_dir)){
                    mkdir($upload_dir, 0777, true);
                }
                $path = $datePath.uniqid('', true) . '.png';
                $savePath = $_SERVER['DOCUMENT_ROOT'] . $path;
                $img_url = $_SERVER['DOCUMENT_ROOT'].$image['url']['imgFile'];
                $img_url=str_replace('//','/',$img_url);
                fdump_api([$image,$img_url,$imageUrl],'qrcode_image',1);
                $phone_model = I('phone_model','');
                /*if(strpos($phone_model,'-AN00') == false){
                    $image = imagecreatefromstring(file_get_contents($img_url));
                    $image = imagerotate($image, -90, 0);
                    imagejpeg($image, $img_url, 100);
                    imagedestroy($image);
                }*/
                if (function_exists('exif_read_data') && function_exists('imagecreatefromstring') && function_exists('imagerotate')) {
                    // 处理图片旋转问题
                    $image = imagecreatefromstring(file_get_contents($img_url));
                    $exif = exif_read_data($img_url);
                    if (!empty($exif['Orientation'])) {
                        switch ($exif['Orientation']) {
                            case 8:
                                $image = imagerotate($image, 90, 0);
                                break;
                            case 3:
                                $image = imagerotate($image, 180, 0);
                                break;
                            case 6:
                                $image = imagerotate($image, -90, 0);
                                break;
                        }
                        imagejpeg($image, $img_url, 100);
                        imagedestroy($image);
                    }
                }

                $config = [
                    [
                        'file_path' => $img_url,
                        'main' => ['font' => '', 'size' => $size, 'color' => '#FF7B23', 'locate' => 9, 'offset' => [-30, -10]],
                    ]
                ];
                $thisConfig = $config[0];
                $image = ImageQrModel::open($thisConfig['file_path']);
                $imgwidth=$image->width();
                if($imgwidth>0 && $imgwidth<=400){
                    $thisConfig['main']['size']=30;
                }else if($imgwidth>400 && $imgwidth<=600){
                    $thisConfig['main']['size']=40;
                }else if($imgwidth>600 && $imgwidth<=800){
                    $thisConfig['main']['size']=50;
                }else if($imgwidth>800 && $imgwidth<=1000){
                    $thisConfig['main']['size']=60;
                }else if($imgwidth>1000 && $imgwidth<=1200){
                    $thisConfig['main']['size']=70;
                }else if($imgwidth>1200 && $imgwidth<=1400){
                    $thisConfig['main']['size']=80;
                }
                //fdump_api([$image,$thisConfig['file_path']],'1227-7',1);
                $image->text(date("Y-m-d H:i:s"), $thisConfig['main']['font'], $thisConfig['main']['size'], $thisConfig['main']['color'], $thisConfig['main']['locate'], $thisConfig['main']['offset'])
                    ->save($savePath);
                try {
                    $arr = getimagesize($savePath);
                    $pathinfo = pathinfo($savePath);
                    $models = '\app\common\model\service\image\ImageService/encodePngToJpg';
                    $heiht = $arr[1];
                    $with = $arr[0];
                    if ($heiht > 10000) {
                        $heiht = floor($heiht / 20);
                        $with = floor($with / 20);
                    } elseif ($heiht > 3000) {
                        $heiht = floor($heiht / 10);
                        $with = floor($with / 10);
                    } elseif ($heiht > 2000) {
                        $heiht = floor($heiht / 5);
                        $with = floor($with / 5);
                    } elseif ($heiht > 1000) {
                        $heiht = floor($heiht / 2);
                        $with = floor($with / 2);
                    }
                    $heiht = intval($heiht);
                    $with = intval($with);
                    $param = [
                        'params'     => [
                            'imgPath'      => $savePath,
                            'savePath'      => $savePath,
                            'format'       => isset($pathinfo['extension']) ? $pathinfo['extension'] : 'jpg',  //统一默认转 jpg
                            'heiht'        => $heiht ,
                            'with'         => $with
                        ]
                    ];
                    invoke_v20_service($models,$param);
                }catch (\Exception $e){
                    
                }
                if (true) {
                    $file_handle = new file_handle();
                    $file_handle->upload('.'.$path);
                    $imageUrl_path = replace_file_domain($path);
                    $imageUrl = $path;
                    if ($file_handle->check_open_oss() && file_exists('.'.$path)) {
                        unlink('.'.$path);
                       
                    }
                }
                unlink($img_url);
                $imageUrlDomain=replace_file_domain($imageUrl);
                fdump_api([$img_url,$imageUrl,$imageUrlDomain],'qrcode_image',1);
                $this->returnCode(0, ['url' => thumb_img($imageUrl, 200, 200, 'fill'),'imageUrl_path'=>$imageUrl_path, 'imageUrl'=>$imageUrlDomain ]);
            }
        } else {
            $this->returnCode(1001, [], isset($errors[$_FILES['imgFile']['error']]) ? $errors[$_FILES['imgFile']['error']] : '上传失败');
        }
    }

    //添加记录
    public function add_record()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        //增加工作人员判断
        $village_user_bind['village_id'] = $village_id;
        $village_user_bind['type'] = 4;
        $village_user_bind['uid'] = $this->_uid;
        $village_user_bind['status'] = ['not in', [3,4]];
        $bind_info = M('House_village_user_bind')->where($village_user_bind)->find();
        if(empty($bind_info)){
            $this->returnCode('20120052');
        }
        $house_worker = D('House_worker')->where(array('village_id'=>$bind_info['village_id'],'phone'=>$bind_info['phone'],'status'=>1,'is_del'=>0))->find();
        if(empty($house_worker)){
            $this->returnCode('20120052');
        }
        $qrcode_person = M('Wisdom_qrcode_person')->where(array('uid'=>$house_worker['wid']))->find();
        if(empty($qrcode_person)){
            $this->returnCode('20090239');
        }
        if($qrcode_person['status'] != 1){
            $this->returnCode('20090231');
        }
        $qrcode_id = I('qrcode_id');
        if(empty($qrcode_id)){
            $this->returnCode('20090237');
        }
        $cate_id_info = M('Wisdom_qrcode')->where(array('id'=>$qrcode_id))->field('cate_id')->find();
        $cate_id = $cate_id_info['cate_id'];
        if(empty($cate_id)){
            $this->returnCode('20090240');
        }

        $data['village_id'] = $village_id;
        $data['cate_id'] = $cate_id;
        $data['qrcode_id'] = $qrcode_id;
        $data['uid'] = $house_worker['wid'];
        $data['add_time'] = time();
        unset($_POST['cate_id']);
        unset($_POST['village_id']);
        unset($_POST['qrcode_id']);
        unset($_POST['ticket']);
        unset($_POST['now_lang']);
        unset($_POST['wxapp_type']);
        unset($_POST['app_type']);
        unset($_POST['Device-Id']);
        unset($_POST['app_version']);
        unset($_POST['now_city']);
        unset($_POST['now_area']);
        foreach($_POST as $k=>$v){
            if($v['record_cate_field_config']){
                foreach($v['record_cate_field_config'] as $k1=>$v1){
                    if($v1['value'] == '' && $v1['is_must'] == 1){
                        $this->returnCodeOk($v1['title'].'为必填项!');
                    }
                }
            }
        }
        $data['entication_field'] = serialize($_POST);
        $data['test'] = $_POST['test'];

        $insert_id = M('Wisdom_qrcode_record_log')->data($data)->add();
        if($insert_id){
            //todo 同步写入工单及时率
            $param=[
                'qrcode_person'=>$qrcode_person,
                'log'=>$data,
                'village_id'=>$village_id,
                'uid'=>$house_worker['wid'],
                'group_id'=>$house_worker['department_id'],
                'worker_id'=>$house_worker['wid'],
                'order_id'=>$cate_id
            ];
            D('Wisdom_qrcode_cate')->addOrderTimely($param);
            //如果存在异常状态, 则直接提交工单
            $record_cate_field_config = $_POST['test'][count($_POST['test'])-1]['record_cate_field_config'];
            $record_cate_field_config_arr = array_combine( array_column($record_cate_field_config,'key'),array_column($record_cate_field_config,'value') );
            if( isset( $record_cate_field_config_arr['FIXED_POINT_IS_ABNORMALITY'] ) && $record_cate_field_config_arr['FIXED_POINT_IS_ABNORMALITY'] == '是' ){
                $log_where = ['id'=>$insert_id];
                $log_data = ['is_abnormal'=>1];
                invoke_v20_service('app\community\model\service\WisdowQrcodeService/updateWisdomQrcodeRecordLog', ['where'=>$log_where,'data'=>$log_data]);
                $data['village_id'] = $village_id;
                $data['cate_id'] = $cate_id;
                $data['qrcode_id'] = $qrcode_id;
                $data['inspection_id'] = $insert_id;
                $info = [
                    'login_phone' => $bind_info['phone'],
                    'login_name' => $bind_info['name']
                ];
                $this->inspectionOrderAdd($data,$info);
            }

            $this->returnCodeOk(L_('添加记录成功!'));
        }else{
            $this->returnCodeOk(L_('添加记录失败,请重试!'));
        }

    }


    /**
     * Notes: 提交工单
     * @author: wanzy
     * @date_time: 2021/8/17 10:27
     */
    function inspectionOrderAdd($post,$userinfo)
    {
        $village_id = $post['village_id'];
//        $db_house_new_repair_works_order_service = new WisdowQrcodeService();
        $where['village_id'] = $village_id;
        $where['id'] = $post['cate_id'];
//        $QrcodeCate = $db_house_new_repair_works_order_service->getWisdomQrcodeCateOne($where);
        $QrcodeCateRes = invoke_v20_service('app\community\model\service\WisdowQrcodeService/getWisdomQrcodeCateOne', ['where'=>$where]);
        $QrcodeCate = $QrcodeCateRes['data']['retval'];

//        $QrcodeInfo = $db_house_new_repair_works_order_service->getQrcodeOne(['id'=>$post['qrcode_id']]);
        $QrcodeInfoRes = invoke_v20_service('app\community\model\service\WisdowQrcodeService/getQrcodeOne', ['where'=>['id'=>$post['qrcode_id']]]);
        $QrcodeInfo = $QrcodeInfoRes['data']['retval'];

        $workorder_category_id = $QrcodeCate ? $QrcodeCate['workorder_category_id'] : 0;


        $order_content = htmlspecialchars( json_encode( $post['test'], true) );

//        $userinfoD = (new HouseWorkerService())->getOneWorker(['village_id'=>$village_id,'phone'=>$userinfo['user']['login_phone'],'name'=>$userinfo['user']['login_name']], 'wid,name,type,phone');
        $getWorkerWhere = ['village_id'=>$village_id,'phone'=>$userinfo['login_phone'],'name'=>$userinfo['login_name']];
        $getWorkerField = 'wid,name,type,phone';
        $userinfoDRes = invoke_v20_service('app\community\model\service\HouseWorkerService/getOneWorker', ['where'=>$getWorkerWhere,'field'=>$getWorkerField]);
        $userinfoD = $userinfoDRes['data']['retval'];

        $data = [
            'village_id' => $village_id,
            'category_id' => 0,
            'type_id' => 0,
            'cat_fid' => $workorder_category_id,
            'cat_id' => 0,
            'address_type' => 'public',
            'address_id' => $QrcodeInfo ? $QrcodeInfo['id'] : 0 ,
            'address_text_name' => $QrcodeInfo ? $QrcodeInfo['name'] : '',
            'label_txt' => '',
            'order_imgs' => '',
            'order_type' => 4,
            'order_content' => $order_content?$order_content:'',
            'worker_type' => 0,
            'worker_id' => $userinfoD?$userinfoD['wid']:0,
            'login_role' => $userinfo['login_role'],
            'phone' => $userinfo['login_phone'],
            'name' => $userinfo['login_name'],
            'event_status' => 10,
            'wisdomqrcode_id' => $post['qrcode_id'],
            'inspection_id' => $post['inspection_id'],
            'inspection_auto_add' => 1,
        ];
        try{
//            $repair_cate_service = new RepairCateService();
//            $info = $repair_cate_service->addWorksOrder($data,true);
            $infoRes = invoke_v20_service('app\community\model\service\RepairCateService/addWorksOrder', ['data'=>$data,'auto_assign'=>true]);
            $info = $infoRes['data']['retval'];
            if( empty($info['order_id']) ){
                fdump_api(['file' => 'app\community\model\service\RepairCateService/addWorksOrder', 'error_msg' => $infoRes['data']['error_msg']], 'autoAddWorksOrderErrLog', 1);
              $this->returnCodeError('巡检上报成功,但工单创建失败,请手动创建工单');
            }else{
                $work_order_id = $info['order_id'];
                $record_log_where['id'] = $post['inspection_id'];
//                $wisdomQrcodeRecordLog = new WisdomQrcodeRecordLog();
//                $wisdomQrcodeRecordLog->updateRecordData($record_log_where,['work_order_id'=>$work_order_id]);
                M('Wisdom_qrcode_record_log')->where($record_log_where)->save(['work_order_id'=>$work_order_id]);
            }
        }catch (\Exception $e){
            fdump_api(['file' => $e->getFile(), 'code' => $e->getCode(), 'mes' => $e->getMessage(), 'line' => $e->getLine()], '$tryCatchErrLog', 1);
            $this->returnCodeError('自动工单创建失败,请手动创建工单');
        }
    }

    //添加qrcode类别
    public function qrcode_cate()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        //增加工作人员判断
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $village_user_bind['village_id'] = $village_id;
        $village_user_bind['type'] = 4;
        $village_user_bind['uid'] = $this->_uid;
        $village_user_bind['status'] = ['not in', [3,4]];
        $bind_info = M('House_village_user_bind')->where($village_user_bind)->find();
        if(empty($bind_info)){
            $this->returnCode('20120052');
        }
        $house_worker = D('House_worker')->where(array('village_id'=>$bind_info['village_id'],'phone'=>$bind_info['phone'],'status'=>1,'is_del'=>0))->find();
        if(empty($house_worker)){
            $this->returnCode('20120052');
        }
        $qrcode_person = M('Wisdom_qrcode_person')->where(array('uid'=>$house_worker['wid']))->select();
        $cate = [];
        foreach($qrcode_person as $k=>$v){
            $cate[] = $v['cate_id'];
        }
        $cate['village_id'] = $village_id;
        $dataList = D('Wisdom_qrcode_cate')->where($cate)->select();
        $cate_list = [];
        foreach($dataList as $k=>$value){
            $list['cate_name'] =$value['cate_name'];
            $list['cate_id'] =$value['id'];
            $list['village_id'] =$value['village_id'];
            $cate_list[] = $list;
        }
        $arr = [];
        $test_cate_list = array(
            'cate_name'=>'全部',
            'cate_id'=>'',
            'village_id' =>''
        );
        array_unshift($cate_list,$test_cate_list);
        $arr['cate_list'] = $cate_list;
        $this->returnCode(0, $arr);
    }

