    {
        $aPage = I('page');
        if(empty($aPage)){
            $this->returnCodeError('分页参数必须穿');
        }
        $floor_id = I('floor_id');
        if(empty($floor_id)){
            $this->returnCodeError('单元id必须存在');
        }
