            $list['page'] = $k + 1;
            $list['room_id'] = $v['pigcms_id'];
            $list['room_info'] = $v['layer'] . '#'.$v['room'];
            $vacancy_arr[] = $list;
        }
        if($vacancy_arr){
            foreach($vacancy_arr as $k=>$v){
                if($v['page'] == $aPage){
                    $pigcms_id = $v['room_id'];
                }

                if($v['page'] == ($aPage-1)){
                    $arr['start_room_info'] = $v['room_info'];
                }else{
                    $arr['start_room_info'] = '';
                }
                if($v['page'] == ($aPage+1)){
                    $arr['last_room_info'] = $v['room_info'];
                }else{
                    $arr['last_room_info'] = '';
                }
            }
        }
        if(!$pigcms_id){
            $this->returnCode('20090171');
