            'room_address' => $find_village['village_name'].' '.$find_village_floor['floor_layer'].$find_village_floor['floor_name'].$find_village_room['layer'].'#'.$find_village_room['room']
        );
        $arr['find_info'] = $find_info;


        $read_person = M('Meter_read_person')->where(array('uid'=>$house_worker['wid'],'village_id'=>$find_village_floor['village_id'],'status'=>1))->select();
        if(empty($read_person)){
            $this->returnCode('20090243');
        }
        foreach($read_person as $k=>$v){
            $read_persons[] = $v['cate_id'];
        }
        $where['id'] = array('in',$read_persons);
        $read_cate = M('Meter_read_cate')->where($where)->select();
        foreach($read_cate as $k1=>&$v1){

            $record = M('Meter_read_record')->where(array('cate_id'=>$v1['id'],'room_id'=>$find_village_room['pigcms_id'],'village_id'=>$find_village_floor['village_id']))->find();
            if($record){
                $v1['add_time_d'] = date('d',$record['add_time']);
                if(date('d',$record['add_time']) >= $v1['cycle_time']){
                    $v1['status'] = 2;
                    $v1['statusDesc'] = '已抄';
                }else{
                    $v1['status'] = 1;
                    $v1['statusDesc'] = '未抄';
                }
            }else{
                $v1['status'] = 1;
                $v1['statusDesc'] = '未抄';
                $v1['add_time_d'] = '未';
            }

        }
        $arr['read_cate'] = $read_cate;
        $arr['total_page'] = $total_page;
        $this->returnCode(0, $arr);
    }

    public function room_info_new_project()
    {
        $aPage = I('page');
        if(empty($aPage)){
            $this->returnCodeError('分页参数必须穿');
        }
        $layer_id = I('layer_id');
        if(empty($layer_id)){
            $this->returnCodeError('楼层id必须存在');
        }
        $arr = [];
        $database_house_village_user_vacancy = D('House_village_user_vacancy');
        $vacancy_where['layer_id'] = $layer_id;
        $vacancy_where['uid'] = array('neq',0);
        $vacancy_list = $database_house_village_user_vacancy->house_village_user_vacancy_page_list_room_new($vacancy_where , true , 'pigcms_id asc' , 9999999);
        $vacancy_list = $vacancy_list['result']['list'];

        if($vacancy_list){
            $total_page = count($vacancy_list);
        }else{
            $total_page = 0;
        }
        $vacancy_arr = [];
        foreach($vacancy_list as $k1=>$v1) {
            $list['page'] = $k1 + 1;
            $list['room_id'] = $v1['pigcms_id'];
            $list['room_info'] = $v1['layer'] . '#'.$v1['room'];
            $vacancy_arr[] = $list;
        }

        if($vacancy_arr){
            $arr['start_room_info'] = '';
            $arr['last_room_info'] = '';
            foreach($vacancy_arr as $k=>$v){
                if($v['page'] == $aPage){
                    $pigcms_id = $v['room_id'];
                }

                if($v['page'] == ($aPage-1)){
                    $arr['start_room_info'] = $v['room_info'];
                }
                if($v['page'] == ($aPage+1)){
                    $arr['last_room_info'] = $v['room_info'];
                }
            }
        }
        if(!$pigcms_id){
            $this->returnCode('20090171');
        }
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        //增加工作人员判断
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $village_user_bind['village_id'] = $village_id;
        $village_user_bind['type'] = 4;
        $village_user_bind['uid'] = $this->_uid;
        $village_user_bind['status'] = ['not in', [3,4]];
        $bind_info = M('House_village_user_bind')->where($village_user_bind)->find();
        if(empty($bind_info)){
            $this->returnCode('20120052');
        }
        $house_worker = D('House_worker')->where(array('village_id'=>$bind_info['village_id'],'phone'=>$bind_info['phone'],'status'=>1,'is_del'=>0))->find();
        if(empty($house_worker)){
            $this->returnCode('20120052');
        }

        $database_house_village_user_bind = D('House_village_user_bind');
        $database_house_village_user_vacancy = D('House_village_user_vacancy');

        $database_house_village = D('House_village');
        $database_house_village_floor = D('House_village_floor');
        //$pigcms_id = I('pigcms_id');//房间id

        $bind_where['pigcms_id'] = $pigcms_id;
//查询 房间信息 单元信息 小区信息
        $find_village_room = $database_house_village_user_vacancy->get_find_room_info($pigcms_id , "pigcms_id,uid,name,phone,floor_id,village_id,layer,layer_id,room,housesize,single_id");
        $find_village_floor = $database_house_village_floor->get_unit_find($find_village_room['floor_id'] , 'village_id,floor_name,floor_layer');
        $find_village = $database_house_village->get_village_info($find_village_room['village_id'] , 'village_name,village_address');
        $find_info = array(
            'room_id'         =>  $find_village_room['pigcms_id'],//房间id
            'user_name'         =>  $find_village_room['name'],//业主名称
            'user_phone'         =>  $find_village_room['phone'],//业主联系方式
            'vacancy_layer'         =>  $find_village_room['layer'],
            'vacancy_floor_id'      =>  $find_village_room['floor_id'],
            'vacancy_room'          =>  $find_village_room['room'],
            'vacancy_housesize'          =>  $find_village_room['housesize'],
            'village_name'          =>  $find_village['village_name'],
            'village_address'       =>  $find_village['village_address'],
            'floor_name'            =>  $find_village_floor['floor_name'],
            'floor_layer'           =>  $find_village_floor['floor_layer'],
            'village_id'            =>  $find_village_floor['village_id'],
//            'room_address' => $find_village['village_name'].' '.$find_village_floor['floor_layer'].$find_village_floor['floor_name'].$find_village_room['layer'].'#'.$find_village_room['room']
            'room_address' => $find_village['village_name'].' '.D('House_village')->get_single_floor_room($find_village_room['single_id'],$find_village_room['floor_id'],$find_village_room['layer_id'],$find_village_room['pigcms_id'],$find_village_room['village_id'])

        );
        $arr['find_info'] = $find_info;


        $read_person = M('Meter_read_person')->where(array('uid'=>$house_worker['wid'],'village_id'=>$find_village_floor['village_id'],'status'=>1))->select();
        if(empty($read_person)){
            $this->returnCode('20090243');
        }
        foreach($read_person as $k=>$v){
            $read_persons[] = $v['cate_id'];
        }
        $where['id'] = array('in',$read_persons);
        $read_cate = M('Meter_read_cate')->where($where)->select();
        $month_start_time = strtotime(date("Y-m-01", time()));
        foreach($read_cate as $k1=>&$v1){

            $record = M('Meter_read_record')->order('add_time DESC')->where(array('cate_id'=>$v1['id'],'room_id'=>$find_village_room['pigcms_id'],'village_id'=>$find_village_floor['village_id']))->find();

            if($record){
                $add_time_d = date('d',$record['add_time']);
                if($record['add_time'] < $month_start_time){
                    $v1['status'] = 1;
                    $v1['statusDesc'] = '未抄';
                }elseif($record['add_time'] >= $month_start_time && intval($add_time_d) >= intval($v1['cycle_time'])){
                    $v1['status'] = 2;
                    $v1['statusDesc'] = '已抄';
                }else{
                    $v1['status'] = 1;
                    $v1['statusDesc'] = '未抄完';
                }
            }else{
                $v1['status'] = 1;
                $v1['statusDesc'] = '未抄';
            }

        }
        $arr['read_cate'] = $read_cate;
        $arr['total_page'] = $total_page;
        $this->returnCode(0, $arr);
    }


