    //移动抄表==>提交数据
    public function add_meter_read()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $village_user_bind['village_id'] = $village_id;
        $village_user_bind['type'] = 4;
        $village_user_bind['uid'] = $this->_uid;
        $village_user_bind['status'] = ['not in', [3,4]];
        $bind_info = M('House_village_user_bind')->where($village_user_bind)->find();
        if(empty($bind_info)){
            $this->returnCode('20120052');
        }
        $house_worker = D('House_worker')->where(array('village_id'=>$bind_info['village_id'],'phone'=>$bind_info['phone'],'status'=>1,'is_del'=>0))->find();
        if(empty($house_worker)){
            $this->returnCode('20120052');
        }
        $cate_id = I('cate_id');//水电煤分类id
        if(empty($cate_id)){
            $this->returnCode('20045009');
        }

        $room_id = I('room_id');//房间ID
        if(empty($room_id)){
            $this->returnCode('20120050');
        }
        $database_house_village_user_vacancy = D('House_village_user_vacancy');
        $find_village_room = $database_house_village_user_vacancy->get_find_room_info($room_id , "pigcms_id,uid,name,phone,floor_id,village_id,layer,room,housesize");
        $floor_id = I('floor_id');//房间单元ID
        if(empty($floor_id)){
            $this->returnCode('20120051');
        }

        $user_bind_id = I('user_bind_id');//业主ID
        if(empty($user_bind_id)){
            $this->returnCode('20090009');
        }

        $user_bind_phone = I('user_bind_phone');//业主手机号
        if(empty($user_bind_phone)){
            $this->returnCode('20090244');
        }

        $start_num = I('start_num',0,'floatval');//起度
        $end_num = I('end_num',0,'floatval');//止度
        if(empty($end_num)){
            $this->returnCode('20090245');
        }

        $where['room_id'] = $room_id;
        $where['floor_id'] = $floor_id;
        $where['village_id'] = $village_id;
        $where['cate_id'] = $cate_id;
        $record = M('Meter_read_record')->where($where)->order('id desc')->find();
        // 获取最小 起度
        if($record){
            $start_num_min = $record['end_num'];
        }else{
            $start_num_min = 0.00;
        }
//        dump($start_num);
//        dump($start_num_min);die;
        if (!$start_num) {
            $start_num = $start_num_min;
        }
        if (floatval($start_num)>floatval($end_num)) {
            $this->returnCodeError('止度不能小于起度');
        }
        /*if (floatval($start_num_min)>floatval($start_num)) {
            $this->returnCodeError('当前起度不能小于上次抄表的止度'.$start_num_min);
        }*/
        $read_person = M('Meter_read_person')->where(array('uid'=>$house_worker['wid'],'village_id'=>$village_id,'status'=>1,'cate_id'=>$cate_id))->find();
        if(empty($read_person)){
            $this->returnCode('20090243');
        }

        $project = M('Meter_read_project')->where(array('cate_id'=>$cate_id,'village_id'=>$village_id))->select();
        if(empty($project)){
            $this->returnCode('20090246');
        }
        $room_ids_arr = '';
        foreach($project as $k=>$v){
            if($v['room_id']){
                $room_ids_arr .= $v['room_id'].',';
            }
        }
        $room_ids_arr = trim($room_ids_arr, ',');
        $room_ids_arr = explode(',',$room_ids_arr);
        if(in_array($room_id,$room_ids_arr)){
            $data['village_id'] = $village_id;
            $data['floor_id'] = $floor_id;
            $data['room_id'] = $room_id;
            $data['cate_id'] = $cate_id;
            $data['project_id'] = $v['id'];//项目id
            $data['user_bind_id'] = $user_bind_id;//业主id
            $data['user_name'] = $find_village_room['name'];//业主名称
            $data['user_bind_phone'] = $user_bind_phone;//业主手机号
            $data['unit_price'] = $v['unit_price'];//单价
            $data['rate'] = $v['rate'];//倍率
            $data['pool_ammeter'] = $v['pool'];//公摊
            $data['person_id'] = $house_worker['wid'];//负责人ID
            $data['start_num'] = $start_num;//起度
            $data['end_num'] = $end_num;//止度
            $data['add_time'] = time();
            $data['cost_num'] = (floatval($end_num)-floatval($start_num)+floatval($v['pool'])*floatval($v['rate']));///未缴数量//($data['last_ammeter'] - $data['start_ammeter'] +$data['pool_ammeter'])*$data['rate']
            $data['cost_money'] = $data['cost_num'] * $v['unit_price'];//未缴费用//$data['unit_price'] * $data['cost_num']
            $insertID = M('Meter_read_record')->data($data)->add();
            if($insertID){
                // 金额 = （止度-起度+公摊）*倍率 * 单价
                $meter_read_cate = M('Meter_read_cate')->where(['id'=>$cate_id])->find();
                $where_bind = array(
                    'floor_id'=>$floor_id,
                    'vacancy_id'=>$room_id,
                    'type'=> ['in',[0,3]],
                    'status' => ['not in', [3,4]],
                );
                $res = M('House_village_user_bind')->where($where_bind)->find();
                if($res){
                    $ydate = date('Y', time());
                    $mdate = date('m', time());
                    $gas['ydate']= $electric['ydate']= $water['ydate'] = $ydate? $ydate : '';
                    $gas['mdate']= $electric['mdate']= $water['mdate'] = $mdate? $mdate : '';
                    $gas['type']= $electric['type']= $water['type'] = 1;
                    $gas['village_id']= $electric['village_id']= $water['village_id'] = $this->village_id;
                    $gas['uid']= $electric['uid']= $water['uid'] = $res['uid'];
                    $gas['usernum']= $electric['usernum']= $water['usernum'] = $res['usernum'];
                    $gas['name']= $electric['name']= $water['name'] = $res['name'];
                    $gas['phone']= $electric['phone']= $water['phone'] = $res['phone'];
                    $gas['bind_id']= $electric['bind_id']= $water['bind_id'] = $res['pigcms_id'];
                    $gas['add_time']= $electric['add_time']= $water['add_time'] = time();
                }
                if($meter_read_cate && $meter_read_cate['cate_name'] == '电费' && $data['cost_money']){
                    $where_bind = array(
                        'floor_id'=>$floor_id,
                        'vacancy_id'=>$room_id,
                        'type'=> ['in',[0,3]],
                        'status' => ['not in', [3,4]],
                    );
                    M('House_village_user_bind')->where($where_bind)->setInc('electric_price',$data['cost_money']);
                    $electric['electric_price'] = $data['cost_money'];
                    M('House_village_user_paylist')->data($electric)->add();
                    M('House_village_user_edit_price_record')->add(['pigcms_id'=>$res['pigcms_id'],'money'=>$data['cost_money'],'detail'=>'增加'.$data['cost_money'].'元','action'=>'移动抄表-增加','add_time'=>time(),'name'=>$bind_info['name'],'phone'=>$bind_info['phone'],'type'=>2]);
                }elseif($meter_read_cate && ($meter_read_cate['cate_name'] == '煤气费' || $meter_read_cate['cate_name'] == '燃气费') && $data['cost_money']){
                    $where_bind = array(
                        'floor_id'=>$floor_id,
                        'vacancy_id'=>$room_id,
                        'type'=> ['in',[0,3]],
                        'status' => ['not in', [3,4]],
                    );
                    M('House_village_user_bind')->where($where_bind)->setInc('gas_price',$data['cost_money']);
                    $gas['gas_price'] = $data['cost_money'];
                    M('House_village_user_paylist')->data($gas)->add();
                    M('House_village_user_edit_price_record')->add(['pigcms_id'=>$res['pigcms_id'],'money'=>$data['cost_money'],'detail'=>'增加'.$data['cost_money'].'元','action'=>'移动抄表-增加','add_time'=>time(),'name'=>$bind_info['name'],'phone'=>$bind_info['phone'],'type'=>3]);
                }elseif($meter_read_cate && $meter_read_cate['cate_name'] == '水费' && $data['cost_money']){
                    $where_bind = array(
                        'floor_id'=>$floor_id,
                        'vacancy_id'=>$room_id,
                        'type'=> ['in',[0,3]],
                        'status' => ['not in', [3,4]],
                    );
                    M('House_village_user_bind')->where($where_bind)->setInc('water_price',$data['cost_money']);
                    $water['water_price'] = $data['cost_money'];
                    M('House_village_user_paylist')->data($water)->add();
                    M('House_village_user_edit_price_record')->add(['pigcms_id'=>$res['pigcms_id'],'money'=>$data['cost_money'],'detail'=>'增加'.$data['cost_money'].'元','action'=>'移动抄表-增加','add_time'=>time(),'name'=>$bind_info['name'],'phone'=>$bind_info['phone'],'type'=>1]);
                }
                //新增优化 start
                $address = D('House_village')->get_single_floor_room($res['single_id'],$res['floor_id'],$res['layer_id'],$res['vacancy_id'],$village_id);
                $openid = D('User')->where(['uid'=>$res['uid']])->getField('openid');
                //$house_village_name = D('House_village')->where(['village_id'=>$village_id])->getField('village_name');
                $house_village = D('House_village')->where(['village_id'=>$village_id])->field('village_name,property_id')->find();
                if($openid){
                    $model = new templateNews(C('config.wechat_appid'), C('config.wechat_appsecret'));
                    $keyword = '尊敬的业主，您有新的账单';
                    $remark = '您的待缴总额剩余：￥'.$data['cost_money'].'元，点击缴费！';
                    $db_house_village = D('House_village');
                    $app_version = intval($_POST['app_version']);
                    $deviceId = trim($_POST['Device-Id']);
                    $param = [
                        'pageName' => 'payMentlist',
                        'isAll' => true,
                        'urlParam' => 'village_id='.$village_id.'&pigcms_id='.$res['pigcms_id'],
                    ];
                    $payMentlistUrl = $db_house_village->villagePagePath($app_version,$deviceId,$param);
                    $href = $payMentlistUrl;
                    $getIsAihorseCustomized = D('Config_customization')->getIsAihorseCustomized();
                    if($getIsAihorseCustomized){
                        $village_info_arr= M('House_village_info')->where(['village_id'=>$this->village_id])->field('third_pay_url,third_ccb_pay_url')->find();
                        $href = isset($village_info_arr['third_pay_url']) && $village_info_arr['third_pay_url'] ? $village_info_arr['third_pay_url'] : $href;
                        $href = isset($village_info_arr['third_ccb_pay_url']) && $village_info_arr['third_ccb_pay_url'] ? $village_info_arr['third_ccb_pay_url'] : $href;
                    }
                    $meter_read_cate['cate_name'] = $meter_read_cate['cate_name']??'';
                    $thing10 = $v['name'];
                    if (mb_strlen($v['name'], 'utf8') > 12) {
                        $thing10 = mb_substr($v['name'], 0, 12, 'utf8') . '......';
                    }
                
                    $model->sendTempMsg('TM01008',//todo 类目模板TM01008
                        array(
                            'href' => $href,
                            'wecha_id' => $openid,
                            'first' => $keyword,
                            'keynote1' => $house_village['village_name'],
                            'keynote2' => $address,
                            'remark' => $remark,
                            'new_info' => [//新版本发送需要的信息
                                'type'=>0,//缴费提醒类型（0：提醒缴费，1：提醒缴费成功）
                                'thing2'=>$find_village_room['name'],//业主姓名
                                'thing3'=>$address,//地址
                                'thing9'=>$meter_read_cate['cate_name']?:'物业费',//缴费类型
                                'thing10'=>$thing10,//账单名称
                                'amount4'=>$data['cost_money'].'元',//账单金额
                            ],
                        ),0,$house_village['property_id'],1
                    );
                }
                //新增优化 end
                $this->returnCodeOk(L_('上传成功!'));
            }else{
                $this->returnCodeOk(L_('上传失败!'));
            }

        }else{
            $this->returnCode('20090247');
        }

    }

    public function meter_read_cate()
    {
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $read_cate = M('Meter_read_cate')->where(array('village_id'=>$village_id))->select();
        $dataList = [];
        foreach($read_cate as $v){
            $list['cate_id'] = $v['id'];
            $list['cate_name'] = $v['cate_name'];
            $list['village_id'] = $v['village_id'];
            $dataList[] = $list;
        }
        $arr = [];
        $test_cate_list = array(
            'cate_name'=>'全部',
            'cate_id'=>'',
            'village_id' =>''
        );
        array_unshift($dataList,$test_cate_list);
        $arr['dataList'] = $dataList;
        $this->returnCode(0, $arr);
    }

    //移动抄表(对应房间)==>记录
    public function record_room_list()
    {
        $room_id = I('room_id');
        if(empty($room_id)){
            $this->returnCode('20120038');
        }
        $aPage = I('page',1);
        $where = [];
        $cate_id = I('cate_id');
        if($cate_id){
            $where['cate_id'] = $cate_id;
        }
        $add_time = I('add_time');
        if($add_time){
            $start_time = strtotime($add_time.'00:00:00');
            $end_time = strtotime($add_time.'23:59:59');
            $where['add_time'] = array('between',array($start_time,$end_time));
        }
        $database_house_village_user_vacancy = D('House_village_user_vacancy');
        $database_house_village_floor = D('House_village_floor');
        $record_list = M('Meter_read_record')->where(array('room_id'=>$room_id))->where($where)->page($aPage,10)->select();
        $record_list_count = M('Meter_read_record')->where(array('room_id'=>$room_id))->where($where)->count();

        $arr = [];
        $dataList = [];
        foreach($record_list as $k=>$v){
            $list['add_time'] = date('Y-m-d H:i:s',$v['add_time']);
            $list['start_num'] = $v['start_num'];//起度
            $list['end_num'] = $v['end_num'];//止度
            $users = D('User')->where(array('uid'=>$v['uid'],'status'=>1))->find();
            $user = D('User')->where(array('uid'=>$v['person_id'],'status'=>1))->find();
            $house_worker = D('House_worker')->where(array('wid'=>$v['person_id'],'is_del'=>0,'status'=>1,'village_id'=>$v['village_id']))->find();
            $list['user_name'] = $users['nickname'];
            $list['worker_name'] = $house_worker['name'];
            $find_village_room = $database_house_village_user_vacancy->get_find_room_info($v['room_id'] , "uid,name,phone,floor_id,village_id,layer,room,housesize");
            $find_village_floor = $database_house_village_floor->get_unit_find($find_village_room['floor_id'] , 'village_id,floor_name,floor_layer');
            $list['room_name'] = $find_village_room['room'];
            $list['user_name'] = $find_village_room['name'];
            $list['user_phone'] = $find_village_room['phone'];
            $list['user_address'] = $find_village_floor['floor_layer'].$find_village_floor['floor_name'].$find_village_room['layer'].'#'.$find_village_room['room'];

            $project = M('Meter_read_project')->where(array('id'=>$v['project_id'],'village_id'=>$v['village_id'],'cate_id'=>$v['cate_id']))->find();
            $cate = M('meter_read_cate')->where(array('id'=>$v['cate_id']))->find();
            $list['cate_name'] = $cate['cate_name'];
            $list['project_name'] = $project['project_name'];
            $list['unit_price'] = $project['unit_price'];//单价
            $list['rate'] = $project['rate'];//倍率
            $list['pool'] = $project['pool'];//公摊
            $dataList[] = $list;
        }
        $arr['dataList'] = $dataList;
        $arr['record_list_count'] = $record_list_count;
        $this->returnCode(0, $arr);
    }


