    /**区块-wan*/
    // 访客开门
    private function time_list($time_limit = 1) {
        $time_arr = array();
        $time_arr[] = array(
            'value'=>'1小时',
            'type'=>'1',
            'time'=>'1'
        );
        if ($time_limit>=2) {
            $time_arr[] = array(
                'value'=>'2小时',
                'type'=>'1',
                'time'=>2
            );
        }
        if ($time_limit>=3) {
            $time_arr[] = array(
                'value'=>'3小时',
                'type'=>'1',
                'time'=>3
            );
        }
        if ($time_limit>=5) {
            $time_arr[] = array(
                'value'=>'5小时',
                'type'=>'1',
                'time'=>5
            );
        }
        if ($time_limit>=8) {
            $time_arr[] = array(
                'value'=>'8小时',
                'type'=>'1',
                'time'=>8
            );
        }
        if ($time_limit>=10) {
            $time_arr[] = array(
                'value'=>'10小时',
                'type'=>'1',
                'time'=>10
            );
        }
        if ($time_limit>=12) {
            $time_arr[] = array(
                'value'=>'12小时',
                'type'=>'1',
                'time'=>12
            );
        }
        if ($time_limit>12) {
            $days=intval($time_limit*1/24);
            for($i=1;$i<=$days;$i++){
                $key_val = array(
                    'value' => "{$i}天",
                    'type' => "2",
                    'time' => $i
                );
                $time_arr[] = $key_val;
            }
        }

        return $time_arr;
    }

    public function visitor_list_open() {
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_info = M('House_village')->where(array('village_id' => $village_id))->field('owe_property_open_door, owe_property_open_door_day, temporary_visitor_switch,temporary_visitor_time')->find();
        $owe_property_days = 0;
        $temporary_visitor_time_limit = 168; // 默认168小时 即 7天
        $temporary_visitor_switch=intval($village_info['temporary_visitor_switch']);
        if ($this->config['house_village_temporary_visitor_time'] > 0) {
            $temporary_visitor_time_limit = floatval($this->config['house_village_temporary_visitor_time']);
        }
        if ($village_info['temporary_visitor_time'] > 0) {
            if ($this->config['house_village_temporary_visitor_time'] > 0 && $village_info['temporary_visitor_time'] < $this->config['house_village_temporary_visitor_time']) {
                $temporary_visitor_time_limit = floatval($village_info['temporary_visitor_time']);
            }
        }
        if(empty($this->_uid)){
            $this->returnCode('20000009');
        }
        $uid = $this->_uid;
        $now_village_bind= D('House_village_user_bind')->get_one_by_bindId($pigcms_id);
        if (empty($now_village_bind)) {
            $this->returnCode('20120004');
        }
        $info = array(
            'tip' => 0,
            'tip_info' => ''
        );
        // 处理下分享提示图片
        $visitor_open_img = $this->config['site_url'] . '/static/images/house/shareMask.png';
        // 处理返回可选择时间
        $time_list = $this->time_list($temporary_visitor_time_limit);
        if ($now_village_bind['type'] == 4) {
            // 考虑到安全问题，工作人员门禁权限不可分享
            $info['tip'] = 1;
            $info['tip_info'] = '工作人员不能分享门禁';
            $village_floor_list = [
                'list' => [],
                'visitor_open_img' => $visitor_open_img,
                'info' => $info,
                'temporary_visitor_time_limit' => $temporary_visitor_time_limit,
                'temporary_visitor_switch'=>$temporary_visitor_switch,  
                'time_list' => $time_list
            ];
            $this->returnCode(0, $village_floor_list);
        } else {
            $userTimes =  D('House_village_user_bind')->getUserEndTime($pigcms_id);
            $dayTimes = strtotime(date('y-m-d', time()));
            if (isset($userTimes['propertyEndTime'])&&$userTimes['propertyEndTime']&&$userTimes['propertyEndTime']<$dayTimes) {
                $info['tip'] = 1;
                $info['tip_info'] = '您的权限已到期，请联系物业管理人员！';
            }
        }
        // 处理下分享提示图片
        $visitor_open_img = $this->config['site_url'] . '/static/images/house/shareMask.png';
        // 获取所有该用户在小区的开门权限（工作人员除外-考虑到安全性，主要是工作人员拥有对应小区所有门禁开门权限）
        $m_house_village_door_user = M('House_village_door_user');
        $m_house_village_floor = M('House_village_floor');
        $m_house_village_door = M('House_village_door');
        $m_house_village_user_bind = M('House_village_user_bind');
        $d_house_face_device = M('House_face_device');

        $where['a.uid'] = $uid;
        $where['a.status'] = 1;
        $where['b.village_id'] = $village_id;
        $aUserSelect = $m_house_village_user_bind->alias('a')
            ->join('LEFT JOIN pigcms_house_village as b on b.village_id=a.village_id')
            ->distinct(true)
            ->field(array('a.pigcms_id','a.parent_id','a.type','a.name','a.village_id', 'a.floor_id', 'a.property_price', 'a.property_endtime', 'a.phone', 'a.open_door_day', 'b.village_name', 'b.village_address', 'b.owe_property_open_door', 'b.owe_property_open_door_day'))
            ->where($where)
            ->order('a.type DESC')
            ->select();

        // 处理数据-层次为  小区-门禁-具体信息
        $open_list_info = array();
        // 查询出来的门禁信息存储
        $door_list_info = array();
        // 查询出来的单元信息存储
        $floor_list_info = array();
        // 查询出来的可以开门的信息存储
        $aDoor_is_open = array();
        // 存储信息
        $bind_info = array();
        // 是否有蓝牙门禁
        $is_ly = false;
        // 是否有人脸门禁
        $is_face = false;

        $aDoor = array();
        $db_house_village_public_area = M('House_village_public_area');
        $house_village_public_area = $db_house_village_public_area->where(['village_id' => $village_id])->getField('public_area_id,public_area_name');
        if (!empty($aUserSelect)) {
            foreach ($aUserSelect as $k => $v) {
                if(isset($v['open_door_day']) && $v['open_door_day']>0){
                    $v['owe_property_open_door_day']=$v['open_door_day'];
                }
                if ($v['type'] == 1 || $v['type'] == 2) {
                    // 家属和租客 物业费信息以业主为准
                    if ($bind_info[$v['parent_id']]) {
                        $v['property_price'] = $bind_info[$v['parent_id']]['property_price'];
                        $v['property_endtime'] = $bind_info[$v['parent_id']]['property_endtime'];
                    } else {
                        $msg = $m_house_village_user_bind->where(array('pigcms_id' => $v['parent_id']))->field('property_price, property_endtime')->find();
                        $v['property_price'] = $msg['property_price'];
                        $v['property_endtime'] = $msg['property_endtime'];
                    }
                }
                $bind_info[$v['pigcms_id']] = $v;
                if (!$open_list_info[$v['village_id']]) {
                    // 处理小区层信息
                    $open_list_info[$v['village_id']] = array(
                        'village_name' => $v['village_name'],
                        'village_address' => $v['village_address']
                    );
                    // 放置门禁信息数组
                    $open_list_info[$v['village_id']]['door_list'] = array();
                }
                // 避免重复查询门禁信息
                if ($door_list_info && $door_list_info[$v['village_id']]) {
                    $aDoorList = $door_list_info[$v['village_id']];
                } else {
                    $condition_door['door_status'] = 1;
                    $condition_door['village_id'] = $v['village_id'];
                    $aDoorList = $m_house_village_door->group('village_id, door_device_id')->field(true)->where($condition_door)->select();
                    if (!empty($aDoorList) && !$is_ly) {
                        $is_ly = true;
                    }
                    // 获取对应的人脸门禁设备
                    $condition_face_door['device_status'] = 1;
                    $condition_face_door['village_id'] = $v['village_id'];
                    $condition_face_door['is_del'] = 0;
                    $aFaceDoorList = $d_house_face_device->group('village_id, device_id')->field(true)->where($condition_face_door)->select();
                    if (!empty($aFaceDoorList) && !$is_face) {
                        $is_face = true;
                    }
                    if ($aFaceDoorList) {
                        $aDoorList = array_merge($aDoorList, $aFaceDoorList);
                    }
                    $door_list_info[$v['village_id']] = $aDoorList;
                }
                // 默认存在单元门禁
                if (empty($aDoorList)) {
                    unset($open_list_info[$v['village_id']]);
                    continue;
                } else {
                    $open_list_info[$v['village_id']]['have_village_door'] = true;
                    $open_list_info[$v['village_id']]['tip_info'] = '';
                }

                if ($v['type'] == 4) {
                    // 工作人员信息 无法分享
                    continue;
                } else {
                    // 绑定的单元-即拥有该小区的大门和改单元门禁权限
                    $village_floor_id = $v['floor_id'];
                    // 开门到期时间
                    $property_endtime = 0;

                    // 允许开门情况下继续判断
                    if (!$v['property_endtime']) {
                        $ban_open_status = false;   // 是否禁止开门  false 可以开门  true 禁止开门
                    } else {
                        $ban_open_status = false; // 默认可以开门
                        $owe_property_days = 0;
                        if ( $v['property_endtime'] > 0) {
                            // 计算 当前时间到物业截止时间的天数
                            $owe_property_days = (strtotime(date('y-m-d', time())) - strtotime(date('y-m-d', $v['property_endtime']))) / 86400;
                        }
                        if (!$v['owe_property_open_door'] && $v['property_endtime']>0 && (time() > $v['property_endtime'])) {
                            // 判断  不能欠款延期开门 且 当前时间大于 物业截止时间  开门禁止
                            $ban_open_status = true;
                        } else if ($v['owe_property_open_door_day'] > 0 && $owe_property_days >= 0 && $owe_property_days > $v['owe_property_open_door_day']) {
                            // 判断  可以欠款延期开门 且 延期天数大于0 且  当前时间到物业截止时间的天数存在 且大于 延期天数 开门禁止
                            $ban_open_status = true;
                        }
                        // 处理下开门到期时间
                        if ($v['property_endtime'] > 0) {
                            $property_endtime = $v['property_endtime'];
                            if ($v['owe_property_open_door'] && $v['owe_property_open_door_day'] > 0) {
                                $property_endtime +=  $v['owe_property_open_door_day'] * 86400;
                            }
                        }
                    }
                    foreach ($aDoorList as $kk => &$vv) {
                        if (isset($vv['device_id']) && $vv['device_id']>0) {
                            $key = 'face_' . $vv['device_id'];
                            $vv['key_type'] = 'face';
                        } elseif (isset($vv['door_id']) && $vv['door_id']>0) {
                            $key = 'ly_' . $vv['door_id'];
                            $vv['key_type'] = 'ly';
                        } else {
                            fdump('--------------------'.__LINE__,'open_List', true);
                            fdump($vv,'open_List', true);
                            continue;
                        }
                        $floor_arr = [];
                        if (!empty($aDoor_is_open) && !empty($aDoor_is_open[$vv['door_id']])) {

                            // 判断下哪一个有效期更长
                            if ($aDoor_is_open[$key]['door_end_time'] == 0 || ($property_endtime > 0 && $aDoor_is_open[$key]['door_end_time'] && $aDoor_is_open[$key]['door_end_time'] > $property_endtime)) {
                                // 如果已经存在的门禁权限更久 将跳过下面的步骤
                                continue;
                            }
                            // 门禁信息已经查询过，直接赋予新的状态
                            $vv = $aDoor_is_open[$key];
                        } elseif ($vv['floor_id'] != "-1") {
                            $floor_arr = explode(',',$vv['floor_id']);
                            // 避免重复查询单元信息
                            $vv['floor_name'] = $vv['device_name']?$vv['device_name']:$vv['door_name'];
                            $vv['floor_layer'] = '';
                            $vv['door_type'] = 1; // 小区单元门
                        } elseif (isset($vv['public_area_id']) && $vv['public_area_id']>0) {
                            $house_name = C('config.house_name') ? C('config.house_name').L_('大门') : L_('小区').L_('大门');
                            $vv['floor_name'] = $house_village_public_area[$vv['public_area_id']] ? $house_village_public_area[$vv['public_area_id']] : $house_name;
                            $vv['floor_layer'] = $vv['device_name']?$vv['device_name']:$vv['door_name'];
                            $vv['door_type'] = 2; // 小区大门
                        } else {
                            $vv['floor_name'] = $vv['device_name']?$vv['device_name']:$vv['door_name'];
                            $vv['floor_layer'] = '';
                            $vv['door_type'] = 2; // 小区大门
                        }
                        if ($v['type'] == 1 || $v['type'] == 2) {
                            $vv['door_user_type'] = 4; // 家属
                        } else {
                            $vv['door_user_type'] = 1; // 业主
                        }

                        $vv['door_end_time'] = $property_endtime>0?date('Y-m-d H:i', $property_endtime):0;
                        if (isset($vv['door_id']) && $vv['door_id']>0) {
                            $userWhere = array(
                                'user_id' => $uid,
                                'door_fid' => $vv['door_id'],
                            );
                            $aDoorFind = $m_house_village_door_user->field(true)->where($userWhere)->find();
                        } else {
                            $aDoorFind = array();
                        }
                        if (!$ban_open_status && empty($aDoorFind) && $vv['floor_id'] == -1) {
                            if (empty($aDoor_is_open) || empty($aDoor_is_open[$key])) {
                                $vv['open_status'] = 1;
                                $vv['open_status_txt'] = '可以打开';
                                $aDoor[] = $vv;
                                $aDoor_is_open[$key] = $vv;
                            }
                            $aDoor_is_open[$key]['door_user_type'] = 1;
                            $open_list_info[$vv['village_id']]['door_list'][$key] = $vv;
                        } elseif (!$ban_open_status && empty($aDoorFind) && ($village_floor_id==0 || $vv['floor_id'] == $village_floor_id || in_array($village_floor_id, $floor_arr))) {
                            if (empty($aDoor_is_open) || empty($aDoor_is_open[$key])) {
                                $vv['open_status'] = 1;
                                $vv['open_status_txt'] = '可以打开';
                                $aDoor[] = $vv;
                                $aDoor_is_open[$key] = $vv;
                            }
                            $aDoor_is_open[$key]['door_user_type'] = 1;
                            $open_list_info[$vv['village_id']]['door_list'][$key] = $vv;
                        } elseif (!$ban_open_status && $aDoorFind['status'] == 1 && ($village_floor_id==0 || $vv['floor_id'] == $village_floor_id || in_array($village_floor_id, $floor_arr))) {
                            if ($aDoorFind == 0 || time() > $aDoorFind['end_time']) {
                                if (empty($aDoor_is_open) || empty($aDoor_is_open[$key])) {
                                    $vv['open_status'] = 1;
                                    $vv['open_status_txt'] = '可以打开';
                                    $aDoor[] = $vv;
                                    $aDoor_is_open[$key] = $vv;
                                }
                                $aDoor_is_open[$key]['door_user_type'] = 1;
                                $open_list_info[$vv['village_id']]['door_list'][$key] = $vv;
                            } else {
                                $vv['open_status']	=	2;	//时间过期
                                $vv['open_status_txt']	=	'已过期，请联系物业';
                            }
                            $open_list_info[$vv['village_id']]['door_list'][$key] = $vv;
                        } elseif (!$ban_open_status && $aDoorFind['status'] == 0 && ($village_floor_id==0 || $vv['floor_id'] == $village_floor_id || in_array($village_floor_id, $floor_arr))) {
                            $vv['open_status']	=	0;		//禁止使用
                            $vv['open_status_txt']	=	'您没有权限开门，请联系物业';		//禁止使用
                            $open_list_info[$vv['village_id']]['door_list'][$key] = $vv;
                        } elseif ($ban_open_status && ($village_floor_id==0 || $vv['floor_id'] == $village_floor_id)) {
                            $vv['open_status']	=	3;//欠物业费
                            $vv['open_status_txt']	=	'您的权限已到期，请联系物业管理人员';
                            $open_list_info[$vv['village_id']]['door_list'][$key] = $vv;
                        } elseif ($ban_open_status && $vv['floor_id'] == -1) {
                            $vv['open_status']	=	3;//欠物业费
                            $vv['open_status_txt']	=	'您的权限已到期，请联系物业管理人员';
                            $open_list_info[$vv['village_id']]['door_list'][$key] = $vv;
                        }
                    }
                    if (empty($open_list_info[$v['village_id']]['door_list']) && $open_list_info[$v['village_id']]['have_village_door']) {
                        $open_list_info[$v['village_id']]['have_floor_door'] = false;
                        $open_list_info[$v['village_id']]['tip_info'] = '您入住的单元暂未添加门禁';
                    } else {
                        $open_list_info[$v['village_id']]['have_floor_door'] = true;
                    }
                }
            }
        }

        // 处理返回可选择时间
        $time_list = $this->time_list($temporary_visitor_time_limit);

        $village_floor_list = [
            'list' => $aDoor,
            'visitor_open_img' => $visitor_open_img,
            'info' => $info,
            'temporary_visitor_time_limit' => $temporary_visitor_time_limit,
            'temporary_visitor_switch'=>$temporary_visitor_switch,
            'time_list' => $time_list
        ];

        $this->returnCode(0, $village_floor_list);
    }



    // 社区添加门禁分享信息
    public function house_village_door_share_add()
    {
        if(empty($this->_uid)){
            $this->returnCode('10044010');
        }
        $uid = $this->_uid;
        if(empty($uid)){
            $this->returnCode('10044010');
        }

        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        // 获取小区信息
        $village_info = M('House_village')->where(array('village_id' => $village_id))->field('temporary_visitor_time, village_name')->find();
        $village_name = $village_info['village_name'];
        $now_village_bind = D('House_village_user_bind')->get_one_by_bindId($pigcms_id);
        $address = $now_village_bind['address'];
        if ($address) {
            if(strpos($address,$village_name) !== false){
                $address_info = $address;
            } else {
                $address_info = $village_name . $address;
            }
        } else {
            $address_info = $village_name;
        }

        // 获取单元信息

        // 选中单元信息处理
        $data = array();
        $data['share_info'] = serialize($_POST['share_info']);
        $data['share_address'] = $address_info;
        $data['village_id'] = $village_id;
        $data['share_uid'] = $uid;
        $data['open_uid'] = 0;
        $now_time = time();
        $data['share_time'] = $now_time;
        // 有时间类型的取时间类型，没有默认为0 即分钟 分享时间计时方式（0: 分钟，1:小时，2:天）
        $share_time_type = !empty($_POST['share_time_type']) ? intval($_POST['share_time_type']) : 0;
        $data['share_time_type'] = $share_time_type;
        $share_time_length = !empty($_POST['share_time_length']) ? $_POST['share_time_length'] : 0;
        if ($share_time_length <= 0) {
            $this->returnCodeError('分享时间不能为零');
        }
        $data['share_time_length'] = $share_time_length;
        // 计算截止时间 是否上传正确

        $temporary_visitor_time_limit = 168; // 默认168小时  即7天
        if ($this->config['house_village_temporary_visitor_time'] > 0) {
            $temporary_visitor_time_limit = floatval($this->config['house_village_temporary_visitor_time']);
        }
        if ($village_info['temporary_visitor_time'] > 0) {
            if ($this->config['house_village_temporary_visitor_time'] > 0 && $village_info['temporary_visitor_time'] < $this->config['house_village_temporary_visitor_time']) {
                $temporary_visitor_time_limit = floatval($village_info['temporary_visitor_time']);
            }
        }
        // 判断时间是否传值正确
//        if (empty($_POST['share_end_time'])) {
//            $this->error_tips('请上传分享有效时间');
//        } elseif ($temporary_visitor_time_limit == -1) {
//            $data['share_end_time'] = strtotime($_POST['share_end_time']);
//        } else {
//            $share_end_time = strtotime($_POST['share_end_time']);
//            $diff_time = intval($share_end_time) - intval($now_time);
//            if ($diff_time > ($temporary_visitor_time_limit*3600)) {
//                $share_end_time = date('Y-m-d H:i', intval($now_time)+(intval($temporary_visitor_time_limit)*3600));
//                $this->error_tips('分享时间不得超过'.$share_end_time);
//            } else {
//                $data['share_end_time'] = strtotime($_POST['share_end_time']);
//                $data['share_time_length'] = intval($diff_time)/3600;
//                $data['share_time_type'] = 1;
//            }
//        }
        if (!empty($share_time_type)) {
            if (0 == $share_time_type) {
                if ($temporary_visitor_time_limit > 0 && $share_time_length > $temporary_visitor_time_limit) {
                    $this->returnCodeError('分享时间不得超过'.($temporary_visitor_time_limit * 60).'分钟');
                }
                $data['share_end_time'] = strtotime("+" . $share_time_length . " minute");
            } elseif (1 == $share_time_type) {
                if ($temporary_visitor_time_limit > 0 && $share_time_length > $temporary_visitor_time_limit) {
                    $this->returnCodeError('分享时间不得超过'.$temporary_visitor_time_limit.'小时');
                }
                $data['share_end_time'] = strtotime("+" . $share_time_length . " hour");
            } elseif (2 == $share_time_type) {
                if ($temporary_visitor_time_limit > 0 && $share_time_length > $temporary_visitor_time_limit) {
                    $this->returnCodeError('分享时间不得超过'.($temporary_visitor_time_limit/24).'天');
                }
                $data['share_end_time'] = strtotime("+" . $share_time_length . " day");
            } else {
                if ($temporary_visitor_time_limit > 0 && $share_time_length > $temporary_visitor_time_limit) {
                    $this->returnCodeError('分享时间不得超过'.($temporary_visitor_time_limit * 60).'分钟');
                }
                $data['share_end_time'] = strtotime("+" . $share_time_length . " minute");
            }
        } else {
            if ($temporary_visitor_time_limit > 0 && $share_time_length > $temporary_visitor_time_limit) {
                $this->returnCodeError('分享时间不得超过'.($temporary_visitor_time_limit * 60).'分钟');
            }
            $data['share_end_time'] = strtotime("+" . $share_time_length . " minute");
        }
        $data['share_use'] = 0;
        $data['share_status'] = 0;
        $addInfo = M('House_village_door_share')->add($data);
        if (!$addInfo) {
            $this->returnCodeError('分享失败');
        } else {
            $base_url = D('House_village')->base_url;
            $my_times = '' . $data['share_time_length'];
            if (0==$data['share_time_type']) {
                $my_times .= '分钟';
            } elseif (1==$data['share_time_type']) {
                $my_times .= '小时';
            } elseif (2==$data['share_time_type']) {
                $my_times .= '天';
            }
            // 处理返回分享信息
            if ($this->config['wechat_share_img']) {
                $imgUrl = replace_file_domain($this->config['wechat_share_img']);
            } else {
                $imgUrl = replace_file_domain($this->config['site_logo']);
            }
            // 微信路径后期换成二维码页面
            $db_house_village = D('House_village');
            $app_version = intval($_POST['app_version']);
            $deviceId = trim($_POST['Device-Id']);
            $param = [
                'pageName' => 'QRcode',
                'isAll' => true,
                'urlParam' => 'door_share_id=' . $addInfo,
            ];
            $QRcodeUrl = $db_house_village->villagePagePath($app_version,$deviceId,$param);
            $share_weixin_info = array(
                'imgUrl' => $imgUrl,
                'sendFriendLink' => $QRcodeUrl,
                'tTitle' => '智能访客开门',
                'tContent' => '我赠送一个'.$my_times.'的临时开门权限。来自【'.$data['share_address'].$this->config['house_name'].'】',
                'img' => $this->config['site_url'] . '/static/wxapp/visitor_open.png',
            );
            // 小程序
            $wxapp_type = isset($_POST['wxapp_type']) ? trim($_POST['wxapp_type']) : '';
            $app_type = isset($_POST['app_type']) ? trim($_POST['app_type']) : '';
            if ('village'==$this->config['system_type'] || ($wxapp_type == 'village' && $app_type == 'wxapp')) {
                $sendFriendLink = '/pages/village_menu/index?redirect=share_freiend_opendoor&door_share_id='.$addInfo.'&village_id='.$village_id;
            } else {
                $sendFriendLink = '/pages/plat_menu/index?redirect=share_freiend_opendoor&door_share_id='.$addInfo.'&village_id='.$village_id;
            }
            $share_wxapp_info = array(
                'imgUrl' => $imgUrl,
                'sendFriendLink' => $sendFriendLink,
                'tTitle' => '智能访客开门',
                'tContent' => '我赠送一个'.$my_times.'的临时开门权限。来自【'.$data['share_address'].$this->config['house_name'].'】',
                'img' => $this->config['site_url'] . '/static/wxapp/visitor_open.png',
            );
            $return = array();
            $return['door_share_id'] = $addInfo;
            $return['share_address'] = $address_info;
            $return['share_weixin_info'] = $share_weixin_info;
            $return['share_wxapp_info'] = $share_wxapp_info;

            $return['share_wx'] = $this->config['pay_wxapp_important'] && $this->config['pay_wxapp_username'] ? 'wxapp' : 'h5';
            $return['userName'] = $this->config['pay_wxapp_username'];

            $this->returnCode(0, $return);
        }
    }

    public function house_village_door_share_info() {
        $door_share_id	= I('door_share_id');
        if(empty($door_share_id)){
            $this->returnCode('60000003');
        }
        $where = array();
        $where['share_status'] = 0;
        $where['door_share_id'] = $door_share_id;
        $list = M('House_village_door_share')->where($where)->find();
        if (!empty($list) && $list['share_info']) {
            $share_info = $list['share_info'] = unserialize($list['share_info']);
            if (!empty($share_info)) {
                foreach ($share_info as $key =>$val) {
                    $condition_door['door_status'] = 1;
                    $condition_door['door_id'] = $val;
                    $aDoorList	=	M('House_village_door')->group('door_id')->field(true)->where($condition_door)->select();
                    $floor_id = reset($aDoorList)['floor_id'];
                    $data = $list['share_info'][$key] =	M('House_village_floor')->field(array('floor_name','floor_layer', 'floor_id'))->where(array('floor_id'=>$floor_id))->find();
                    if (!empty($aDoorList)) {
                        $aDoorList = reset($aDoorList);
                        $list['share_info'][$key]['floor_id'] = $aDoorList['floor_id'];
                        $list['share_info'][$key]['door_psword'] = $aDoorList['door_psword'];
                        $list['share_info'][$key]['door_id'] = $aDoorList['door_id'];
                        $list['share_info'][$key]['door_device_id'] = $aDoorList['door_device_id'];
                        $list['share_info'][$key]['door_name'] = $aDoorList['door_name'];
                    }
                    if(empty($data) && $aDoorList['floor_id'] == '-1') {
                        $list['share_info'][$key]['floor_name'] = $this->config['house_name'] ? $this->config['house_name'] : L_('小区');
                        $list['share_info'][$key]['floor_layer'] = L_('大门');
                    }
                }
                $list['share_info'] = $this->wxapp_door($list['share_info']);
            }
            // 获取小区信息
            $list['village_name'] = M('House_village')->where(array('village_id' => $list['village_id']))->getField('village_name');
            // 返回二维码链接
            $see_qrcode_img = $this->config['site_url'] . '/index.php?g=Index&c=Recognition_wxapp&a=see_qrcode&type=doorshare&img=1&id='.$door_share_id;
            $list['see_qrcode_img'] = $see_qrcode_img;

            $my_times = '' . $list['share_time_length'];
            if (0==$list['share_time_type']) {
                $my_times .= '分钟';
            } elseif (1==$list['share_time_type']) {
                $my_times .= '小时';
            } elseif (2==$list['share_time_type']) {
                $my_times .= '天';
            }
            $list['share_title'] = '我赠送一个'.$my_times.'的临时开门权限。来自【'.$list['share_address'].$this->config['house_name'].'】';

            $this->returnCode(0,$list);
        } else {
            $this->returnCode(0,array());
        }
    }

    // 获取门禁密码
    private function wxapp_door($aDoor){
        foreach ($aDoor as &$item) {
            if($this->DEVICE_ID=='wxapp'){
                if(strlen($item['door_device_id']) == 17 && substr($item['door_device_id'],-5) == 'BLOCK'){
                    $pwdArr = str_split($item['door_psword']);
                    $new16Pwd = '';
                    foreach($pwdArr as $pwdValue){
                        $new16Pwd .= '0'.$pwdValue;
                    }
                    $lockDate = 'EEA2'.substr($item['door_device_id'],0,12).$new16Pwd.date('ymd').'ED';
                    $item['lockData'] = $lockDate;
                }else{
                    $lockDate = S($item['door_psword'].$item['door_device_id']);
                    if(empty($lockDate)) {
                        $return_msg = file_get_contents("http://o2o-service-qcloud.pigcms.com:8080/dhpkgcomm/app/wxlockData?DEVICEPSW={$item['door_psword']}&DEVICE_ID={$item['door_device_id']}");
                        $return_msg = json_decode($return_msg,true);
                        $item['lockData'] = $return_msg['lockData'];
                        S($item['door_psword'].$item['door_device_id'],$item['lockData'],86400);
                    }else{
                        $item['lockData'] = $lockDate;
                    }
                }
            }
        }
        return $aDoor;
    }

    // 处理分享信息
    public function door_share_info() {
        $share_info = array();
        $share_info['is_owner'] = false;
        if($this->_uid){
            $uid = $this->_uid;
            // 绑定分享id
            $door_share_id = I('door_share_id', 0, 'intval');
            $share_uid = M('House_village_door_share')->where(array('door_share_id'=>$door_share_id))->getField('share_uid');
            if ($share_uid == $uid) {
                $share_info['is_owner'] = true;
            } elseif ($door_share_id > 0) {
                $this->bind_share_user($uid, $door_share_id);
            }
            // 获取绑定的信息
            $bind_share_msg = D('House_village_bind_share')->bind_share_msg($uid);

            if ($bind_share_msg){
                $share_info['share_count'] = count($bind_share_msg);
                $share_info['bind_share_msg'] = $bind_share_msg;
                $now_time = time();
                $is_over = true; // 如果均过期返回true， 如果存在未过期，则返回false
                foreach ($bind_share_msg as &$val) {
                    if ($now_time < $val['share_end_time']) {
                        $is_over = false;
                    }
                }
                $share_info['is_over'] = $is_over;
            }
        } else {
            $this->returnCode('20090009');
        }
        $this->returnCode(0, $share_info);
    }

    // 绑定 分享门禁与用户
    private function bind_share_user($uid, $door_share_id) {
        $door_share = M('House_village_bind_share')->where(array('door_share_id'=>$door_share_id))->find();
        if ($door_share && $door_share['uid'] != $uid) {
            $this->returnCodeError('该链接已被其他人使用，请联系业主重新生成。');
        } elseif (!$door_share) {
            M('House_village_bind_share')->data(array('uid' => $uid, 'door_share_id'=>$door_share_id, 'add_time' => time()))->add();
        }
    }


    // 人脸门禁
    // 获取绑定信息
    public function face_img_info() {
//	    if (!$this->is_weixin_browser && !$this->is_app_browser) {
//            $this->returnCodeError('请在微信或APP中使用本功能！');
//        }
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $add_pigcms_id = $_POST['add_pigcms_id'];
        $now_village_bind= D('House_village_user_bind')->get_one_by_bindId($pigcms_id);
        $d_house_village_user_bind = M('House_village_user_bind');
        $d_house_face_img = M('House_face_img');

        $userTimes =  D('House_village_user_bind')->getUserEndTime($now_village_bind['pigcms_id']);
        $dayTimes = strtotime(date('y-m-d', time()));
        if (isset($userTimes['propertyEndTime'])&&$userTimes['propertyEndTime']&&$userTimes['propertyEndTime']<$dayTimes) {
            $this->returnCodeError('您的权限已到期，请联系物业管理人员！');
        }

//        $now_village_bind = $d_house_village_user_bind->where(array('pigcms_id' => $now_village_bind['pigcms_id']))->find();

        if (4==$now_village_bind['type']) {
            // 获取工作人员信息
            $m_house_worker = M('House_worker');
            if (empty($now_village_bind['uid'])) {
                $this->returnCodeError('请先绑定为平台用户！');
            }
            $now_user = D('User')->get_user($now_village_bind['uid']);
            $worker_info = $m_house_worker->where(array('phone'=>$now_user['phone'],'status'=>1, 'village_id' => $now_village_bind['village_id']))->field('village_id,wid,phone,status,open_door')->find();
            if ($worker_info['open_door'] != 1) {
                $this->returnCodeError('您是物业工作人员，没有权限绑定人脸识别开门！');
            }
        }


        $m_house_face_device = M('House_face_device');
//        $condition_face_device['village_id'] = $village_id;
//        $aDoor_count = $m_house_face_device->field(true)->where($condition_face_device)->count();
//
//        $m_house_camera_device = M('House_camera_device');
//        $condition_camera['village_id'] = $village_id;
//        $camera_count = $m_house_camera_device->field(true)->where($condition_camera)->count();
//
//        if ((!$aDoor_count || $aDoor_count<=0) && (!$camera_count || $camera_count<=0)) {
//            $this->returnCodeError('当前小区没有人脸门禁或者摄像机设备！');
//        }
        if ($add_pigcms_id>0) {
            $where = array(
                'pigcms_id' => $add_pigcms_id,
            );
            $village_info = $d_house_village_user_bind->where($where)->find();
            if (!empty($village_info)) {
                if ($village_id != $village_info['village_id']) {
                    $this->returnCodeError('所选操作对象错误！');
                }
                if ($village_info['pigcms_id'] != $now_village_bind['pigcms_id'] && $village_info['parent_id'] != $now_village_bind['pigcms_id']) {
                    $this->returnCodeError('所选操作对象错误！');
                }
//                if (in_array($village_info['type'], array(4))) {
//                    $this->returnCodeError('所选操作对象错误！');
//                }
                $now_village_bind = $village_info;
            }
        } elseif (0==$now_village_bind['type'] || 3==$now_village_bind['type']) {
            // 新页面出来强制跳转过去
            $db_house_village = D('House_village');
            $app_version = intval($_POST['app_version']);
            $deviceId = trim($_POST['Device-Id']);
            $param = [
                'pageName' => 'selectBindFace',
                'isAll' => true,
                'urlParam' => '',
            ];
            $selectBindFaceUrl = $db_house_village->villagePagePath($app_version,$deviceId,$param);
            $rdirect_info = array(
                'url' => $selectBindFaceUrl,
                'is_rdirect' => true
            );
            // 1标识 前端开启人脸识别  2标识 关闭用户端人脸
            $rdirect_info['my_face_door_switch'] = $this->config['my_face_door_switch'] ? 2 : 1;
            $this->returnCode(0, $rdirect_info);
        }
        $now_village_bind['is_rdirect'] = false;
        // 查询正常和加密的人脸图片
        if ($now_village_bind['uid']) {
            $now_village_bind['face_num'] = $d_house_face_img->where(array('uid' => $now_village_bind['uid'], 'status'=>['in', [0,3]], 'img_url' => array('neq', '')))->order('id asc')->limit(3)->count();
        } else {
            $now_village_bind['face_num'] = 0;
        }
        if ($now_village_bind['face_num'] > 0) {
            $now_village_bind['is_bind_face'] = true;
        } else {
            $now_village_bind['is_bind_face'] = false;
        }
        if (!empty($add_pigcms_id)) {
            $where = array(
                'pigcms_id' => $add_pigcms_id,
            );
            $village_info = $d_house_village_user_bind->where($where)->find();
            $uid = $village_info['uid'];
            $add_face_time = $village_info['add_face_time'];
        } else {
            $uid = $now_village_bind['uid'];
            $add_face_time = $now_village_bind['add_face_time'];
        }
        if ($uid>0) {
            $face_img_list = $d_house_face_img->where(array('uid' => $uid, 'status'=>['in', [0,3]], 'img_url' => array('neq', '')))->order('id asc')->limit(5)->select();
        } else {
            $face_img_list = [];
        }
        if($face_img_list){
            import('@.ORG.face.word_encryption');
            $word_encryption = new word_encryption();
            foreach($face_img_list as $kk=>&$vv){
                if (3==$vv['status']) {
                    // 加密的图片解密
                    $vv['img_url'] = $word_encryption->text_decrypt($vv['img_url']);
                }
                $vv['face_img_url'] = thumb_img($vv['img_url'], 200, 200, 'fill');
            }
        }else{
            $face_img_list = [];
        }

        //查询图片上传配置
        $face_img_set=D('House_village_info')->where(array('village_id'=>$village_id))->field('face_door_set')->find();
        if (!empty($face_img_set)){
            $now_village_bind['face_img_set']=$face_img_set['face_door_set'];
        }
        $now_village_bind['face_img'] =$face_img_list;
        if ($now_village_bind['add_face_time'] && 0==$now_village_bind['face_img_status'] && time() > ($add_face_time + 60*10)) {
            $now_village_bind['is_new_face'] = true;
        } else {
            $now_village_bind['is_new_face'] = false;
        }
        // 1标识 前端开启人脸识别  2标识 关闭用户端人脸
        $now_village_bind['my_face_door_switch'] = $this->config['my_face_door_switch'] ? 2 : 1;
        
        $this->returnCode(0, $now_village_bind);
    }
    /*     * *图片上传** */
    public function ajax_face_img(){
        fdump_api(['图片上传'.__LINE__,$_FILES,$_POST],'ajax_face_img');
        $errors = [
            UPLOAD_ERR_INI_SIZE => '上传的文件超过了 php.ini 中 upload_max_filesize 选项限制的值',
            UPLOAD_ERR_FORM_SIZE => '上传文件的大小超过了 HTML 表单中 MAX_FILE_SIZE 选项指定的值',
            UPLOAD_ERR_PARTIAL => '文件只有部分被上传',
            UPLOAD_ERR_NO_FILE => '没有文件被上传',
            UPLOAD_ERR_NO_TMP_DIR => '找不到临时文件夹',
            UPLOAD_ERR_CANT_WRITE => '文件写入失败'
        ];
        if ($_FILES['imgFile']['error'] === UPLOAD_ERR_OK) {
            set_time_limit(0);
            $image = D('Image')->handle(0, 'facehouse', 2, array('size' => 10,'imgsize'=>$_FILES['imgFile']['size']), false);
            fdump_api(['图片上传'.__LINE__,$image],'ajax_face_img',1);
            if ($image['error']) {
                $this->returnCode(1001, [], $image['message']);
            } else {
                try {
                    $imgtype = $_FILES['imgFile']['type'] ? strtolower($_FILES['imgFile']['type']) : '';
                    if ($_FILES['imgFile']['size'] > 4100000 && $imgtype && (strpos($imgtype, 'jpeg') || strpos($imgtype, 'jpg'))) {
                        $img_url = $image['url']['imgFile'];
                    } else {
                        $img_url = D('Image')->transform_image($image['url']['imgFile']);
                        if (strstr($img_url, '_newChange') !== false) {
                            unlink('.' . $image['url']['imgFile']);
                        }
                        if (!isset($img_url) || !$img_url) {
                            $img_url = $image['url']['imgFile'];
                        }
                    }
                }catch (\Exception $e){
                    $img_url=$image['url']['imgFile'];
                }
                $imageUrl = replace_file_domain($img_url);
                $img_tmp_path = $_SERVER['DOCUMENT_ROOT'].$image['url']['imgFile'];
                $img_tmp_path=str_replace('//','/',$img_tmp_path);
                $file_handle = new file_handle();
                if ($file_handle->check_open_oss() && file_exists($img_tmp_path)) {
                    unlink($img_tmp_path);
                }
//                $whereDevice = ['device_type' => ['not in', [5,6]],'is_del' => 0];
//                $faceDeviceCount = M('House_face_device')->where($whereDevice)->count();
//                if ($faceDeviceCount<=0) {
//                    $info = D('Face_door_a5_service')->faceAnalysisScore($imageUrl);
//                    if (!$info['checkImg'] && $info['checkImgErr']) {
//                        // 报错
//                        $this->returnCode(1001, [], $info['checkImgErr']);
//                    }
//                }
                $urlThumb=thumb_img($imageUrl, 200, 200, 'fill');
                fdump_api([__LINE__,'urlThumb'=>$urlThumb,'img_url'=>$img_url,'imageUrl'=>$imageUrl],'ajax_face_img_return',1);
                $this->returnCode(0, ['url' => $urlThumb,'imageUrl_path'=>$img_url, 'imageUrl'=>$imageUrl ]);
            }
        } else {
            $this->returnCode(1001, [], isset($errors[$_FILES['imgFile']['error']]) ? $errors[$_FILES['imgFile']['error']] : '上传失败');
        }
    }
	
	
    // 绑定人脸信息
    public function face_img_add() {
//	    if (!$this->is_weixin_browser && !$this->is_app_browser) {
//            $this->returnCodeError('请在微信或APP中使用本功能！');
//        }
        $pigcms_id = I('pigcms_id', '');//绑定用户id
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $now_village_bind= D('House_village_user_bind')->get_one_by_bindId($pigcms_id);
        $d_house_village_user_bind = M('House_village_user_bind');

        $userTimes =  D('House_village_user_bind')->getUserEndTime($now_village_bind['pigcms_id']);
        $dayTimes = strtotime(date('y-m-d', time()));
        if (isset($userTimes['propertyEndTime'])&&$userTimes['propertyEndTime']&&$userTimes['propertyEndTime']<$dayTimes) {
            $this->returnCodeError('您的权限已到期，请联系物业管理人员！');
        }

        $now_village_bind = $d_house_village_user_bind->where(array('pigcms_id' => $now_village_bind['pigcms_id']))->find();

        if (4==$now_village_bind['type']) {
            // 获取工作人员信息
            $m_house_worker = M('House_worker');
            if (empty($now_village_bind['uid'])) {
                $this->returnCodeError('请先绑定为平台用户！');
            }
            $now_user = D('User')->get_user($now_village_bind['uid']);
            $worker_info = $m_house_worker->where(array('phone'=>$now_user['phone'],'status'=>1, 'village_id' => $now_village_bind['village_id']))->field('village_id,wid,phone,status,open_door')->find();
            if ($worker_info['open_door'] != 1) {
                $this->returnCodeError('您是物业工作人员，没有权限绑定人脸识别开门！');
            }
        }

        $m_house_face_device = M('House_face_device');
        $condition_face_device['village_id'] = $village_id;
        $aDoor_count = $m_house_face_device->field(true)->where($condition_face_device)->count();

        $m_house_camera_device = M('House_camera_device');
        $condition_camera =[];
        $condition_camera['village_id'] = $village_id;
        $condition_camera['camera_status'] = 0;
        $camera_count = $m_house_camera_device->field(true)->where($condition_camera)->count();

//        if ((!$aDoor_count || $aDoor_count<=0) && (!$camera_count || $camera_count<=0)) {
//            $this->returnCodeError('当前小区没有人脸门禁或者摄像机设备！');
//        }

        if($_POST){
            $add_pigcms_id = $_POST['add_pigcms_id'];
            if ((!$add_pigcms_id || $add_pigcms_id<=0) && 0==$now_village_bind['type'] && 3==$now_village_bind['type']) {
                $this->returnCodeError('缺少绑定对象！');
            } elseif (!$add_pigcms_id || $add_pigcms_id<=0) {
                $add_pigcms_id = $now_village_bind['pigcms_id'];
            }
            $face_img = $_POST['face_img'];
            if ($face_img && is_string($face_img)) {
                $face_img = explode(';',$face_img);
            }
            /*if (empty($face_img)) {
                $this->returnCodeError('请上传人脸识别图片！');
            }
            if (count($face_img)<1) {
                $this->returnCodeError('请最少上传1张图片！');
            }*/

            $where = array(
                'pigcms_id' => $add_pigcms_id,
            );
            $village_info = $d_house_village_user_bind->where($where)->find();
            if (empty($village_info['uid'])) {
                // 如果绑定这没有注册用户自动帮其注册
                if(empty($village_info['phone']) && $village_info['name']){
                    $data_user = array(
                        'nickname' 	=> $village_info['name'],
                        'source' 	=> 'houseautoreg',
                    );
                    $reg_result = D('User')->autoreg($data_user);
                    $village_info['uid'] = $reg_result['uid'];
                }elseif ($village_info['phone']){
                    $village_info['phone'] = trim($village_info['phone']);

                    $where['phone'] = $village_info['phone'];
                    $where['status'] = array('in','0,1');
                    $res = D('User')->where($where)->field('uid')->find();
                    if(empty($res['uid'])){
                        $data_user = array(
                            'nickname' 	=> $village_info['name'],
                            'phone' 	=> $village_info['phone'],
                            'source' 	=> 'houseautoreg',
                        );
                        $reg_result = D('User')->autoreg($data_user);
                        if($reg_result['error_code']){
                            $this->returnCodeError($reg_result['error_code']);
                        }
                        $village_info['uid'] = $reg_result['uid'];
                    }else{
                        $village_info['uid'] = $res['uid'];
                    }
                }
                if ($village_info['uid']) {
                    D('house_village_user_bind')->where(['pigcms_id'=>$add_pigcms_id])->save(['uid'=>$village_info['uid']]);
                } else {
                    $this->returnCodeError('请先绑定为平台用户！');
                }
            }
            $d_house_face_img = M('House_face_img');
            $save = array(
                'status' => 1,
                'del_time' => time()
            );
            if(empty($face_img)){
                // 删除现有图片 添加新图片
                $d_house_face_img->where(array('uid' => $village_info['uid'],'status' => ['in', [0,3]]))->data($save)->save();
                $this->returnCodeError('保存成功！');
                $this->returnCode(0, $now_village_bind,'保存成功');
            }
            $data = array();
            $img = array();
            $img['uid'] = $village_info['uid'];
            $img['add_time'] = time();
            $img['status'] = 3;
            $img['bind_pigcms_id'] = $village_info['pigcms_id'];
            import('@.ORG.face.word_encryption');
            $word_encryption = new word_encryption();
            foreach ($face_img as $val) {
                if ($val) {
                    $val = str_replace('?x-oss-process=image/resize,m_fill,w_200,h_200', '', $val);
                    // 图片加密
                    $val =  $word_encryption->text_encryption($val);
                    $img['img_url'] = $val;
                    $data[] = $img;
                }
            }
            if (empty($data)) {
                $this->returnCodeError('请上传人脸识别图片！');
            }
            // 删除现有图片 添加新图片
            $d_house_face_img->where(array('uid' => $village_info['uid'],'status' => ['in', [0,3]]))->data($save)->save();
            $tip = $d_house_face_img->addAll($data);
            if($tip){
                if ($village_info['uid']) {
                    $hik_info_vision_i_community_app_key=C('config.hik_info_vision_i_community_app_key');
                    $hik_info_vision_i_community_app_secret=C('config.hik_info_vision_i_community_app_secret');
                    if($hik_info_vision_i_community_app_key && $hik_info_vision_i_community_app_secret){
                        $hikRet=invoke_v20_service('\app\community\model\service\Device\HikInfoVisionICommunityService/sycBindUserToHikCommunity', ['village_id'=>$village_info['village_id'],'pigcms_id'=>$village_info['pigcms_id']]);
                    }
                    // 计划任务
                    if ($aDoor_count>0) {
                        $otherParam = [
                            'log_name' => 'userToDevicePlan',
                            'logType' => 'user',
                            'operator_type' => 'userBind',
                            'operator_id' => $pigcms_id,
                            'log_operator' => $now_village_bind['name']?$now_village_bind['name']:'住户_'.$pigcms_id,
                            'log_phone' => $now_village_bind['phone']?$now_village_bind['phone']:'',
                        ];
//                    D('House_village_face_door')->create_village_plan($village_info['village_id'],'house_user_face_device_info', $village_info['uid']);
                        D('House_face_img')->house_user_face_device_info($village_info['uid'],$add_pigcms_id,false,$otherParam);
                    }
                    // 上传百度AI 人脸库
                    if ($camera_count>0) {
                        // 直接调用
//                    D('House_face_img')->baidu_face_edit($village_info['village_id'], $village_info['uid']);
                        // 计划任务
                        D('House_face_img')->create_baidu_ai_face_plan($village_info['village_id'], 'baidu_face_edit', $village_info['uid']);
                    }
                }
                $d_house_village_user_bind->where($where)->setField('add_face_time', time());
                $this->returnCode(0, $now_village_bind);
            }else{
                $this->returnCodeError('绑定失败！');
            }
        } else {
            $this->returnCodeError('请提交数据！');
        }
    }

    //
    public function house_face_select() {
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $now_village_bind= D('House_village_user_bind')->get_one_by_bindId($pigcms_id);
        if ($now_village_bind['type']!=0 && $now_village_bind['type']!=3) {
            $data = [
                'village_info' => [],
                'now_village_bind' => $now_village_bind,
            ];
	        $data['use_new_page'] = $this->config['faceImgUseNewPage'] == 1 ? 1 : 0; //有这个值表示后端代码已更新，前端页面根据这个参数判断是否是用新版的人脸上传页面
	        $this->returnCode(0, $data);
        }
        $d_house_village_user_bind = M('House_village_user_bind');
        $d_house_face_img = M('House_face_img');
        $where = array(
            'village_id' => $village_id,
            'parent_id' => $now_village_bind['pigcms_id'],
            'type' => array('NOT IN', array(0,3,4)),
            'status' => ['not in', [3,4]],
        );
        $village_info = $d_house_village_user_bind->where($where)->select();
        if ($village_info) {
            foreach ($village_info as &$item) {
                if ($item['uid']>0) {
                    $item['face_num'] = $d_house_face_img->where(array('uid' => $item['uid'], 'status'=>['in', [0,3]], 'img_url' => array('neq', '')))->count();
                } else {
                    $item['face_num'] = 0;
                }
                if ($item['face_num'] > 0) {
                    $item['is_bind_face'] = true;
                } else {
                    $item['is_bind_face'] = false;
                }
            }
        }
        if ($now_village_bind['uid']>0) {
            $now_village_bind['face_num'] = $d_house_face_img->where(array('uid' => $now_village_bind['uid'], 'status'=>['in', [0,3]], 'img_url' => array('neq', '')))->count();
        } else {
            $now_village_bind['face_num'] = 0;
        }
        if ($now_village_bind['face_num'] > 0) {
            $now_village_bind['is_bind_face'] = true;
        } else {
            $now_village_bind['is_bind_face'] = false;
        }
        $data = array(
            'village_info' => $village_info,
            'now_village_bind' => $now_village_bind,
        );
	    $data['use_new_page'] = 0; //有这个值表示后端代码已更新，前端页面根据这个参数判断是否是用新版的人脸上传页面
        $this->returnCode(0, $data);
    }

    /*重新同步数据到设备*/
    public function new_bind_face() {
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $add_pigcms_id = I('add_pigcms_id', '');// 操作对象
        if (empty($add_pigcms_id)) {
            $this->returnCodeError('请上传操作对象！');
        }
        $now_village_bind= D('House_village_user_bind')->get_one_by_bindId($pigcms_id);
        $d_house_village_user_bind = M('House_village_user_bind');
        $where = array(
            'pigcms_id' => $add_pigcms_id,
        );
        $village_info = $d_house_village_user_bind->where($where)->find();
        if (empty($village_info['uid'])) {
            $this->returnCodeError('请先绑定为平台用户！');
        }
        if ($now_village_bind['type']!=0 && $now_village_bind['type']!=3 && $now_village_bind['pigcms_id']!=$pigcms_id) {
            $this->returnCodeError('操作对象有误！');
        }
        $otherParam = [
            'log_name' => 'userToDevicePlan',
            'logType' => 'user',
            'operator_type' => 'userBind',
            'operator_id' => $pigcms_id,
            'log_operator' => $now_village_bind['name']?$now_village_bind['name']:'住户_'.$pigcms_id,
            'log_phone' => $now_village_bind['phone']?$now_village_bind['phone']:'',
        ];
//                    D('House_village_face_door')->create_village_plan($village_info['village_id'],'house_user_face_device_info', $village_info['uid']);
        $info = D('House_face_img')->house_user_face_device_info($village_info['uid'],$add_pigcms_id,false,$otherParam);
        if($info && (!isset($info['err_msg']) || !$info['err_msg'])){
            $d_house_village_user_bind->where($where)->setField('add_face_time', time());
            $this->returnCode(0,'操作成功！');
        } elseif (isset($info['err_msg']) && $info['err_msg']) {
            exit(json_encode(array('errorCode'=>1001,'errorMsg'=>$info['err_msg'])));
        } else {
            $this->returnCodeError('没有可同步设备！');
        }
    }


    /*设置通知*/
    public function notice_family() {
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $d_house_village_user_bind = M('House_village_user_bind');
        $d_house_village_face_notice = M('House_village_face_notice');
        // 即时查询新数据
        $now_village_bind = $d_house_village_user_bind->where(array('pigcms_id' => $pigcms_id))->find();

        $where = array();
        $where['village_id'] = $village_id;
        if (0==$now_village_bind['type'] || 3==$now_village_bind['type']) {
            $bind_id = $now_village_bind['pigcms_id'];
            $where['parent_id'] = $bind_id;
        } elseif (1==$now_village_bind['type'] && 1==$now_village_bind['relatives_type']) {
            $parent_info = $d_house_village_user_bind->where(array('pigcms_id'=> $now_village_bind['parent_id']))->find();
            $bind_id = $parent_info['pigcms_id'];
            $where['parent_id'] = $bind_id;
            $where['pigcms_id'] = array('neq', $now_village_bind['pigcms_id']);
        } else {
            $this->returnCodeError('当前您不能进行此操作！');
        }
        $where['type'] = ['not in', [0,3,4]];
        $where['status'] = ['not in', [3,4]];
        $info = $d_house_village_user_bind->where($where)->select();
        if ($info) {
            $is_all_notice = 0; // 全部通知
            foreach ($info as &$val) {
                $notice = $d_house_village_face_notice->where(array('notice_id' => $bind_id,'bind_id' => $val['pigcms_id']))->find();
                if (!$notice) {
                    // 默认通知
                    $notice = array(
                        'notice_id' => $bind_id,
                        'is_notice' => 0
                    );
                } elseif ($notice && 1==$notice['is_notice']) {
                    $is_all_notice = 1;
                }
                $val['notice'] = $notice;
            }
            $now_village_bind['is_all_notice'] = $is_all_notice;
        }

        $arr = array(
            'info' => $info,
            'now_village_bind' => $now_village_bind,
        );
        $this->returnCode(0, $arr);
    }

    /*设置通知*/
    public function notice_set() {
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            $this->returnCode('20120004');
        }
        $d_house_village_user_bind = M('House_village_user_bind');
        $d_house_village_face_notice = M('House_village_face_notice');
        // 即时查询新数据
        $now_village_bind = $d_house_village_user_bind->where(array('pigcms_id' => $pigcms_id))->find();

        $where = array();
        $where['village_id'] = $village_id;
        $where['status'] = ['not in', [3,4]];
        if (0==$now_village_bind['type'] || 3==$now_village_bind['type']) {
            $bind_id = $now_village_bind['pigcms_id'];
            $where['parent_id'] = $bind_id;
        } elseif (1==$now_village_bind['type'] && 1==$now_village_bind['relatives_type']) {
            $parent_info = $d_house_village_user_bind->where(array('pigcms_id'=> $now_village_bind['parent_id']))->find();
            $bind_id = $parent_info['pigcms_id'];
            $where['parent_id'] = $bind_id;
            $where['pigcms_id'] = array('neq', $now_village_bind['pigcms_id']);
        } else {
            $this->returnCodeError('当前您不能进行此操作！');
        }
        if($_POST){
            if (empty($_POST['type'])) {
                $this->returnCodeError('参数错误！');
            }
            $set_data = array();
            if ('all'==trim($_POST['type'])) {
                if (1==intval($_POST['is_notice'])) {
                    $is_all_notice = 0;
                    $set_data['is_all_notice'] = true;
                } elseif (empty($_POST['is_notice'])) {
                    $is_all_notice = 1;
                    $set_data['is_all_notice'] = false;
                } else {
                    $is_all_notice = 0;
                    $set_data['is_all_notice'] = true;
                }
                if ($is_all_notice != $now_village_bind['is_all_notice']) {
                    $set = $d_house_village_user_bind->where(array('pigcms_id' => $now_village_bind['pigcms_id']))->setField('is_all_notice', $is_all_notice);
                } else {
                    $set = true;
                }
                $set_data['type'] = 'all';
            } else {
                $info = $d_house_village_user_bind->where($where)->field('pigcms_id')->select();
                $data['notice_id'] = $bind_id;
                $data['bind_id'] = intval($_POST['add_pigcms_id']);
                $key = $d_house_village_face_notice->where($data)->find();
                if (1==intval($_POST['is_notice'])) {
                    $is_notice = 0;
                } elseif (empty($_POST['is_notice'])) {
                    $is_notice = 1;
                } else {
                    $is_notice = 0;
                }
                if (!$key) {
                    $data['add_time'] = time();
                    $data['is_notice'] = $is_notice;
                    $set = $d_house_village_face_notice->data($data)->add();
                } else {
                    $data['last_time'] = time();
                    $data['id'] = $key['id'];
                    $data['is_notice'] = $is_notice;
                    $set = $d_house_village_face_notice->data($data)->save();
                }
                if ($set && 1==$is_notice && 0 == $now_village_bind['is_all_notice']) {
                    $d_house_village_user_bind->where(array('pigcms_id' => $now_village_bind['pigcms_id']))->setField('is_all_notice', 1);
                    $set_data['is_all_notice'] = false;
                } elseif ($info) {
                    // 查询绑定的通知人数 比对实际人数是否相等
                    $bind_notice = $d_house_village_face_notice->where(array('notice_id' => $bind_id, 'is_notice' => 0))->field('id')->select();
                    fdump($bind_notice,'$bind_notice');
                    fdump($info,'$info');
                    if (count($bind_notice)>0 && count($bind_notice)==count($info)) {
                        $set_data['is_all_notice'] = true;
                        if ($set && 0 != $now_village_bind['is_all_notice']) {
                            $d_house_village_user_bind->where(array('pigcms_id' => $now_village_bind['pigcms_id']))->setField('is_all_notice', 0);
                        }
                    } else {
                        $set_data['is_all_notice'] = false;
                    }
                }
                $set_data['type'] = 'single';
            }
            if (!$set) {
                $this->returnCodeError('操作失败！');
            }
            $this->returnCode(0, $set_data);
        } else {
            $this->returnCodeError('参数错误！');
        }
    }

    /*人脸识别门禁开门*/
    public function open_face_door() {
        if($this->_uid){
            $pigcms_id = I('pigcms_id', '');//房间号
            if (empty($pigcms_id)) {
                $this->returnCode('20120004');
            }
            $d_house_village_user_bind = M('House_village_user_bind');
            // 即时查询新数据
            $now_village_bind = $d_house_village_user_bind->where(array('pigcms_id' => $pigcms_id))->find();
            $is_owner = true;
            if ($now_village_bind['uid']!=$this->_uid) {
                $is_owner = false;
            }
            if ($now_village_bind['type'] == 1 || $now_village_bind['type'] == 2) {
                $info = $d_house_village_user_bind->where(array('pigcms_id' => $now_village_bind['parent_id']))->field('property_price, property_endtime')->find();
                $now_village_bind['property_endtime'] = $info['property_endtime'];
            }

            $device_id = I('device_id', '', 'trim');
            if (empty($device_id)) {
                $this->returnCodeError('缺少开门设备id');
            }
            $d_house_face_device = M('House_face_device');
            if (strpos($device_id, 'hik_channel_') !== false) {
                $hik_channel_id = str_replace('hik_channel_', '', $device_id);
                $whereChannel = array('channel_id' => $hik_channel_id);
                $channelInfo = M('House_device_channel')->where($whereChannel)->find();
                $device_face_info = $d_house_face_device->where(array('device_id' => $channelInfo['device_id']))->find();
                $device_id = isset($device_face_info['device_id']) ? intval($device_face_info['device_id']) : $device_id;
            } else {
                $device_face_info = $d_house_face_device->where(array('device_id' => $device_id))->find();

                if ($device_face_info['device_status']!=1) {
                    $this->returnCodeError('当前设备异常，请联系物业检查网络');
                }
            }

            $is_func_cloudmrsqfw_special=D('Config_customization')->getFuncCloudmrsqfwSpecial();
            if($is_func_cloudmrsqfw_special && $device_face_info['third_dev_source']=='lilin_pf' && !empty($device_face_info['third_dev_id'])){
                $models = '\app\community\model\service\Device\LiLinDevAccessApiService/remoteOpenOpt';
                $param = [
                    'deviceId' => $device_face_info['third_dev_id'],
                    'village_id'=>$device_face_info['village_id'],
                    'direction' => 1,
                    'openType' => 1,
                ];
                $remoteOpenRet = invoke_v20_service($models,$param);
                $retvalOpt = $remoteOpenRet['data']['retval'];
                if ($retvalOpt && isset($retvalOpt['err_code']) && $retvalOpt['err_code'] == 0) {
                    $this->returnCodeError('开门成功');
                } else {
                    $err_msg='开门失败';
                    if($retvalOpt && $retvalOpt['err_msg'] && $retvalOpt['err_msg']){
                        $err_msg=$retvalOpt['err_msg'];
                    }
                    $this->returnCodeError($err_msg);
                }
                $this->returnCodeError('开门失败！');
            }
            if (31 === intval($device_face_info['device_type'])) {
                $notify_time = isset($device_face_info['login_time']) && $device_face_info['login_time'] ? intval($device_face_info['login_time']) : 0;
                if (!$notify_time) {
                    $notify_time = isset($device_face_info['notify_time']) && $device_face_info['notify_time'] ? intval($device_face_info['notify_time']) : 0;
                }
                $nowTime = time();
                if ($nowTime - $notify_time > 300) {
                    $this->returnCodeError('当前设备异常，请联系物业检查网络');
                }
                // 西函门禁
                $db_house_face_device_cmd = M('House_face_device_cmd');
                // 去重下
                $whereCmd = [
                    'village_id' => $device_face_info['village_id'], 'device_id' => $device_id,
                    'cmd_name' => 'devDoor.openOnce', 'exec_status' => 0,
                ];
                $cmdInfo = $db_house_face_device_cmd->where($whereCmd)->find();
                if (empty($cmdInfo)) {
                    $cmdParams = [
                        'village_id' => $device_face_info['village_id'], 'cmd_name' => 'devDoor.openOnce', 'add_time' => $nowTime,
                        'exec_status' => 0, 'device_id' => $device_id, 'device_sn' => $device_face_info['device_sn'],
                        'device_type' => $device_face_info['device_type'], 'device_type_str' => 'xihan',
                        'relate_id' => $device_id, 'relate_type' => 'house_face_device'
                    ];
                    $cmd_data = [
                        'method' => 'devDoor.openOnce',
                        'params' => ['channel' => 0],
                    ];
                    $dataCmd = $cmdParams;
                    $dataCmd['cmd_data'] = json_encode($cmd_data, JSON_UNESCAPED_UNICODE);
                    $cmdId = $db_house_face_device_cmd->add($dataCmd);

                    if ($device_face_info['floor_id'] == '-1') {
                        $log_name = D('House_village_public_area')->where(['public_area_id' => $device_face_info['public_area_id']])->getField('public_area_name');
                    } else {
                        $floor_data = D('House_village_floor')->where(['floor_id' => $device_face_info['floor_id']])->field('floor_name,single_id')->find();
                        if ($floor_data) {
                            $single_name = D('house_village_single')->where(['id' => $floor_data['single_id']])->getField('single_name');
                            if (preg_match('/[\x7f-\xff]/', $single_name . $floor_data['floor_name'])) {
                                $log_name = $single_name . $floor_data['floor_name'];
                            } else {
                                $log_name = $single_name . '号楼-' . $floor_data['floor_name'] . '单元';
                            }
                        } else {
                            $log_name = '--';
                        }
                    }
                    $log_from = 2;
                    $user_data = [
                        'eventId' => 'openOnce_' . $cmdId,
                        'uid' => isset($now_village_bind['uid']) ? $now_village_bind['uid'] : 0,
                        'log_bind_id' => $pigcms_id ? $pigcms_id : 0,
                        'log_name' => $log_name,
                        'log_from' => $log_from,
                        'log_business_id' => $device_face_info['village_id'] ? $device_face_info['village_id'] : 0,
                        'log_more_id' => $now_village_bind['floor_id'] ? $now_village_bind['floor_id'] : 0,
                        'device_id' => $device_id,
                        'log_status' => 0,
                        'log_time' => $nowTime,
                    ];
                    $res = D('House_user_log')->add($user_data);
                    $d_house_face_device->where(['device_id' => $device_id])->save(['last_open_time' => $nowTime]);
                }
                $this->returnCode(0, $device_id);
            }
            if (30 === intval($device_face_info['device_type'])) {
                // 260云 将设备相关信息加入指令中等候
                $login_time = isset($device_face_info['login_time']) ? intval($device_face_info['login_time']) : 0;
                $parameterPolling = D('House_village_device_cmd')::PARAMETER_POLLING;
                $spaceTimeCondition = intval($parameterPolling) * 10; // 判断离线间隔时间
                $spaceTime = time() - $login_time;
                if ($login_time === 0 || $spaceTime > $spaceTimeCondition) {
                    $array = array(
                        'errorCode'=>1001,
                        'errorMsg'=>'设备不在线请先检查网络！'
                    );
                    exit(json_encode($array));
                }
                $data = [];
                $data['device_id'] = $device_id;
                $data['device_sn'] = $device_face_info['device_sn'];
                $data['opendoor'] = 1;
                $data['employeeId'] = $pigcms_id;
                $data['device_type'] = 30;
                $arr = D('House_village_device_cmd')->addOrUpdateRestartCmd($data);
                if (isset($arr['err']) && intval($arr['err']) > 0) {
                    $array = array(
                        'errorCode'=>1001,
                        'errorMsg'=>$arr['msg']
                    );
                    exit(json_encode($array));
                }
            }
            if ($now_village_bind['type']!=4 && $device_face_info['device_type']==29 && isset($device_face_info['thirdDeviceTypeStr'])&&$device_face_info['thirdDeviceTypeStr']==2) {
                $db_house_village_nmv_card = M('House_village_nmv_card');
                $whereNmvCard = ['bind_id'=>$pigcms_id];
                $nmv_card = $db_house_village_nmv_card->where($whereNmvCard)->find();
                $expiration_time = isset($nmv_card['expiration_time'])&&$nmv_card['expiration_time']?$nmv_card['expiration_time']:0;
                if ($expiration_time<time()) {
                    $this->returnCodeError('您的权限已到期，请联系物业管理人员！');
                }
            } else {
                $userTimes =  D('House_village_user_bind')->getUserEndTime($now_village_bind['pigcms_id']);
                $dayTimes = strtotime(date('y-m-d', time()));
                if (isset($userTimes['propertyEndTime'])&&$userTimes['propertyEndTime']&&$userTimes['propertyEndTime']<$dayTimes) {
                    $this->returnCodeError('您的权限已到期，请联系物业管理人员！');
                }
            }
            if (isset($device_face_info['thirdProtocol']) && intval($device_face_info['thirdProtocol']) == 15 && isset($channelInfo)) {
                $models = '\app\community\model\service\Device\HikInfoVisionICommunityService/controlDoorState';
                $param = [
                    'channel_id' => $channelInfo['channel_id'],
                    'doorIndexCode' => $channelInfo['channelId'],
                ];
                $thirdDeviceInfo = invoke_v20_service($models,$param);
                $thirdDevice = $thirdDeviceInfo['data']['retval'];
                if (isset($thirdDevice['code']) && $thirdDevice['code'] == 0) {
                    $this->returnCodeError('开门成功');
                } else {
                    !$thirdDevice['msg'] && $thirdDevice['msg'] = '开门失败';
                    $this->returnCodeError($thirdDevice['msg']);
                }
            }
            if (isset($device_face_info['thirdProtocol']) && $device_face_info['thirdProtocol']>0 && !in_array($device_face_info['thirdProtocol'], [11,15])) {
                try {
                    $res = invoke_v20_service('\app\community\model\service\FaceDeviceService/openFaceDoor', ['device_id'=>$device_id,'pigcms_id' => $pigcms_id]);

                    $res = $res['data']['retval'];
                    if (isset($res['code']) && $res['code']>0) {
                        $this->returnCodeError('开门失败');
                    } elseif (!$res) {
                        $this->returnCodeError('开门失败');
                    }
                }catch (Exception $e) {
                    fdump_api([$e->getMessage(), '开门失败', $device_id, $device_id], 'open_face/errOpenFaceDoorLog');
                    $this->returnCodeError('开门失败');
                }
            } elseif (1==$device_face_info['device_type']) {
                // 判断是A1/A2/A3 分别开门
                $d_open_face = D('House_face_img');
                $params = array(
                    'pigcms_id' => $pigcms_id
                );
                try {
                    $data = $d_open_face->open_a1_face_door($device_face_info['device_id'],$device_face_info['device_sn'],$params);
                }catch (Exception $e) {
                    fdump('line:>>>>>>>>>>>>>>>>>>>>>>'.__LINE__,'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);
                    fdump($e->getMessage(),'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);
                    $this->returnCodeError('开门失败');
                }
            } elseif (2==$device_face_info['device_type']) {
                try {
                    $data = D('House_village_face_door')->sendOpendoor($pigcms_id,'pigcms_id',$device_face_info['device_sn']);
                }catch (Exception $e) {
                    fdump('line:>>>>>>>>>>>>>>>>>>>>>>'.__LINE__,'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);
                    fdump($e->getMessage(),'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);
                    $this->returnCodeError('开门失败');
                }
                if ($data['code']==0) {
                    if (!$data['msg']) {
                        $data['msg'] = '开门失败';
                    }
                    fdump('line:>>>>>>>>>>>>>>>>>>>>>>'.__LINE__,'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);
                    fdump($data,'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);
                    $this->returnCodeError($data['msg']);
                }
            } elseif(3==$device_face_info['device_type'])  {
                try {
                    $data = D('House_village_face_door')->send_open_a3_door($device_id,$pigcms_id,'pigcms_id',$is_owner,$this->_uid);
                }catch (Exception $e) {
                    fdump('line:>>>>>>>>>>>>>>>>>>>>>>'.__LINE__,'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);
                    fdump($e->getMessage(),'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);

                    $info = D('House_village_face_door')->get_a3_device($device_id);
                    if (!$info || !$info['data']['online']) {
                        $this->returnCodeError('当前设备异常，请联系物业检查网络');
                    } else {
                        $this->returnCodeError('开门失败');
                    }
                }
                if ($data['code']==0) {
                    if (!$data['msg']) {
                        $data['msg'] = '开门失败';
                    }
                    fdump('line:>>>>>>>>>>>>>>>>>>>>>>'.__LINE__,'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);
                    fdump($data,'api/log/'.date('Ymd').'/open_face/open_face_door_err',true);
                    $this->returnCodeError($data['msg']);
                }
                hook::hook_exec('house_cost_notice',array('bind_id'=>$pigcms_id));
            } elseif(5==$device_face_info['device_type'] || 6==$device_face_info['device_type'])  {
                $info = D('Face_door_a5_service')->getEquipmentInfo($device_face_info['device_sn']);
                if($info['deviceStatus'] != 1 ){
                    $data['msg'] = '当前设备异常，请联系物业检查网络';
                    $this->returnCodeError($data['msg']);
                }
                $data = D('Face_door_a5_service')->remoteOpen($device_face_info['device_sn']);
                if($data['code'] == 200 || $data==true){
                    D('Face_door_a5_service')->openDoor($device_face_info['device_sn'],$pigcms_id);
                    $this->returnCodeError('开门成功');
                }else{
                    D('Face_door_a5_service')->openDoor($device_face_info['device_sn'],$pigcms_id,1);
                    $this->returnCodeError('开门失败');
                }
            } elseif (7==$device_face_info['device_type']) {
                if ($is_owner) {
                    $operator_type = 0;
                } else {
                    $operator_type = 2;
                }
                $msg = [
                    'operator_type' => $operator_type,
                    'operator_id' => $pigcms_id,
                ];
                $data = D('Face_door_a7_service')->face_a7_open_door_record($device_face_info['device_id'],$pigcms_id,$msg,$device_face_info['village_id'], $device_face_info);
                if($data['code'] == 200){
                    if (!$data['msg']) {
                        $data['msg'] = '开门失败';
                    }
                    $this->returnCodeError($data['msg']);
                } else {
                    $this->returnCode(0, ['device_id'=> $device_id,'msg' =>'开门成功！']);
                }
            } elseif (8==$device_face_info['device_type']){
                $res = D('Face_local_area_device')->openDoor($device_id,$pigcms_id);
                if($res){
                    $this->returnCode(0, ['device_id'=> $device_id,'msg' =>'开门命令已经下发请等待开门']);
                }else{
                    $this->returnCodeError('开门失败');
                }
            } elseif (4==$device_face_info['device_type']) {
                $data = D('Face_door_a4_service')->deviceA4Unlock($device_face_info['device_id'],$pigcms_id,0,$device_face_info,$is_owner,$this->_uid);
                if($data['code'] == 0){
                    $info = D('Face_door_a4_service')->getA4Device($device_face_info['device_id']);
                    if (!$info || !$info['online']) {
                        $this->returnCodeError('当前设备异常，请联系物业检查网络');
                    }
                    if (!$data['msg']) {
                        $data['msg'] = '开门失败';
                    }
                    $this->returnCodeError($data['msg']);
                } else {
                    $this->returnCode(0, ['device_id'=> $device_id,'msg' =>'开门成功！']);
                }
            } elseif (21==$device_face_info['device_type']) {
                $data = D('Face_door_d1_service')->d1_send_open($device_face_info['device_id'],$pigcms_id,$device_face_info);
                if($data['code'] == 200){
                    $this->returnCodeError('开门失败');
//                    if (!$data['msg']) {
//                        $data['msg'] = '开门失败';
//                    }
//                    $this->returnCodeError($data['msg']);
                } else {
                    $this->returnCodeError('开门成功');
                }
            }elseif(22 == $device_face_info['device_type']){
                $res = D('Face_door_card_service')->openDoor($device_face_info['device_id'],$now_village_bind);
                if(!$res){
                    $data['msg'] = '开门失败';
                    $this->returnCodeError($data['msg']);
                }
//                else {
//                    $this->returnCode(0, ['device_id'=> $device_id,'msg' =>'开门命令已经下发请等待开门']);
//                }
                $this->returnCodeError('开门成功');
            }elseif (61==$device_face_info['device_type']) {
                /**
                 * todo A185开闸
                 */
                $a185 = D('Face_a185_request_record');
                $res=$a185->a185_gpio($device_face_info['device_id'],$device_face_info['village_id'],$pigcms_id);
                fdump($device_face_info,'api/log/'.date('Ymd').'/d3/a185_gpio',true);
            } elseif (23==$device_face_info['device_type']) {
                /**
                 * todo d3开闸
                 */
                $d3 = D('Face_d3_request_record');
                $res=$d3->d3_gpio($device_face_info['device_id'],$device_face_info['village_id'],$pigcms_id);

                if($res['error'] > 0){
                    $data['msg'] = '开门失败';
                    $this->returnCodeError($data['msg']);
                }
                $this->returnCodeError('开门成功');
            }
            elseif (24==$device_face_info['device_type']) {
                /**
                 * todo d4开门
                 */
                $d3 = D('Face_d4_request_record');
                $res=$d3->d4_gpio($device_face_info['device_id'],$device_face_info['village_id'],$pigcms_id);
                if($res['error'] > 0){
                    $data['msg'] = '开门失败';
                    $this->returnCodeError($data['msg']);
                }
                $this->returnCodeError('开门成功');
            }elseif (88 == $device_face_info['device_type']){
                //todo 大华远程开门
                $authInfo = invoke_v20_service('\app\community\model\service\DaHuaService/getToken');
                $authInfo = $authInfo['data']['retval'];
                $res = invoke_v20_service('\app\community\model\service\DaHuaService/getDoorDevice', ['authInfo'=>$authInfo,'deviceName'=>$device_face_info['device_name'],'deviceIp'=>$device_face_info['device_ip']]);
                $res = $res['data']['retval'];
                fdump_api(['获取$res=='.__LINE__,$res],'dahua/open_face_door',1);
                $channelCodeList = [];
                if($res['success'] == true){
                    $data = $res['data']['pageData'][0]['accessControlChannelList'];
                    foreach ($data as $v){
                        $channelCodeList[] = $v['channelCode'];
                    }
                }
                fdump_api(['获取$channelCodeList=='.__LINE__,$channelCodeList],'dahua/open_face_door',1);
                if($channelCodeList){
                    $res = invoke_v20_service('\app\community\model\service\DaHuaService/openDoor', ['authInfo'=>$authInfo,'channelCodeList'=>$channelCodeList]);
                    $res = $res['data']['retval'];
                    fdump_api(['openDoor返回=='.__LINE__,$res],'dahua/open_face_door',1);
                    if($res['success'] == true){
                        D('Face_door_a5_service')->openDoor($device_face_info['device_sn'],$pigcms_id);
                        $this->returnCodeError('开门成功');
                    }
                }
                D('Face_door_a5_service')->openDoor($device_face_info['device_sn'],$pigcms_id,1);
                $data['msg'] = '开门失败';
                $this->returnCodeError($data['msg']);
            }
            elseif (29==$device_face_info['device_type']){
                // 朵普云对讲
                $res = invoke_v20_service('\app\community\model\service\CloudIntercomService/openDoor',[$device_face_info['village_id'],$device_face_info['device_sn']]);
                if($res['retval']['code'] > 0){
                    $data['msg'] = '开门失败';
                    $this->returnCodeError($data['msg']);
                }
                $this->returnCodeError('开门成功');
            }
            $this->returnCode(0, $device_id);

        } else {
            $this->returnCode('20090009');
        }
    }

    public function house_worker()
    {
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $where_user_bind = array(
            'type'=>4,
            'uid'=>$this->_uid,
            'village_id'=>$village_id,
            'status'=>['not in', [3,4]]
        );
        $user_bind = D('House_village_user_bind')->where($where_user_bind)->find();
        if(empty($user_bind)){
            $this->returnCode('20090248');
        }


        $house_worker = D('House_worker')->where(array('phone'=>$user_bind['phone'],'village_id'=>$village_id,'is_del'=>0))->find();
        if(empty($house_worker)){
            $this->returnCode('20090248');
        }
        $arr = [];
        $base_url = D('House_village')->base_url;
        $menus_list = array();
        //判断是否有我的应用
        $where_bind = array(
            'from'=>0,
            'use_id'=> $village_id,
            'status' => 0
        );
        $house_village = M('House_village')->where(array('village_id'=>$village_id))->find();
        if ($house_village['property_id']>0) {
            $where_bind['use_id'] =  $house_village['village_id'];
        }
        $application_arr = M('Application_bind')->where($where_bind)->getField('application_id',true);
        //获取购买功能套餐包含的功能应用
        $package_order_data = D('PrivilegePackage')->getPackageContent($house_village['property_id']);
        $content_id = $package_order_data['content'];
        if (empty($application_arr)) {
            $arr['application_arr'] = (object)[];

            $arr['menus_list'] = [];
        }else{
            $arr['application_arr'] = $application_arr;

            if(in_array('23',$application_arr)){

                $qrcode_person = M('Wisdom_qrcode_person')->where(array('uid'=>$house_worker['wid']))->find();

                if($qrcode_person && in_array('20',$content_id)){//购买的功能套餐包含智慧二位码显示
                    $menus_list[] = array(
                        'title' => '智慧二维码',
                        'url'=>$this->config['site_url'] . $base_url . 'pages/village/smartQRcode/taskList',
                    );
                }
                $arr['menus_list'] = $menus_list;
            }
            //2020/8/24 start 新增 查询是否添加收费管理
            $is_open_pay_management = D('House_menu_new')->getPayCostAppIsUsable($village_id);
            //2020/8/24 end
            if(in_array('9',$application_arr)) {
                $read_person = M('Meter_read_person')->where(array('uid' => $house_worker['wid'], 'village_id' => $village_id))->find();
                if ($read_person && $is_open_pay_management && in_array('14',$content_id)) {//购买的功能套餐包含移动抄表显示
                    $menus_list[] = array(
                        'title' => '移动抄表',
                        'url' => $this->config['site_url'] . $base_url . 'pages/village/mobileMeterReading/selectRoomy',
                    );
                }

                $arr['menus_list'] = $menus_list;
            }
            if(empty($menus_list)){
                $arr['menus_list'] = [];
            }
        }



        $this->returnCode(0,$arr);
    }



    public function get_house_village()
    {
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }

        $house_village = D('House_village')->where(array('village_id'=>$village_id))->find();
        $arr = [];
        if(empty($house_village)){
            $arr['get_house_village'] = array(
                'village_id'=>0,
                'village_address'=>'',
                'village_name'=>'',
            );
        } else {
            $arr['get_house_village'] = array(
                'village_id'=>$house_village['village_id'],
                'village_address'=>$house_village['village_address'],
                'village_name'=>$house_village['village_name'],
            );
        }
        $this->returnCode(0,$arr);
    }

