    public function tel_alarm_phone() {
        $village_id = I('village_id');
        $arr = array();
        if (empty($village_id)) {
            fdump_api(['缺少小区id'.__LINE__,$_GET,$_POST],'tel_alarm_phone/tel_alarm_phone_err_log',1);
            // 不传参数 依旧不返回报错
            $this->returnCode(0, $arr);
        }
        $pigcms_id = I('pigcms_id', '');//房间号
        if (empty($pigcms_id)) {
            if (empty($this->_uid)) {
                // 未登陆 依旧不返回报错
                fdump_api(['未登陆'.__LINE__,$_GET,$_POST],'tel_alarm_phone/tel_alarm_phone_err_log',1);
                $this->returnCode(0, $arr);
            }
            $where = [
                'type'=>['in',[0,1,2,3]],
                'village_id' => $village_id,
                'uid' => $this->_uid,
                'status' => ['not in', [3,4]]
            ];
            $pigcms_id = M('House_village_user_bind')->where($where)->order('type ASC')->getField('pigcms_id');
            if (empty($pigcms_id)) {
                // 不传参数 依旧不返回报错
                fdump_api(['拿不到身份信息'.__LINE__,$_GET,$_POST,$this->_uid,M('House_village_user_bind')->_sql(),M('House_village_user_bind')->getDbError()],'tel_alarm_phone/tel_alarm_phone_err_log',1);
                $this->returnCode(0, $arr);
            }
        }
        $lock_key = $key = 'houseAlarmPhone_'.$this->_uid;
        $add = [
            'businessKey' => $lock_key,
            'businessId' => $pigcms_id,
            'lockTime' => time(),
        ];
        $lockMsgId = M('house_lock_msg')->add($add);
        if (!$lockMsgId) {
            $this->returnCode(0, []);
        }
        $host = C('REDIS_HOST');
        $port = C('REDIS_PORT');
        $pass = C('REDIS_AUTH');
        if ($host && $port && $pass) {
            $redis = new Redis();
            $redis->pconnect($host, $port);
            $redis->auth($pass); //密码验证
            $is_lock = $redis->setnx($lock_key, 1); // 加锁
            if($is_lock == true){ // 获取锁权限
                // 第一次触发
            }else{
                fdump(['连续重复点击了一键报警'.__LINE__,$_POST,$_SESSION[$key],$this->_uid,$pigcms_id],'tel_alarm_phone/tel_alarm_phone_err_log',true);
                // 防止死锁
                if($redis->ttl($lock_key) == -1){
                    $redis->expire($lock_key, 1);
                }
                $this->returnCodeOk(array());
            }
        }
        if ($_SESSION[$key]) {
            fdump(['连续重复点击了一键报警'.__LINE__,$_POST,$_SESSION[$key],$this->_uid,$pigcms_id],'tel_alarm_phone/tel_alarm_phone_err_log',true);
            // 防止死锁
            if($redis && $redis->ttl($lock_key) == -1){
                $redis->expire($lock_key, 1);
            }
            $this->returnCode(0, []);
        }
        $d_house_village_user_bind = M('House_village_user_bind');
        $d_house_worker = M('House_worker');
        $where = array(
            'pg.village_id' => $village_id,
            'pg.section_status' => 4,   // 只查询安保部门
            'pg.is_del' => 0,
            'pg.status' => 1,
            'hw.status' => 1,
            'hw.is_del' => 0
        );
        $field = 'hw.wid, hw.phone, hw.openid, hw.nickname, hw.qy_id, hw.qy_status';
        $security_list = $d_house_worker->join('as hw LEFT JOIN '.C('DB_PREFIX').'property_group as pg ON hw.department_id=pg.id')->field($field)->where($where)->select();
        if (empty($security_list)) {
            fdump_api(['没有对应工作人员 依旧不返回报错'.__LINE__,$_GET,$_POST,$where,$security_list],'tel_alarm_phone/tel_alarm_phone_err_log',1);
            //没有对应工作人员 依旧不返回报错
            $this->returnCode(0, $arr);
        }

        $long = I('long','');
        $lat = I('lat','');
        $area_detail = ''; // 处理详细地址
        if ($lat && $long) {
            $area_info = D('Area')->cityMatching($lat, $long);
            if ($area_info && $area_info['area_info']) {
                $province_name = $area_info['area_info']['province_name'];
                $city_name = $area_info['area_info']['city_name'];
                $district_name = $area_info['area_info']['area_name'];
            }
            if ($area_info && $area_info['address_addr']) {
                $address_addr = $area_info['address_addr'];
                $address_name = $area_info['address_name'];
            }
            if ($address_addr) {
                $area_detail = $address_addr . $address_name;
            } elseif ($province_name || $city_name || $district_name) {
                $area_detail = $address_addr . $address_name;
            }
        }
        // 获取用户信息
        $bind_field = 'pigcms_id, usernum, name, phone, type, relatives_type, village_id, floor_id, vacancy_id, parent_id';
        $user = $d_house_village_user_bind->where(array('pigcms_id' => $pigcms_id))->field($bind_field)->find();
        if (empty($user)) {
            fdump_api(['对应用户信息没有 依旧不返回报错'.__LINE__,$_GET,$_POST,$user,$d_house_village_user_bind->_sql(),$d_house_village_user_bind->getDbError()],'tel_alarm_phone/tel_alarm_phone_err_log',1);
            //对应用户信息没有 依旧不返回报错
            $this->returnCode(0, $arr);
        }
        // 处理用户信息
        if (!$area_detail) {
            // 如果没有记录单元和房间且存在上级业主，查询业主的信息
            if (($user['floor_id']<=0 || $user['vacancy_id']<=0) && $user['parent_id']>0) {
                $user_parent = $d_house_village_user_bind->where(array('pigcms_id' => $user['parent_id']))->field($bind_field)->find();
                if ($user_parent['floor_id']<=0 || $user_parent['vacancy_id']<=0) {
                    fdump_api(['父级没有信息'.__LINE__,$_GET,$_POST,$user_parent],'tel_alarm_phone/tel_alarm_phone_err_log',1);
                    //对应用户信息没有 依旧不返回报错
                    $this->returnCode(0, $arr);
                }
                $user_detail = D('House_village')->get_single_floor_room($user_parent['single_id'],$user_parent['floor_id'],$user_parent['layer_id'],$user_parent['vacancy_id'],$village_id);
                if (!$user_detail) {
                    $user_detail = $user_parent['address'];
                }
            } else {
                $user_detail = D('House_village')->get_single_floor_room($user['single_id'],$user['floor_id'],$user['layer_id'],$user['vacancy_id'],$user);
                if (!$user_detail) {
                    $user_detail = $user['address'];
                }
            }
        }
        $model = new templateNews(C('config.wechat_appid'), C('config.wechat_appsecret'));
        $href = '';
        $first = "{$user['name']}触发了一键报警按钮";
        $keyword1 = "姓名：{$user['name']}；电话：{$user['phone']}";
        if ($area_detail) {
            $keyword2 = "当前所处位置：{$area_detail}";
        } elseif ($user_detail) {
            $keyword2 = "居住位置：{$user_detail}";
        } else {
            $keyword2 = '';
        }
        $remark = '请尽快确认业主安全';
        foreach ($security_list as $val) {
//            $data = array(
//                'tempKey' => 'OPENTM400166399',
//                'dataArr' => array(
//                    'href' => $href,
//                    'wecha_id' => $val['openid'],
//                    'first' => $first,
//                    'keyword1' => $keyword1,
//                    'keyword2' =>$keyword2,
//                    'keyword3' => date("Y年m月d日 H:i"),
//                    'remark' => $remark
//                )
//            );
//            $token_info = D('Property_group')->send_msg('work', $val['wid'], $data, $token_info);
            if ($val['openid']) {
                $model->sendTempMsg('OPENTM400166399',
                    array(
                        'href' => $href,
                        'wecha_id' => $val['openid'],
                        'first' => $first,
                        'keyword1' => $keyword1,
                        'keyword2' => $keyword2,
                        'keyword3' => date("Y年m月d日 H:i"),
                        'remark' => $remark
                    )
                );
            } else {
                fdump_api(['推送对象未授权微信'.__LINE__,$_GET,$_POST,$val],'tel_alarm_phone/tel_alarm_phone_err_log',1);
            }
        }
        $arr = $security_list;
        $_SESSION[$key] = null;
        if($is_lock == true){ // 获取锁权限
            $redis->del($lock_key);
        }
        $this->returnCode(0, $arr);

    }
    //老板本停车优惠券（废弃）
