    //新版本停车优惠券
    public function park_coupon_info()
    {

        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $village_id = I('village_id');
       /* if (empty($village_id)) {
            $this->returnCode('30000001');
        }*/
        $coupons_id = I('coupons_id');
        if(!$coupons_id){
            $this->returnCodeError('传参异常');
        }
        $arr = array();

        $coupons_info = D('Park_shop_coupons')->where(['id'=>$coupons_id])->find();
        if($coupons_info){
            $arr['receive_coupon_fee'] = $coupons_info['free_money'];
            $arr['coupons_id'] = $coupons_id;
        }else{
            $this->returnCodeError('优惠券不存在');
        }

        $dataList = array();
        $park_coupon_list = M('House_village_park_coupon')->where(array('user_id'=>$this->_uid,'village_id'=>$coupons_info['village_id']))->order('`id` DESC')->select();
        if(empty($park_coupon_list)){
            $dataList = [];
        }
        foreach($park_coupon_list as $k=>$v){
            $list = array();
            $list['car_number'] = $v['car_number'];
            $dataList[] = $list;
        }
        $dataList = array_unique($dataList, SORT_REGULAR);	//二维数组去重
        $arr['dataList'] = $dataList;
        $this->returnCode(0, $arr);

    }
    /**
     * 领取优惠券
     */
    public function park_coupon_add()
    {
        if (empty($this->_uid)) {
            $this->returnCode('20000009');
        }
        $village_id = I('village_id');
        //2021/1/26 优惠券改版 start
        $coupons_id = I('coupons_id');
        $random_code = I('random_code');
        if(!$coupons_id){
            $this->returnCodeError('传参异常');
        }
        //2021/1/26 优惠券改版 end
        if(empty(I('car_number'))){
            $this->returnCodeError('车牌号不能为空!');
        }
        $car_number = I('car_number','','trim');
        $coupons_info = D('Park_shop_coupons')->where(['id'=>$coupons_id])->find();
        if($coupons_info){
            if($coupons_info['status'] == 2) {//动态码
                if ($coupons_info['random_code'] != $random_code) {
                    $this->returnCodeError('该码已失效!');
                    die;
                }
            }
            $park_coupons = D('Park_coupons')->where(['c_id'=>$coupons_info['cid']])->find();
            if (empty($park_coupons)){
                $this->returnCodeError('未查询到优惠券信息!'); 
            }
            if ($park_coupons['status']!=0){
                $this->returnCodeError('当前优惠券已停止使用!');
            }
            $data['money'] = $coupons_info['free_money'];
            $data['coupons_id'] = $coupons_id;
        }else{
            $data['money'] = 0.00;
            $this->returnCodeError('该码已失效!');
            die;
        }
        $where = array();
        $where['coupons_id'] = $coupons_id;
        $where['car_number'] = $car_number;
        $where['is_use'] = 0;
        $start_time = strtotime(date('Y-m-d', time()));
        $end_time = strtotime(date('Y-m-d', time()) . ' 23:59:59');
        $where['add_time'] = array('between', array($start_time, $end_time));
        $park_coupon_list = M('House_village_park_coupon')->where($where)->find();
        if ($park_coupon_list) {
            $this->returnCodeError('你已经领过了,不能重复领取!');
        }
        if (empty($village_id)) {
            $village_id=$coupons_info['village_id'];
        }
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $garage_id = isset($park_coupons['garage_id']) ? intval($park_coupons['garage_id']) : 0;
        $house_park_garage_config = D('House_village_park_garage_config')->getVillageParkConfig($garage_id, $village_id);
        $park_sys_type = isset($house_park_garage_config['park_sys_type']) ? trim($house_park_garage_config['park_sys_type']) : '';
        fdump_api($house_park_garage_config, '$house_park_garage_config');
        if ($house_park_garage_config && !in_array($park_sys_type, ['D3', 'A11','HXT85'])) {
            //判断小区有没有对接停车主机，若未对接则报错。
            $park_system = M('Park_system')->where(['park_id' => $village_id])->find();
            if (empty($park_system)) {
                $this->returnCodeError('系统尚未对接停车场，无法领取优惠券。请联系管理员');
            }
        }
        if ($coupons_info['residue_num'] <= 0 || ($coupons_info['num'] - $coupons_info['buy_num']) <= 0) {
            $this->returnCodeError('暂无优惠券可领取!');
            die;
        }
        //2021/1/26 优惠券改版 end
        $in_park = M('In_park')->where(array('car_number'=>$car_number,'is_paid'=>0))->order('id desc')->find();
        $nowTime = time();
        $data['car_number'] = $car_number;
        $data['user_id'] = $this->_uid;
        $data['add_time'] = $nowTime;
        $data['is_download'] = 0;//未下发
        $data['is_use'] = 0;//未使用
        $data['village_id'] = $village_id;
        $data['ticket_id'] = createRandomStr(15);
        $data['park_sys_type'] = $park_sys_type;
        $data['garage_id'] = $garage_id;
        $park_coupon_id = M('House_village_park_coupon')->data($data)->add();
        if($park_coupon_id){
            $db_house_village_car_flow_coupon = M('House_village_car_flow_coupon');
            $flowCoupon = [
                'park_coupon_id' => $park_coupon_id, 'uid' => $this->_uid, 'village_id' => $village_id,
                'car_number' => $car_number, 'park_sys_type' => $park_sys_type, 'is_use' => 0,
                'ticket_id' => $data['ticket_id'], 'money' => $data['money'], 'coupons_id' => $coupons_id,
                'receive_time' => $nowTime, 'is_download' => 0, 'add_time' => $nowTime,
            ];
            $uniqueArr = [
                'car_number' => $car_number, 'uid' => $this->_uid, 'village_id' => $village_id, 
                'park_sys_type' => $park_sys_type, 'is_use' => 0,
            ];
            $unique_id = md5(json_encode($uniqueArr, JSON_UNESCAPED_UNICODE));
            $whereUnique = [
                'unique_id' => $unique_id,
            ];
            $flowCouponInfo = $db_house_village_car_flow_coupon->where($whereUnique)->find();
            if (isset($flowCouponInfo['id']) && $flowCouponInfo['id']) {
                $flowCoupon['update_time'] = $nowTime;
                $db_house_village_car_flow_coupon->where($whereUnique)->data($flowCoupon)->save();
            } else {
                $flowCoupon['unique_id'] = $unique_id;
                $flowCoupon['add_time'] = $nowTime;
                $db_house_village_car_flow_coupon->data($flowCoupon)->add();
            }
            if ($park_sys_type == 'A1') {
                //模拟进入停车队列数据
                $house_village = M('House_village')->where(['village_id'=>$village_id])->field('village_name,property_id')->find();
                $property_id=0;
                $village_name='';
                if($house_village){
                    $village_name=$house_village['village_name'];
                    $property_id=$house_village['property_id'];
                }
                $json_data['service_name'] = 'deliver_ticket';
                $json_data['ticket_id'] = $data['ticket_id'];
                $json_data['create_time'] = $data['add_time'];
                $json_data['limit_day'] = strtotime(date('Y-m-d',time()).' 23:59:59');
                $json_data['money'] = $data['money'];
                $json_data['duration'] = '';
                $json_data['car_number'] = $car_number;
                $json_data['ticket_unit'] = '';
                $json_data['discount'] = '';
                $json_data['ticket_type'] = 0;//0表示减免停车金额,
                $json_data['remark'] = '';
                $json_data['shop_name'] = $village_name ? $village_name : '';
                $json_data['time_range'] = 0;
                $json_data['park_id'] = $park_system['park_id'];
                $json_data['fix_code_name'] = '';
                $json_data['starttime'] = '';
                $json_data['endtime'] = '';
                $json_data['startdate'] = '';
                $json_data['enddate'] = '';
                $json_data['active_start_time'] = '';
                $json_data['active_end_time'] = '';
                $json_data['buy_money'] = '';
                $json_data['shop_id'] = $village_id;
                if($in_park){
                    $json_data['have_order'] = 1;
                    $json_data['order_id'] = $in_park['order_id'];
                }else{
                    $json_data['have_order'] = 0;
                    $json_data['order_id'] = '';
                }
                $post_data['unserialize_desc'] = serialize($json_data);
                $post_data['park_id'] = $park_system['park_id'];
                $post_data['token'] = $park_system['token'];
                $post_data['service_name'] = 'deliver_ticket';
                $post_data['car_number'] = $car_number;
                $post_data['order_id'] = $in_park['order_id'] ? $in_park['order_id'] : 0;
                $post_data['create_time'] = time();
                $post_data['ticket_id'] = $data['ticket_id'];
                $post_data['village_id'] = $village_id;
                $res = M('Park_total_record')->data($post_data)->add();//优惠券下发
                if($res){
                    //如果车在场内，记录下券ID
                    if($in_park){
                        M('In_park')->where(['id' => $in_park['id']])->data(['coupon_id' => $park_coupon_id])->save();
                    }
                    M('House_village_park_coupon')->where(array('id'=>$park_coupon_id))->data(array('is_download'=>1))->save();
                    // 一旦领取了该优惠券  原来的优惠券全部置为已使用
                    $where_no_use['car_number'] = $car_number;
                    $where_no_use['is_use'] = 0;
                    $where_no_use['is_download'] = 1;
                    $where_no_use['village_id'] = $village_id;
                    $where_no_use['user_id'] = $this->_uid;
                    $where_no_use['id'] = array('neq', $park_coupon_id);
                    $data_no_use = [
                        'is_use' => 1, 'use_time' => time()
                    ];
                    M('House_village_park_coupon')->where($where_no_use)->data($data_no_use)->save();
                    $data_no_use_record = [
                        'status' => 2, 'car_number' => $car_number, 'park_id' => $village_id,
                        'service_name' => 'deliver_ticket', 'token' => $park_system['token']
                    ];
                    M('Park_total_record')->data($data_no_use_record)->setField('status', 1);
                    //2021/1/26 优惠券改版 start 领取成功后修改随机码
                    D('House_village_park_coupons')->receiveParkCar($coupons_id);
                    //2021/1/26 优惠券改版 end
                    //向用户发送优惠券模板消息
                    $now_user = D('User')->get_user($this->_uid);
                    if ($now_user['openid']) {
                        $model = new templateNews(C('config.wechat_appid'), C('config.wechat_appsecret'));
                        $model->sendTempMsg('OPENTM400166399',
                            array(
                                'href' => $this->config['site_url'] . D('House_village')->base_url,
                                'wecha_id' => $now_user['openid'], 'first' => '停车优惠券领取成功通知',
                                'keyword1' => '车牌号（' . $car_number . '）', 'keyword2' => '立减' . getFormatNumber($data['money']) . '元优惠',
                                'keyword3' => date("Y年m月d日 H:i"), 'remark' => '车辆出场可直接抵扣优惠金额'
                            ), 0, $property_id, 1
                        );
                    }
                    $this->returnCodeOk('领取成功!');
                }else{
                    $this->returnCodeError('领取失败!');
                }
            } 
            else {
                $house_village = M('House_village')->where(['village_id' => $village_id])->field('village_name,property_id')->find();
                $property_id = 0;
                $village_name = '';
                if ($house_village) {
                    $village_name = $house_village['village_name'];
                    $property_id = $house_village['property_id'];
                }
                // 一旦领取了该优惠券  原来的优惠券全部置为已使用
                $nowTime = time();
                $where_no_use = [];
                $where_no_use['id'] = array('neq', $park_coupon_id);
                $where_no_use['user_id'] = $this->_uid;
                $where_no_use['village_id'] = $village_id;
                $where_no_use['car_number'] = $car_number;
                $where_no_use['park_sys_type'] = $park_sys_type;
                $where_no_use['is_use'] = 0;
                $data_no_use = ['is_use' => 1, 'use_time' => $nowTime];
                M('House_village_park_coupon')->where($where_no_use)->data($data_no_use)->save();
                $whereFlowTemp = [
                    'car_number' => $car_number, 'uid' => $this->_uid, 'village_id' => $village_id,
                    'park_sys_type' => $park_sys_type, 'is_use' => 0,
                ];
                $flowTempList = $db_house_village_car_flow_coupon->where($whereFlowTemp)->select();
                foreach ($flowTempList as $item) {
                    $car_number = isset($item['car_number']) ? trim($item['car_number']) : '';
                    $uid = isset($item['uid']) ? intval($item['uid']) : 0;
                    $village_id = isset($item['village_id']) ? intval($item['village_id']) : 0;
                    $park_sys_type = isset($item['park_sys_type']) ? trim($item['park_sys_type']) : '';
                    $id = isset($item['id']) ? intval($item['id']) : 0;
                    $uniqueArr = [
                        'car_number' => $car_number, 'uid' => $uid, 'village_id' => $village_id,
                        'park_sys_type' => $park_sys_type, 'is_use' => 1,
                    ];
                    $unique_id = md5(json_encode($uniqueArr, JSON_UNESCAPED_UNICODE));
                    $flowTempArr = array('is_use' => 1, 'use_time' => $nowTime, 'unique_id' => $unique_id);
                    $db_house_village_car_flow_coupon->where(['id' => $id])->data($flowTempArr)->save();
                }
                //2021/1/26 优惠券改版 start 领取成功后修改随机码
                D('House_village_park_coupons')->receiveParkCar($coupons_id);
                //2021/1/26 优惠券改版 end
                //向用户发送优惠券模板消息
                $now_user = D('User')->get_user($this->_uid);
                if ($now_user['openid']) {
                    $model = new templateNews(C('config.wechat_appid'), C('config.wechat_appsecret'));
                    $model->sendTempMsg('OPENTM400166399', array(
                        'href' => $this->config['site_url'] . D('House_village')->base_url,
                        'wecha_id' => $now_user['openid'], 'first' => '停车优惠券领取成功通知',
                        'keyword1' => '车牌号（' . $car_number . '）', 'keyword2' => '立减' . getFormatNumber($data['money']) . '元优惠',
                        'keyword3' => date("Y年m月d日 H:i"), 'remark' => '车辆出场可直接抵扣优惠金额'
                    ), 0, $property_id, 1);
                }
                $this->returnCodeOk('领取成功!');
            }
        }else{
            $this->returnCodeError('领取失败!!');
        }

    }

    //临时车支付页面
    public function park_pay_order_info()
    {
        $dataList = [];
        if($this->_uid){
            $parking_car = M('Temp_park_log')->where(array('user_id'=>$this->_uid))->group('car_number')->order('`id` DESC')->limit(6)->select();
            if($parking_car){
                foreach($parking_car as $vv){
                    $dataList[] = $vv['car_number'];
                }
            }
        }
        $arr['dataList'] = $dataList;
        $this->returnCode(0, $arr);
    }

    public function park_pay_order()
    {

        if (empty($this->_uid)) {
            //临时用户特殊处理
            if(empty($_POST['tmp_ticket'])){
                $this->returnCode('20000009');
            }
            $info = ticket::get($_POST['tmp_ticket'], $this->DEVICE_ID, true);
            if ($info) {
                $this->_uid = 900000000 + $info['uid'];
            }
            if (empty($this->_uid)) {
                $this->returnCode('20000009');
            }
        }

        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $channel_id = I('channel_id','0', 'trim');  
        if(isset($_POST['channel_id']) && !empty($_POST['channel_id'])){
            $channel_id=trim($_POST['channel_id']);
        }
        $passage_id=0;
        if(isset($_POST['passage_id']) && !empty($_POST['passage_id'])){
            $passage_id=intval($_POST['passage_id']);
        }
        $garage_id=0;
        if(isset($_POST['garage_id']) && !empty($_POST['garage_id'])){
            $garage_id=intval($_POST['garage_id']);
        }
        $whereArr=array('village_id'=>$village_id,'channel_number'=>$channel_id,'status'=>1);
        if($garage_id>0){
            $whereArr['garage_id']=$garage_id;
        }
        $channel_info = M('Park_passage')->where($whereArr)->find();

        if($channel_info && isset($channel_info['garage_id']) && ($channel_info['garage_id']>0)){
            $garage_id=$channel_info['garage_id'];
        }
        fdump_api([$channel_info],'park_pay_order_0411_2',1);
  
        $house_park_garage_config=D('House_village_park_garage_config')->getVillageParkConfig($garage_id,$village_id);
        if(!$house_park_garage_config || $house_park_garage_config['park_versions'] != 2){
            fdump_api(['智慧停车功能已停用,请联系停车场人员配置'.__LINE__,$house_park_garage_config,$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
            $this->returnCodeError('智慧停车功能已停用,请联系停车场人员配置!');
        }
        // 如果车牌号为空  且 判断依据 spread=1 为预付   spread=2 为直付
        $car_number = I('car_number', '', 'trim');
        $spread = I('spread', '', 'intval');
        $data = [];
        $data['car_number'] = $car_number;
        $data['spread'] = $spread;
        
        $village_park_config=$house_park_garage_config;
        fdump_api([$village_park_config,$village_id,$spread],'park_pay_order_0411',1);
        if($channel_info['park_sys_type']=='third_ai_park'){
            $ctrlNo=$channel_info['device_number'];
            $retCarFee = D('ParkService')->queryOrderPriceThirdAiPark($village_id,$channel_info,$car_number,$spread,$this->_uid);
            $data['query_order_no']='';
            $err_msg='没有查到停车费用！';
            if(empty($car_number)){
                $err_msg='请输入车牌号查询停车费用！';
            }
            if($retCarFee && isset($retCarFee['query_order_no']) && !empty($retCarFee['query_order_no'])){
                $data['query_order_no']=$retCarFee['query_order_no'];
                if(isset($retCarFee['data']) && isset($retCarFee['data']['carNo'])){
                    $data['car_number']=$retCarFee['data']['carNo'];
                }
                $this->returnCode(0, $data);
            }else if($retCarFee && isset($retCarFee['err_msg']) && $retCarFee['err_msg']){
                $err_msg=$retCarFee['err_msg'];
                if(empty($car_number)){
                    $err_msg='请输入车牌号查询停车费用！';
                }
            }
            $this->returnCodeError($err_msg);
        }else if (2==$village_park_config['park_versions'] && 'D1'==$village_park_config['park_sys_type']) {
           if (!$car_number) {
               fdump_api(['请填写车牌号'.__LINE__,$house_park_garage_config,$village_park_config,$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
               $this->returnCodeError('请填写车牌号!');
           }
            $param = [
                'car_number' => $car_number,
                'garage_id'=>$garage_id,
            ];
            $msg = D('ParkService')->queryOrderPrice($village_id, $param);
            if ($msg['error']) {
                fdump_api(['错误'.__LINE__,$msg, $param,$village_park_config,$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
                $this->returnCodeError($msg['msg']);
            }
            $data['query_order_no'] = $msg['query_order_no'];
            $this->returnCode(0, $data);

        }
        elseif (2==$village_park_config['park_versions'] && ('HXT85'==$village_park_config['park_sys_type'] || 'D3'==$village_park_config['park_sys_type'])) {
            if ($spread==2){
                // 直付
                if(empty($channel_info)){
                    fdump_api(['出场设备信息不存在'.__LINE__,$channel_info,$village_park_config,$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
                    $this->returnCodeError('出场设备信息不存在!');
                }else{
                    $visitor_info = D('House_village_visitor')->where(['village_id'=>$village_id,'uid'=>$this->_uid,'_string'=>'car_id is not null and car_id <> ""'])->order('id DESC')->select();
                    fdump_api([$visitor_info,$car_number],'park_pay_order_0411_2',1);
                    //获取设备推送的车牌信息
                    if(!$car_number){
                        $where_log = [];
                        $where_log['channel_id']=$channel_info['device_number'];
                        $where_log['park_type']=2;
                        $time_condition = " add_time >= " . (time() - 300) . ' AND  add_time <=' . (time() + 180) ;
                        $where_log['_string']=$time_condition;
                        $log_info1 = D('Park_plateresult_log')->where($where_log)->order('id DESC')->find();
                        $data['query_order_no']='';
                        if(!empty($log_info1)){
                            $msg = D('ParkService')->queryOrderPriceD3($village_id,$log_info1['car_number'],$this->_uid,$spread,$channel_info['device_number'],$garage_id,$village_park_config['free_park_time']);
                            if ($msg['error']) {
                                fdump_api(['错误'.__LINE__,$msg, $log_info1['car_number'],$village_park_config,$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
                                $this->returnCodeError($msg['msg']);
                            }
                            fdump_api([$log_info1,$msg],'park_pay_order_0411_2',1);
                            $data['query_order_no'] = $msg['query_order_no'];

                        }else{
                            if (empty($this->_uid)){
                                $this->returnCode('20000009');
                            }
                            $msg = D('ParkService')->queryOrderPriceD3($village_id,'',$this->_uid,$spread,$channel_info['device_number'],$garage_id,$village_park_config['free_park_time']);
                            if ($msg['error']) {
                                fdump_api(['错误'.__LINE__,$msg, $log_info1['car_number'],$village_park_config,$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
                                $this->returnCodeError($msg['msg']);
                            }
                            fdump_api([$log_info1,$msg],'park_pay_order_0411_2',1);
                            $data['query_order_no'] = $msg['query_order_no'];
                        }
                        fdump_api([$data],'park_pay_order_0411_2',1);
                        if(empty($data['query_order_no'])){
                            fdump_api(['未获取到车辆出场信息'.__LINE__,$data,$village_park_config,$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
                            $this->returnCodeError('未获取到车辆出场信息!');
                        }
                    }
                    elseif (empty($visitor_info)&&!$car_number){
                        fdump_api(['临时车信息不存在,若为已到期月租车辆请先到物业缴费'.__LINE__,$visitor_info,$village_park_config,$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
                        $this->returnCodeError('请填写车牌号!');
                       // $this->returnCodeError('临时车信息不存在,若为已到期月租车辆请先到物业缴费!');
                    }elseif(!empty($car_number)){
                        $msg = D('ParkService')->queryOrderPriceD3($village_id,$car_number,$this->_uid,$spread,$channel_info['device_number'],$garage_id,$village_park_config['free_park_time']);
                        if ($msg['error']) {
                            fdump_api(['错误'.__LINE__,$msg, $car_number,$village_park_config,$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
                            $this->returnCodeError($msg['msg']);
                        }
                        $data['query_order_no'] = $msg['query_order_no'];
