            $json_data['pay_scene'] = $pay_scene;
            $json_data['out_channel_id'] = $channel_id;
            $json_data['query_order_no'] = '';
            $json_data['licence'] = '';
            $json_data['service_name'] = 'query_price';
            $json_data['msg_id'] = md5(uniqid(microtime(true),true));


            $post_data['unserialize_desc'] = serialize($json_data);
            if ('D3'!=$village_park_config['park_sys_type']) {
                $post_data['park_id'] = $park_system['park_id'];
                $post_data['token'] = $park_system['token'];
                $post_data['service_name'] = 'query_price';
            }else{
                $post_data['park_id'] =$village_id;
            }
            $post_data['park_id'] = $park_system['park_id'];
            $post_data['msg_id'] = $json_data['msg_id'];


            $post_data['order_id'] = $in_park['order_id']? $in_park['order_id']:'';
            $post_data['create_time'] = time();
            $post_data['village_id'] = $village_id;
            $post_data['car_number'] = $car_number;
            if (2==$spread && !empty(C('customization.a1_park_direct_payment'))){
                $pay_scene = 1;
            }
            $post_data['pay_scene'] = $pay_scene;
            fdump_api(['预付查询-直付出场，下发命令记录'.__LINE__,$post_data,$spread,$json_data],'park/'.$park_system['park_id'].'/park_pay_order_log',1);
            $res = M('Park_total_record')->data($post_data)->add();
            if($res){
                $park_log['car_number'] = I('car_number');
                $park_log['user_id'] = $this->_uid ? : 0;
                $park_log['add_time'] = time();
                M('Temp_park_log')->data($park_log)->add();
                $this->returnCode(0,$data);
            }else{
                fdump_api(['查询失败'.__LINE__,M('Park_total_record')->getDbError(),$this->_uid,$_REQUEST],'park/'.$village_id.'/errParkPayOrderLog',1);
                $this->returnCodeError('查询失败!');
            }
        }
    }


    /**
     * 轮训请求数据
     */
    public function upload_query_price()
    {
        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        // 如果车牌号为空  且 判断依据 spread=1 为预付   spread=2 为直付
        $car_number = I('car_number', '', 'trim');
        $query_order_no = I('query_order_no', '', 'trim');
        if(empty($car_number) && !$query_order_no){
            $this->returnCodeError('车牌号不能为空!');
        }

        $house_village = D('House_village')->where(array('village_id'=>$village_id))->find();
        $arr = [];
        $where_temp = [];
        $where_temp['is_out_park'] = 0;
        $where_temp['status'] = 0;
        $where_temp['village_id'] = $village_id;
        if ($car_number) {
            $where_temp['car_number'] = $car_number;
        }
        $query_order_no_id=$query_order_no;
        if(strpos($query_order_no,'query_price_') !== false){
            $query_order_no_id = str_replace('query_price_','',$query_order_no);
        }
        if(!empty($query_order_no_id)){
            $where_temp['id'] = $query_order_no_id;
        }
        $parking_temp = M('House_village_parking_temp')->where($where_temp)->order('id desc')->find();
        if ('D7'==$parking_temp['park_sys_type']){
            if($parking_temp){
                $arr['in_time'] = $parking_temp['in_time'] ? date('Y-m-d H:i:s',$parking_temp['in_time']) : '';

                $duration = $parking_temp['duration'] ? $parking_temp['duration'] : 0;
//            $duration = 1666;
                $hour = 0;
                $day = 0;
                if ($duration>=1440) {
                    $day = intval($duration/1440);
                    $duration = $duration - $day*1440;
                }
                if ($duration>60) {
                    $hour = intval($duration/60);
                    $duration = $duration - $hour*60;
                }
                $minute = $duration;
                $duration_msg = '';
                if ($day) {
                    $duration_msg .=$day.'天 ';
                }
                if ($hour) {
                    $duration_msg .=$hour.'小时';
                }
                if ($minute) {
                    $duration_msg .=$minute.'分钟';
                }

                $arr['duration_num'] = $parking_temp['duration'] ? $parking_temp['duration'] : 0;
                $arr['duration'] = $duration_msg;
                $arr['free_out_time'] = $parking_temp['free_out_time']? $parking_temp['free_out_time']:0;
                $arr['free_out_time_desc'] = $parking_temp['free_out_time']? $parking_temp['free_out_time']:0;
                $arr['price'] = floatval($parking_temp['price'])>0 ? $parking_temp['price']:0;
                $arr['village_name'] = $house_village['village_name']?$house_village['village_name']:'';
            }else{
                $arr['in_time'] ='';
                $arr['duration'] ='';
                $arr['free_out_time'] ='';
                $arr['free_out_time_desc'] = '';
                $arr['price'] ='';
                $arr['village_name'] = '';
            }
            $arr['car_number'] = $parking_temp['car_number'];
        }
        elseif ( in_array($parking_temp['park_sys_type'],['D3','A11','HXT85'])){
            if($parking_temp){
                $arr['in_time'] = $parking_temp['in_time'] ? date('Y-m-d H:i:s',$parking_temp['in_time']) : '';

                $duration = $parking_temp['duration'] ? $parking_temp['duration'] : 0;
//            $duration = 1666;
                $hour = 0;
                $day = 0;
                if ($duration>=1440) {
                    $day = intval($duration/1440);
                    $duration = $duration - $day*1440;
                }
                if ($duration>60) {
                    $hour = intval($duration/60);
                    $duration = $duration - $hour*60;
                }
                $minute = $duration;
                $duration_msg = '';
                if ($day) {
                    $duration_msg .=$day.'天 ';
                }
                if ($hour) {
                    $duration_msg .=$hour.'小时';
                }
                if ($minute) {
                    $duration_msg .=$minute.'分钟';
                }

                $arr['duration_num'] = $parking_temp['duration'] ? $parking_temp['duration'] : 0;
                $arr['duration'] = $duration_msg;
                $arr['free_out_time'] = $parking_temp['free_out_time']? $parking_temp['free_out_time']:0;
                $arr['free_out_time_desc'] = $parking_temp['free_out_time']? $parking_temp['free_out_time']:0;
                $arr['price'] = floatval($parking_temp['price'])>0 ? $parking_temp['price']:0;
                $arr['village_name'] = $house_village['village_name']?$house_village['village_name']:'';
                if (floatval($arr['price']) == 0 && strpos($parking_temp['car_number'],'临') !== false) {
                    // 费用是0 且是 无牌车
                    $data = [
                        'param' => [
                            'query_order_no' => $parking_temp['query_order_no'],
                            'car_number'     => $parking_temp['car_number'],
                            'village_id'     => $village_id,
                            'device_number'  => $parking_temp['out_channel_id'],
                            'inParkOrderId'  => $parking_temp['order_id'],
                        ]
                    ];
                    fdump_api(['data' => $data], '$CarNoPayToOut', 1);
                    $toOut = invoke_v20_service('\app\community\model\service\Park\A11Service/CarNoPayToOut',$data);
                    fdump_api(['1data' => $data, 'toOut' => $toOut], '$CarNoPayToOut', 1);
                }
            }else{
                $arr['in_time'] ='';
                $arr['duration'] ='';
                $arr['free_out_time'] ='';
                $arr['free_out_time_desc'] = '';
                $arr['price'] ='';
                $arr['village_name'] = '';
            }
            $arr['car_number'] = $parking_temp['car_number'];
        }else{
            if($parking_temp){
                if($parking_temp['park_sys_type'] == 'D6'){
                    if($parking_temp['state'] == 1 && !empty($parking_temp['errmsg'])){
                        $this->returnCodeError($parking_temp['errmsg']);
                    }
                }
                $arr['in_time'] = $parking_temp['in_time'] ? date('Y-m-d H:i:s',$parking_temp['in_time']) : '';

                $duration = $parking_temp['duration'] ? $parking_temp['duration'] : 0;
//            $duration = 1666;
                $hour = 0;
                $day = 0;
                if ($duration>=1440) {
                    $day = intval($duration/1440);
                    $duration = $duration - $day*1440;
                }
                if ($duration>60) {
                    $hour = intval($duration/60);
                    $duration = $duration - $hour*60;
                }
                $minute = $duration;
                $duration_msg = '';
                if ($day) {
                    $duration_msg .=$day.'天 ';
                }
                if ($hour) {
                    $duration_msg .=$hour.'小时';
                }
                if ($minute) {
                    $duration_msg .=$minute.'分钟';
                }

                $arr['duration_num'] = $parking_temp['duration'] ? $parking_temp['duration'] : 0;
                $arr['duration'] = $duration_msg;
                $arr['free_out_time'] = $parking_temp['free_out_time']? $parking_temp['free_out_time']:0;
                $arr['free_out_time_desc'] = $parking_temp['free_out_time']? $parking_temp['free_out_time']:0;
                $arr['price'] = floatval($parking_temp['price'])>0 ? $parking_temp['price']:0;
                $arr['village_name'] = $house_village['village_name']?$house_village['village_name']:'';
            }else{
                $arr['in_time'] ='';
                $arr['duration'] ='';
                $arr['free_out_time'] ='';
                $arr['free_out_time_desc'] = '';
                $arr['price'] ='';
                $arr['village_name'] = '';
            }
            $arr['car_number'] = $parking_temp['car_number'];
        }

        $this->returnCode(0, $arr);

    }


    public function park_go_pay_old()
    {
        fdump($_POST, 'park_go_pay', true);
        $pay_type = I('type','park');
        $village_id = I('village_id', '');

        $pay_name = $this->pay_list_type[$pay_type];
        if(empty($pay_name)){
            fdump_api(['msg' => '去支付-当前访问的缴费类型不存在','$_POST' => $_POST,'$_GET' => $_GET],"park/{$village_id}/err_park_go_pay_old",1);
            $this->returnCodeError('当前访问的缴费类型不存在');
        }
        $pigcms_id = I('pigcms_id', '');
//        if (empty($pigcms_id)) {
//            $this->returnCode('20120004');
//        }
        $car_type = I('car_type','','trim');
        if(empty($car_type)){//车类型 month_type  stored_type temporary_type
            fdump_api(['msg' => '去支付-车类型不能为空','$_POST' => $_POST,'$_GET' => $_GET],"park/{$village_id}/err_park_go_pay_old",1);
            $this->returnCodeError('车类型不能为空!');
        }

        if($car_type == 'month_type'){
            if(empty(I('month_end_time'))){
                fdump_api(['msg' => '去支付-到期时间不能为空','$_POST' => $_POST,'$_GET' => $_GET],"park/{$village_id}/err_park_go_pay_old",1);
                $this->returnCodeError('到期时间不能为空!');
            }
        }
//        if(empty(I('car_id'))){//车辆id
//            $this->returnCodeError('车辆id不能为空!');
//        }
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $now_village = $this->get_village($village_id);
        if ($car_type != 'temporary_type') {
            $now_user_info = $this->get_user_village_info($pigcms_id, $village_id, $this->_uid);//==>郭先森==>获取当前社区我的信息
        }

        //家属 获取业主的欠费信息
//        if ($now_user_info['parent_id']) {
//            $now_user_info = $this->get_user_village_info($now_user_info['parent_id'], $village_id, $this->_uid);
//        }
        if (!isset($_POST['money'])) {
            fdump_api(['msg' => '去支付-缺少金额','$_POST' => $_POST,'$_GET' => $_GET],"park/{$village_id}/err_park_go_pay_old",1);
            $this->returnCode('20120048');
        }
        if(I('car_type') == 'month_type'){
            $data_order['month_end_time'] = I('month_end_time')?strtotime(I('month_end_time').' 23:59:59'):'';//如果为月租车则记录到期时间
        }
        $garage_id=0;
        $car_id = I('car_id','', 'trim');
        if (!empty($car_id)) {
            $parking_car_single = D('House_village_parking_car')->where(array('car_id'=>$car_id))->find();
            if (empty($parking_car_single)) {
                fdump_api(['msg' => '去支付-对应车辆不存在','$_POST' => $_POST,'$_GET' => $_GET,'$car_id' => $car_id],"park/{$village_id}/err_park_go_pay_old",1);
                $this->returnCodeError('对应车辆不存在!');
            }
            if(isset($parking_car_single['garage_id']) && $parking_car_single['garage_id']>0){
                $garage_id=$parking_car_single['garage_id'];
            }
            $data_order['car_number'] = $parking_car_single['province'].$parking_car_single['car_number'];
            if(I('car_type') == 'month_type'){
                // 如果是月租车  传值结束时间小于等于当前时间进行拦截
                if ($parking_car_single['end_time'] && intval($parking_car_single['end_time'])>=strtotime(I('month_end_time'))) {
                    fdump_api(['msg' => '去支付-月租车到期时间必须大于当前到期时间','$_POST' => $_POST,'$_GET' => $_GET,'$parking_car_single' => $parking_car_single],"park/{$village_id}/err_park_go_pay_old",1);
                    $this->returnCodeError('月租车到期时间必须大于当前到期时间!');
                }
            }
        }
        $house_order_name=$this->config['house_name'];
        if(empty($house_order_name)){
            $house_order_name='社区';
        }
        $house_order_name=trim($house_order_name);
        $data_order['money'] = I('money') + 0;
        $data_order['order_name'] = $house_order_name.'缴费：' . $pay_name;
        $data_order['uid'] = $this->_uid ? : 0;
        $data_order['bind_id'] = ($now_user_info&&$now_user_info['pigcms_id'])?$now_user_info['pigcms_id']:'';
        $data_order['village_id'] = $now_village['village_id'];
        $data_order['time'] = $_SERVER['REQUEST_TIME'];
        $data_order['paid'] = 0;
        $data_order['order_type'] = $pay_type;
        $data_order['car_type'] = I('car_type');
        $data_order['car_id'] = $car_id;
        if(I('car_type') == 'temporary_type'){
            $car_number = I('car_number', '', 'trim');
            if(empty($car_number)){
                fdump_api(['msg' => '去支付-车牌号不能为空','$_POST' => $_POST,'$_GET' => $_GET,'$data_order' => $data_order],"park/{$village_id}/err_park_go_pay_old",1);
                $this->returnCodeError('车牌号不能为空!');
            }
            $data_order['car_number'] = $car_number;//如果是临时车,则需要传
			$data_order['order_name'].= '（ ' . $car_number . ' ）';
            
            $whereTemp = [
                'car_number' => $car_number,
                'village_id' => $village_id,
                'is_paid' => 0,
            ];
            $temp = M('House_village_parking_temp')->where($whereTemp)->field('id,order_id, price')->order('id DESC')->find();
            
			// 如果是d1查询当前记录订单金额
            //$village_park_config = M('House_village_park_config')->where(array('village_id'=>$village_id))->find();
            if ( $temp && 'D1'==$temp['park_sys_type']) {
                /*
                $whereTemp = [
                    'service_name' => 'd1_query_price',
                    'car_number' => $car_number,
                    'comid' => trim($village_park_config['comid']),
                    'is_paid' => 0,
                ];
                $temp = M('House_village_parking_temp')->where($whereTemp)->field('id,order_id, price')->order('id DESC')->find();
                */
                if ($temp) {
                    if ($temp['price'] && $temp['price']!=$data_order['money']) {
                        $data_order['money'] = $temp['price'];
                    }
                    if ($temp['order_id']) {
                        $data_order['third_id'] = $temp['order_id'];
                    }
                } else {
                    fdump_api(['msg' => '去支付-未查到对应待支付订单','$_POST' => $_POST,'$_GET' => $_GET,'$data_order' => $data_order,'$whereTemp' => $whereTemp],"park/{$village_id}/err_park_go_pay_old",1);
                    $this->returnCodeError('未查到对应待支付订单!');
                }
            }
            elseif( $temp && 'D3'==$temp['park_sys_type']){
                /*
                $whereTemp = [
                    'park_sys_type' => 'D3',
                    'car_number' => $car_number,
                    'village_id' => $village_id,
                    'is_paid' => 0,
                ];
                $temp = M('House_village_parking_temp')->where($whereTemp)->field('id,order_id, price')->order('id DESC')->find();
                */
                if ($temp) {
                    if ($temp['price'] && $temp['price']!=$data_order['money']) {
                        $data_order['money'] = $temp['price'];
                    }
                    if ($temp['order_id']) {
                        $data_order['third_id'] = $temp['order_id'];
                    }
                } else {
                    fdump_api(['msg' => '去支付-未查到对应待支付订单','$_POST' => $_POST,'$_GET' => $_GET,'$data_order' => $data_order,'$whereTemp' => $whereTemp],"park/{$village_id}/err_park_go_pay_old",1);
                    $this->returnCodeError('未查到对应待支付订单!');
                }
            }
            elseif($temp && 'A1'==$temp['park_sys_type']){
                /*
                $whereTemp = [
                    'park_sys_type' => 'A1',
                    'service_name' => 'query_price',
                    'car_number' => $car_number,
                    'village_id' => $village_id,
                    'is_paid' => 0,
                ];
                $temp = M('House_village_parking_temp')->where($whereTemp)->field('id,order_id, price')->order('id DESC')->find();
                */
                if ($temp) {
                    if ($temp['price'] && $temp['price']!=$data_order['money']) {
                        $data_order['money'] = $temp['price'];
                    }
                    if ($temp['order_id']) {
                        $data_order['third_id'] = $temp['order_id'];
                    }
                } else {
                    fdump_api(['msg' => '去支付-未查到对应待支付订单','$_POST' => $_POST,'$_GET' => $_GET,'$data_order' => $data_order,'$whereTemp' => $whereTemp],"park/{$village_id}/err_park_go_pay_old",1);
                    $this->returnCodeError('未查到对应待支付订单!');
                }
            }
        }

		//临时车停车可以不用登录
		if($this->_uid){
			$userinfo =  D('User')->get_user($this->_uid);
			$property_info = D('House_village_pay_order')->get_score($data_order,$userinfo);
			$data_order['score_can_use'] = $property_info['use_total_score_count'];
			$data_order['score_can_pay'] = $property_info['use_total_money'];
			$data_order['score_percent'] = $property_info['score_percent'];
			$data_order['score_can_get'] = $property_info['generate_integral'];
			$data_order['property_month_num'] = isset($_POST['park_month_num'])?$_POST['park_month_num']:0;
			$data_order['presented_property_month_num'] = isset($_POST['presented_park_month_num'])?$_POST['presented_park_month_num']:0;
			$score_data['score'] = $property_info['use_total_score_count'];
			$score_data['desc'] = "缴纳".$data_order['order_name']." ".$_POST['money'].C('config.Currency_txt')." 支出积分";
			$score_data['generate_integral'] = $property_info['generate_integral'];
			$score_data['generate_integral_desc'] = "缴纳【".$data_order['order_name']."】".$_POST['money'].C('config.Currency_txt')." 增加积分";
		}
        $nolicence=false;
        if($order_id = D('House_village_pay_order')->data($data_order)->add()){
            if (!empty($car_number)&&!empty($village_id)){
                $whereIn = array('car_number'=>$car_number,'village_id'=>$village_id,'is_paid'=>0,'is_out'=>0);
                if ($temp && isset($temp['order_id'])&&trim($temp['order_id'])) {
                    $whereIn['order_id'] = trim($temp['order_id']);
                }
                $inParkMsg = D('In_park')->where($whereIn)->find();
                fdump_api(['msg' => '去支付-入场信息','$_POST' => $_POST,'$data_order' => $data_order,'$inParkMsg' => $inParkMsg],"park/{$village_id}/park_go_pay_old_log",1);
                D('In_park')->where($whereIn)->data(array('pay_order_id' => $order_id))->save();
                $provice=mb_substr($car_number,0,1);
                if ($provice=='临'||$provice=='L'||$provice=='无'){
                    $nolicence=true;
                } 
            }
            
            //添加到订单，直接支付
            $now_order = D('House_village_pay_order')->field(true)->where(array('order_id' => $order_id))->find();
            $pay_order_param = array(
                'business_type' => 'house_village_pay',
                'business_id' => $now_order['order_id'],
                'order_name' => $now_order['order_name'],
                'uid' => $now_order['uid'],
                'total_money' => $now_order['money'],
                'wx_cheap' => 0,
                'nolicence'=>$nolicence
            );
            if ($this->config['open_village_sub_mchid'] && $now_village['sub_mch_id']) {
                $pay_order_param['is_own'] = 5;
            } else {
                $pay_order_param['is_own'] = 4;

            }

            $plat_order_result = D('Plat_order')->add_order($pay_order_param);


            if ($plat_order_result['error_code']) {
                $this->returnCodeError($plat_order_result['error_msg']);
            }
            if ($nolicence==true&&empty($now_order['money'])){
                $pay_order_info=[
                    'paid_time'=>time(),
                    'paid_money'=>$now_order['money'],
                    'paid'=>1,
                    'system_score'=>0,
                    'system_score_money'=>0,
                    'system_balance'=>0,
                    'uid'=>$now_order['uid'],
                    'is_own'=>0,
                ];
                D('House_village_pay_order')->after_pay($plat_order_result['order_id'],$pay_order_info);
                $this->returnCodeError('当前停车未产生费用无需支付，道闸抬杆时候请通行!');
            }
            $base_url = D('House_village')->base_url;
            $arr['type'] = 'plat';
            $arr['order_id'] = $plat_order_result['order_id'];
            $arr['order_url'] = $this->config['site_url'] . $base_url . 'pages/shop_new/confirmOrder/pay?order_id=' . $plat_order_result['order_id'] . '&type=plat&order_from=1';
            $this->returnCode(0, $arr);

        } else {
            fdump_api(['msg' => '去支付-保存订单失败','$_POST' => $_POST,'$_GET' => $_GET,'$data_order' => $data_order],"park/{$village_id}/err_park_go_pay_old",1);
            $this->returnCode('40000002');
        }
    }

    public function park_go_pay()
    {
        
        fdump_api($_POST,'go_pay_0507',1);
        
        $pay_type = I('type','park');

        $pay_name = $this->pay_list_type[$pay_type];
        if(empty($pay_name)){
            $this->returnCodeError('当前访问的缴费类型不存在');
        }
        $pigcms_id = I('pigcms_id', '');
