//        if(empty(I('car_id'))){//车辆id
//            $this->returnCodeError('车辆id不能为空!');
//        }
        $village_id = I('village_id', '');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $now_village = $this->get_village($village_id);
        /*
        if ($car_type != 'temporary_type') {
            $now_user_info = $this->get_user_village_info($pigcms_id, $village_id, $this->_uid);//==>郭先森==>获取当前社区我的信息
        }
        */
        $new_charge_time=D('House_new_charge_time')->where(array('property_id'=>$now_village['property_id']))->find();
        $is_new_effect_time=false;
        if (!empty($new_charge_time) && isset($new_charge_time['take_effect_time']) && $new_charge_time['take_effect_time']){
            $take_effect_time=$new_charge_time['take_effect_time'];
            $nowtime=time();
            if ($nowtime>$take_effect_time) {
                // 设置了生效时间 并且 当前时间大于生效时间 返回true 其他返回false
                $is_new_effect_time= true;
            }
        }
        if(!$is_new_effect_time){
            $this->park_go_pay_old();
            exit();
        }
        //家属 获取业主的欠费信息
//        if ($now_user_info['parent_id']) {
//            $now_user_info = $this->get_user_village_info($now_user_info['parent_id'], $village_id, $this->_uid);
//        }
        if ((!isset($_POST['money'])||$_POST['money']<=0)&&$car_type != 'temporary_type') {
            $this->returnCodeError('支付金额需大于0!');
        }
        $car_number = I('car_number', '', 'trim');
        $query_order_no = I('query_order_no', '');
        $where_temp = [
            'village_id' => $village_id,
        ];
        if ($car_number) {
            $where_temp['car_number'] = $car_number;
        }
        $in_record_id = 0;
        $out_record_id = 0;
        $in_time = 0;
        $query_time = 0;
        if(strpos($query_order_no,'query_price_') !== false){
            $query_order_no = str_replace('query_price_','',$query_order_no);
            $where_temp['id'] = $query_order_no;
            $parking_temp = M('House_village_parking_temp')->where($where_temp)->order('id desc')->find();
            if (isset($parking_temp['price']) && floatval($parking_temp['price']) > 0) {
                $_POST['money'] = $parking_temp['price'];
            }
            $in_record_id = isset($parking_temp['in_record_id']) && $parking_temp['in_record_id'] ? intval($parking_temp['in_record_id']) : 0;
            $out_record_id = isset($parking_temp['out_record_id']) && $parking_temp['out_record_id'] ? intval($parking_temp['out_record_id']) : 0;
            $in_time = isset($parking_temp['in_time']) && $parking_temp['in_time'] ? intval($parking_temp['in_time']) : 0;
            $query_time = isset($parking_temp['query_time']) && $parking_temp['query_time'] ? intval($parking_temp['query_time']) : 0;
        }
        if ((!isset($_POST['money'])||$_POST['money']<=0)&&$car_type == 'temporary_type') {
            if(isset($parking_temp) && $parking_temp['is_pay_scene'] == 2 && $parking_temp['park_sys_type']!='third_ai_park'){
                // todo 无牌车支付 直接进行出场
                $out_channel_id = $parking_temp['out_channel_id'];
                if(!$out_channel_id){
                    $out_channel_id = '1';
                }
                $park_system = M('Park_system')->where(array('park_id'=>$parking_temp['village_id']))->find();
                $nowtime = date("mdHis");
                $orderid = $nowtime . sprintf("%04d", $parking_temp['id']);
                $json_data['state'] = 1;
                $json_data['order_id'] = $parking_temp['order_id'];
                $json_data['service_name'] = 'outpark';
                $json_data['trade_no'] = $orderid;
                $json_data['pay_type'] = 'scancode';
                $json_data['out_channel_id'] = $out_channel_id;//通道号暂时写1
                $json_data['total'] = floatval($parking_temp['price']);
                $json_data['errmsg'] = '支付成功';
                $json_data['pay_time'] = time();
                $json_data['car_number'] = $car_number;
                $json_data['arrive_money'] = floatval($parking_temp['price']);
                $json_data['fee'] = 0.00;
                $json_data['account_type'] = 1;
                $json_data['remark'] = '收到无牌车停车费-'.$json_data['car_number'];

                $post_data['unserialize_desc'] = serialize($json_data);
                $post_data['park_id'] = $park_system['park_id'];
                $post_data['token'] = $park_system['token'];
                $post_data['service_name'] = 'outpark';
                $post_data['order_id'] = $parking_temp['order_id'] ? $parking_temp['order_id'] : '';
                $post_data['create_time'] = time();
                $post_data['car_number'] = $car_number;
                $post_data['village_id'] = $parking_temp['village_id'];
                $res = M('Park_total_record')->data($post_data)->add();
                $this->returnCodeError('当前停车未产生费用无需支付，道闸抬杆时候请通行!');
            } else {
                $this->returnCodeError('当前停车未产生费用无需支付，道闸抬杆时候请通行!');
            }
        }
        if(I('car_type') == 'month_type'){
            $data_order['month_end_time'] = I('month_end_time')?strtotime($month_end_time):'';//如果为月租车则记录到期时间
        }

        $car_id = I('car_id','', 'trim');
        $bind_car=[];
        $parking_car_single=[];
        if (!empty($car_id)) {
            $parking_car_single = D('House_village_parking_car')->where(array('car_id'=>$car_id))->find();
            if (empty($parking_car_single)) {
                $this->returnCodeError('对应车辆不存在!');
            }
            if(I('car_type') == 'month_type'){
                // 如果是月租车  传值结束时间小于等于当前时间进行拦截
                if ($parking_car_single['end_time'] && intval($parking_car_single['end_time'])>=strtotime($month_end_time)) {
                    $this->returnCodeError('月租车到期时间必须大于当前到期时间!');
                }
            }
            $bind_car = D('House_village_bind_car')->where(array('car_id'=>$car_id))->find();
        }
        /*
        if(I('car_type') == 'stored_type'){
            $park_config=M('House_village_park_config')->where(array('village_id'=>$village_id))->find();

            if (!empty($park_config)&&$park_config['park_sys_type']=='D7'&&($parking_car_single['parking_car_type']<17||$parking_car_single['parking_car_type']>20)){
                $this->returnCodeError('当前车辆非储值车类型，无法充值!');
            }
        }
        if(I('car_type') == 'month_type'){
            $park_config=M('House_village_park_config')->where(array('village_id'=>$village_id))->find();

            if (!empty($park_config)&&$park_config['park_sys_type']=='D7'&&($parking_car_single['parking_car_type']>8)){
                $this->returnCodeError('当前车辆非月租车类型，无法充值!');
            }
        }
        */
        $house_order_name=$this->config['house_name'];
        if(empty($house_order_name)){
            $house_order_name='社区';
        }
        $house_order_name=trim($house_order_name);
        $data_order['money'] = I('money') + 0;
        $data_order['order_name'] = $house_order_name.'缴费：' . $pay_name;
        $data_order['uid'] = $this->_uid ? : 0;
        $data_order['bind_id'] = 0;
        $data_order['village_id'] = $now_village['village_id'];
        $data_order['time'] = $_SERVER['REQUEST_TIME'];
        $data_order['paid'] = 0;
        $data_order['order_type'] = $pay_type;
        $data_order['car_type'] = I('car_type');
        $data_order['car_id'] = $car_id;
        $postData=array();
        $postData['order_type'] = 'park_new';
        $postData['order_name'] = '新版停车费';
        $postData['village_id'] = $village_id;
        $postData['is_paid'] = 2;
        $postData['is_prepare'] = 2;
        $postData['pay_bind_id'] = $data_order['bind_id'];
        $postData['pigcms_id'] = ($bind_car&&$bind_car['user_id'])?$bind_car['user_id']:'0';
        $postData['position_id'] = ($parking_car_single&&$parking_car_single['car_position_id'])?$parking_car_single['car_position_id']:'0';
        $postData['stored_balance'] = ($parking_car_single&&$parking_car_single['stored_balance'])?$parking_car_single['stored_balance']:'0';
        $postData['property_id'] = $now_village['property_id'];
        $postData['order_no'] = '';
        $postData['add_time'] = time();
        $postData['from'] = 0;
        $postData['rule_id'] = 0;
        $postData['project_id'] = 0;
        $park_sys_type='';
        if(I('car_type') == 'temporary_type'){
            if(empty($car_number)){
                $this->returnCodeError('车牌号不能为空!');
            }
            if (strpos($car_number,'-')!=false){
                $count=strpos($car_number,'-');
                $car_number=substr_replace($car_number,"",$count,1);
            }
            $data_order['car_number'] = $car_number;//如果是临时车,则需要传
            $data_order['order_name'].= '（ ' . $car_number . ' ）';
            
            $whereTemp = [
                'car_number' => $car_number,
                'village_id' => $village_id,
                'is_paid' => 0,
            ];
            $nowtime=time();
            $add_time_max=$nowtime+10;
            $add_time_min=$nowtime-600;
            $whereTemp['_string'] = ' (add_time>'.$add_time_min.' AND add_time<'.$add_time_max.')';
            $temp = M('House_village_parking_temp')->where($whereTemp)->field('*')->order('id DESC')->find();
            if(empty($temp)){
                $this->returnCodeError('未查到对应待支付订单!');
            }
            fdump_api( ['whereTemp'=>$whereTemp,'temp'=>$temp] ,'go_pay_0507',1);
            if(isset($temp['rule_id'])){
                $postData['rule_id'] = $temp['rule_id'];
                $postData['project_id'] = $temp['project_id'];
            }
            $park_sys_type=$temp['park_sys_type'];
            // 如果是d1查询当前记录订单金额
            //$village_park_config = M('House_village_park_config')->where(array('village_id'=>$village_id))->find();
            if ($temp && 'D1'==$temp['park_sys_type']) {
                /*
                $whereTemp = [
                    'service_name' => 'd1_query_price',
                    'car_number' => $car_number,
                    'comid' => trim($village_park_config['comid']),
                    'is_paid' => 0,
                ];
                $temp = M('House_village_parking_temp')->where($whereTemp)->field('id,order_id, price')->order('id DESC')->find();
                */
                    if ($temp['price'] && $temp['price']!=$data_order['money']) {
                        $data_order['money'] = $temp['price'];
                    }
                    if ($temp['order_id']) {
                        $data_order['third_id'] = $temp['order_id'];
                    }
  
            }
            elseif($temp && ('HXT85'==$temp['park_sys_type'] || 'D3'==$temp['park_sys_type'])){
                /*
                $whereTemp = [
                    'park_sys_type' => 'D3',
                    'car_number' => $car_number,
                    'village_id' => $village_id,
                    'is_paid' => 0,
                ];
                $temp = M('House_village_parking_temp')->where($whereTemp)->field('id,order_id, price')->order('id DESC')->find();
                */
                    if ($temp['price'] && $temp['price']!=$data_order['money']) {
                        $data_order['money'] = $temp['price'];
                    }
                    if ($temp['order_id']) {
                        $data_order['third_id'] = $temp['order_id'];
                    }
                    $info=D('House_village_car_access_record')->getTempRuleId($village_id);
                    $postData['rule_id'] = $info['id'];
                    $postData['project_id'] = $info['charge_project_id'];
                    !$in_record_id && $in_record_id = isset($temp['in_record_id']) && $temp['in_record_id'] ? intval($temp['in_record_id']) : 0;
                    !$out_record_id && $out_record_id = isset($temp['out_record_id']) && $temp['out_record_id'] ? intval($temp['out_record_id']) : 0;
                    !$in_time && $in_time = isset($temp['in_time']) && $temp['in_time'] ? intval($temp['in_time']) : 0;
                    !$query_time && $query_time = isset($temp['query_time']) && $temp['query_time'] ? intval($temp['query_time']) : 0;
 
            }
            elseif($temp && 'D6'==$temp['park_sys_type']){
                //todo D6智慧停车生成订单
                /*
                $whereTemp = [
                    'park_sys_type' => 'D6',
                    'car_number' => $car_number,
                    'village_id' => $village_id,
                    'is_paid' => 0,
                ];
                $temp = M('House_village_parking_temp')->where($whereTemp)->field('id,order_id, price')->order('id DESC')->find();
                */
                    if ($temp['price'] && $temp['price']!=$data_order['money']) {
                        $data_order['money'] = $temp['price'];
                    }
                    if ($temp['order_id']) {
                        $data_order['third_id'] = $temp['order_id'];
                    }
                    $info=D('House_village_car_access_record')->getTempRuleId($village_id);
                    $postData['rule_id'] = 0;
                    $postData['project_id'] = 0;

            }
            $whereArr=array('car_type'=>'temporary_type','car_number'=>$car_number,'uid'=>$this->_uid,'order_type'=>'park_new');
            $whereArr['village_id']=$village_id;
            $new_pay_order = D('House_new_pay_order')->field('order_id,summary_id,pay_time,add_time')->order('order_id desc')->where($whereArr)->find();
            $pre_temp_time=time()-61;
            if($new_pay_order && $new_pay_order['pay_time']<100 && $new_pay_order['add_time']>$pre_temp_time && $new_pay_order['summary_id']>0){
                $wherePlatArr=array('business_type' => 'village_new_pay', 'business_id' => $new_pay_order['summary_id']);
                $plat_order = M('Plat_order')->field('order_id')->where($wherePlatArr)->find();
                if($plat_order){
                    $order_info_where=array('business'=>'village_new_pay','business_order_id'=>$plat_order['order_id']);
                    $pay_order_info=M('Pay_order_info')->field('orderid,addtime')->where($order_info_where)->find();
                    if($pay_order_info && $pay_order_info['orderid']){
                        $this->returnCodeError('您已经在'.$pay_order_info['addtime'].'发起的支付正在支付中，请勿重复支付！');
                    }
                }
                
            }elseif($new_pay_order && $new_pay_order['pay_time']>100 && $new_pay_order['add_time']>$pre_temp_time){
                $this->returnCodeError('您已经在'.date('Y-m-d H:i:s',$new_pay_order['pay_time']).'支付过一笔金额是'.$new_pay_order['pay_money'].'元的车费订单了，请勿重复支付！');
            }
            $whereArr=array('car_type'=>'temporary_type','car_number'=>$car_number,'uid'=>$this->_uid,'order_type'=>'park_new');
            $whereArr['village_id']=$village_id;
            $new_pay_order = D('House_new_pay_order')->field('order_id,summary_id,pay_time,add_time')->order('order_id desc')->where($whereArr)->find();
            $pre_temp_time=time()-61;
            if($new_pay_order && $new_pay_order['pay_time']<100 && $new_pay_order['add_time']>$pre_temp_time && $new_pay_order['summary_id']>0){
                $wherePlatArr=array('business_type' => 'village_new_pay', 'business_id' => $new_pay_order['summary_id']);
                $plat_order = M('Plat_order')->field('order_id')->where($wherePlatArr)->find();
                if($plat_order){
                    $order_info_where=array('business'=>'village_new_pay','business_order_id'=>$plat_order['order_id']);
                    $pay_order_info=M('Pay_order_info')->field('orderid,addtime')->where($order_info_where)->find();
                    if($pay_order_info && $pay_order_info['orderid']){
                        $this->returnCodeError('您已经在'.$pay_order_info['addtime'].'发起的支付正在支付中，请勿重复支付！');
                    }
                }
                
            }elseif($new_pay_order && $new_pay_order['pay_time']>100 && $new_pay_order['pay_time']>$pre_temp_time){
                $this->returnCodeError('您已经在'.date('Y-m-d H:i:s',$new_pay_order['pay_time']).'支付过一笔金额是'.$new_pay_order['pay_money'].'元的车费订单了，请勿重复支付！');
            }
            if($temp['park_sys_type']=='third_ai_park'){
                $postData['order_type_flag']='third_ai_park_order';
                 //去下单
                $thirdAiParkOrder = D('ParkService')->thirdAiParkOrderPayCreate($temp);
                if(empty($thirdAiParkOrder) || !isset($thirdAiParkOrder['data']) || !isset($thirdAiParkOrder['data']['payOrderNo'])){
                    $err_msg = '下单请求失败！';
                    if(!empty($thirdAiParkOrder) && isset($thirdAiParkOrder['err_msg']) && $thirdAiParkOrder['err_msg']){
                        $err_msg= $thirdAiParkOrder['err_msg'];
                    }
                    $this->returnCodeError($err_msg);
                }else{
                    $extra_data =$thirdAiParkOrder['data'];
                    $parkKey = $temp['comid'] ? $temp['comid'] : $temp['token'];
                    $extra_data['parkKey']=$parkKey;
                    $extra_data['ctrlNo']= $temp['out_channel_id'];
                    $extra_data['orderNo']= $temp['order_id'];
                    $extra_data['parking_temp_id']=$temp['id'];
                    $postData['extra_data']=json_encode($extra_data,JSON_UNESCAPED_UNICODE);
                    $postData['order_no'] = $thirdAiParkOrder['data']['payOrderNo'];
                    $postData['order_serial']= $thirdAiParkOrder['data']['payOrderNo'];
                }
            }
        }
        elseif(I('car_type') == 'month_type'){
            $rule_info = M('house_new_charge_rule')->where(array('id'=>I('rule_id')))->field('*')->find();
            $postData['position_id']=$position_id ? $position_id:0;
            $postData['rule_id'] = $rule_info['id'];
            $postData['project_id'] = $rule_info['charge_project_id'];
            $standard_info = M('House_new_charge_standard_bind')->where(array('rule_id'=>$rule_info['id'],'position_id'=>$postData['position_id']))->field('*')->find();
            if(empty($standard_info) ){
                $standard_info=array();
                $standard_info['cycle']=$rule_info['cyclicity_set'];
                if($rule_info['fees_type']==4){
                    $standard_info['cycle']=$rule_info['park_charge_id'];
                }
            }
            $cycle=!empty($standard_info) && $standard_info['cycle'] ?$standard_info['cycle']:1 ;
            $postData['service_month_num'] =$cycle;
            $start_time=$start_date ? strtotime($start_date):0;
            $service_start_time = strtotime(date('Y-m-d 00:00:00'));
            if($start_time>100){
                $service_start_time=$start_time;
            }
            $postData['service_start_time'] = $service_start_time;
            $data_order['money']=$rule_info['unit_price']*$cycle;
            if($rule_info['bill_create_set'] == 1){
                $postData['service_end_time'] = $postData['service_start_time']+86400*$cycle-1;
            }elseif ($rule_info['bill_create_set'] == 2){
                //todo 判断是不是按照自然月来生成订单
                if(C('config.open_natural_month') == 1){
                    $postData['service_end_time'] = strtotime("+$cycle month",$postData['service_start_time'])-1;
                }else{
                    $cycle = $cycle*30;
                    $postData['service_end_time'] = strtotime("+$cycle day",$postData['service_start_time'])-1;
                }
            }else{
                $postData['service_end_time'] = strtotime("+$cycle year",$postData['service_start_time'])-1;
            }
            fdump_api([I('car_type'),$postData],'go_pay_0507',1);
            $bind_info = M('House_village_bind_car')->where(array('car_id'=>$car_id,'village_id'=>$village_id))->order('id desc')->field('*')->find();
            if(!empty($bind_info)){
                $user_info = M('house_village_user_bind')->where(array('pigcms_id'=>$bind_info['user_id']))->field('*')->find();
                if (!empty($user_info)){
                    $postData['pigcms_id'] = $user_info['pigcms_id']?$user_info['pigcms_id']:0;
                    $postData['name'] = $user_info['name']?$user_info['name']:'';
                    $postData['phone'] = $user_info['phone']?$user_info['phone']:'';
                    if($user_info['vacancy_id']>0){
                        $postData['room_id'] =$user_info['vacancy_id'];
                    }
                }
            }

        }

        //临时车停车可以不用登录
        if($this->_uid){
            $postData['uid']=$this->_uid;
            $userinfo =  D('User')->get_user($this->_uid);

            $postData['pay_bind_name'] = $userinfo['name']?$userinfo['name']:'';
            $postData['pay_bind_phone'] = $userinfo['phone']?$userinfo['phone']:'';
        }
        $postData['total_money'] = $data_order['money'];
        $postData['modify_money'] = $data_order['money'];
        $postData['unit_price'] = $data_order['money'];
        $postData['car_type'] = I('car_type');
        $postData['car_number'] = (!$car_number&&$parking_car_single)?$parking_car_single['province'].$parking_car_single['car_number']:$car_number;
        $postData['car_id'] = $car_id;
        fdump_api([$postData],'go_pay_0507',1);
        $order_id= D('House_new_pay_order')->data($postData)->add();
        if($order_id){
            $summaryData['uid'] = isset($postData['uid'])?$postData['uid']:0;
            $summaryData['pay_uid'] = isset($postData['uid'])?$postData['uid']:0;
            $summaryData['order_no'] =$postData['order_no'] ? $postData['order_no']: build_real_orderid($summaryData['uid']);
            $summaryData['total_money'] = $data_order['money'];
            $summaryData['is_paid'] = 2;
            $summaryData['pay_type'] = 4;
            $summaryData['is_online'] = 1;
            $summaryData['village_id'] = $village_id;
            $summaryData['pay_bind_id'] = $data_order['bind_id'];
            $summaryData['pigcms_id'] = $postData['pigcms_id'];
            $summaryData['position_id'] = $postData['position_id'];
            $summaryData['property_id'] = $now_village['property_id'];
            if (I('car_type') == 'month_type'){
                $summaryData['position_id'] = $postData['position_id'];
                $summaryData['pigcms_id'] = $user_info['pigcms_id']?$user_info['pigcms_id']:0;
                $summaryData['name'] = $user_info['name']?$user_info['name']:'';
                $summaryData['phone'] = $user_info['phone']?$user_info['phone']:'';
            }
            $summary_order_id = D('House_new_pay_order_summary')->data($summaryData)->add();
            fdump_api([$summary_order_id,$summaryData],'go_pay_0507',1);
            if ($summary_order_id){
                D('House_new_pay_order')->where(array('order_id' => $order_id))->data(['summary_id'=>$summary_order_id,'pay_type'=>4])->save();
            }
            $recordIds = [];
            if (isset($in_record_id) && $in_record_id) {
                $recordIds[] = $in_record_id;
            }
            if (isset($out_record_id) && $out_record_id) {
                $recordIds[] = $out_record_id;
            }
            if (! empty($recordIds)) {
                $whereRecord = [
                    'record_id' => ['in', $recordIds]
                ];
                M('House_village_car_access_record')->where($whereRecord)->data(array('pay_order_id' => $summary_order_id, 'update_time' => time()))->save();
            } else if($park_sys_type!='third_ai_park') {
                $whereInPark = array('car_number'=>$car_number,'village_id'=>$village_id,'is_paid'=>0,'is_out'=>0);
                $in_park_id = D('In_park')->where($whereInPark)->getField('id');
                if (!empty($car_number)&&!empty($village_id) && $in_park_id){
                    D('In_park')->where($whereInPark)->data(array('pay_order_id' => $summary_order_id))->save();
                    $whereRecord = [
                        'car_number'    => $car_number, 'park_id' => $village_id,
                        'accessType'    => 1, 'from_id' => $in_park_id
                    ];
                    $in_park_info = M('House_village_car_access_record')->where($whereRecord)->find();
                    if (empty($in_park_info) && ($query_time || $in_time)) {
                        !$in_time && $in_time = $query_time;
                        $starttime = $in_time - 30;
                        $endtime = $in_time + 30;
                        $whereRecord = [
                            'car_number' => $car_number, 'park_id' => $village_id, 'accessType' => 1,
                        ];
                        $whereRecord['accessTime'] = array('between',array($starttime,$endtime));
                        $in_park_info = M('House_village_car_access_record')->where($whereRecord)->order('accessTime DESC')->find();
                    }
                    if (! empty($in_park_info)) {
                        M('House_village_car_access_record')->where(['record_id' => $in_park_info['record_id']])->data(array('pay_order_id' => $summary_order_id))->save();
                    }
                }
            }
            //添加到订单，直接支付
           // $now_order = D('House_village_pay_order')->field(true)->where(array('order_id' => $order_id))->find();
            $now_order = D('House_new_pay_order')->field(true)->where(array('order_id' => $order_id))->find();
            $pay_order_param = array(
                'business_type' => 'village_new_pay',
                'business_id' => $summary_order_id,
                'order_name' => $now_order['order_name'],
                'uid' => $now_order['uid'],
                'total_money' => $data_order['money'],
                'wx_cheap' => 0,
            );
            if ($this->config['open_village_sub_mchid'] && $now_village['sub_mch_id']) {
                $pay_order_param['is_own'] = 5;
            } else {
                $pay_order_param['is_own'] = 4;
            }
            $plat_order_result = D('Plat_order')->add_order($pay_order_param);
            fdump_api([$plat_order_result,$pay_order_param],'go_pay_0507',1);
            if ($plat_order_result['error_code']) {
                $this->returnCodeError($plat_order_result['error_msg']);
            }
            $base_url = D('House_village')->base_url;
            $arr['type'] = 'village_new_pay';
            $arr['order_id'] = $plat_order_result['order_id'];
            $arr['order_url'] = $this->config['site_url'] . $base_url . 'pages/pay/check?order_id=' . $plat_order_result['order_id'] . '&order_type=village_new_pay';
            fdump_api([$plat_order_result,$pay_order_param],'go_pay_0507',1);
            $this->returnCode(0, $arr);

        } else {
            $this->returnCode('40000002');
        }
    }


    public function get_adver_info()
    {
