        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $arr = [];
        $adver_village = M('Adver_village')->where(array('village_id'=>$village_id,'status'=>1))->select();
        if(empty($adver_village)){
            $arr['url'] = '';
