        }

        $this->returnCode(0, $arr);
    }


    /**
     * 无牌车入场
     */
    public function nolicence_in_park()
    {
        if (empty($this->_uid)) {
            //临时用户特殊处理
            if(empty($_POST['tmp_ticket'])){
                $this->returnCode('20000009');
            }
            $info = ticket::get($_POST['tmp_ticket'], $this->DEVICE_ID, true);
            if ($info) {
                $this->_uid = 900000000 + $info['uid'];
            }
            if (empty($this->_uid)) {
                $this->returnCode('20000009');
            }
        }

        $village_id = I('village_id');
        if (empty($village_id)) {
            $this->returnCode('30000001');
        }
        $channel_id = I('channel_id','0');
        if(!isset($_POST['channel_id'])){
            $this->returnCodeError('通道id不存在!');
        }
        $where_passage = [];
        $where_passage['channel_number'] = $channel_id;
        $where_passage['village_id'] = $village_id;
        $res = M('Park_passage')->where($where_passage)->find();
        if(empty($res)){
            $this->returnCodeError('通道异常!');
        }
        $park_system = M('Park_system')->where(array('park_id'=>$village_id))->find();
        if(empty($park_system)){
            $this->returnCodeError('该停车配置有误');
        }
        // 随机八位数 数字和大写字母组合
        $car_number = '临'.createRandomStr(7,false,false,true);
        $where_replace = [
            'car_number' => $car_number,
            'is_out_park' => 0,
            'village_id' => $village_id,
        ];
        $replace_car = M('nolicence_in_park')->where($where_replace)->find();
        while($replace_car)
        {
            // 去除和在停车存在重复问题
            $car_number = '临'.createRandomStr(7,false,false,true);
            $where_replace['car_number'] = $car_number;
            $replace_car = M('nolicence_in_park')->where($where_replace)->find();
        }

        $data['uid'] = $this->_uid;
        $data['car_number'] = $car_number;
        $data['is_out_park'] = 0;
        $data['token'] = $park_system['token'];
        $data['village_id'] = $village_id;
        $data['park_id'] = $park_system['park_id'];
        $data['channel_id'] = $channel_id;
        $data['is_in_park'] = 0;
        $add = M('Nolicence_in_park')->data($data)->add();
        if($add){
            $json_data['service_name'] = 'nolicence_in_park';
            $json_data['car_number'] = $car_number;//车牌
            $json_data['park_id'] = $park_system['park_id'];
            $json_data['channel_id'] = $channel_id;
            $json_data['timetemp'] = time();

            $post_data['unserialize_desc'] = serialize($json_data);
            $post_data['park_id'] = $park_system['park_id'];
            $post_data['token'] = $park_system['token'];
            $post_data['service_name'] = 'nolicence_in_park';
            $post_data['create_time'] = time();
            $post_data['village_id'] = $village_id;
            $post_data['car_number'] = $car_number;

            $park_total_record = M('Park_total_record')->data($post_data)->add();//无牌车
            fdump_api([__LINE__,'add_id'=>$add,'park_total_record_id'=>$park_total_record,'post_data'=>$post_data],'park/'.$village_id.'/nolicence_in_park',1);
            if($park_total_record){
                // 将现存的自身无牌车出场
                $where_no = [
                    'uid' => $this->_uid,
                    'park_id' => $park_system['park_id'],
                    'token' =>  $park_system['token'],
                    'is_out_park' => 0,
                    'id' => array('neq', $add)
                ];
                $save_no = [
                    'is_out_park' => 1
                ];
                M('Nolicence_in_park')->where($where_no)->data($save_no)->save();
                $ret = [];
                $ret['errorCode'] = 0;
                $ret['errorMsg'] = '';
                $ret['car_number'] = $car_number;
                $ret['village_id'] = $village_id;
                $ret['channel_id'] = $channel_id;
                $this->returnCode(0, $ret);
            }else{
                $this->returnCodeError('入场信息错误,请联系工作人员处理入场');
            }

        }else{
            $this->returnCodeError('入场信息错误,请联系工作人员处理入场');
        }
    }

    /**
     * 计算出两个日期之间的月份
     * @author Eric
     * @param  [type] $start_date [开始日期，如2014-03]
     * @param  [type] $end_date   [结束日期，如2015-12]
     * @param  string $explode    [年份和月份之间分隔符，此例为 - ]
     * @param  boolean $addOne    [算取完之后最后是否加一月，用于算取时间戳用]
     * @return [type]             [返回是两个月份之间所有月份字符串]
     */
    public function dateMonths($start_date,$end_date,$explode='-',$addOne=false){
        //判断两个时间是不是需要调换顺序
        $start_int = strtotime($start_date);
        $end_int = strtotime($end_date);
        if($start_int > $end_int){
            $tmp = $start_date;
            $start_date = $end_date;
            $end_date = $tmp;
        }


        //结束时间月份+1，如果是13则为新年的一月份
        $start_arr = explode($explode,$start_date);
        $start_year = intval($start_arr[0]);
        $start_month = intval($start_arr[1]);


        $end_arr = explode($explode,$end_date);
        $end_year = intval($end_arr[0]);
        $end_month = intval($end_arr[1]);


        $data = array();
        $data[] = strtotime($start_date);


        $tmp_month = $start_month;
        $tmp_year = $start_year;


        //如果起止不相等，一直循环
        while (!(($tmp_month == $end_month) && ($tmp_year == $end_year))) {
            $tmp_month ++;
            //超过十二月份，到新年的一月份
            if($tmp_month > 12){
                $tmp_month = 1;
                $tmp_year++;
            }
            $data[] = strtotime($tmp_year.$explode.str_pad($tmp_month,2,'0',STR_PAD_LEFT));
        }


        if($addOne == true){
            $tmp_month ++;
            //超过十二月份，到新年的一月份
            if($tmp_month > 12){
                $tmp_month = 1;
                $tmp_year++;
            }
            $data[] = $tmp_year.$explode.str_pad($tmp_month,2,'0',STR_PAD_LEFT);
        }


        return $data;
    }

    /**
     * 计算物业费
     * @author lijie
     * @date_time 2020/07/20 15:48
     * @param $dateMonths
     * @param $chargingStandard
     * @param $housesize
     * @return float|int
     */
    public function property_price($dateMonths,$chargingStandard,$housesize)
    {
        $property_price = 0;
        foreach ($dateMonths as $value){
            foreach ($chargingStandard as $v){
                if($value >= strtotime($v['date_month'])){
                    $price = $v['price'];
                }
            }
            if(isset($price)){
                $property_price += $price*$housesize;
            }
            unset($price);
        }
        return $property_price;
    }

    /**
     * 获取预缴物业费的费用
     * @author lijie
     * @date_time 2020/07/27
     * @param $chargingStandard
     * @param $housesize
     * @param $month
     * @param $num
     * @return float|int
     */
    public function get_all_fee($chargingStandard,$housesize,$month,$num)
    {
        foreach ($chargingStandard as $value){
            if(strtotime($value['date_month']) <= $month){
                $price = $value['price'];
            }
        }
        $property_price = $price*$housesize*$num;
        return $property_price;
    }

    /**
     * 获取当月物业费收费标准
     * @author lijie
     * @date_time 2020/07/30
     * @param $chargingStandard
     * @param $month
     * @return mixed
     */
    public function get_now_property_fee($chargingStandard,$month)
    {
        foreach ($chargingStandard as $value) {
            if (strtotime($value['date_month']) <= $month) {
                $price = $value['price'];
            }
        }
        return isset($price) ? $price : 0;
    }

