    /**物料领取者确认*/
    public function checkout_list() {
        $receive_id = I('receive_id');
        if (empty($receive_id)) {
            $this->returnCodeError('请使用正确工作人员身份进入');
        }
        $where = array(
            'mc.receive_type' => 0,
            'mc.receive_id' => $receive_id,
        );
        $d_materiel_checkout = M('Materiel_checkout');
        $count = $d_materiel_checkout->join('as mc LEFT JOIN '.C('DB_PREFIX').'materiel_type_msg as mt ON mc.type_id=mt.type_id')->where($where)->count();
        if (!$_GET['page'] && $_POST['page']) {
            $_GET['page'] = $_POST['page'];
        }
        $pageSize = 20;
        $totalPage = ceil($count / $pageSize);
        if ($_GET['page'] > $totalPage) {
            $list = array();
        } else {
            import('@.ORG.merchant_page');
            $p = new Page($count, $pageSize, 'page');
            $field = "mc.id,mc.receive_type,mc.receive_id,mc.receive_name,mc.receive_phone,mc.receive_num,mc.receive_time,mc.remark,mc.confirm_status,mc.confirm_time,mc.add_time,mc.last_time,mt.type_name";
            $list = $d_materiel_checkout->join('as mc LEFT JOIN '.C('DB_PREFIX').'materiel_type_msg as mt ON mc.type_id=mt.type_id')->field($field)->where($where)->order('`id` DESC')->limit($p->firstRow . ',' . $p->listRows)->select();
            if($list){
                foreach ($list as &$v){
                    $v['receive_time']=date('Y-m-d H:i:s',$v['receive_time']);
                }
                unset($v);
            }
        }
        $arr = array(
            'count' => $count,
            'totalPage' => $totalPage,
            'page' => $_GET['page'],
            'list' => $list
        );
        $this->returnCode(0, $arr);
    }

    public function confirm_checkout() {
        $receive_id = I('receive_id');
        if (empty($receive_id)) {
            $this->returnCodeError('请使用正确工作人员身份进入');
        }
        $id = I('id');
        if (empty($id)) {
            $this->returnCodeError('请选择确认对象');
        }
        $d_materiel_checkout = M('Materiel_checkout');
        $checkout_info = $d_materiel_checkout->where(array('id' => $id,'receive_id' => $receive_id))->find();
        if (empty($checkout_info)) {
            $this->returnCodeError('确认对象不存在或者错误');
        } elseif ($checkout_info['confirm_status'] == 1) {
            $this->returnCodeError('该对象已经被确认');
        }
        $data = array(
            'confirm_status' => 1,
            'confirm_time' => time(),
        );
        $save_id = $d_materiel_checkout->where(array('id' => $id,'receive_id' => $receive_id))->data($data)->save();
        if (!$save_id) {
            $this->returnCodeError('操作失败！请重试~');
        }
        $arr = array(
            'id' => $save_id
        );
        $this->returnCode(0, $arr);

    }

