     */
    public function getTopWeatherTrafficInfo(){
        $village_id = I('village_id', 0, 'intval');
        // 获取小区信息
        $village_info = D('House_village')->get_village_info($village_id,'area_id');
        // 获取小区地址信息
        $area_name = D('Area')->name($village_info['area_id']);
        // 汉字全转拼音
        $pinyin = invoke_v20_service('\app\community\model\service\AreaService/getAreaPinYin',[$area_name]);

        $weather = '';
        $temperature = '';
        if(isset($pinyin['data']['retval']) && !empty($pinyin['data']['retval'])){
            $url = 'https://o2o-service.pigcms.com/weather.php?location='.$pinyin['data']['retval'];
            $res = httpRequest($url);
            $result = json_decode($res[1],true);
            if(!$result['error']){
                $weather = '今日'.$result['result']['cond_txt'];
                $temperature = $result['result']['tmp'].'℃';
            }
        }
        $data = [
            'weather' => $weather,
            'temperature' => $temperature,
            'traffic' => [
                'title' => '车辆限行',
                'limit_number' => '',
            ]
        ];
        $this->returnCode(0, $data);
    }

    /**
