     * Time: 19:42
     */
    public function getVillageGuessLikeStoreList(){
        $village_id = I('village_id', 0, 'intval');
        $guess_like_id = I('guess_like_id', 0, 'intval');

        $order = 'juli';
        $deliver_type = 'all';
        $lat = isset($_POST['lat']) ? htmlspecialchars($_POST['lat']) : 0;
        $long = isset($_POST['lng']) ? htmlspecialchars($_POST['lng']) : (isset($_POST['long']) ? htmlspecialchars($_POST['long']) : 0);
        $is_search = 0;
        $page = I('page', 0, 'intval');
        $search_type = '';
        $specialUrl = '';
        $limit = 6;
        // 检查猜你喜欢标题栏 参数是否正确
        $res = D('House_village_guess_like')->where(array('id' => $guess_like_id))->find();
        if (empty($res)){
            $this->returnCode(1001, $res,'猜你喜欢标题导航栏参数错误');
        }
        if($res['status'] == 0){
            $this->returnCode(1001, $res,'该标题导航栏已被禁用');
        }
        if($res['is_del'] == 1){
            $this->returnCode(1001, $res,'该标题导航栏已被删除');
        }

        $this->send_time_type = [
            L_('分钟'),
            L_('小时'),
            L_('天'),
            L_('周'),
            L_('月'),
        ];
        // 获取所有的店铺ID
        $store = D('House_village_guess_like_store')->where(array('guess_like_id' => $guess_like_id))->field('store_id')->select();
        $store_ids = array_column($store,'store_id');

        $merchantStoreShopDB = D('Merchant_store_shop');
        $where = array('deliver_type' => $deliver_type, 'order' => $order, 'lat' => $lat, 'long' => $long, 'page' => $page, 'search_type'=>$search_type,'special' => $specialUrl);
        $store_ids && $where['store_ids'] = $store_ids;
        $limit && $where['limit'] = 0;
        $where['show_method'] = 1;

        /*获取自营商家下的店铺*/
        if(C('config.open_kefu_url') && C('config.kefu_mer_id')>0){
            $store_arr=M('Merchant_store')->where(array('mer_id'=>C('config.kefu_mer_id')))->getField('store_id',true);
        }

        // 店铺分类
        $database_shop_category = D('Shop_category');
        $category_list = $database_shop_category->lists();

        $return = array();
        $lists = $merchantStoreShopDB->get_list_by_option($where,1,$is_search,$limit,true);
        foreach ($lists['shop_list'] as $row) {
            $temp = array();
            $temp['store_id'] = $row['store_id'];
            $temp['jdlq'] = $row['jdlq'];
            if(is_array($store_arr) && in_array($temp['store_id'], $store_arr)){
                $temp['is_self']=1;
            }else{
                $temp['is_self']=0;
            }
            $temp['name'] = html_entity_decode($row['name'], ENT_QUOTES);
            $temp['store_theme'] = $row['store_theme'];
            $temp['isverify'] = $row['isverify'];
            $temp['extra_price'] = $row['extra_price'];
            $temp['juli_wx'] = $row['juli'];
            $temp['range'] = $row['range'];
            $temp['image'] = $row['image'];
            if($row['logo']){
                $temp['image'] = replace_file_domain($row['logo']);
            }
            $temp['image'] = thumb_img($temp['image'],180,120,'fill');

            $temp['star'] = number_format($row['score_mean'],1);
            if($temp['star'] == '0.0'){
                $temp['star'] = '5.0';
            }
            $temp['month_sale_count'] = $row['sale_count'] + $row['virtual_sale_count'];
            $temp['shop_fitment_color'] = $row['shop_fitment_color'] ? $row['shop_fitment_color'] : '113533';			//背景色
            $temp['shop_fitment_front_color'] = 'ffffff';		//标题色
            $temp['is_new'] = ($row['create_time'] + 864000) < time() ? 0 : 1;
            $temp['delivery'] = $deliver_type == 'pick' ? 0 : $row['deliver'];//是否支持配送
            $temp['delivery'] = $temp['delivery'] ? true : false;
            $temp['delivery_time'] = $row['send_time'];//配送时长
            $temp['send_time_type'] = $row['send_time_type'];
            $temp['delivery_time_type'] = $this->send_time_type[$row['send_time_type']];
            $temp['delivery_price'] = getFormatNumber($row['basic_price']);//起送价
            $temp['delivery_money'] = getFormatNumber($row['delivery_fee']) ?: '0';//配送费
            $temp['delivery_system'] = $row['deliver_type'] == 0 || $row['deliver_type'] == 3 ? true : false;//是否是平台配送
            $temp['is_close'] = 1;
            $temp['deliver_type'] = $row['deliver_type'];
            if ($merchantStoreShopDB->checkTime($row)) {
                $temp['is_close'] = 0;
            }
            $temp['is_close'] = $temp['is_close'] ? $temp['is_close'] : $row['is_close'];
            $temp['time'] = $merchantStoreShopDB->getBuniessName($row);

            $temp['check_age_object'] = array();
            $temp['check_age_object']['age_tips_status0'] = 0;//0=正常 1=重新输入生日 2=未达到法定年龄
            $temp['check_age_object']['age_tips0'] = L_('澳洲法律规定X1岁以下的未成年人不能抽烟、喝酒，如果要购买烟酒类商品必须出示身份证件证明自己已满X1周岁。',$row['age_limit_buy']);
            $temp['check_age_object']['age_tips_title0'] = L_('您已达到购买烟酒产品法定年龄');
            $temp['check_age_object']['age_tips_status1'] = 1;//0=正常 1=重新输入生日 2=未达到法定年龄
            $temp['check_age_object']['age_tips1'] = L_('您购买的是烟酒类产品，所以我们需要确认您的年龄需满X1周岁或者以上。在递送时，您有可能被要求出示相关证件。',$row['age_limit_buy']);
            $temp['check_age_object']['age_tips_title1'] = L_('请输入您的生日信息');
            $temp['check_age_object']['age_tips_status2'] = 2;//0=正常 1=重新输入生日 2=未达到法定年龄
            $temp['check_age_object']['age_tips2'] = L_('澳洲法律规定X1岁以下的未成年人不能抽烟、喝酒，如果要购买烟酒类商品必须出示身份证件证明自己已满X1周岁。',$row['age_limit_buy']);
            $temp['check_age_object']['age_tips_title2'] = L_('您未达到购买烟酒产品法定年龄');
            $temp['check_age_object']['age_limit_buy'] = $row['age_limit_buy'];
            $temp['check_age_object']['check_age'] = false;//是否判断用户年龄
            if($row['age_limit_buy_switch'] == 1 && $row['age_limit_buy'] > 0){ // 1=开启验证
                $temp['check_age_object']['check_age'] = true;
            }

            if($is_search){
                $temp['goods_list'] = $row['goods_list'] ? $row['goods_list'] : array();
            }

            if($where['key']){
                $temp['name_arr'] = $row['name_arr'];
            }

            $temp['coupon_list'] = array();
            if ($row['is_invoice']) {
                $temp['coupon_list']['invoice'] = floatval($row['invoice_price']);
            }
// 			$temp['coupon_list']['isdiscountgoods'] = 0;
            if ($row['isDiscountGoods']) {
                $temp['coupon_list']['isdiscountgoods'] = 1;
            }
            if ($row['isdiscountsort']) {//店铺的商品分类折扣
                $temp['coupon_list']['isdiscountsort'] = 1;
            }
            if ($row['store_discount'] != 0 && $row['store_discount'] != 100) {
                $temp['coupon_list']['discount'] = $row['store_discount']/10;
            }
            $system_delivery = array();
            foreach ($row['system_discount'] as $row_d) {
                if ($row_d['type'] == 0) {//新单
                    $temp['coupon_list']['system_newuser'][] = array('money' => floatval($row_d['full_money']), 'minus' => floatval($row_d['reduce_money']),'order_count'=>$row_d['order_count'],'percentage_status'=>$row_d['percentage_status'],'usage_scenario'=>$row_d['usage_scenario']);
                } elseif ($row_d['type'] == 1) {//满减
                    $temp['coupon_list']['system_minus'][] = array('money' => floatval($row_d['full_money']), 'minus' => floatval($row_d['reduce_money']),'order_count'=>$row_d['order_count'],'percentage_status'=>$row_d['percentage_status'],'usage_scenario'=>$row_d['usage_scenario']);
                } elseif ($row_d['type'] == 2) {//配送
                    if ($row_d['full_money'] >= 0 && $row_d['reduce_money'] > 0) {
                        //$system_delivery[] = array('money' => floatval($row_d['full_money']), 'minus' => floatval($row_d['reduce_money']),'order_count'=>$row_d['order_count'],'percentage_status'=>$row_d['percentage_status']);
                        $temp['coupon_list']['system_minus'][] = array('money' => floatval($row_d['full_money']), 'minus' => floatval($row_d['reduce_money']),'order_count'=>$row_d['order_count'],'percentage_status'=>$row_d['percentage_status'],'type'=>$row_d['type'],'usage_scenario'=>$row_d['usage_scenario']);
                    }
                }
            }

            foreach ($row['merchant_discount'] as $row_m) {
                if ($row_m['type'] == 0) {
                    $temp['coupon_list']['newuser'][] = array('money' => floatval($row_m['full_money']), 'minus' => floatval($row_m['reduce_money']));
                } elseif ($row_m['type'] == 1) {
                    $temp['coupon_list']['minus'][] = array('money' => floatval($row_m['full_money']), 'minus' => floatval($row_m['reduce_money']));
                }
            }

            if ($row['deliver']) {
                if ($temp['delivery_system']) {
                    $system_delivery && $temp['coupon_list']['delivery'] = $system_delivery;
                } else {
                    if ($row['is_have_two_time']) {
                        if ($row['reach_delivery_fee_type2'] == 0) {
                            if ($row['basic_price'] > 0 && $row['delivery_fee2'] > 0) {
                                $temp['coupon_list']['delivery'][] = array('money' => floatval($row['basic_price']), 'minus' => floatval($row['delivery_fee2']));
                            }
                        } elseif ($row['reach_delivery_fee_type2'] == 1) {
                            //$temp['coupon_list']['delivery'] = array('money' => false, 'minus' => $row['delivery_fee']);
                        } elseif ($row['reach_delivery_fee_type2'] == 2) {
                            $row['delivery_fee2'] && $temp['coupon_list']['delivery'][] = array('money' => floatval($row['no_delivery_fee_value2']), 'minus' => floatval($row['delivery_fee2']));
                        }
                    } else {
                        if ($row['reach_delivery_fee_type'] == 0) {
                            if ($row['basic_price'] > 0 && $row['delivery_fee'] > 0) {
                                $temp['coupon_list']['delivery'][] = array('money' => floatval($row['basic_price']), 'minus' => floatval($row['delivery_fee']));
                            }
                        } elseif ($row['reach_delivery_fee_type'] == 1) {
                            //$temp['coupon_list']['delivery'] = array('money' => false, 'minus' => $row['delivery_fee']);
                        } elseif ($row['reach_delivery_fee_type'] == 2) {
                            $row['delivery_fee'] && $temp['coupon_list']['delivery'][] = array('money' => floatval($row['no_delivery_fee_value']), 'minus' => floatval($row['delivery_fee']));
                        }
                    }
                }

                // 平台免配送费设置
                if ($row['deliver_discount']) {
                    $temp['coupon_list']['delivery_free'] = $row['deliver_discount'];
                    $temp['deliver_discount'] = $row['deliver_discount'];
                }
            }
            $temp['coupon_count'] = count($temp['coupon_list']);

            $shop_new = new Shop_newAction();
            $temp['coupon_list'] = $shop_new->simpleParseCoupon($temp['coupon_list'],'array');

            //增加满赠活动
            $activity = D('Store_full_gift_activity')->getCurrentActivityByStoreId($row['store_id']);
            if ($activity) {
                $setting = D('Store_full_gift_activity')->getSettingByActivityId($activity['id']);
                if ($setting) {
                    if($setting[0]['full_price'] > 0){
                        array_push($temp['coupon_list'], ['type' => 'full_gift', 'text' => L_('满') . C('config.Currency_symbol') . $setting[0]['full_price'] . L_('得赠品')]);
                    }else{
                        array_push($temp['coupon_list'], ['type' => 'full_gift', 'text' => L_('下单得赠品')]);
                    }
                }
            }

            $temp['deliver_name'] = isset($this->config['deliver_name']) && !empty($this->config['deliver_name']) ? $this->config['deliver_name'] : L_('平台配送');

            // 显示描述 所属分类
            if ($row['preference_desc']) {
                // 优选 主推描述
                $temp['preference_desc'] = $row['preference_desc'];
            }else{
                // 前三子分类
                $condition_shop_category['store_id'] = $row['store_id'];
                $relation_ids = array_column(D('Shop_category_relation')->field(true)->where($condition_shop_category)->select(), 'cat_id') ;
                $category_arr = array();
                $index = 0;
                foreach ($category_list as $_cate) {
                    if ($index>=3) {
                        break;
                    }
                    foreach ($_cate['son_list'] as $_sub_cate) {
                        if ($index>=3) {
                            break;
                        }
                        if (in_array($_sub_cate['cat_id'], $relation_ids)) {
                            $index ++;
                            $category_arr[] = $_sub_cate['cat_name'];
                        }
                    }
                }
                $temp['category_arr'] = $category_arr;
            }

            $temp['next_date']  = (object)array();//下一阶段营业时间
            $temp['is_advance'] = false;

            if($temp['is_close']){
                $next_date = D('Merchant_store_open_time')->get_next_time($temp['store_id']);
                $temp['next_date'] = $next_date;
                if($next_date['type']<>3){
                    $temp['is_advance'] = true;
                }
            }
            $temp['current_liveshow_id'] = $row['current_liveshow_id'];

            // 店铺跳转地址
            if($res['store_type'] == 0){
                // 外卖店铺
                $temp['url'] = $this->config['site_url'].'/packapp/plat/pages/shop_new/shopDetail/shopDetail?store_id='.$row['store_id'];
            }else{
                // 非外卖
                $temp['url'] = $this->config['site_url'].'/packapp/platn/pages/store/v1/home/index?store_id='.$row['store_id'];
            }

            $return[] = $temp;

            //热门关键词
            $tmp_key = explode(' ',$row['search_keywords']);
            if(!empty($tmp_key)){
                foreach($tmp_key as $key=>$value){
                    if(empty($value)){
                        unset($tmp_key[$key]);
                    }
                }
            }
            if(!empty($tmp_key)){
                $hot_keywords = array_unique(array_merge($hot_keywords,$tmp_key));
            }
        }
        $this->returnCode(0, $return);
    }

    /**
     * 处理多宫格数据列表
     * User: zhanghan
     * Date: 2022/2/8
     * Time: 17:51
     * @param $village_id
     * @param $grid
     * @return array|mixed
     */
    public function dealGridList($village_id,$village_modules,$grid){
        $grid_list = invoke_v20_service('\app\mall\model\service\MallHomeDecorateService/getSixList', [0,1,$village_id,$grid])['data']['retval'];
        $type = 8;
        if($grid == 3){
            $type = 9;
        }
        // 总平台权限
        //$res = $this->dealSysVisualizeAssign($village_id,$type);
        if(isset($village_modules['switch']) && intval($village_modules['switch']) > 0){
            $grid_list2 = invoke_v20_service('\app\mall\model\service\MallHomeDecorateService/getSixList', [0,1,0,$grid])['data']['retval'];
            if(!empty($grid_list2)){
                $grid_list = array_merge($grid_list,$grid_list2);
            }
        }
        if(!empty($grid_list)){
            foreach ($grid_list as &$vva){
                foreach ($vva['related_goods'] as $k1 => $v1){
                    if(in_array($vva['type'],['limited','bargain','group'])){
                        $vva['related_goods'][$k1]['url'] = $this->config['site_url'].'/packapp/plat/pages/shopmall_third/commodity_details?goods_id='.$v1['goods_id'].'&source=village';
                    }
                }
                // 三宫格
                if($grid == 3){
                    switch ($vva['type']){
                        case 'bargain':
                            $vva['url'] = $this->config['site_url'].'/packapp/plat/pages/shopmall_third/bargaining';
                            break;
                        case 'limited':
                            $vva['url'] = $this->config['site_url'].'/packapp/plat/pages/shopmall_third/flashSale';
                            break;
                        default :
                            $vva['url'] = $this->config['site_url'].'/packapp/plat/pages/shopmall_third/makeGroup';
                            break;
                    }
                }
            }

            //根据字段 sort 对数组 $grid_list 进行降序排列
            $sort = array_column($grid_list,'sort');
            array_multisort($sort,SORT_DESC,$grid_list);

            // 四宫格小于四个商品不展示
            if($grid == 4 && count($grid_list[0]['related_goods']) < 4){
                return [];
            }

            return $grid_list[0];
        }else{
            return [];
        }
    }

    /**
     * 处理可视化页面总平台设置小区权限 小区是否有相关权限
     * User: zhanghan
     * Date: 2022/2/8
     * Time: 17:34
     * @param $village_id
     * @param $type
     * @return bool
     */
    public function dealSysVisualizeAssign($village_id,$type){
        if(empty($village_id) || empty($type)){
            $this->returnCode('20090005');
        }
        $switch = C('config.house_visualize_switch') ? C('config.house_visualize_switch') : 0;
        // 总平台权限
        if($switch > 0){
            $assign_type = D('House_visualize_assign')->house_visualize_assign($village_id,$type);

            if(!$assign_type['type_0'] && $assign_type['type_'.$type]){
                return true;
            }
        }
        return false;
    }

    //todo 寻求帮助
    public function getAskHelp(){
        $village_id = I('village_id', 0, 'intval');
        if (empty($village_id)) {
            $this->returnCode('20090005');
        }
        $info=D('House_village_info')->getAskHelp($this->config,$village_id);
        if($info['error']){
            $this->returnCode(0, $info['data']);
        }else{
            $this->returnCode('20090005',[],$info['data']);
        }
    }
    public function get_shop_goods_seckill($village_id=0){
        $database_house_village_nav = D('House_village_nav');

        //todo 功能导航
        $assign_type=D('House_visualize_assign')->house_visualize_assign($village_id,15);
        $where=array('type'=>21,'block_type_id'=>'shop_goods_seckill');
        $where['_string'] =' (village_id = '.$village_id.') ';
        if(!$assign_type['type_15']){
            $where['_string'] .= ' or (village_id =0 and (filter_village_ids is null OR  !FIND_IN_SET('.$village_id.', filter_village_ids )))';
        }
        $where['status'] = array('neq',4);
        $result = $database_house_village_nav->house_village_nav_page_list($where , '*' , 'sort DESC,status DESC,id desc',300);
        $shopGoodsDataInfo=array();
        if(isset($result['shopGoodsList']) && $result['shopGoodsList']){
            $shopGoodsData=D('Admin')->getSeckillGoods($result['shopGoodsList'], true);
            if($shopGoodsData){
                foreach ($shopGoodsData as $kk=>$vv){
                    if($kk<30){
                        $shopGoodsDataInfo[]=$vv;
                    }else{
                        break;
                    }
                }
            }
        }
        return $shopGoodsDataInfo;
    }
    public function getHomePagePopInfo(){
        $pigcms_id = I('pigcms_id',0, 'intval');
        $village_id = I('village_id', 0, 'intval');
        if($pigcms_id<1 || $village_id<1 || $this->_uid<1){
            $this->returnCode(0, array('popinfo'=>''));
        }
        $where=array();
        $where['uid'] = $this->_uid;
        $where['village_id'] = $village_id;
        $where['pigcms_id'] = $pigcms_id;
        $House_village_user_bindModel = D('House_village_user_bind');
        $user_bind = $House_village_user_bindModel->field('*')->where($where)->find();
        if(empty($user_bind) || $user_bind['status']!=1){
            $this->returnCode(0, array('popinfo'=>''));
        }
        $nowtime=time();
        $whereArr=array('type'=>20,'block_type_id'=>'house_wap_index_pop');
        $whereArr['_string'] ='';
        $whereArr['status'] = 1;
        $assign_type=D('House_visualize_assign')->house_visualize_assign($village_id,14);
        if(!$assign_type['type_14']){
            $whereArr['_string'] =  ' start_time <= '.$nowtime.' AND end_time>='.$nowtime.' AND ((village_id = '.$village_id.')  or (village_id =0 and (filter_village_ids is null OR  !FIND_IN_SET('.$village_id.', filter_village_ids ))))';
        }else{
            $whereArr['village_id'] =$village_id;
            $whereArr['_string'] =  ' start_time <= '.$nowtime.' AND end_time>='.$nowtime;
        }
        $village_nav=M('House_village_nav')->where($whereArr)->field('*')->order('id desc')->find();
        if(empty($village_nav)){
            $this->returnCode(0, array('popinfo'=>''));
        }
        $today=date('Y-m-d').' 00:00:01';
        $todayTime=strtotime($today);
        $todayEndTime=$todayTime+86398;
        $whereArr=array('village_id'=>$village_id,'u_bind_id'=>$pigcms_id,'xtype'=>'0','related_id'=>$village_nav['id']);
        $whereArr['_string']= ' add_time >= '.$todayTime.' AND add_time<='.$todayEndTime;
        $pop_control=M('House_village_pop_control')->where($whereArr)->field('*')->order('id desc')->find();
        if(!empty($pop_control)){
             //今天弹过了
            $this->returnCode(0, array('popinfo'=>''));
        }
        $popinfo=array();
        $popinfo['id']=$village_nav['id'];
        $popinfo['name']=$village_nav['name'];
        $popinfo['village_id']=$village_id;
        if($village_nav['img'] && substr($village_nav['img'],1,6) == 'static'){
            $village_nav['img'] = C('config.site_url').$village_nav['img'];
        }elseif($village_nav['img'] && substr($village_nav['img'],'0','4') == '000/'){
            $village_nav['img']= file_domain().'/upload/adver/' . $village_nav['img'];
        }elseif($village_nav['img']){
            $village_nav['img']= file_domain().'/upload/service/'.$village_nav['img'];
        }
        $popinfo['img']=$village_nav['img'] ? $village_nav['img']:'';
        $popinfo['url']=$village_nav['url'] ;
        $saveArr=array('village_id'=>$village_id,'u_bind_id'=>$pigcms_id);
        $saveArr['uid']=$this->_uid ? $this->_uid: $user_bind['uid'];
        $saveArr['room_id']=$user_bind['vacancy_id'];
        $saveArr['xtype']=0;
        $saveArr['add_time']=$nowtime;
        $saveArr['nums']=1;
        $saveArr['related_id']=$village_nav['id'];
        M('House_village_pop_control')->data($saveArr)->add();
        $this->returnCode(0, array('popinfo'=>$popinfo));
    }

}
